/* Profile header: the archetype blend as one line of words under the name. */
.hero-streaks-line { position: relative; font-family: var(--serif); font-size: var(--fs-read); line-height: 1.35; color: var(--muted);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hero-streaks-line.is-wrapped { white-space: normal; overflow: visible; }
.hero-streaks-probe { position: absolute; left: 0; top: 0; visibility: hidden; white-space: nowrap; pointer-events: none; }
