/* The streaks line reads as the name's subtitle, so it sits close under it. */
.hero-mix { margin-top: 12px; max-width: 420px; }
.hero-mix-pcts { display: flex; margin-top: 6px; font-family: var(--sans); font-size: var(--fs-label); font-weight: 600; font-variant-numeric: tabular-nums; color: var(--muted); }
.hero-mix-pcts span { white-space: nowrap; }
.hero-mix-pcts span:first-child { color: var(--ink); }


/* Share sheet: Post (4:5) or Story (9:16). A compact toggle labelled like the colour row under it. */
.share-formats { display: flex; align-items: center; gap: 12px; margin-top: 7px; }
.share-format-seg { display: inline-flex; gap: 2px; padding: 3px; border: 1px solid var(--line-2); border-radius: var(--radius-sm); background: var(--panel-2); }
.share-format { display: inline-flex; align-items: center; gap: 7px; padding: 5px 12px; border: 0; border-radius: calc(var(--radius-sm) - 2px);
  font: inherit; font-size: var(--fs-meta); font-weight: 600; color: var(--muted); background: transparent; cursor: pointer; }
