@media (max-width: 768px) {
  .onboard-dropline, .btn.onboard-import-btn.onboard-import-backbtn { display: none; }
}

/* The invited landing (rule 198): the inviter's row under the question. */
.onboard-cine-h-invited { font-size: clamp(26px, 7.2vw, 32px); } /* type scale exception: the landing's fluid headline */
.onboard-invited-card { display: flex; align-items: center; gap: 12px; margin: 14px 0 4px; padding: 10px 12px; border-radius: 12px;
  background: rgba(20,20,23,.72); border: 1px solid var(--line-2); text-align: left; }
.onboard-invited-card .friend-av { flex-basis: 40px; width: 40px; height: 40px; font-size: var(--fs-ui); }
.onboard-invited-card .friend-name { font-size: var(--fs-ui); }

/* "Who do you watch films with?" (WhoYouWatchWith, rule 197). */
.social-step .account-lead { margin-bottom: var(--sp-12); }
.social-step-rows { margin: 0 0 6px; }
.social-step-handle { font-weight: 500; color: var(--faint); font-size: var(--fs-meta); }
.social-step-follow { flex: none; min-width: 88px; }
.social-step-follow.is-on { color: var(--accent-2); border-color: transparent; opacity: 1; }
.social-step-none { color: var(--muted); font-size: var(--fs-meta); line-height: 1.5; margin: 6px 0 10px; }
.social-step-fine { font-size: var(--fs-meta); color: var(--faint); margin: 2px 0 var(--sp-16); line-height: 1.5; }
.social-step-actions { display: flex; flex-direction: column; align-items: center; gap: 14px; }
.social-step-skip { color: var(--accent-2); font-weight: 600; font-size: var(--fs-meta); }

/* The invited reveal (rule 198): "You and <Name>: NN%" with Follow, under the picks. */
.rv-match { display: flex; align-items: center; gap: 12px; margin: var(--sp-16) auto 0; max-width: 420px; padding: 12px 14px; border-radius: 12px;
  background: var(--panel); border: 1px solid var(--line-2); text-align: left; }
.rv-match .friend-av { flex-basis: 40px; width: 40px; height: 40px; font-size: var(--fs-ui); }
.rv-match-m { flex: 1; min-width: 0; }
.rv-match-l { font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; color: var(--ink); line-height: 1.15; }
.rv-match-l b { color: var(--accent-2); font-weight: 600; }
.rv-match-s { font-size: var(--fs-meta); color: var(--faint); margin-top: 2px; }
.rv-match-follow { flex: none; min-width: 84px; }
.rv-match-follow.is-on { color: var(--accent-2); border-color: transparent; opacity: 1; }
.onboard-import-alt { line-height: 1.7; }

/* Reveal: the first picks inside the archetype card. */
.rpicks { margin-top: var(--sp-24); }
.rpicks-eye { margin-bottom: 10px; }
.rpicks-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.rpick { min-width: 0; text-align: left; }
.rpick-poster { width: 100%; aspect-ratio: 2 / 3; object-fit: cover; display: block; border: 1px solid var(--line-2); background: var(--panel-2); }
.rpick-match { display: block; margin-top: 6px; font-size: var(--fs-meta); font-weight: 700; color: var(--accent-2); font-variant-numeric: tabular-nums; }
.rpick-title { display: block; margin-top: 2px; font-size: var(--fs-label); color: var(--muted); line-height: 1.3; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* The third pick is the one the account unlocks. */
.rpick.is-locked .rpick-poster { filter: blur(6px) brightness(.7); }
.rpick.is-locked .rpick-match, .rpick.is-locked .rpick-title { filter: blur(4px); user-select: none; }
.rpick.is-locked { overflow: hidden; }

/* Reveal: the save, right under the card. Google is the cream primary here. */
/* The archetype reveal (LockedIdentity; owner, 2026-09-30, option A "the print develops"): a
   centered title card, then the picks and the save rise in. Reduced motion: finished at once. */
.rv { max-width: 440px; margin: var(--sp-16) auto 0; text-align: center; }
.rv-eye { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .16em; text-transform: uppercase; color: var(--eyebrow); font-weight: 600; }
.rv-name { font-family: var(--serif); font-weight: 600; font-size: clamp(40px, 12vw, 52px); line-height: 1.02; letter-spacing: -.01em; color: var(--ink); margin: 12px 0 0; } /* type scale exception: the reveal's archetype name */
.rv-mark { width: 56px; height: 3px; background: var(--shadow); margin: 16px auto 0; }
.rv-tag { font-family: var(--serif); font-style: italic; font-size: var(--fs-card); line-height: 1.35; color: var(--muted); margin: 14px 10px 0; }
.rv-streak { font-size: var(--fs-meta); color: var(--accent-2); margin: 8px 0 0; }
.rv-picks { margin-top: 30px; }
.rv-picks .rpicks-eye { text-align: center; }
.rv .rpick-poster { border-color: var(--ink); filter: var(--grade); }
.rv .rpick.is-locked .rpick-poster { filter: blur(6px) brightness(.7); }
.rv .rv-eye { animation: rvIn 400ms ease 80ms both; }
.rv .rv-name { animation: rvDevelop 1000ms cubic-bezier(.3,.6,.2,1) 250ms both; }
.rv .rv-mark { animation: rvDraw 420ms cubic-bezier(.2,.7,.2,1) 1050ms both; }
.rv .rv-tag { animation: rvUp 500ms ease 1150ms both; }
.rv .rv-streak { animation: rvUp 500ms ease 1300ms both; }
.rv .rv-picks-eye { animation: rvIn 400ms ease 1400ms both; }
.rv .rv-rise { animation: rvRise 520ms cubic-bezier(.2,.7,.2,1) both; }
.rv div.rv-rise:not(.rpick) { animation-name: rvIn; }
.rv-save { animation: rvUp 500ms ease 2200ms both; }
@keyframes rvIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes rvUp { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
@keyframes rvRise { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: none; } }
@keyframes rvDraw { from { width: 0; } to { width: 56px; } }
@keyframes rvDevelop {
  0% { opacity: 0; filter: blur(18px) brightness(2.2); transform: scale(1.04); }
  35% { opacity: .75; filter: blur(8px) brightness(1.7); }
  45% { opacity: .5; } 52% { opacity: .9; } 58% { opacity: .7; }
  100% { opacity: 1; filter: blur(0) brightness(1); transform: none; }
}
@media (prefers-reduced-motion: reduce) { .rv *, .rv-save { animation: none !important; } }
.reveal-save { max-width: 440px; margin: var(--sp-24) auto 0; text-align: center; border-top: 1px solid var(--line); padding-top: 14px; }
.reveal-save-eye { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .16em; text-transform: uppercase; font-weight: 700; color: var(--faint); margin-bottom: 8px; }
