.reveal-save-sub { font-size: var(--fs-meta); color: var(--muted); line-height: 1.5; margin: var(--sp-8) auto 0; max-width: 340px; }
.reveal-save-auth { margin-top: var(--sp-16); display: flex; justify-content: center; }
.reveal-save-auth .signin-form { margin: 0 auto; }
.reveal-save .oauth-btn-primary { background: var(--ink); color: var(--bg); border-color: var(--ink); box-shadow: 4px 4px 0 var(--shadow); }
.reveal-save .oauth-btn-primary:hover { background: #fff8ea; border-color: #fff8ea; }
.reveal-save-fine { font-size: var(--fs-label); color: var(--faint); margin-top: var(--sp-12); }
/* "Rate more" and "Start over": reachable, never competing with the save. */
.reveal-save-exits { margin-top: var(--sp-24); font-size: var(--fs-meta); } /* no rule above it: it doubled the footer's (owner, 2026-11-04: "random extra section lines") */


/* Handle step: one field, pre-filled, one tap. */
.acct-handle-screen { padding-top: var(--sp-40); max-width: 420px; }
.acct-handle-screen .account-title { margin: var(--sp-8) 0 var(--sp-8); }
.acct-handle-screen .account-lead { margin: 0 0 var(--sp-24); max-width: none; }
.acct-handle-fine { font-size: var(--fs-meta); color: var(--faint); text-align: center; margin: var(--sp-4) 0 0; }

/* Discover, first visit after sign-up: three for tonight and one next step. */
.dsc-welcome { margin-bottom: var(--sp-32); }
.dsc-welcome-h { font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; color: var(--ink); margin: var(--sp-4) 0 14px; line-height: 1.15; }
