/* Desktop: the six starter picks sit on one row. */
@media (min-width: 760px) { .dsc-starter .dsc-welcome-row { max-width: none; grid-template-columns: repeat(6, minmax(0, 1fr)); } }
.dsc-welcome-pick { appearance: none; background: none; border: 0; padding: 0; cursor: pointer; font: inherit; color: inherit; }
.dsc-welcome-pick .rpick-poster { border-color: var(--ink); }
.dsc-welcome-next { appearance: none; cursor: pointer; font: inherit; text-align: left; width: 100%; max-width: 520px; margin-top: var(--sp-24);
  display: flex; align-items: center; gap: var(--sp-12); padding: 14px var(--sp-16); border-radius: var(--radius);
  background: var(--panel); border: 1px solid var(--line-2); color: var(--muted); font-size: var(--fs-meta); line-height: 1.45; transition: border-color var(--dur) var(--ease); }
.dsc-welcome-next:hover { border-color: var(--faint); }
.dsc-welcome-next b { color: var(--ink); font-weight: 700; }
