/* Three for tonight's Tonight and its drawer (rule 1142; mockups/journeys/onboarding-moments-v1-b.html moment 1). */
.dsc-welcome-sub { font-size: var(--fs-meta); color: var(--muted); margin: -8px 0 14px; }
.dsc-welcome-col { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.dsc-welcome-col .rpick-title { white-space: normal; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; min-height: 2.6em; }
.dsc-welcome-tonight { appearance: none; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; gap: 6px; width: 100%;
  height: var(--btn-h-sm); padding: 0 8px; border-radius: 999px; border: 1px solid var(--line-2); background: rgba(255, 255, 255, .05);
  color: var(--ink); font: inherit; font-size: var(--fs-meta); font-weight: 600; white-space: nowrap; }
.dsc-welcome-tonight svg { width: 12px; height: 12px; color: var(--accent-2); flex: none; }
.dsc-welcome-tonight.is-on { background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); color: var(--ink); }
@media (hover: hover) { .dsc-welcome-tonight:hover { border-color: var(--faint); } }
.dsc-tonight-lead { font-family: var(--serif); font-size: var(--fs-card); font-weight: 500; line-height: 1.4; color: var(--ink); margin: var(--sp-16) 0 0; }
.dsc-tonight-why { font-size: var(--fs-ui); color: var(--muted); margin: var(--sp-8) 0 0; }
.dsc-tonight-acts { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: var(--sp-24); }
.dsc-tonight-acts .btn { min-height: var(--btn-h-lg); width: 100%; }
/* Follow-up emails off (rule 1157): one button, and why there is no email. */
.dsc-tonight-acts.dsc-tonight-one { grid-template-columns: 1fr; }
.dsc-tonight-note { font-size: var(--fs-meta); color: var(--faint); margin: var(--sp-12) 0 0; text-align: center; }

/* Reveal: the first picks are scored cold for a new quiz (about 12s); say so under the tiles. */
.rpicks-wait { font-size: var(--fs-meta); color: var(--muted); margin-top: var(--sp-8); animation: rpicksWait 1.6s ease-in-out infinite; }
@keyframes rpicksWait { 0%, 100% { opacity: .55; } 50% { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .rpicks-wait { animation: none; } }

/* Activity: a follow row is not one big link; only the handle is (the avatar links quietly). */
.act-cardrow.act-cardrow-static { cursor: default; }
.act-cardrow.act-cardrow-static:hover { background: none; }
.act-av-link { display: inline-flex; flex: none; text-decoration: none; }
.act-handle { color: inherit; text-decoration: underline; text-underline-offset: 3px; text-decoration-thickness: 1px; }
.act-handle:hover { color: var(--accent-2); }

/* Browse (Discover → Explore → Browse): the long scroll, in Tonight's sheet with Tonight's chips. */
.browse { display: flex; flex-direction: column; gap: 12px; }
.browse-sort .mood-seg { font-size: var(--fs-meta); padding: 9px 4px; }
.browse-selects { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.browse-select { width: 100%; min-width: 0; text-overflow: ellipsis; }
.browse-bar { display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: var(--fs-meta); color: var(--muted); }
.browse-seen { display: inline-flex; align-items: center; gap: 7px; cursor: pointer; }
.browse-seen input { accent-color: var(--accent-2); }
.browse-count { color: var(--faint); font-size: var(--fs-meta); text-align: right; }
.browse-grid { margin-top: 2px; }
.browse-year { color: var(--faint); font-weight: 400; }
.browse-empty { color: var(--muted); text-align: center; font-size: var(--fs-meta); margin: 24px 0; }
.browse-none { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: var(--sp-8) var(--sp-12); margin: var(--sp-24) 0; color: var(--muted); font: 400 var(--fs-meta)/1.4 var(--sans); }
.browse-none p { margin: 0; }
.browse-loading { display: flex; justify-content: center; padding: var(--sp-16) 0; }
/* Past two screens of grid: back to the top, or out, without the long scroll up. Sticky to the
   bottom of the modal's own scroll, so it rides along with the grid. */
.browse-float { position: sticky; bottom: calc(12px + env(safe-area-inset-bottom)); z-index: 3; display: flex; justify-content: center; gap: 8px;
  margin-top: 12px; pointer-events: none; animation: fade .2s ease; }
.browse-float button { pointer-events: auto; font-family: var(--label); font-size: var(--fs-label); letter-spacing: .1em; text-transform: uppercase; font-weight: 600;
  padding: 10px 16px; border-radius: 999px; border: 1px solid var(--line-2); background: var(--panel); color: var(--ink);
  box-shadow: 0 6px 20px rgba(0,0,0,.45); cursor: pointer; min-height: var(--btn-h); }
.browse-float button:hover { border-color: var(--faint); }
@media (max-width: 420px) { .browse-sort .mood-seg { font-size: var(--fs-label); padding: 8px 2px; } }
/* A <button> centres its content vertically; in a grid row the one-line titles sat lower than
   the two-line ones. Top-align every card. */
.browse-grid .lib-card { display: flex; flex-direction: column; justify-content: flex-start; align-self: start; }

/* Taste test: "Seen any of these?" after the deck. Three across on a phone, four on desktop;
   each tap moves a poster through loved / liked / not for me / unseen. */
/* The grid scrolls on its own and the button stays on screen, however short the phone. */
.ttbig { height: 100dvh; max-height: 100dvh; }
.ttbig .ttreel-qbody { flex: 1 1 auto; overflow-y: auto; min-height: 0; padding-top: var(--sp-8); }
.ttbig .ttreel-start { flex: none; }
.ttbig .tt-qprompt { margin-top: 4px; }
.ttbig-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin: 16px auto 4px; width: 100%; max-width: 520px; }
/* Desktop: 6 across in 2 rows, sized from the window's height so all twelve fit above the button.
   Centred with auto margins, not justify-content: a centred block taller than its scroll box was
   cut off at the top as well as the bottom, where it could not be scrolled to (the heading sat
   under the header and the third row under the button on a short laptop window). */
@media (min-width: 760px) {
  .ttbig .ttreel-qbody { justify-content: flex-start; }
  .ttbig .ttreel-qbody > :first-child { margin-top: auto; }
  .ttbig .ttreel-qbody > :last-child { margin-bottom: auto; }
  /* Up to 1040px across on a laptop (owner, 2026-09-28: the posters sat small in a lot of empty
     space); the height term still keeps both rows and the button on screen. */
  .ttbig .ttreel-qbody { max-width: 1100px; }
  .ttbig .ttreel-start { max-width: 760px; }
  .ttbig-grid { grid-template-columns: repeat(6, 1fr); gap: 12px; max-width: min(1040px, calc((100dvh - 300px) * 2 + 40px)); }
  .ttbig .ttreel-start { max-width: 560px; margin-top: var(--sp-16); margin-bottom: 24px; }
}
/* "Your taste so far" (lib/taste/maturity.ts, TasteSoFar): the still-developing pill under a starting
   archetype, and the unlock steps under the hero. */
.dev-pill { display: inline-flex; gap: 6px; align-items: center; font-size: var(--fs-label); color: var(--faint); border: 1px solid var(--line-2); border-radius: 999px; padding: 3px 9px; margin-top: 6px; }
.dev-pill i { width: 7px; height: 7px; border-radius: 50%; background: var(--accent); }
/* Discover's "Starter picks" for a newcomer (under 30 rated), popular films in their lanes. */
.dsc-starter { margin: var(--sp-16) 0 6px; }
.dsc-starter-p { font-size: var(--fs-meta); color: var(--muted); line-height: 1.5; margin: 2px 0 10px; }

/* "Haven't seen many of these?" (TasteTest phase "famous", lib/taste-test/low-history.ts): one tap
   marks a famous film seen; the chosen ones carry the accent keyline and a check. */
.ttfam-po { appearance: none; padding: 0; border: 1px solid rgba(255,255,255,.18); border-radius: var(--radius-sm, 6px); background: var(--panel); position: relative; aspect-ratio: 2 / 3; overflow: hidden; cursor: pointer; }
.ttfam-po img { width: 100%; height: 100%; object-fit: cover; display: block; }
.ttfam-po.on { outline: 2px solid var(--select); outline-offset: 1px; }
.ttfam-t { position: absolute; left: 4px; right: 4px; bottom: 4px; font-size: var(--fs-label); line-height: 1.2; color: var(--ink); background: rgba(11,11,13,.8); padding: 2px 4px; border-radius: 4px; text-align: left; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.ttfam-check { position: absolute; top: 4px; right: 4px; width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; font-size: var(--fs-label); font-weight: 700; background: var(--accent); color: var(--bg); }
.ttfam-count { margin-top: 8px; font-size: var(--fs-meta); font-weight: 600; color: var(--accent-2); text-align: center; }
.ttfam-actions { flex: none; display: flex; flex-direction: column; align-items: stretch; gap: 8px; width: 100%; max-width: 560px; margin: 0 auto; padding-bottom: var(--sp-24); }
.ttfam-actions .ttreel-start { margin-top: 10px; margin-bottom: 0; }

/* The deck's forming guess (TasteTest, lib/taste/maturity.ts FORMING_FROM): a small card pinned
   under the reel, the archetype never blurred (muted while its read is on the way), a bar to 15. */
.ttform { position: absolute; left: 12px; right: 12px; bottom: calc(10px + env(safe-area-inset-bottom)); z-index: 4;
  display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 12px;
  background: rgba(20,20,23,.92); border: 1px solid var(--line-2); backdrop-filter: blur(10px);
  max-width: 520px; margin: 0 auto; animation: rvUp 320ms ease both; }
.ttform.is-ready { border-color: var(--accent); }
/* Room for the forming card under every card's answers, so it never covers a button. */
.ttreel-overlay.has-ttform .reel-body { padding-bottom: calc(86px + env(safe-area-inset-bottom)); }
.ttform-m { flex: 1; min-width: 0; }
.ttform-eye { font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; color: var(--faint); font-weight: 700; }
.ttform-name { font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; line-height: 1.2; margin-top: 2px; color: var(--ink);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: color 300ms ease; }
.ttform-name.is-stale { color: var(--muted); }
.ttform-name.is-forming { color: var(--muted); font-style: italic; }
.ttform-pill { appearance: none; flex: none; border: 0; cursor: pointer; font: inherit; font-size: var(--fs-meta); font-weight: 700;
  background: var(--accent); color: var(--bg); border-radius: 999px; padding: 6px 12px; }
.ttform-pill:hover { filter: brightness(1.08); }
/* A contrarian at Reveal (rule 250): one quiet line under the card's row, full width. */
/* Teaser A (rule 1009): the note is one line under the name, inside the block; Reveal it stays right. */
.ttform-more { font-size: var(--fs-meta); line-height: 1.3; color: var(--muted); margin-top: 2px; }
.ttform-decide { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ttreel-overlay.has-ttform.has-ttform-more .reel-body, .ttreel-overlay.has-ttform.has-ttform-more .ttq-slide { padding-bottom: calc(96px + env(safe-area-inset-bottom)); }
@media (prefers-reduced-motion: reduce) { .ttform { animation: none; } .ttform-name { transition: none; } }
.ttfam-back { align-self: center; margin-top: 4px; }
.ttreel-done { font-size: var(--fs-label); color: var(--muted); white-space: nowrap; }

/* The phone's rating sheet for "Seen any of these?" (BigOneSheet): above the Taste Test overlay. */
.ttsheet-film { display: flex; flex-direction: column; align-items: center; gap: 10px; margin: 8px 0 14px; }
.ttbig-card { position: relative; border: 2px solid transparent; border-radius: var(--radius-sm); overflow: hidden;
  background: var(--panel-2); cursor: pointer; aspect-ratio: 2 / 3; container-type: inline-size; transition: border-color .15s ease; }
.ttbig-card img { width: 100%; height: 100%; object-fit: cover; display: block; opacity: .82; transition: opacity .15s ease; }
.ttbig-card:hover img, .ttbig-card.on img { opacity: 1; }
.ttbig-card.is-rated { border-color: var(--accent-2); }
.ttbig-card.is-want { border-color: var(--line-2); }
/* The controls: hidden until the poster is hovered (a real mouse) or tapped (touch, one card at
   a time). They cover the lower part of the poster on a dark fade, so the art still reads. */
.ttbig-star { position: relative; display: inline-block; font-size: clamp(11px, 17cqw, 24px); line-height: 1; width: 1em; height: 1em; } /* type scale exception: star glyphs */
/* A phone's four-across poster is too narrow for the full label. */
.browse-summary { margin: -2px 0 0; font-size: var(--fs-ui); color: var(--ink); line-height: 1.4; }
.browse-loading-top { padding: 10px 0 4px; }
.browse-grid.is-stale { opacity: .3; pointer-events: none; transition: opacity .15s ease; }
/* Browse lane picker: search box over a scrolling list grouped by parent genre. */
.browse-lane-btn { text-align: left; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.browse-lane-btn.on { color: var(--ink); border-color: var(--line-2); }
.browse-lanes { border: 1px solid var(--line-2); border-radius: var(--radius); background: var(--panel); padding: 10px; display: flex; flex-direction: column; gap: 8px; }
.browse-lane-search { flex: none; width: 100%; font-size: var(--fs-read); }
.browse-lane-list { max-height: 300px; overflow-y: auto; display: flex; flex-direction: column; gap: 2px; }
.browse-lane-parent { font-size: var(--fs-label); letter-spacing: .12em; text-transform: uppercase; font-weight: 700; color: var(--faint); padding: 10px 8px 4px; }
.browse-lane-opt { appearance: none; background: none; border: 0; text-align: left; font: inherit; font-size: var(--fs-ui); color: var(--ink); padding: 8px; border-radius: var(--radius-sm); cursor: pointer; width: 100%; }
.browse-lane-opt:hover, .browse-lane-opt.on { background: var(--panel-2); }
.browse-lane-opt.on { color: var(--ink); font-weight: 600; }
.browse-lane-any { color: var(--muted); }
.browse-lane-none { color: var(--muted); font-size: var(--fs-meta); padding: 10px 8px; }
.browse-lanes-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; font-size: var(--fs-ui); font-weight: 600; color: var(--ink); padding: 2px 4px; }
.browse-picked { display: flex; flex-wrap: wrap; gap: 6px; }
.browse-lane-opt:disabled { opacity: .4; cursor: default; }

/* Archetypes directory: Contrarian sits apart from the 14, as a streak. */
.arche-streaks-hd { margin: 34px 0 4px; font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase;
  color: var(--muted); font-weight: 600; }
.arche-streaks-sub { margin: 0 0 14px; font-size: var(--fs-meta); color: var(--faint); }
/* The archetypes' next step (rule 214): its own heading and rule, the cream button, the import
   as a quiet link under it. */
.arche-cta { margin: 32px 0 8px; padding: var(--sp-24) 0 var(--sp-8); border-top: 1px solid var(--line); text-align: center; }
.arche-cta-t { font-family: var(--serif); font-size: var(--fs-title); font-weight: 600; letter-spacing: -.01em; margin: 0 0 6px; color: var(--ink); }
.arche-cta-s { margin: 0 0 var(--sp-16); font-size: var(--fs-meta); color: var(--muted); }
.arche-cta-go { display: inline-flex; align-items: center; justify-content: center; min-width: 240px; }
.arche-cta-alt { margin-top: 14px; font-size: var(--fs-meta); color: var(--muted); }
@media (max-width: 560px) { .arche-cta-go { width: 100%; min-width: 0; } }

/* Taste match page (2026-09-26): one sentence under the score, lanes as links, posters for how
   ratings line up, picks for each other as rails, one line each on where two people differ. */
/* Straight under the score now: the one-line summary that sat between them ("You often rate the
   films you share the same way") only restated "How your ratings line up" further down. */
.mx-share.mx-share-top { margin: var(--sp-24) 0 var(--sp-24); }
.mx-sub { font-size: var(--fs-meta); color: var(--faint); margin: -4px 0 12px; }
a.mx-chip-lane { text-decoration: none; }
a.mx-chip-lane:hover { border-color: var(--ink); }
.mx-line-n { font-family: var(--ui); font-size: var(--fs-title); font-weight: 600; line-height: 1; color: var(--ink); font-variant-numeric: tabular-nums; }
.mx-line-k { font-size: var(--fs-meta); color: var(--muted); margin-top: 3px; }
.mx-split { display: flex; align-items: center; gap: 12px; margin-top: 10px; padding: 10px 12px; border: 1px solid var(--shadow, #8c2030); border-radius: var(--radius); text-decoration: none; color: inherit; }
.mx-split img { width: 44px; aspect-ratio: 2 / 3; object-fit: cover; border-radius: 6px; flex: none; }
.mx-split b { display: block; font-size: var(--fs-ui); color: var(--ink); }
.mx-split span span { font-size: var(--fs-meta); color: var(--muted); }
.hrail { display: flex; gap: 10px; overflow-x: auto; padding-bottom: 4px; scrollbar-width: none; }
.hrail::-webkit-scrollbar { display: none; }
.hrail-card { flex: 0 0 104px; text-decoration: none; color: inherit; }
.hrail-poster { aspect-ratio: 2 / 3; border-radius: var(--radius-sm); overflow: hidden; border: 1px solid var(--line); background: var(--panel-2); }
.hrail-poster img { width: 100%; height: 100%; object-fit: cover; display: block; }
.hrail-match { font-size: var(--fs-meta); font-weight: 700; color: var(--accent-2); margin-top: 5px; }
.hrail-title { font-size: var(--fs-label); color: var(--muted); line-height: 1.25; margin-top: 1px; }
/* Movie night: how the vote works, and keeping the ticket as a vote of its own. */
.mx-differ { display: flex; flex-direction: column; gap: 8px; }
.mx-differ-row { display: flex; flex-direction: column; gap: 2px; padding: 11px 13px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--panel); font-size: var(--fs-ui); color: var(--muted); line-height: 1.35; }
.mx-differ-who { font-size: var(--fs-meta); font-weight: 700; color: var(--ink); }

.tn-to-mn { text-align: center; font-size: var(--fs-meta); color: var(--muted); margin: var(--sp-16) 0 0; }
/* The link keeps its look; padding pulled back by a negative margin gives it a 36px hit area. */
.tn-to-mn .linkbtn { padding-block: 10px; margin-block: -10px; }
/* Movie night room (2026-09-25): the room reads like Tonight. One eyebrow + serif line per
   screen, the roster as a row of faces, the mood chips inline, one primary button, and the
   pick as the same red ticket Tonight hands out. mnr- so it cannot collide with the older
   mn- sheet classes that are still used by the group movie night. */
.mnr .mnr-head { margin: 2px 0 14px; }
.mnr .mnr-title { margin: 8px 0 0; line-height: 1.08; }
.mnr-lede { font-size: var(--fs-ui); line-height: 1.5; color: var(--muted); margin: 10px 0 0; }
.mnr > .mnr-lede { margin: 0 0 16px; }
.mnr-seats { display: flex; flex-wrap: wrap; gap: 14px 12px; margin: 4px 0 12px; }
.mnr-seat { display: flex; flex-direction: column; align-items: center; gap: 6px; width: 54px; appearance: none; background: none; border: 0; padding: 0; font: inherit; color: inherit; }
.mnr-seat-av { position: relative; display: block; width: 44px; height: 44px; }
.mnr-seat-av .friend-av { width: 44px; height: 44px; flex: none; font-family: var(--serif); font-size: var(--fs-card); }
.mnr-seat-name { max-width: 58px; font-size: var(--fs-label); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mnr-seat-ok { position: absolute; right: -5px; bottom: -5px; width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center;
  background: var(--accent); color: var(--bg); font-size: 10px; font-weight: 800; border: 2px solid var(--bg); line-height: 1; } /* type scale exception: initials or a glyph in a fixed box */
.mnr-seat-x { position: absolute; top: -7px; right: -7px; width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; padding: 0;
  background: var(--panel-2); color: var(--faint); border: 1px solid var(--line-2); font-size: var(--fs-label); line-height: 1; cursor: pointer; }
.mnr-seat-x:hover { color: var(--ink); border-color: var(--ink); }
.mnr-seat-invite { cursor: pointer; }
.mnr-seat-invite .friend-av { background: none !important; border: 1px dashed var(--line-2); color: var(--muted); font-family: var(--sans); font-size: var(--fs-card); }
.mnr-seat-invite:hover .friend-av { border-color: var(--ink); color: var(--ink); }
.mnr-status { font-size: var(--fs-meta); color: var(--accent-2); margin: 0 0 16px; }
.mnr-link { display: flex; align-items: center; gap: 4px; padding: 4px 4px 4px 14px; border: 1px solid var(--line-2); border-radius: var(--radius); background: var(--panel); }
.mnr-link-url { flex: 1; min-width: 0; font-size: var(--fs-meta); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mnr-link-btn { flex: none; display: inline-flex; align-items: center; gap: 6px; appearance: none; border: 0; background: none; color: var(--muted); font: inherit; font-size: var(--fs-meta); font-weight: 700; padding: 10px 10px; cursor: pointer; border-radius: var(--radius-sm); }
.mnr-link-btn:hover { color: var(--ink); }
.mnr-wide { display: flex; width: 100%; align-items: center; justify-content: center; margin-top: 10px; text-align: center; min-height: 48px; }
/* The mode labels are short on purpose, and never wrap: at 340px the three still sit on one line. */
.mnr .mnr-mode { margin: var(--sp-16) 0 0; }
.mnr-mode .mood-seg { white-space: nowrap; font-size: var(--fs-meta); padding: 9px 4px; min-width: 0; }
.mnr-modehint { font-size: var(--fs-label); color: var(--faint); margin: 7px 0 0; text-align: center; }
/* The mood step (owner-approved mockup, 2026-09-30): the room's settings as one card (Edit opens
   them in place for the host; read-only for everyone else), then YOUR MOOD chips and Tonight's
   quiet rows (Genre, Age rating, Length). */
.mnr-room { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: var(--sp-16);
  padding: 12px 14px; border: 1px solid var(--line); border-radius: var(--radius-field); background: var(--panel); }
.mnr-room-main { min-width: 0; }
.mnr-room-k, .mnr-room-sk { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; font-weight: 700; color: var(--faint); }
.mnr-room-v { font-size: var(--fs-ui); font-weight: 600; color: var(--ink); margin-top: 3px; }
.mnr-room-btn { flex: none; appearance: none; border: 0; background: none; font: inherit; font-size: var(--fs-meta); font-weight: 600; color: var(--accent-2); cursor: pointer; padding: 8px 0 8px 8px; }
.mnr-room-btn:hover { color: var(--ink); }
.mnr-room-edit { margin-top: var(--sp-16); padding: 12px 14px 14px; border: 1px solid var(--line-2); border-radius: var(--radius-field); background: var(--panel); }
.mnr-room-top { display: flex; align-items: center; justify-content: space-between; }
.mnr-room-sk { margin: 12px 0 6px; }
.mnr .mnr-room-edit .mnr-mode { margin: 0; }
.mnr-room-edit .mnr-occasion-chips { margin: 0; }
.mnr-lang-chips { margin-top: 8px; }
.mnr-eb-note { font-weight: 500; letter-spacing: 0; text-transform: none; }
.mnr-mood-chips { margin-top: 0; }
/* The iPhone's primary (PrimaryButtonStyle; owner, 2026-11-05: "I like how the buttons look on iPhone", rule 1103): a 44 cream pill, 15 semibold. */
.mnr-primary { display: flex; width: 100%; align-items: center; justify-content: center; gap: 6px; min-height: var(--btn-h); padding: 0 var(--sp-16); margin-top: var(--sp-16); font-size: var(--fs-ui); text-align: center; text-decoration: none; }
.mnr-primary.mnr-done:disabled { opacity: 1; color: var(--muted); }
.mnr-open-banner { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 0 0 16px; padding: 12px 14px;
  border: 1px solid var(--accent); border-radius: var(--radius-sm); background: var(--accent-soft); color: var(--ink); font-size: var(--fs-ui); }
.mnr-open-banner .btn { flex: none; min-height: var(--btn-h-sm); padding: 0 16px; }
.mnr-early { margin-top: 14px; font-size: var(--fs-meta); color: var(--muted); text-align: center; }
.mnr-tie { margin-top: 14px; } .mnr-tie .mnr-hint { text-align: center; } .mnr-tie .mnr-primary { margin-top: 10px; }
.mnr-hint { font-size: var(--fs-meta); color: var(--faint); text-align: center; margin-top: 10px; line-height: 1.45; }
/* Rule 1103: tonight's room, named from its taste. The faces and the name centred as one group. */
.mnr-rn { margin: var(--sp-12) 0 var(--sp-8); text-align: center; }
.mnr-rn-k { font-size: var(--fs-label); font-weight: 600; letter-spacing: 1.6px; text-transform: uppercase; color: var(--accent-2); }
.mnr-rn-row { display: flex; align-items: center; justify-content: center; flex-direction: column; gap: var(--sp-8); margin-top: var(--sp-8); }
.mnr-rn-faces { display: flex; flex: none; }
.mnr-rn-face { width: 28px; height: 28px; border-radius: var(--radius-sm); display: inline-flex; align-items: center; justify-content: center; font-family: var(--serif); font-size: var(--fs-meta); font-weight: 600; margin-right: -5px; box-shadow: 0 0 0 2px var(--bg); object-fit: cover; }
.mnr-rn-v { max-width: 100%; font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; line-height: 1.1; color: var(--ink); overflow-wrap: anywhere; }
.mnr-rn-tap { background: none; border: 0; padding: 0; cursor: pointer; text-align: center; }
.mnr-rn-line { display: flex; align-items: center; justify-content: center; gap: var(--sp-8); max-width: 100%; }
.mnr-rn-line .mnr-rn-v { min-width: 0; }
.mnr-rn-ib { flex: none; width: 32px; height: 32px; border-radius: 50%; border: 1px solid var(--line); background: none; color: var(--ink); display: inline-flex; align-items: center; justify-content: center; cursor: pointer; }
.mnr-rn-ib:disabled { opacity: 0.4; cursor: default; }
.mnr-rn-fld { position: relative; display: block; margin-top: var(--sp-16); }
.mnr-rn-fld .input { width: 100%; font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; padding-right: 64px; }
.mnr-rn-fld small { position: absolute; right: 14px; top: 50%; transform: translateY(-50%); font-size: var(--fs-meta); color: var(--faint); }
.mnr-rn-subh { margin: var(--sp-24) 0 var(--sp-4); font-size: var(--fs-label); font-weight: 600; letter-spacing: 1.6px; text-transform: uppercase; color: var(--faint); }
.mnr-rn-chips { display: flex; flex-wrap: wrap; gap: var(--sp-8); margin-top: var(--sp-8); }
.mnr-rn-chip { height: 34px; padding: 0 13px; border-radius: 999px; border: 1px solid var(--line); background: none; color: var(--ink); display: inline-flex; align-items: center; gap: 6px; font-size: var(--fs-meta); cursor: pointer; white-space: nowrap; }
.mnr-rn-chip.on { margin-top: var(--sp-12); background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); color: var(--ink); font-weight: 600; }
/* A little more air (owner, 2026-11-05: "a little more spread out vertically"): 16 above, 24 below, 16 inside, 8 from ring to words. */
.mnr-steps { list-style: none; margin: var(--sp-16) 0 var(--sp-24); padding: var(--sp-16) var(--sp-12); display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--sp-8); border: 1px solid var(--line); border-radius: var(--radius-card); background: var(--panel); }
.mnr-steps li { position: relative; display: flex; flex-direction: column; align-items: center; gap: var(--sp-8); text-align: center; font-size: var(--fs-meta); line-height: 1.35; color: var(--muted); }
.mnr-steps li + li::before { content: ""; position: absolute; top: 12px; right: calc(50% + 18px); width: calc(100% - 28px); height: 1px; background: var(--line-2); }
.mnr-step-n { width: 24px; height: 24px; border-radius: 50%; border: 1px solid var(--accent); color: var(--accent-2); display: inline-flex; align-items: center; justify-content: center; font-family: var(--serif); font-size: var(--fs-meta); font-weight: 600; background: var(--bg); }
/* The iPhone's quiet button at body size (QuietButtonStyle(size: bodySize)): "Join as a guest instead", "Host your own". */
.mnr-quiet-link { display: block; margin: 16px auto 0; font-size: var(--fs-ui); text-align: center; }
.fp-actions .fp-btn.mnr-join-go { min-height: var(--btn-h); }
.mnr-signin { margin-top: 2px; }
.mnr-card { margin-top: var(--sp-16); padding: 16px; border: 1px solid var(--accent); border-radius: var(--radius); background: var(--panel); }
.mnr-card-h { font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; line-height: 1.2; color: var(--ink); }
.mnr-card-p { font-size: var(--fs-meta); line-height: 1.5; color: var(--muted); margin: 6px 0 4px; }
/* The pick. */
.mnr-tw { display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: 6px; margin-top: 12px; }
.mnr-tw-k { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; font-weight: 600; color: rgba(239, 232, 218, .75); margin-right: 2px; }
.mnr-tw-you { font-size: var(--fs-meta); font-weight: 700; color: var(--ink); margin-left: 4px; }
.mnr-arche { text-align: center; font-size: var(--fs-meta); color: var(--muted); margin: var(--sp-16) 0 0; }
.mnr-arche b { font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; color: var(--ink); }
.mnr-alts .tn-gcard.on .tn-gposter { outline: 2px solid var(--select); outline-offset: 2px; }
.mnr-after { margin-top: var(--sp-16); font-size: var(--fs-meta); color: var(--muted); }

/* The ticket, Tonight's and the room's (2026-09-25): one dark piece, the film's still filling
   it with the title laid on the image, and a perforated stub on the right (Admit N, barcode). */
/* Pinned, not stretched (owner, 2026-10-02: "Half ticket stub isn't rendering"): Safari does not
   stretch flex items inside a <button>, so the stub stopped partway down and the still ended above
   the last row. The still, its shade and the stub hang off the ticket's own edges instead. */
.tkt { position: relative; display: block; width: 100%; appearance: none; padding: 0 54px 0 0; margin: 0; text-align: left; cursor: pointer;
  border: 1px solid var(--line); border-radius: var(--radius-field); background: var(--panel); color: var(--ink); overflow: hidden;
  animation: tnPrint .42s cubic-bezier(.2, .9, .25, 1.06) both; }
.tkt-main { position: static; display: flex; min-width: 0; min-height: 260px; flex-direction: column; justify-content: flex-end; }
.tkt-img { position: absolute; top: 0; left: 0; bottom: 0; width: calc(100% - 54px); height: 100%; object-fit: cover; object-position: 50% 25%; filter: var(--grade);
  opacity: 0; transition: opacity .35s ease; }
.tkt-img.on { opacity: 1; }
/* Darker from the top and sooner, with a soft shadow on the words: "Now showing", the date and the
   title were hard to read on a light or busy still (owner-approved mockup A, 2026-09-30). */
.tkt-main::after { content: ""; position: absolute; top: 0; left: 0; bottom: 0; right: 54px; background: linear-gradient(180deg, rgba(11,11,13,.38) 0%, rgba(11,11,13,.74) 30%, rgba(11,11,13,.97) 70%); }
.tkt-eyebrow, .tkt-date, .tkt-title, .tkt-lane, .tkt-meta { text-shadow: 0 1px 3px rgba(0,0,0,.85), 0 0 14px rgba(0,0,0,.5); }
.tkt-body { position: relative; z-index: 1; display: flex; flex-direction: column; padding: 16px; }
.tkt-eyebrow { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .16em; text-transform: uppercase; font-weight: 700; color: var(--accent-2); }
.tkt-date { font-size: var(--fs-label); color: rgba(239,232,218,.82); margin-top: 2px; }
.tkt-title { font-family: var(--serif); font-size: var(--fs-title); font-weight: 600; line-height: 1.05; margin: 6px 0 2px; text-wrap: balance; }
.tkt-tags { margin: 6px 0 2px; }
.tkt-meta { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; font-size: var(--fs-meta); color: var(--muted); margin-top: 6px; }
.tkt-meta b { color: var(--ink); font-weight: 700; white-space: nowrap; animation: tkStamp .3s ease-out .34s both; }
@keyframes tkStamp { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
.tkt .mnr-tw { justify-content: flex-start; }
.tkt-stub { position: absolute; top: 0; right: 0; bottom: 0; width: 54px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; border-left: 2px dashed var(--line-2); }
/* The perforation's notches, punched through the top and bottom edge. */
.tkt-stub::before, .tkt-stub::after { content: ""; position: absolute; left: -9px; width: 16px; height: 16px; border-radius: 50%; background: var(--bg); border: 1px solid var(--line); }
.tkt-stub::before { top: -9px; } .tkt-stub::after { bottom: -9px; }
.tkt-adm { writing-mode: vertical-rl; transform: rotate(180deg); font-family: var(--label); font-size: var(--fs-label); letter-spacing: .2em; text-transform: uppercase; font-weight: 700; color: var(--muted); }
.tkt-bc { width: 20px; height: 60px; opacity: .6; background: repeating-linear-gradient(0deg, var(--ink) 0 2px, transparent 2px 4px, var(--ink) 4px 5px, transparent 5px 8px); }
/* The stub is the red part of the ticket: the brand's deep red (the share card's spine), with the
   word and the barcode in cream on it. */
.tkt-stub { background: var(--shadow); border-left-color: rgba(239,232,218,.45); }
.tkt-adm { color: var(--ink); }
.tkt-bc { opacity: .75; }
@media (prefers-reduced-motion: reduce) { .tkt, .tkt-meta b { animation: none; } }


/* Group Film DNA heading: the explainer lives behind the shared (i) pop (SectionInfo). The heading
   is centred, so the pop sets its own alignment, like the profile's. */
.gpage-dna-h { display: flex; align-items: center; justify-content: center; gap: 8px; text-align: center; }
.gpage-dna-h .sec-info-pop { text-align: left; }
.gpage-dna-h .sec-info-pop b { color: var(--ink); font-weight: 600; }

/* Share, the third button in the row under the ticket: square, icon only, same outline. */
.tn-decide .tn-share { flex: 0 0 46px; height: 46px; display: grid; place-items: center; appearance: none; cursor: pointer; font-size: var(--fs-card); padding: 0; }
.tn-decide:has(.tn-share) .tn-ticket-trailer, .tn-decide:has(.tn-share) .thx-spin { flex: 1 1 0; }

/* "Not interested", asked the first few times (HideAsk.tsx): the app's sheet, a serif title like
   the drawers', the Browse checkbox, and the two buttons side by side. */
/* Above the reels (120) and film sheets (1000) it is opened from; below the toasts (2000). */
.hideask-overlay { z-index: 1500; }
.hideask-h { font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; color: var(--ink); letter-spacing: -.01em; line-height: 1.2; padding-right: var(--sp-16); }
.hideask-p { font-size: var(--fs-meta); line-height: 1.5; color: var(--muted); margin: 8px 0 14px; }
.hideask-check { display: flex; align-items: center; gap: 10px; margin-bottom: var(--sp-16); }
.hideask-actions { display: flex; gap: 10px; }
.hideask-actions .btn { flex: 1; }
/* Settings → Hidden films: the Blocked accounts row with a small poster. */
.pm-hidden-poster { width: 34px; aspect-ratio: 2 / 3; object-fit: cover; border-radius: 4px; flex: 0 0 auto; background: var(--panel-2); }
.pm-hidden-year { color: var(--muted); }
/* On a hidden film's sheet: one quiet line with the way back. */



/* The (i) under the archetype: a row per bar segment, keyed to its colour, with the reason, then
   the big lanes that did not make the header. */
/* How you got <archetype> (owner, 2026-09-29: "kinda ugly and a lot to read"): three rows you can
   scan, each a name with its role as a chip, what the archetype is, and a few words on why, ticked. */
.arch-why { display: flex; flex-direction: column; }
.arch-why-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.arch-why-row { display: flex; align-items: stretch; gap: 12px; padding: 12px 14px 12px 12px; border: 1px solid var(--line); border-radius: 12px; background: rgba(255,255,255,.025); }
.arch-why-row.is-lead { border-color: var(--line-2); background: rgba(255,255,255,.05); }
.arch-why-body { display: flex; flex-direction: column; gap: 4px; min-width: 0; flex: 1; }
.arch-why-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.arch-why-name { font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; line-height: 1.15; color: var(--ink); }
.arch-why-role { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .12em; text-transform: uppercase; font-weight: 700; color: var(--muted);
  white-space: nowrap; padding: 4px 8px; border-radius: 999px; border: 1px solid var(--line-2); }
.arch-why-row.is-lead .arch-why-role { color: var(--bg); background: var(--accent-2); border-color: var(--accent-2); }
.arch-why-reason { display: flex; align-items: center; gap: 7px; font-size: var(--fs-meta); line-height: 1.35; color: var(--ink); font-weight: 600; margin-top: 2px; }
.arch-why-tick { flex: none; width: 17px; height: 17px; border-radius: 50%; display: grid; place-items: center; font-size: 10px; font-weight: 800; /* type scale exception: initials or a glyph in a fixed box */
  color: var(--accent-2); background: rgba(111,147,196,.18); }
.arch-why-also { margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--line); }
.arch-why-also p { margin: 4px 0 0; font-size: var(--fs-meta); line-height: 1.45; color: var(--muted); }

/* ── Profile list sections with pictures (deepest cut, hot takes, people), in the profile's own
   language: flat on the panel, hairline keylines, small square corners, posters and faces in the
   print grade, labels in tracked caps, the viewer's theme colour for "you". No haze, no pills. ── */
.deepcut-t { font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; line-height: 1.1; letter-spacing: -.01em; color: var(--ink); }
.deepcut-m { font-size: var(--fs-meta); color: var(--faint); margin-top: 5px; }
/* The reason it is the deepest cut (rule 705), in the reading voice. */
.deepcut-why { margin: var(--sp-8) 0 0; font-family: var(--read); font-size: var(--fs-ui); line-height: 1.5; color: var(--muted); }
.deepcut-pills { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; }
.pill-you, .pill-note { font-family: var(--sans); font-size: var(--fs-label); letter-spacing: 0; text-transform: none; font-weight: 600;
  border: 1px solid var(--line-2); border-radius: 2px; padding: 5px 9px; background: none; }
.pill-you { color: var(--ink); }
.pill-you i { font-style: normal; color: var(--you); margin-left: 4px; }
.pill-note { color: var(--faint); }

.takes-row { display: flex; gap: 10px; overflow-x: auto; margin-top: 4px; padding-bottom: 2px; scrollbar-width: none; }
.takes-row::-webkit-scrollbar { display: none; }
.take { flex: 0 0 100px; width: 100px; padding: 0; border: 0; background: none; cursor: pointer; text-align: left; color: inherit; font: inherit; }
.take-poster { display: block; width: 100px; aspect-ratio: 2 / 3; object-fit: cover; border-radius: var(--radius-sm); border: 1px solid var(--line-2);
  filter: var(--grade); background: var(--panel-2); transition: border-color var(--dur) var(--ease); }
.take:hover .take-poster { border-color: var(--ink); }
.take:focus-visible .take-poster { outline: 2px solid var(--accent); outline-offset: 2px; }
.take-poster-empty { display: flex; align-items: center; justify-content: center; padding: 8px; text-align: center; }
.take-poster-empty span { font-size: var(--fs-label); line-height: 1.25; color: var(--faint); }
.gap { display: block; margin-top: 10px; }
.gap-track { position: relative; display: block; height: 9px; }
.gap-track::before { content: ""; position: absolute; left: 0; right: 0; top: 4px; height: 1px; background: var(--line-2); }
.gap-span { position: absolute; top: 4px; height: 1px; background: var(--you); }
.gap-dot { position: absolute; top: 1px; width: 7px; height: 7px; margin-left: -3.5px; }
.gap-most { background: var(--bg); border: 1px solid var(--faint); }
.gap-you { background: var(--you); }
.gap-k { display: flex; flex-direction: column; gap: 3px; margin-top: 7px; white-space: nowrap; line-height: 1.2;
  font-family: var(--label); font-size: var(--fs-label); letter-spacing: .12em; text-transform: uppercase; font-weight: 600; }
.gap-k b { color: var(--you); font-weight: 600; max-width: 100%; overflow: hidden; text-overflow: ellipsis; }
.gap-k span { color: var(--faint); }

.faces-row { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px; margin: var(--sp-4) 0 var(--sp-16); }
.face { display: flex; flex-direction: column; min-width: 0; text-decoration: none; color: inherit; }
.face .headshot { width: 100%; height: auto; aspect-ratio: 1; }
.face:hover .headshot { border-color: var(--ink); }
.face-n { font-size: var(--fs-meta); color: var(--ink); margin-top: 8px; line-height: 1.25; }
.face:hover .face-n { color: var(--accent-2); }
.face-c { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .12em; text-transform: uppercase; font-weight: 600; color: var(--faint); margin-top: 4px; }
.headshot { width: 72px; height: 72px; border-radius: var(--radius-sm); object-fit: cover; object-position: center 22%; border: 1px solid var(--line-2);
  filter: var(--grade); flex: none; background: var(--panel-2); transition: border-color var(--dur) var(--ease); }
/* No photo: the initial tile every avatar in the app uses (.hero-avatar, .friend-av). */
.headshot-empty { display: inline-flex; align-items: center; justify-content: center; filter: none;
  background: linear-gradient(155deg, var(--accent), var(--accent-2)); color: var(--bg); font-family: var(--serif); font-weight: 600; font-size: var(--fs-heading); }
.headshot-sm { width: 26px; height: 26px; font-size: var(--fs-meta); border-radius: 2px; }
.cast-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px; }
.cast-chip { display: inline-flex; align-items: center; gap: 8px; padding: 3px 10px 3px 3px; border-radius: 2px; border: 1px solid var(--line-2);
  font-size: var(--fs-meta); color: var(--ink); text-decoration: none; transition: border-color var(--dur) var(--ease); }
.cast-chip:hover { border-color: var(--ink); }
@media (max-width: 520px) {
  .faces-row { gap: 8px; }
  .face-n { font-size: var(--fs-label); }
  .face-c { font-size: var(--fs-label); letter-spacing: .08em; }
  .deepcut-t { font-size: var(--fs-heading); }
}


/* ── Decades watched: a share on every bar; a tapped (or hovered) bar's count in a small label over it. ── */
.decades-tile { display: flex; flex-direction: column; }
/* The count label (owner, 2026-11-06): one at a time, over its bar, muted with the number in ink. */
.dec-tip-row { position: relative; height: 18px; margin: 0 0 4px; }
.dec-tip { position: absolute; top: 0; white-space: nowrap; font-family: var(--label); font-size: var(--fs-label); font-weight: 500; letter-spacing: 0; color: var(--muted); font-variant-numeric: tabular-nums; }
.dec-tip b { color: var(--ink); font-weight: 600; }
.decades-tile .decades { height: 104px; gap: 5px; margin-top: auto; }
.decades-tile .decade-col { padding: 0; border: 0; background: none; font: inherit; color: inherit; cursor: pointer; gap: 5px; min-width: 0; }
.decades-tile .decade-val { opacity: 1; transform: none; font-family: var(--label); font-size: var(--fs-label); font-weight: 600; letter-spacing: .02em; color: var(--faint); }
.decades-tile .decade-bar { border-radius: 1px; background: var(--line-2); min-height: 2px; transition: background var(--dur) var(--ease); }
@media (hover: hover) { .decades-tile .decade-col:hover .decade-bar { background: var(--muted); } }
/* A tap leaves no hover behind on a touch screen: only the tapped bar is lit. */
@media (hover: none) { .decades-tile .decade-col:hover:not(.peak):not(.on) .decade-bar { background: var(--line-2); } }
.decades-tile .decade-col.peak .decade-bar { background: var(--you); }
.decades-tile .decade-col.on:not(.peak) .decade-bar { background: var(--ink); }
.decades-tile .decade-col.on .decade-val, .decades-tile .decade-col.on .decade-k { color: var(--ink); }
.decades-tile .decade-k { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .06em; text-transform: uppercase; color: var(--faint); white-space: nowrap; }
.decades-tile .decade-col:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
@media (max-width: 520px) {
  .decades-tile .decades { gap: 3px; }
  .decades-tile .decade-val { font-size: var(--fs-label); letter-spacing: 0; }
  .decades-tile .decade-k { font-size: var(--fs-label); letter-spacing: 0; }
}
/* One baseline, one-line labels, a value riding each bar (owner, 2026-11-03; rule 702): every bar
   grows up from the bottom of a fixed track, the % sits just above its own bar, and the label under
   it is "90s" or "2000s" on one line (lib/decades.ts), never uppercased or wrapped. */
.decades-tile .decades { align-items: stretch; height: 132px; gap: 0; }
.decades-tile .decade-col { min-height: 44px; }
.decades-tile .decade-track { padding-left: 2.5px; padding-right: 2.5px; }
.decades-tile .decade-col { justify-content: flex-start; height: 100%; }
.decades-tile .decade-track { flex: 1; min-height: 0; width: 100%; display: flex; flex-direction: column; justify-content: flex-end; padding-top: var(--sp-16); }
.decades-tile .decade-bar { position: relative; flex: none; }
.decades-tile .decade-val { position: absolute; left: -4px; right: -4px; bottom: calc(100% + 3px); text-align: center; white-space: nowrap; letter-spacing: 0; font-variant-numeric: tabular-nums; }
.decades-tile .decade-k { flex: none; text-transform: none; letter-spacing: 0; overflow: hidden; text-overflow: clip; max-width: 100%; }

/* ── Why you enjoyed it: across the row, posters on the left, the reading on the right; the same
   flat keylined look as the tiles above (no blue wash). ── */
.wl-empty { margin: 0; font-size: var(--fs-meta); color: var(--faint); line-height: 1.5; }
.wl-traits { list-style: none; margin: 0 0 14px; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.wl-traits .wl-trait { display: grid; grid-template-columns: minmax(0, 1fr) 110px 128px; align-items: center; gap: 12px; padding: 0; border-radius: 0; background: none; font-size: var(--fs-meta); color: var(--ink); }
.wl-trait-n { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wl-trait-bar { position: relative; height: 1px; background: var(--line-2); }
.wl-trait-bar i { position: absolute; left: 0; top: -1px; height: 3px; background: var(--you); }
.wl-trait-p { text-align: right; font-family: var(--label); font-size: var(--fs-label); letter-spacing: .12em; text-transform: uppercase; font-weight: 600; color: var(--faint); white-space: nowrap; }
@media (max-width: 760px) {
  .wl-traits .wl-trait { grid-template-columns: minmax(0, 1fr) 48px 112px; gap: 10px; }
}

/* Hot takes: the four biggest gaps in a fixed four-up grid that fills the tile (no poster cut off
   at the edge), centred in whatever height its row gives it beside people. */
.hot-tile { display: flex; flex-direction: column; }
.hot-tile .takes-row { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; overflow: visible; margin: auto 0; padding: 6px 0 4px; }
.hot-tile .take { width: auto; min-width: 0; }
.hot-tile .take-poster { width: 100%; }
@media (max-width: 520px) {
  .hot-tile .takes-row { gap: 8px; }
  .hot-tile .gap-k { font-size: var(--fs-label); letter-spacing: .08em; }
}

/* The archetype's ⓘ as a centred panel: wide enough for a lane and its reason on one line, and
   above every section so nothing paints over it. Phones get it near full width. */
.info-modal-overlay { align-items: center; padding: var(--sp-24) var(--sp-16); }
.info-modal { position: relative; width: min(560px, 100%); max-height: calc(100dvh - 40px); overflow-y: auto;
  background: var(--panel); border: 1px solid var(--line-2); border-radius: var(--radius); padding: var(--sp-24) var(--sp-24) var(--sp-24);
  box-shadow: var(--shadow-offset); animation: sec-info-pop-in .18s ease; }
@keyframes sec-info-pop-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
.info-modal-hd { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 6px; }
.info-modal-hd .sec-info-pop-title { margin: 0; }
.info-modal .arch-why-name { font-size: var(--fs-card); }
.info-modal .arch-why-reason, .info-modal .arch-why-also p { font-size: var(--fs-ui); }
@media (max-width: 520px) { .info-modal { padding: var(--sp-16) var(--sp-16) var(--sp-16); } }


/* ── Group page, in the profile's look: serif name, square keylined member avatars, the report as
   an archetype card (crimson spine, left-aligned, the name at the archetype's size), shared
   shelves as a list with how many share each, the split as two plain rows, the Group Film DNA
   in a keylined panel under a quiet label. ── */
.gpage-head .gpage-name { font-family: var(--serif); font-weight: 600; letter-spacing: -.015em; }
.gpage-photo { border-radius: var(--radius-sm); border-color: var(--ink); }
.gpage-avatars { gap: 10px; }
.gpage-av { border-radius: var(--radius-sm); border: 1px solid var(--line-2); box-shadow: 0 0 0 2px var(--bg); font-family: var(--serif); font-size: var(--fs-meta); color: var(--bg);
  background: linear-gradient(155deg, var(--accent), var(--accent-2)); }
.gpage-av:nth-child(even) { background: linear-gradient(155deg, var(--accent), var(--accent-2)); }
.gpage-av-more { background: var(--panel-2); color: var(--muted); font-family: var(--label); font-size: var(--fs-label); }
.gpage-avatars:hover .gpage-av { border-color: var(--ink); }
.gpage-av-count { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; font-weight: 600; color: var(--faint); white-space: nowrap; }
.gpage-avatars:hover .gpage-av-count { color: var(--ink); }

.grp-hero { position: relative; overflow: hidden; margin: var(--sp-16) 0 14px; padding: var(--sp-24) 30px var(--sp-24) 44px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--bg); text-align: left; }
.grp-hero::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 14px; background: var(--shadow); }
.grp-hero-eyebrow { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; font-weight: 600; color: var(--eyebrow); }
.grp-hero-arche { font-family: var(--serif); font-size: min(var(--fs-display), 10vw); line-height: 1.04; font-weight: 600; letter-spacing: -.015em; color: var(--ink); margin: 10px 0 12px; }
.grp-hero-why { margin: 0; max-width: 62ch; font-size: var(--fs-ui); line-height: 1.6; color: var(--muted); }
.grp-hero-cols { display: grid; grid-template-columns: minmax(0, 3fr) minmax(0, 2fr); gap: var(--sp-24); margin-top: var(--sp-24); padding-top: var(--sp-24); border-top: 1px solid var(--line); }
.grp-hero-cols > .grp-hero-col:only-child { grid-column: 1 / -1; }
.grp-hero-h { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; font-weight: 600; color: var(--faint); margin-bottom: 8px; }
.grp-shelf-count { display: inline-flex; align-items: center; gap: 8px; flex: none; font-family: var(--sans); font-size: var(--fs-label); letter-spacing: 0; text-transform: none; font-weight: 500; color: var(--faint); white-space: nowrap; }
.grp-split-name { display: inline-block; font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; line-height: 1.2; color: var(--ink); text-decoration: none; margin: 2px 0 12px; }
.grp-split-name:hover { color: var(--accent-2); }
.grp-split-rows { display: flex; flex-direction: column; gap: 8px; }
.grp-split-row { display: flex; align-items: baseline; flex-wrap: wrap; gap: 4px 8px; font-size: var(--fs-meta); color: var(--muted); line-height: 1.4; }
.grp-split-row b { color: var(--ink); font-weight: 600; }
.grp-split-dir { font-size: var(--fs-label); color: var(--faint); width: 10px; }
.grp-split-dir.up { color: var(--you); }

.gpage-radar { margin: 0 0 14px; padding: var(--sp-24) var(--sp-24) var(--sp-16); border: 1px solid var(--line-2); border-radius: var(--radius); background: var(--panel); }
.gpage-dna-h { justify-content: flex-start; font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; font-weight: 600; color: var(--eyebrow); }
@media (max-width: 640px) {
  .grp-hero { padding: var(--sp-24) var(--sp-16) var(--sp-24) 30px; }
  .grp-hero::before { width: 10px; }
  .grp-hero-cols { grid-template-columns: minmax(0, 1fr); gap: var(--sp-24); }
  .gpage-av-count { display: none; }
  .gpage-radar { padding: var(--sp-16) 14px 14px; }
}

/* ── Group feed, same look: the week as a card with the spine, superlatives as tiles (role in
   caps, the handle large, the receipt under a quiet toggle, no medals), recent logs as rows with a
   keylined poster, the title in serif and square reaction chips. ── */
.grp-week { position: relative; overflow: hidden; margin: var(--sp-16) 0 6px; padding: var(--sp-24) var(--sp-24) var(--sp-24) var(--sp-40); border: 1px solid var(--line); border-radius: var(--radius); background: var(--bg); }
.grp-week::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 10px; background: var(--shadow); }
.grp-week-row { display: flex; align-items: baseline; gap: 10px; margin-top: 6px; }
.grp-week-n { font-family: var(--ui); font-size: var(--fs-display); font-weight: 600; line-height: 1; color: var(--ink); font-variant-numeric: tabular-nums; }
.grp-week-k { font-family: var(--serif); font-size: var(--fs-heading); color: var(--ink); }
.grp-week-cap { margin: 10px 0 0; color: var(--muted); font-size: var(--fs-ui); line-height: 1.55; max-width: 62ch; }
/* Section titles in the serif with the subtitle under them and a hairline above, like "Our taste"
   (owner-approved mockup A, 2026-09-30: headers and dividers "could look better"). */
.gpage .grp-section-h { font-family: var(--serif); font-size: var(--fs-heading); letter-spacing: -.01em; text-transform: none; font-weight: 600; color: var(--ink);
  line-height: 1.15; margin: 30px 0 14px; padding-top: 24px; border-top: 1px solid var(--line); gap: 4px; }
.gpage .grp-section-h small { margin-left: 0; font-size: var(--fs-meta); font-weight: 400; color: var(--faint); }
.gpage .grp-sups { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; align-items: start; }
.gpage .grp-sup { background: var(--panel); border: 1px solid var(--line-2); border-radius: var(--radius); transform: none; }
.gpage .grp-sup:hover { border-color: var(--ink); transform: none; }
.gpage .grp-sup.open { border-color: var(--ink); }
.gpage .grp-sup::before { display: none; }
.gpage .grp-sup-hd { display: flex; flex-direction: column; align-items: flex-start; gap: 4px; padding: var(--sp-16) var(--sp-16) 14px; }
.gpage .grp-sup-medal { display: none; }
.gpage .grp-sup-tt { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; font-weight: 600; color: var(--accent-2); line-height: 1.3; }
.gpage .grp-sup-who { margin: 0; text-align: left; font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; color: var(--ink); line-height: 1.2; overflow-wrap: anywhere; }
.gpage .grp-sup-who .n { font-family: var(--sans); font-size: var(--fs-meta); font-weight: 400; color: var(--faint); }
.gpage .grp-sup-dd { font-size: var(--fs-meta); color: var(--muted); margin: 0; }
.gpage .grp-sup-caret { margin: 6px 0 0; transform: none; font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; font-weight: 600; color: var(--faint); }
.gpage .grp-sup.open .grp-sup-caret { transform: none; color: var(--ink); }
.gpage .grp-sup-body { padding: 0 var(--sp-16); }
.gpage .grp-sup.open .grp-sup-body { max-height: 400px; padding-bottom: 16px; }
.gpage .grp-sup-receipt { font-size: var(--fs-meta); color: var(--muted); line-height: 1.5; border-top: 1px solid var(--line); padding: 10px 0 0; background: none; border-radius: 0; margin: 0; }
.gpage .grp-sup-rx { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; padding: 0; } /* the 54px indent was for the old medal; the tile has none */
.gpage .grp-sup-rx button, .gpage .react-btn { border: 1px solid var(--line-2); border-radius: 2px; background: none; padding: 3px 8px; font-size: var(--fs-meta); color: var(--muted); }
.gpage .grp-sup-rx button.on, .gpage .react-btn.on { background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); color: var(--ink); }
.gpage .comm-feed-film { font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; color: var(--ink); margin-top: 2px; }
.gpage .comm-feed-film .yr { font-family: var(--sans); font-size: var(--fs-meta); font-weight: 400; color: var(--faint); margin-left: 6px; }
@media (max-width: 640px) {
  .gpage .grp-sups { grid-template-columns: minmax(0, 1fr); }
  .grp-week { padding: var(--sp-16) var(--sp-16) var(--sp-16) var(--sp-24); }
}

/* ── The group-list film as a centred popup in the profile's look: the poster keylined with the
   offset shadow beside the serif title, then the read, everyone's line, and what to watch next. ── */
.modal.gwl-modal { max-width: 620px; background: var(--panel); border: 1px solid var(--line-2); box-shadow: var(--shadow-offset); }
.gwl-modal .modal-hd { margin-bottom: 0; }
.gwl-modal .gwl-tag { margin: var(--sp-24) 0 var(--sp-8); font-size: var(--fs-label); }
.gwl-modal .gwl-tag i { display: none; }
.gwl-modal .gwl-chip { font-family: var(--sans); font-size: var(--fs-label); letter-spacing: 0; text-transform: none; font-weight: 600; border-radius: 2px; background: none; padding: 4px 8px; }
.gwl-modal .act-foryou b { color: var(--you); }
.gwl-modal .gwl-why-open { margin-top: 16px; border-radius: var(--radius-sm); }

/* Who shares a shelf: their faces, small keylined squares overlapping like the header's. */
.grp-shelf-faces { display: inline-flex; }
.grp-shelf-faces img, .grp-shelf-faces span { position: relative; width: 22px; height: 22px; border-radius: var(--radius-sm); border: 1px solid var(--line-2); box-shadow: 0 0 0 2px var(--bg); object-fit: cover; }
.grp-shelf-faces > * + * { margin-left: -5px; }
.grp-shelf-faces span { display: inline-flex; align-items: center; justify-content: center; font-family: var(--serif); font-size: var(--fs-label); font-weight: 600; letter-spacing: 0; color: var(--bg); background: linear-gradient(155deg, var(--accent), var(--accent-2)); }

/* The room's link, labelled as the way in for people not on Montage (the + seat adds friends). */
.mnr-link-h { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; font-weight: 600; color: var(--faint); margin: var(--sp-16) 0 var(--sp-8); }

/* Group picks on Tonight's ticket: under the stamp, each member's own match and who it is for. */
.grp-tkt-for { font-size: var(--fs-meta); color: rgba(239,232,218,.8); }
/* Directors like this one: square keylined faces in a row that scrolls on a phone. */
/* Label above the row, left-aligned, not floated mid-height beside it. */
.tp-neighbours.tp-similar { flex-direction: column; align-items: flex-start; gap: 10px; margin-top: var(--sp-16); }
.tp-similar-row { display: flex; gap: 10px; max-width: 100%; overflow-x: auto; padding-bottom: 4px; scrollbar-width: none; }
.tp-similar-row::-webkit-scrollbar { display: none; }
.tp-similar-face { flex: 0 0 76px; display: flex; flex-direction: column; gap: 6px; text-decoration: none; color: var(--ink); }
.tp-similar-face img, .tp-similar-ph { width: 76px; height: 76px; object-fit: cover; object-position: center 22%; border: 1px solid var(--line-2); border-radius: var(--radius-sm); filter: var(--grade); transition: border-color var(--dur) var(--ease); }
.tp-similar-face:hover img, .tp-similar-face:hover .tp-similar-ph { border-color: var(--ink); }
.tp-similar-ph { display: flex; align-items: center; justify-content: center; filter: none; background: linear-gradient(155deg, var(--accent), var(--accent-2)); color: var(--bg); font-family: var(--serif); font-weight: 600; font-size: var(--fs-heading); }
.tp-similar-n { font-size: var(--fs-label); line-height: 1.25; color: var(--muted); }
.tp-similar-face:hover .tp-similar-n { color: var(--accent-2); }

/* The film sheet's watch log (FilmActions): "Watched it Today / Before" after a first rating, and
   "Seen N times · ↻ Watched again" on a film already seen. One quiet line under the stars. */
/* Watches on the film sheet (FilmActions): the one-time "When did you watch it?", then one line
   with the count and last date, "+ Log a watch", and the list the count opens. */
.fa-ask { margin: 12px 0; padding: 12px; border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--panel); }
.fa-ask-q { font-size: var(--fs-meta); color: var(--ink); margin-bottom: 9px; }
.fa-ask-chips { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.fa-chip { appearance: none; cursor: pointer; font: inherit; font-family: var(--label); font-size: var(--fs-meta); font-weight: 600; padding: 7px 12px;
  border: 1px solid var(--line-2); border-radius: 999px; background: none; color: var(--ink); }
.fa-chip:hover { border-color: var(--ink); }
.fa-chip.on { background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); color: var(--ink); }
.fa-chip.ghost { border-color: transparent; color: var(--faint); }
.fa-date { font: inherit; font-size: var(--fs-meta); padding: 6px 10px; border: 1px solid var(--line-2); border-radius: var(--radius-sm); background: var(--bg); color: var(--ink); color-scheme: dark; }
/* "Pick a date" (rule 1096): a chip like its neighbours, the native input invisible over it. */
.fa-date-chip { position: relative; display: inline-flex; align-items: center; overflow: hidden; }
.fa-date-chip.is-off { opacity: .5; }
.fa-date-native { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; padding: 0; border: 0; opacity: 0; cursor: pointer;
  font-size: var(--fs-read); /* 16: no zoom on focus in iOS Safari */ -webkit-appearance: none; appearance: none; color-scheme: dark; }
.fa-watches { display: flex; align-items: center; gap: 10px; margin: 10px 0 12px; font-size: var(--fs-meta); color: var(--muted); }

/* Movie night, live: who has the room open, what just happened, and whose votes sit where.
   Green appears nowhere else in the app; it means one thing here, "the room is open on their
   screen now", so it is scoped to the room rather than added to :root. */
.mnr { --mnr-live: #5fbf7a; }
.mnr-live { position: absolute; left: -4px; bottom: -4px; width: 12px; height: 12px; border-radius: 50%; background: var(--mnr-live); border: 2px solid var(--bg); }
.mnr-seat-away { width: auto; min-width: 54px; }
.mnr-seat-away .mnr-seat-av { opacity: .45; }
.mnr-seat-away .mnr-seat-name { max-width: 84px; color: var(--faint); }
/* Voter faces: small overlapping rounded squares (one avatar shape, owner 2026-09-30). */
.mnr-faces { display: inline-flex; align-items: center; }
.mnr-faces > * + * { margin-left: -6px; }
.mnr-face { width: 22px; height: 22px; border-radius: var(--radius-sm); display: inline-grid; place-items: center; object-fit: cover; flex: none;
  background: var(--accent-2); color: var(--bg); border: 2px solid var(--bg); font-family: var(--serif); font-size: var(--fs-label); font-weight: 600; line-height: 1; }
.mnr-alts .tn-gcard.mnr-voted:not(.on) .tn-gposter { outline: 2px solid var(--accent-2); outline-offset: 2px; }

/* Your movie nights (MovieNightHistory.tsx, Social -> People and a group's Watch tab): poster, the
   film in serif, room and date, who was there and the room's number; your stars or "Rate it". */
.mnh-rows { display: flex; flex-direction: column; margin: 10px 0 4px; }
.mnh-row { display: flex; align-items: center; gap: var(--sp-12); padding: var(--sp-12) var(--sp-4); border-bottom: 1px solid var(--line); }
.mnh-row:last-child { border-bottom: 0; }
.mnh-lead { flex: 1; min-width: 0; display: flex; align-items: center; gap: 14px; color: inherit; text-decoration: none; }
.mnh-poster { flex: 0 0 52px; width: 52px; height: 78px; object-fit: cover; border-radius: var(--radius-sm); border: 1px solid var(--line-2); filter: var(--grade); background: var(--panel); }
.mnh-poster-ph { display: inline-flex; align-items: center; justify-content: center; filter: none; font-family: var(--serif); font-size: var(--fs-card); color: var(--accent-2); }
.mnh-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.mnh-title { font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; line-height: 1.2; color: var(--ink); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mnh-lead:hover .mnh-title { color: var(--accent-2); }
.mnh-sub { font-size: var(--fs-meta); color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mnh-who { display: flex; align-items: center; gap: var(--sp-8); margin-top: 3px; font-size: var(--fs-meta); color: var(--muted); }
.mnh-faces img, .mnh-faces span { border-radius: var(--radius-sm); }
.mnh-aside { flex: none; display: flex; align-items: center; }
.mnh-mine { font-size: var(--fs-meta); color: var(--muted); white-space: nowrap; }
.mnh-rate { color: var(--accent-2); font-weight: 600; font-size: var(--fs-meta); }
.mnh-more { color: var(--muted); font-size: var(--fs-meta); font-weight: 600; margin: var(--sp-4) var(--sp-4) 0; }
.mnh-note { font-size: var(--fs-meta); color: var(--faint); margin: var(--sp-12) var(--sp-4) 0; }

/* The "is decided" row in Activity leads with the film's poster, portrait, in the avatar's place. */
.act-av.act-poster { height: 62px; border-radius: 3px; filter: var(--grade); }

/* The archetype sheet: each name's one-line meaning under it, and a readable way in ("How you got
   Hardboiled ›") where a 14px (i) was easy to miss. */
.sec-info-link { font-size: var(--fs-meta); font-weight: 600; color: var(--muted); padding: 6px 0; }

/* Tonight with no film for every filter at once: the filters as chips to drop one at a time. */
.tn-loosen { display: flex; flex-direction: column; gap: 10px; margin-top: 12px; }
.tn-loosen .linkbtn { align-self: flex-start; color: var(--muted); font-weight: 600; }

/* Settings → Suggestions switches, the Browse checkbox row in the drawer's list rhythm. */
.pm-pref { display: flex; align-items: center; gap: 10px; padding: 10px 4px; border-bottom: 1px solid var(--line); font-size: var(--fs-ui); }
.pm-avoid-head { width: 100%; background: none; border-top: 0; border-left: 0; border-right: 0; color: inherit; font: inherit; font-size: var(--fs-ui); text-align: left; cursor: pointer; }
.pm-avoid-head > span:first-child { flex: 1; }
.pm-avoid-count { font-size: var(--fs-meta); color: var(--muted); }
/* Settings: one left edge and one right edge for every header and row (owner, 2026-09-30), the
   12px the Account rows (.pm-item) already sit on. */
.pm-settings .pm-settings-h, .pm-settings .pm-settings-row, .pm-settings .pm-pref, .pm-settings .pm-avoid { padding-left: 12px; padding-right: 12px; }
.pm-settings .pm-pref .pm-settings-h { padding: 0; }
.pm-settings .pm-sec-head { padding-top: 14px; align-items: flex-start; }
.pm-settings .pm-sec-head > .pm-avoid-count, .pm-settings .pm-sec-head > .mood-disclosure-chev { padding-top: 1px; }
.pm-sec-copy { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.pm-sec-sub { font-size: var(--fs-meta); line-height: 1.4; color: var(--muted); }
/* Settings: the "rather avoid" content warnings as toggle chips (owner, 2026-09-29). */
.pm-avoid { display: flex; flex-wrap: wrap; gap: 8px; padding: 4px 4px 12px; border-bottom: 1px solid var(--line); }
.pm-avoid-chip { background: var(--bg); color: inherit; border: 1px solid var(--line); border-radius: 999px; padding: 6px 12px; font: inherit; font-size: var(--fs-meta); cursor: pointer; }
.pm-avoid-chip.on { background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); color: var(--ink); font-weight: 600; }

/* Movie nights history folds: the heading is the toggle, with the count and a chevron. */

/* Profile fold (2026-09-27): who you are stays open (archetype, defining films, tension, Film
   DNA); one dashed row under Film DNA opens the rest. The hint sits on its own line under the
   label. The tension alone takes the full width that the axes used to share. */
.hero-lower.hero-lower-one { grid-template-columns: 1fr; }
.profile-more { padding: 0 0 var(--sp-24); position: relative; z-index: 2; }
.profile-more-row { min-height: 44px; }
.profile-more-row:hover { color: var(--ink); }
.profile-more-hint { display: block; margin-top: 3px; }
/* An empty watchlist on Discover: one line, left where the ranked list will appear. */
.wl-empty-line { margin-top: var(--sp-24); }
@media (max-width: 760px) {
  .profile-more { padding: 0 0 24px; }
}

/* Room ticket chips: what the room asked for; faded where this film does not hit it. */
.mnr-tw .mnr-tw-k { font-size: var(--fs-meta); letter-spacing: 0; text-transform: none; color: var(--ink); opacity: .85; }

/* One muted line under a chip group saying how several picks combine ("any of these"). */
.mood-q-hint { font-size: var(--fs-meta); color: var(--muted); margin: -2px 0 10px; }

/* Browse: "Director or actor" (one person, their films only) */
.browse-person { position: relative; margin-top: 8px; }
.browse-person-input { background-image: none; cursor: text; padding-right: 11px; color: var(--ink); }
.browse-person-input::placeholder { color: var(--muted); }
.browse-person-list { position: absolute; z-index: 20; left: 0; right: 0; top: calc(100% + 4px); border: 1px solid var(--line-2); border-radius: var(--radius); background: var(--panel); padding: 6px; box-shadow: 0 10px 30px rgba(0,0,0,.4); }
.browse-person-opt { appearance: none; background: none; border: 0; font: inherit; font-size: var(--fs-ui); color: var(--ink); width: 100%; display: flex; justify-content: space-between; align-items: center; gap: 10px; padding: 9px 8px; border-radius: var(--radius-sm); cursor: pointer; text-align: left; }
.browse-person-opt:hover, .browse-person-opt:focus-visible { background: var(--line); }
.browse-person-kind { font-size: var(--fs-label); color: var(--muted); font-weight: 500; }
.browse-person-chip { display: flex; align-items: center; gap: 10px; border: 1px solid var(--line-2); border-radius: var(--radius); background: var(--panel); padding: 7px 8px 7px 11px; font-size: var(--fs-ui); font-weight: 600; }
.browse-person-chip a { color: var(--ink); text-decoration: none; flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.browse-person-x { appearance: none; background: none; border: 0; color: var(--muted); font-size: var(--fs-card); line-height: 1; cursor: pointer; padding: 0 4px; }

/* ---- People you follow, on the film sheet (FilmPeople.tsx) ---- */
/* Kept compact on purpose: one row of small faces and one line for Watch with. */
.fp-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 10px; }
.fp-head .tile-h { margin: 0; }
.fp-count { margin-left: 6px; font-weight: 500; letter-spacing: .04em; text-transform: none; color: var(--muted); }
/* Scoped to the row: .fp-name is also the friend preview's name (FriendPreview), and this rule
   shrank that one to 10.5px. Wide enough for a whole handle (it was cut at 50px: "jakelori…"). */
.fp-with { display: flex; align-items: center; gap: 8px; margin-top: 10px; font-size: var(--fs-meta); }
.fp-with .fp-av { flex: none; width: 22px; height: 22px; font-size: 10px; } /* type scale exception: initials or a glyph in a fixed box */
.fp-with .friend-av-img { object-fit: cover; }
.fp-with-also { color: var(--muted); }
/* A real button, not a link: the one action in this section. */
@media (max-width: 559px) {
  .fp-with { align-items: flex-start; }
  .fp-with-also { display: block; font-size: var(--fs-meta); }
}
/* Where to watch: rent/buy folded when there is something to stream. */
.fd-watch-fold { margin-top: 10px; }
.fd-watch-fold summary { list-style: none; cursor: pointer; font-size: var(--fs-meta); font-weight: 600; color: var(--muted); display: inline-flex; gap: 6px; align-items: center; }
.fd-watch-fold summary::-webkit-details-marker { display: none; }
.fd-watch-fold summary::after { content: "\25BE"; font-size: var(--fs-label); }
.fd-watch-fold[open] summary::after { content: "\25B4"; }
.fd-watch-fold summary:hover { color: var(--ink); }
.fd-watch-fold .fd-watch-chips { margin-top: 8px; }

/* A person without a photo in a feed row wears the Social tab's avatar (gradient, one initial),
   the same as the film sheet, the room and the People list; a poster-less film keeps .act-av. */
.act-av.friend-av { flex: 0 0 42px; width: 42px; height: 42px; font-size: var(--fs-read); }

/* ---- A film's series on its sheet (FilmSeries.tsx): one small row, nothing more ---- */
.fsr-head { margin-bottom: 10px; }
.fsr-head .tile-h { margin: 0; }
.fsr-count { margin-left: 8px; font-weight: 500; letter-spacing: .04em; text-transform: none; color: var(--muted); }
.fsr-row { display: flex; gap: 10px; overflow-x: auto; scrollbar-width: none; padding: 4px 3px 2px; margin: -4px -3px 0; }
.fsr-row::-webkit-scrollbar { display: none; }
.fsr-item { flex: 0 0 62px; min-width: 0; display: flex; flex-direction: column; gap: 4px; padding: 0; background: none; border: 0; color: inherit; font: inherit; text-align: left; cursor: pointer; }
.fsr-item.is-this { cursor: default; }
.fsr-poster { position: relative; display: block; width: 62px; height: 93px; border-radius: 3px; border: 1px solid var(--line-2); background: var(--panel-2); overflow: hidden; }
.fsr-poster img { width: 100%; height: 100%; object-fit: cover; filter: var(--grade); display: block; }
.fsr-item.is-this .fsr-poster { outline: 2px solid var(--ink); outline-offset: 1px; }
.fsr-item.is-next .fsr-poster { outline: 2px solid var(--accent-2); outline-offset: 1px; }
.fsr-item:not(.is-this):hover .fsr-poster { border-color: var(--ink); }
.fsr-next { position: absolute; left: 3px; top: 3px; font: 700 var(--fs-label)/1 var(--sans); letter-spacing: .1em; text-transform: uppercase; background: var(--accent-2); color: var(--bg); padding: 3px 4px; border-radius: 2px; }
.fsr-t { max-width: 62px; font-size: var(--fs-label); color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fsr-you { font-size: var(--fs-label); line-height: 1; color: var(--accent); white-space: nowrap; }
.fsr-seen { color: var(--faint); font-size: var(--fs-label); letter-spacing: .1em; text-transform: uppercase; }
.fsr-pct { font-size: 11px; font-weight: 600; color: var(--accent-2); }
.fsr-pct.low { color: var(--faint); font-weight: 500; }

/* A shared profile, signed out: the one clear way in */

/* First sign-in walkthrough (WelcomeTour) */
.wt-overlay { position: fixed; inset: 0; z-index: 1000; background: rgba(0,0,0,.6); display: flex; align-items: flex-end; justify-content: center; }
.wt-sheet { width: 100%; max-width: 440px; background: var(--panel); border: 1px solid var(--line-2); border-bottom: 0; border-radius: var(--radius-drawer) var(--radius-drawer) 0 0; padding: 22px 22px calc(26px + env(safe-area-inset-bottom)); }
@media (min-width: 700px) { .wt-overlay { align-items: center; } .wt-sheet { border-radius: var(--radius-drawer); border-bottom: 1px solid var(--line-2); } }
.wt-score { display: flex; flex-direction: column; align-items: center; }
.wt-score b { font-family: var(--serif); font-size: 44px; color: var(--ink); line-height: 1; } /* type scale exception: match % numerals */
.wt-score span { font-size: 13px; color: var(--accent-2); margin-top: 6px; }
.wt-title { font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; color: var(--ink); line-height: 1.2; margin: 0 0 8px; }
.wt-back, .wt-back-space { flex: 0 0 auto; min-width: 84px; }
/* A group down to one member (GroupPage `solo`): the report waits for a second member. */
.grp-solo { border: 1px solid var(--line-2); background: var(--panel); border-radius: var(--radius); padding: var(--sp-16) var(--sp-16) var(--sp-24); margin: 14px 0; text-align: center; }
.grp-solo-h { font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; color: var(--ink); margin: 6px 0 0; line-height: 1.2; }
.grp-solo-p { font-size: var(--fs-meta); color: var(--muted); line-height: 1.5; margin: 8px auto 0; max-width: 340px; }
.grp-solo-invite { margin-top: 16px; min-width: 200px; }
.wt-next { background: var(--accent-2); color: var(--bg); border: 0; border-radius: 999px; padding: 10px var(--sp-16); font: inherit; font-size: var(--fs-ui); font-weight: 600; cursor: pointer; }

/* Opening splash (Splash.tsx): the fan mark alone, then the app */
/* Installed on an iPhone the status bar is solid (layout.tsx, invariant 93), so the page starts
   under it and its middle sits half a status bar below the screen's: the splash logo read as low
   (owner, 2026-09-29). --chrome-lift is that half, and centred things subtract it. Not in Safari,
   where the page already runs under the status bar. */
@media (display-mode: standalone) { @supports (-webkit-touch-callout: none) { :root { --chrome-lift: 26px; } } }
.splash { position: fixed; inset: 0; z-index: 2000; background: var(--bg); display: flex; align-items: center; justify-content: center; opacity: 1; transition: opacity .2s ease;
  padding-bottom: calc(2 * var(--chrome-lift, 0px)); }
.splash.is-fading { opacity: 0; pointer-events: none; }
.splash[data-skip] { display: none; }
.splash-mark { animation: splash-in .2s ease-out both; }
@keyframes splash-in { from { opacity: 0; transform: scale(.94); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { .splash-mark { animation: none; } .splash { transition: none; } }

/* Social → People: a row of faces with Find people, one movie night block, the feed. The tab bar is
   the heading, with Invite at its right end (first-screen pass A, 2026-10-02). */
.subtabs-end { margin-left: auto; align-self: center; display: flex; align-items: center; gap: 4px; }
.subtabs-end .topicon { width: 32px; height: 32px; }
.people-h-acts { display: inline-flex; align-items: center; gap: 14px; }
.people-find svg { width: 15px; height: 15px; color: var(--accent-2); }
.people-search { margin: 0 0 14px; }
.people-search .ig-search { margin-top: 0; }
.people-side > .people-search:first-child { margin-top: 4px; }
/* The movie night is one block: the start row, then under a hairline the last night, in one card
   with the ink border and the oxblood offset. */
.mn-block { margin: 16px 0 4px; border: 1px solid var(--ink); border-radius: var(--radius); background: var(--bg); box-shadow: var(--shadow-offset); overflow: hidden; }
.mn-block .mn-tonight.dsc-tonight-cta { margin: 0; min-height: 52px; padding: 8px 14px; border: 0; border-radius: 0; box-shadow: none; background: none; }
.mn-block .people-mn-last .mnh-compact { margin: 0; padding: 0 14px; border-top: 1px solid var(--line); }
.mn-block .mnh-last { padding: 8px 0; }
.people-mn { margin-bottom: var(--sp-24); }
/* The feed's heading opens with a rule, as Discover's sections do. */
.circle-feed > .friend-section-h { border-top: 1px solid var(--line); padding: 14px 0 0 4px; margin: 0 0 6px; }
/* The tab bar is the heading now, so whatever leads the view sits right under it. */
.people-side > .people-mn:first-child, .people-side > .people-row-wrap:first-child { margin-top: 0; }
/* People is ONE column on every screen, the phone's order: movie night, your people, the feed
   (owner, 2026-10-02: "we want one single column"). The tab bar is its heading, so the first block
   sits 22px under it, the same as the space below the movie night card. */
.tabview:has(> .people-cols) { padding-top: 0; }
.people-row-wrap { margin: var(--sp-16) 0 var(--sp-24); }
.people-h-row { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.people-h { margin: 0; }
.people-row { display: flex; gap: 14px; overflow-x: auto; scrollbar-width: none; padding: 2px 2px 4px; }
.people-row::-webkit-scrollbar { display: none; }
.people-face { flex: 0 0 64px; display: flex; flex-direction: column; align-items: center; gap: 10px; background: none; border: 0; padding: 0; color: inherit; font: inherit; cursor: pointer; }
.people-av { position: relative; display: block; }
.people-av .friend-av { width: 58px; height: 58px; font-size: var(--fs-heading); }
.people-face.is-suggested .friend-av { outline: 1.5px dashed var(--line-2); outline-offset: 2px; opacity: .85; }
.people-pct { position: absolute; left: 50%; bottom: -7px; transform: translateX(-50%); background: var(--ink); color: var(--bg); font-size: 11px; font-weight: 700; padding: 1px 6px; border-radius: 6px; white-space: nowrap; }
.people-name { font-size: var(--fs-label); color: var(--muted); max-width: 64px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.people-face.is-suggested .people-name { color: var(--accent-2); }
.people-all { margin-top: 14px; }
.people-all-h { font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; color: var(--faint); margin: 14px 0 6px; }
.people-mn-last .mnh-compact { margin: 6px 0 var(--sp-24); padding: 0 2px; }
.mnh-last { display: flex; align-items: center; gap: 10px; width: 100%; padding: 10px 0; background: none; border: 0; color: var(--muted); font: inherit; font-size: var(--fs-meta); text-align: left; cursor: pointer; }
.mnh-last b { color: var(--ink); font-weight: 600; }
.mnh-last-poster { flex: none; width: 24px; height: 36px; border-radius: 3px; object-fit: cover; background: var(--panel-2); display: block; }
.mnh-last-text { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mnh-last-all { flex: none; color: var(--accent-2); font-weight: 600; }

/* The friend preview's own head. The film sheet's "People you follow" row (FilmPeople) also
   names its header .fp-head, and its later rule (space-between, baseline) pulled the preview's
   name to the far right; these are pinned to the preview's sheet so the two cannot collide. */
.fp-sheet .fp-head { display: flex; align-items: center; justify-content: flex-start; gap: 14px; margin-bottom: var(--sp-16); }
.fp-sheet .fp-av-link { text-decoration: none; }
.fp-sheet .fp-av { flex: none; width: 48px; height: 48px; font-size: var(--fs-read); text-decoration: none; }

/* Top bar icons: small, round, no box (owner, 2026-09-27: "too square and big") */
.topicon, .profile-icon { width: 34px; height: 34px; border-radius: 50%; border: 0; background: none; color: var(--muted); }
.topicon:hover, .profile-icon:hover { background: var(--panel); color: var(--ink); border: 0; }
.topicon svg, .profile-icon svg { width: 19px; height: 19px; }

/* Top-bar search pill (GlobalSearch) */
.gs-pill { display: inline-flex; align-items: center; gap: 8px; height: var(--chip-h); padding: 0 14px 0 12px; border-radius: 999px; background: var(--panel); border: 1px solid var(--line); color: var(--muted); font: inherit; font-size: var(--fs-meta); cursor: pointer; min-width: 150px; }
.gs-pill:hover { color: var(--ink); border-color: var(--line-2); }
@media (max-width: 640px) { .gs-pill { min-width: 0; padding: 0 12px; } }
@media (max-width: 400px) { .gs-pill { padding: 0; width: 34px; min-width: 0; justify-content: center; } }
/* Under the Genres box (not under a label), the hint needs room above it. */
.mood-disclosure + .mood-q-hint { margin-top: 12px; }

/* A voter's photo on a poster: the poster's own "fill the frame" image rule (.tn-gposter img)
   also caught the face and blew it up to the whole poster. */
.mnr-faces img.mnr-face { width: 22px; height: 22px; max-width: none; position: static; inset: auto; object-fit: cover; border-radius: var(--radius-sm); }

/* Movie night vote: one list, one choice (TheaterRoom PicksView) */
.mnr-ballot-tag { font-size: var(--fs-label); letter-spacing: 0; text-transform: none; color: var(--accent-2); font-weight: 700; }
/* Trailer and Details: a matching pair of small pill buttons (owner, 2026-09-29: "make the trailer
   and details buttons better"; they were bare links). 32px tall, so each is a real tap target. */
.mnr-ballot-btn, .mnr-ballot-btn.trailer-btn { display: inline-flex !important; align-items: center; gap: 6px; height: 32px; min-height: 32px !important; padding: 0 13px !important;
  border-radius: 999px !important; border: 1px solid var(--line-2) !important; background: rgba(255,255,255,.05) !important; color: var(--ink) !important;
  font: inherit; font-size: var(--fs-meta) !important; font-weight: 600; letter-spacing: .01em; cursor: pointer; transition: border-color .14s, background .14s; }
.mnr-ballot-btn:hover { border-color: var(--faint) !important; background: rgba(255,255,255,.09) !important; }
.mnr-ballot-btn svg, .mnr-ballot-btn .icon { width: 14px; height: 14px; color: var(--accent-2); display: block; flex: none; }
.mnr-ballot-btn.trailer-btn > :first-child { color: var(--accent-2); }
.mnr-ballot-status { font-size: var(--fs-meta); color: var(--muted); text-align: center; margin: 12px 0 10px; }

/* Search for a visitor with no account (GlobalSearch guest): the one quiet invite under the box. */
.gs-guest { margin: 12px 2px 2px; font-size: var(--fs-meta); color: var(--muted); text-align: center; }
.gs-guest a { color: var(--accent-2); font-weight: 600; text-decoration: none; }
.gs-guest a:hover { text-decoration: underline; text-underline-offset: 2px; }

/* Film sheet: every section heading is .sec (dash + grey caps); the count sits beside it. */
.fd-sec { margin: 0 0 12px; }
.fsr-head .fd-sec, .fp-head .fd-sec { margin-bottom: 0; }
/* Series parts: wider, and the title over two lines (it was cut at 62px: "The Lord of t..."). */
.fsr-item { flex: 0 0 84px; }
.fsr-poster { width: 84px; height: 126px; }
.fsr-t { white-space: normal; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; line-height: 1.3; font-size: var(--fs-label); }
/* Film sheet: one size for the lines under a section heading (they were 12px and 13px). */
.sec-sub, .fp-with { font-size: var(--fs-meta); }
.fp-count, .fsr-count { font-size: var(--fs-label); }
/* Film sheet section headings (Because you enjoyed, People you follow, the series, More like):
   the app's section mark (blue dash, grey capitals), one size for all four, and the count beside
   it in plain grey (owner, 2026-09-27: grey and the blue dash, not white sentence case). */
/* font-family again here: a heading placed straight after the hero is caught by .fd-herowrap ~ * (the
   reading face, wider), which made "Because you enjoyed" look a size up from the others. */
.sec.fd-h { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; font-weight: 600; color: var(--muted); }
.sec.fd-h .fp-count, .sec.fd-h .fsr-count, .sec.fd-h .fd-watch-region { font-size: var(--fs-label); letter-spacing: .02em; text-transform: none; font-weight: 400; color: var(--faint); margin-left: 2px; }
/* "Where it might lose you" in the same label type as "Why this fits your taste" above it. */
.fd-caveat .caveat-label { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; font-weight: 700; color: var(--muted); margin-right: 8px; }
/* Where to watch's own labels at the size of the text under every other heading. */
.fd-watch-label, .fd-watch-fold summary { font-size: var(--fs-meta); }
/* The labels above the sheet's sections (the why panel's heading, the info tabs, the caveat label)
   match the section headings, so no heading reads bigger than the one beside it. */
.fd-panel .tile-h, .fd-infopanel .fd-infotab, .fd-caveat .caveat-label { font-size: var(--fs-label); }

/* Google sign-in inside an app's own browser (Auth.tsx OpenInBrowser): what to do instead. */
.oauth-inapp { display: flex; flex-direction: column; gap: 10px; }
.oauth-inapp-msg { margin: 0; font-size: var(--fs-ui); line-height: 1.5; color: var(--ink); }
.oauth-inapp .oauth-btn { text-decoration: none; justify-content: center; }
.oauth-inapp-hint { margin: 0; font-size: var(--fs-meta); color: var(--muted); }
/* Group report film sections (app/g/[id]/GroupFilms.tsx): the film sheet's heading, rows split by
   a rule rather than boxed, and the faces of the members who loved each film. */
.gsection.gf { padding: 16px 16px 8px; background: var(--panel-2); border-color: var(--line); }
.sec.gf-h { margin: 0 0 6px; }
.gf-pg { margin-left: auto; display: inline-flex; align-items: center; gap: 10px; font-size: var(--fs-label); letter-spacing: .02em; text-transform: none; font-weight: 400; color: var(--faint); }
.gf-pg button { appearance: none; background: none; border: 0; padding: 0 2px; font-size: var(--fs-read); line-height: 1; color: var(--muted); cursor: pointer; }
.gf-pg button:disabled { opacity: .3; cursor: default; }
.gf-sub { font-size: var(--fs-meta); color: var(--faint); margin: 0 0 4px; }
.gf-pager { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; }
.gf-pager::-webkit-scrollbar { display: none; }
.gf-page { flex: 0 0 100%; min-width: 0; scroll-snap-align: start; display: flex; flex-direction: column; }
.gf-row, .gf-div { appearance: none; background: none; border: 0; border-top: 1px solid var(--line); width: 100%; text-align: left; color: var(--ink);
  display: flex; align-items: center; gap: 12px; padding: 10px 0; cursor: pointer; font: inherit; }
.gf-page > .gf-row:first-child, .gf-div { border-top: 0; }
.gf-div { align-items: flex-start; gap: 14px; padding: 6px 0 12px; }
.gf-poster { width: 44px; height: 66px; flex: none; border-radius: 4px; object-fit: cover; background: var(--panel); }
.gf-poster.big { width: 74px; height: 111px; border-radius: var(--radius-poster); }
.gf-poster-ph { display: grid; place-items: center; font-family: var(--label); font-size: var(--fs-label); color: var(--faint); }
.gf-meta { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.gf-title { font-size: var(--fs-ui); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gf-title .yr { color: var(--faint); }
.gf-who { display: flex; align-items: center; gap: 7px; margin-top: 6px; min-width: 0; font-size: var(--fs-meta); color: var(--muted); }
.gf-names { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.gf-faces { display: inline-flex; flex: none; }
.gf-faces > * { width: 22px; height: 22px; border-radius: var(--radius-sm); border: 0; box-shadow: 0 0 0 2px var(--panel-2); margin-left: -6px; object-fit: cover;
  display: grid; place-items: center; font: 600 10px var(--label); } /* type scale exception: initials or a glyph in a fixed box */
.gf-faces > :first-child { margin-left: 0; }
.gf-right { flex: none; text-align: right; font-family: var(--label); }
.gf-stars { display: block; font-size: var(--fs-ui); color: var(--accent-2); }
.gf-label { display: block; margin-top: 2px; font-size: var(--fs-label); letter-spacing: .12em; text-transform: uppercase; color: var(--faint); }
.gf-label.on { color: var(--ink); font-weight: 600; }
.gf-bar { display: flex; height: 4px; border-radius: 3px; overflow: hidden; margin-top: 10px; background: var(--line); }
.gf-bar i { display: block; } .gf-bar .hi { background: var(--accent); } .gf-bar .lo { background: var(--red); }
.gf-side { display: flex; align-items: center; gap: 8px; margin-top: 10px; font-size: var(--fs-meta); color: var(--muted); min-width: 0; }
.gf-k { width: 48px; flex: none; font-family: var(--label); font-size: var(--fs-label); letter-spacing: .12em; text-transform: uppercase; }
.gf-side.hi .gf-k, .gf-side.hi .gf-st { color: var(--accent-2); }
.gf-side.lo .gf-k, .gf-side.lo .gf-st { color: #d98a8a; }
.gf-st { margin-left: auto; font-family: var(--label); }
.gf-spread { font-size: var(--fs-meta); color: var(--faint); margin-top: 8px; }
/* Phones: the app's top bar stays pinned but slides out of the way while scrolling down, and back
   the moment you scroll up (HeaderAutoHide sets html[data-hdr=hidden]). The landing and sign-in
   float their brand over the poster wall and are left alone. */
@media (max-width: 759px) {
  /* Hidden by moving its sticky `top` above the screen, NOT by a transform: a transform (or
     will-change: transform) makes the bar the box every position:fixed thing inside it is sized
     against, so the Activity and account drawers, search and menus opened from the bar were
     squeezed to the bar's height (owner, 2026-09-28: "Activity and menu drawers are glitching"). */
  .wrap:not(.wrap-landing):not(.wrap-signin) > .topbar {
    position: sticky; top: 0; z-index: 60; background: var(--bg);
    padding-top: max(10px, env(safe-area-inset-top)); transition: top .22s var(--ease);
  }
  html[data-hdr="hidden"] .wrap:not(.wrap-landing):not(.wrap-signin) > .topbar { top: calc(-96px - env(safe-area-inset-top)); }
  /* The bar clears the notch itself (it has to, pinned), so the page above it does not as well:
     both did, and the top of every app page sat under a double gap (owner, 2026-09-28). */
  .wrap:not(.wrap-landing):not(.wrap-signin):has(> .topbar) { padding-top: 0; }
  /* With the bar slid away, the page scrolled under the see-through status bar (the group's name
     sat on the clock). A solid strip the notch's height stays behind the status bar. */
  body:has(.wrap:not(.wrap-landing):not(.wrap-signin) > .topbar)::after {
    content: ""; position: fixed; top: 0; left: 0; right: 0; height: env(safe-area-inset-top, 0px);
    background: var(--bg); z-index: 59; pointer-events: none; }
}
/* Suggested follows: their own short list under Your people (app/_components/Friends.tsx). */
.people-suggest { margin: -6px 0 var(--sp-24); }
.people-suggest-toggle { width: 100%; background: none; border: 0; padding: 0; color: inherit; font: inherit; cursor: pointer; text-align: left; }
.people-suggest-chev { font-size: var(--fs-ui); font-weight: 600; color: var(--accent-2); }
.people-suggest.is-closed { margin-bottom: 14px; }

/* Movie Night: "What everyone wanted" under a decided ticket, and a seat's picks in the room
   (app/t/[id]/TheaterRoom.tsx). */
.mnr-wanted-picks { display: flex; flex-wrap: wrap; gap: 6px; }
.mnr-pick { font: 600 var(--fs-label)/1 var(--label); letter-spacing: .08em; text-transform: uppercase; padding: 6px 9px; border-radius: 999px; border: 1px solid var(--line-2); color: var(--muted); }
.mnr-pick.on { border-color: rgba(159,189,227,.7); color: #dfe9f7; background: rgba(111,147,196,.32); }
.mnr-seat.is-tappable { cursor: pointer; }
.mnr-seat.is-open .friend-av { outline: 2px solid var(--accent-2); outline-offset: 2px; }
.mnr-seat-pop { margin: -2px 0 14px; padding: 12px 14px; border: 1px solid var(--line); border-radius: 12px; background: var(--panel); }
.mnr-seat-pop-h { font-size: var(--fs-meta); color: var(--muted); margin-bottom: 8px; }
.mnr-seat-pop-h:last-child { margin-bottom: 0; }
.mnr-seat-pop .mnr-pick { color: var(--ink); }

/* Group report rows: names and titles wrap to a second line instead of cutting off ("@alexfiacco
   and @..."), owner 2026-09-28. Two lines at most; the faces sit beside the first line. */
.gf-title { white-space: normal; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; line-height: 1.25; }
.gf-who { align-items: flex-start; }
.gf-side { align-items: flex-start; }
.gf-names { white-space: normal; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; line-height: 1.35; padding-top: 2px; }

/* About: each card is the icon and title on one line, then the text full width, left-aligned. */

/* Canon: the list scrolls between the header and the "Show on my profile" footer, all inside the
   screen. Its height ignored the footer, so the footer covered the last row and the bottom was
   out of reach (owner, 2026-09-28). */
.cv-modal { display: flex; flex-direction: column; max-height: min(88vh, 100dvh - 32px); }
.cv-top, .cv-footer { flex: none; }
.cv-body { flex: 1 1 auto; min-height: 0; max-height: none; overflow-y: auto; -webkit-overflow-scrolling: touch; }

/* Canon, redesigned (owner, 2026-09-28): #1 on its own still, then 2-10 as a ranked 3x3 wall with
   the "Films that define you" numerals (serif 01, 02...), no controls on the posters. Edit turns
   the wall into a numbered list with up, down and remove, and holds the visibility setting. */
.modal.cv-modal { max-width: 720px; }
.cv-eyebrow { color: #c14a52; }
.cv2-icon { width: 36px; height: 36px; border-radius: var(--radius-card); border: 1px solid var(--line-2); background: none; color: var(--muted); display: grid; place-items: center; cursor: pointer; }
.cv2-icon:hover { color: var(--ink); }
.cv2-icon svg { width: 17px; height: 17px; }
.cv2-done { height: 36px; padding: 0 14px; border-radius: var(--radius-card); border: 0; background: var(--ink); color: var(--bg); font: 600 var(--fs-meta) var(--sans); cursor: pointer; }
.cv2-hero { display: flex; gap: 14px; align-items: flex-end; padding: 16px; border-radius: var(--radius-field); background: var(--panel) center / cover no-repeat;
  min-height: 170px; border: 1px solid rgba(193,74,82,.35); margin-top: 4px; }
.cv2-hero.is-link { cursor: pointer; }
.cv2-hero-poster { width: 92px; flex: none; aspect-ratio: 2 / 3; border-radius: 8px; overflow: hidden; box-shadow: 0 8px 24px rgba(0,0,0,.6); background: var(--panel-2); }
.cv2-hero-poster img { width: 100%; height: 100%; object-fit: cover; display: block; }
.cv2-hero-meta { display: flex; flex-direction: column; min-width: 0; }
.cv2-no { font: 600 var(--fs-label)/1 var(--label); letter-spacing: .16em; text-transform: uppercase; color: #e57b83; }
.cv2-hero-title { font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; color: #f4efe6; line-height: 1.15; margin-top: 6px; }
.cv2-hero-sub { font-size: var(--fs-meta); color: #bdb9b0; margin-top: 5px; }
.cv2-hero-line { font-size: var(--fs-meta); color: #d6d1c7; margin-top: 10px; font-style: italic; }
.cv2-wall { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px 12px; margin-top: var(--sp-16); }
.cv2-poster { position: relative; aspect-ratio: 2 / 3; border-radius: 8px; overflow: hidden; background: var(--panel-2); }
.cv2-poster.is-link { cursor: pointer; }
.cv2-poster img { width: 100%; height: 100%; object-fit: cover; display: block; }
.cv2-scrim { position: absolute; inset: 0; background: linear-gradient(180deg, rgba(6,8,13,.55) 0%, transparent 30%); pointer-events: none; }
.cv2-rank { position: absolute; top: 6px; left: 9px; font-family: var(--serif); font-weight: 600; font-size: var(--fs-heading); color: var(--ink); text-shadow: 0 2px 8px rgba(0,0,0,.7); line-height: 1; }
.cv2-cap { font-size: var(--fs-meta); color: var(--muted); margin-top: 8px; line-height: 1.3; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.cv2-ghost { border: 1px dashed var(--line-2); background: none; display: grid; place-items: center; color: var(--faint); font-size: var(--fs-title); }
.cv2-ghost .cv2-rank { color: var(--faint); text-shadow: none; }
.cv2-ghost-cap { color: var(--faint); }
.cv2-hint { font-size: var(--fs-meta); color: var(--muted); margin: 2px 0 12px; }
.cv2-list { border-top: 1px solid var(--line); }
.cv2-row { display: flex; align-items: center; gap: 12px; padding: 9px 0; border-bottom: 1px solid var(--line); }
.cv2-row-rank { width: 26px; flex: none; white-space: nowrap; text-align: right; font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; color: var(--ink); }
.cv2-row-poster { width: 36px; flex: none; aspect-ratio: 2 / 3; border-radius: 4px; overflow: hidden; background: var(--panel-2); }
.cv2-row-poster img { width: 100%; height: 100%; object-fit: cover; display: block; }
.cv2-row-poster .cv-noimg { font-size: 8px; } /* type scale exception: initials or a glyph in a fixed box */
.cv2-row-meta { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.cv2-row-title { font-size: var(--fs-ui); color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cv2-row-sub { font-size: var(--fs-label); color: var(--faint); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cv2-row-btns { display: flex; gap: 6px; flex: none; }
.cv2-row-btns button { width: 32px; height: 32px; border-radius: 8px; border: 1px solid var(--line-2); background: none; color: var(--ink); font-size: var(--fs-ui); cursor: pointer; }
.cv2-row-btns button:disabled { opacity: .3; cursor: default; }
.cv2-row-btns .cv2-x { color: var(--danger); }
.cv2-setting { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-top: var(--sp-16); padding: 14px; border: 1px solid var(--line); border-radius: 12px; }
@media (min-width: 700px) {
  .cv2-hero { min-height: 230px; padding: var(--sp-24); }
  .cv2-hero-poster { width: 130px; }
  .cv2-hero-title { font-size: var(--fs-title); }
  .cv2-wall { gap: var(--sp-24) var(--sp-16); }
  .cv2-cap { font-size: var(--fs-meta); }
}

/* Canon notes: the owner's optional line on why a film is here. A quote in the serif, under the
   #1's title and under each poster's caption; in Edit, a quiet field that reads as a link until used. */
.cv2-hero-note { font-family: var(--serif); font-style: italic; font-size: var(--fs-ui); line-height: 1.35; color: var(--ink); margin-top: 10px; max-width: 46ch; }
/* Brighter than the grey caption above it so it reads on its own, and set off by a faint crimson
   hairline (the Canon's colour) rather than by size or weight, so it stays quiet. */
.cv2-note { font-family: var(--serif); font-style: italic; font-size: var(--fs-meta); line-height: 1.35; color: #ebe5d8; margin-top: 6px;
  padding-left: 8px; border-left: 2px solid rgba(193,74,82,.55);
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
/* In Edit the row is a grid so the note gets the full width under the title and the buttons:
   rank and poster span both lines. */
.cv2-list .cv2-row { display: grid; grid-template-columns: 26px 36px minmax(0, 1fr) auto; column-gap: 12px; row-gap: 2px; }
.cv2-list .cv2-row-rank, .cv2-list .cv2-row-poster { grid-row: span 2; }
.cv2-note-field { grid-column: 3 / 5; position: relative; display: flex; align-items: center; }
.cv2-note-field input { width: 100%; min-width: 0; height: 28px; padding: 0 34px 0 0; border: 0; border-bottom: 1px solid transparent; border-radius: 0;
  background: none; color: var(--ink); font: italic var(--fs-meta) var(--serif); outline: none; }
.cv2-note-field input::placeholder { font: 500 var(--fs-meta) var(--sans); font-style: normal; color: #c98a90; }
.cv2-note-field.on input { border-bottom-color: var(--line-2); }
.cv2-note-field.on input::placeholder { color: var(--faint); }
.cv2-note-left { position: absolute; right: 2px; font: 500 var(--fs-label) var(--sans); color: var(--faint); }
.cv2-note-left.low { color: #e57b83; }
@media (min-width: 700px) {
  .cv2-hero-note { font-size: var(--fs-read); }
  .cv2-note { font-size: var(--fs-meta); }
}

/* A Canon's own page (/u/<id>/canon), the Share link. */
.cv2-page { max-width: 760px; margin: 0 auto; }
.cv2-page-h { margin: 8px 0 4px; }
.cv2-page-sub { color: var(--muted); font-size: var(--fs-meta); margin: 0 0 16px; }
.cv2-cell-link { display: block; color: inherit; text-decoration: none; }
.cv2-page-actions { display: flex; gap: 10px; flex-wrap: wrap; margin: var(--sp-24) 0 10px; }
/* The generic .modal (later in this file) set its own padding and width over the Canon's; the
   Canon lays out its own header and body. Tighter on a phone so the edit rows keep their titles. */
.modal.cv-modal { padding: 0; }
@media (max-width: 480px) {
  .cv-top { padding-left: 16px; padding-right: 16px; }
  .cv-body { padding-left: 16px; padding-right: 16px; }
  .cv2-row { gap: 10px; }
  .cv2-row-btns { gap: 4px; }
  .cv2-row-btns button { width: 30px; height: var(--btn-h-sm); }
  .cv2-wall { gap: 14px 10px; }
}

/* "Sharpen your profile" (ProfileSetup.tsx): the owner's setup steps under the name and counts,
   in the app's panel language (tile eyebrow, serif-free, text-link actions). Only the steps left
   are rows; the finished ones fold into one line. The bar is the rating track, checkpoints at 30
   and 100. Collapsible, gone once done. */
/* Sharpen your profile (rule 84, mockup option A 2026-10-09): one next step, chips for the rest. */
/* Sharpen your profile (rule 84, mockups/sharpen-compact.png): one slim row on the profile, the
   checklist in a bottom drawer (sharpen-final.png). */
.su { position: relative; margin: 12px 0 2px; border: 1px solid var(--line-2); border-radius: var(--radius); background: var(--panel); padding: 12px 14px; }
.su-row { display: flex; align-items: center; gap: 12px; min-height: 66px; cursor: pointer; }
.su-row:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.su-ring { position: relative; flex: none; width: 40px; height: 40px; display: grid; place-items: center; }
.su-ring svg { position: absolute; inset: 0; }
.su-ring b { position: relative; font: 700 var(--fs-label)/1 var(--sans); color: var(--ink); font-variant-numeric: tabular-nums; }
.su-m { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.su-l { font: 600 var(--fs-ui)/1.25 var(--sans); color: var(--ink); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.su-s { font-size: var(--fs-meta); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.su-dashes { display: flex; gap: 5px; margin-top: 5px; }
.su-dashes i { width: 16px; height: 3px; border-radius: 2px; background: var(--line-2); }
.su-dashes i.done { background: var(--accent); }
.su-dashes i.cur { background: var(--ink); }
.su-go { flex: none; min-height: 34px; padding: 0 16px; border: 0; border-radius: var(--btn-r); background: var(--cream); color: var(--cream-ink); font: 600 var(--fs-ui) var(--sans); cursor: pointer; }
.su-go:hover { filter: brightness(1.05); }
.su-x { flex: none; width: 28px; height: 28px; display: grid; place-items: center; background: none; border: 0; border-radius: 8px; color: var(--muted); cursor: pointer; }
.su-x:hover { color: var(--ink); }
.su-st-s { font-size: var(--fs-meta); color: var(--muted); }
/* The taste-test banner: rating first, Letterboxd as the smaller way in, and a close. */
.tt-upsell-sharpen { position: relative; padding: 12px 44px 12px 16px; background: var(--panel); }
.tt-upsell-sharpen .tt-x { position: absolute; top: 6px; right: 6px; width: 32px; height: 32px; border: 0; background: none; color: var(--muted); font-size: var(--fs-card); line-height: 1; cursor: pointer; }
.tt-upsell-sharpen .tt-upsell-alt { flex-basis: 100%; font-size: var(--fs-meta); color: var(--muted); }
.tt-upsell-sharpen .tt-upsell-alt .linkbtn { color: var(--muted); font-size: var(--fs-meta); }
.dsc-welcome-next + .dsc-welcome-next { margin-top: 8px; }
.dsc-welcome-ic { width: 30px; height: 30px; flex: none; display: grid; place-items: center; color: var(--accent-2); }
.dsc-welcome-ic svg { width: 22px; height: 22px; }

/* Discover's "Build your library": first thing on the tab under 100 films, in the same panel
   language as the profile's setup steps (tile eyebrow, serif count, thin bar, text-link action). */
.dsc-build { border: 1px solid var(--line-2); background: var(--panel); border-radius: var(--radius); padding: 12px 16px 12px; margin: var(--sp-4) 0 var(--sp-16); }
.dsc-build-bar { height: 3px; border-radius: 3px; background: var(--line-2); margin-top: 9px; overflow: hidden; }
/* The bar grows to its new length instead of jumping when a rating lands (owner, 2026-09-28). */
.dsc-build-bar span { display: block; height: 100%; background: var(--accent-2); border-radius: 3px; transition: width .4s var(--ease); }

/* How we did (HowWeDid.tsx; owner, 2026-09-30): the films just in from their Letterboxd diary,
   against the match we gave them. A flat card like Build your library: hairline, panel, 8px. Blue
   is the match and your stars; the called-it mark is the "on" state; a surprise is a cream arrow
   on a hairline, never red. */
.hwd { border: 1px solid var(--line-2); background: var(--panel); border-radius: var(--radius); padding: 14px 16px 12px; margin: var(--sp-16) 0 var(--sp-4); }
.hwd-said b, .fa-said b { font-weight: 600; color: var(--accent-2); }
.hwd-mark { flex: none; display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; border-radius: 50%; border: 1px solid var(--line-2); color: var(--ink); }
.hwd-mark.on { background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); color: var(--ink); }
/* The film sheet's line, inside the rating box. */
.fa-said { display: flex; align-items: center; gap: 10px; margin: 10px 0 0; padding: 9px 12px; border: 1px solid var(--line); border-radius: var(--radius); font-family: var(--sans-read); font-size: var(--fs-meta); line-height: 1.4; color: var(--muted); }
.fa-said .hwd-mark { width: 24px; height: 24px; }

/* Canon: add a film by search inside the modal. */
.cv-search { text-align: left; margin: 0 0 16px; }
.cv-empty .cv-search { max-width: 420px; margin: var(--sp-16) auto 0; }
.cv-search .ig-search { margin-top: 0; }
.cv-search .gwl-cands { max-height: 330px; overflow-y: auto; }
.cv-search .act-cardrow:disabled { opacity: 1; cursor: default; }
.cv-search-have { flex: none; font-size: var(--fs-label); color: var(--faint); padding: 0 6px; }
button.cv2-ghost { width: 100%; font: inherit; cursor: pointer; padding: 0; transition: border-color .15s, color .15s; }
button.cv2-ghost:hover, button.cv2-ghost:focus-visible { border-color: var(--line-3, var(--muted)); color: var(--ink); }

/* Social: movie night at the top once you have a circle, and any night you're in that's still open. */
/* Its own space under the search bar (owner, 2026-09-29: it sat flush against it). */
.people-mn.is-top { margin: var(--sp-16) 0 var(--sp-24); }
.people-mn.is-top .mn-tonight { margin-top: 0; }
.people-mn.is-top .mn-block { margin-top: 0; }
.people-mn.is-top .people-mn-last .mnh-compact { margin-bottom: 0; }

/* Group superlatives: the full receipt (lib/group-receipts.ts). */
.gpage .grp-sup.open .grp-sup-body { max-height: 1200px; }
.rcpt { display: flex; flex-direction: column; }
.rcpt-h { font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; color: var(--ink); line-height: 1.25; }
.rcpt-sub { font-size: var(--fs-meta); color: var(--muted); line-height: 1.45; margin: 4px 0 8px; }
.rcpt-film { display: flex; gap: 11px; align-items: center; padding: 8px 0; border-top: 1px solid var(--line); }
.rcpt-poster, .rcpt-sp { appearance: none; border: 0; padding: 0; background: var(--panel-2); cursor: pointer; overflow: hidden; display: grid; place-items: center; flex: none; }
.rcpt-poster { width: 32px; height: 48px; border-radius: 4px; }
.rcpt-poster img, .rcpt-sp img { width: 100%; height: 100%; object-fit: cover; display: block; }
.rcpt-ph { font-size: 7px; line-height: 1.1; color: var(--faint); text-align: center; padding: 2px; overflow: hidden; } /* type scale exception: initials or a glyph in a fixed box */
.rcpt-meta { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.rcpt-title { font-size: var(--fs-ui); font-weight: 600; color: var(--ink); }
.rcpt-title .yr { font-weight: 400; color: var(--faint); font-size: var(--fs-meta); }
.rcpt-note { font-size: var(--fs-label); color: var(--muted); margin-top: -2px; }
.rcpt-chips { display: flex; flex-wrap: wrap; gap: 5px; }
.rcpt-chip { display: inline-flex; align-items: center; gap: 5px; font-size: var(--fs-label); color: var(--muted); padding: 2px 8px 2px 6px; border: 1px solid var(--line-2); border-radius: 999px; white-space: nowrap; }
.rcpt-chip i { width: 7px; height: 7px; border-radius: 50%; }
.rcpt-chip b { color: var(--ink); font-weight: 700; }
.rcpt-chip.on { border-color: rgba(193,74,82,.8); background: rgba(193,74,82,.12); color: #f0b7bb; }
.rcpt-chip.on b { color: #f6c9cc; }
.rcpt-strip { display: flex; gap: 6px; margin: 2px 0 8px; }
.rcpt-sp { width: 44px; height: 66px; border-radius: var(--radius-poster); }
.rcpt-foot { font-size: var(--fs-meta); color: var(--faint); margin-top: 8px; line-height: 1.45; }
.rcpt-foot b { color: var(--muted); }
/* A nudge (a question, not a confirmation): its own mark, and up to two lines of text. */

/* ---- Zoomed in (page zoom or a larger text size, e.g. 200% on a phone lays the page out about
   195px wide). Only below 300px, a width no phone has at normal zoom, so the usual layout is
   untouched. Padding made for a full-width card gives way to the text, and nothing is cut off at
   the card's edge: the archetype name, the Film DNA chart and the taste scales fit. ---- */
@media (max-width: 300px) {
  .wrap { padding-left: 8px; padding-right: 8px; }
  .hero { padding-left: var(--sp-16); padding-right: 10px; }
  .hero::before { width: 8px; }
  .hero-lower, .hero-lower.hero-lower-one, .dna-strip { padding-left: 0; padding-right: 0; grid-template-columns: minmax(0, 1fr); }
  .hero-axis-lab { font-size: var(--fs-label); letter-spacing: 0; gap: 6px; }
  .hero-axis-lab > * { min-width: 0; overflow-wrap: anywhere; }
  /* The chart's labels cannot fit around a chart this small; the dimension named under it (with
     its arrows) says which one is which. */
  .dna-radar-label { display: none; }
  .dna-radar-detail { padding-left: 10px; padding-right: 10px; }
  .dna-detail-nav { flex-wrap: wrap; justify-content: center; }
  .dna-detail-rank { overflow-wrap: anywhere; }
  .hero-stats { grid-template-columns: minmax(0, 1fr); }
  /* "Why X" and "See all 14 archetypes" stay on one line on a phone; zoomed this far they take two. */
  .hero-blend-tail { flex-wrap: wrap; row-gap: 6px; }
  .hero-blend-tail .hml-link { overflow: visible; }
  /* The header: a smaller mark, and the search pill down to its icon, so the row fits. */
  .brand .brandmark { height: 28px; margin: 0; }
  .brand > svg { display: none !important; } /* the wordmark (display is set inline); the fan glyph stays */
  .gs-pill { min-width: 0; padding: 0 9px; }
  .topbar-actions { gap: 4px; }
  .topbar-signin { padding: 0 9px; }
  /* Landing: the hero is taller than the screen when zoomed, so it starts below the header
     (the way the open import form does) instead of running up under it. */
  .wrap-landing .onboard-cine { justify-content: flex-start; }
  .wrap-landing .onboard-cine .onboard-cine-fg { padding-top: calc(74px + env(safe-area-inset-top)); }
  /* The bottom tabs: all three names fit, with less tracking. */
  .tabbar .tabbtn { min-width: 0; }
  .tabbar .tabbtn .tablabel { letter-spacing: .02em; font-size: var(--fs-label); }
  /* The quiz's stars: five across still, a little smaller. */
  .dstar-wrap, .dstar { width: 34px; height: 34px; }
  .dstar { font-size: 28px; line-height: 34px; }
}

/* Keyboard focus, everywhere (accessibility, 2026-09-29): a steel-blue ring on whatever Tab lands
   on. :focus-visible only, so it never shows on a tap or a click; nothing changes for touch or
   mouse. :where() keeps it weaker than any component's own focus style, which still wins. Text
   fields are left alone: they show their caret, and a click focuses them visibly anyway. */
:where(a, button, summary, select, [role="button"], [role="switch"], [role="option"], [role="tab"], [role="link"], [tabindex]:not([tabindex="-1"])):focus-visible {
  outline: 2px solid var(--accent-2);
  outline-offset: 2px;
}
/* The Film DNA chart's points are SVG, which does not draw an outline in every browser: a ring
   in the stroke instead, for the keyboard only. */
.dna-radar-dot:focus-visible { stroke: var(--accent-2); stroke-width: 3; }

/* Tonight's Occasion row on one line on a phone (owner, 2026-09-29): the chips tighten a little so
   the label and the four choices fit a 336px panel. */
@media (max-width: 480px) {
  .tn-occasion { flex-wrap: nowrap; gap: 4px; overflow-x: auto; scrollbar-width: none; }
  .tn-occasion::-webkit-scrollbar { display: none; }
  .tn-occasion .mood-chip-sm { padding: 6px 8px; font-size: var(--fs-meta); white-space: nowrap; flex: none; }
}
/* Tonight: what the occasion leans toward, under the row (only when it is not Solo). */
.tn-occasion-note { font-size: var(--fs-meta); line-height: 1.45; color: var(--muted); margin: 2px 0 6px; }
.tn-occasion-note .linkbtn { font-size: inherit; }

/* ---- Loading wireframes (owner, 2026-09-28: "When a page is loading in have it sit in a wireframe
   so stuff doesn't move all over the place when stuff loads in; like have fixed positions").
   One look everywhere: a block in the panel colour with a slow sheen, standing exactly where the
   content will land. A placeholder wears the real element's own class (.hc-card, .tastemix-tile,
   .lib-poster, .fd-hero, .gpage-photo, .act-poster...) plus .skel, so it takes that element's size,
   ratio and margins, and the content replaces it without moving anything below. Text is a
   .skel-text inside the real text element (app/_components/Skeleton.tsx), riding its line box so
   the line keeps its real height. Still (no sheen) under reduced motion. It sits late in the file
   so the fill wins over the background of the class it borrows its shape from. */
@keyframes skel-sheen { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
.skel {
  --skel-fill: linear-gradient(90deg, var(--panel-2) 25%, var(--line-2) 50%, var(--panel-2) 75%);
  background: var(--skel-fill); background-size: 200% 100%; animation: skel-sheen 1.8s ease-in-out infinite;
  border-color: transparent; box-shadow: none; filter: none; color: transparent; pointer-events: none;
}
/* Borrowed classes that paint their own fill with a stronger selector (every other member avatar,
   the movie night card) are handed the wireframe's fill back. */
.gpage-av.skel:nth-child(n), .mn-tonight.dsc-tonight-cta.skel {
  background: var(--skel-fill); background-size: 200% 100%; border-color: transparent; box-shadow: none; }
@media (prefers-reduced-motion: reduce) { .skel { --skel-fill: var(--panel-2); animation: none; } }
/* A word's worth of block on a line of real text; SkelLines sets several on lines of their own. */
.skel-text { display: inline-block; max-width: 100%; height: .8em; vertical-align: middle; overflow: hidden;
  border-radius: var(--radius-sm); line-height: 1; }
.skel-line { display: block; height: 12px; border-radius: var(--radius-sm); }
/* The film sheet's ratings card: the rating row, then the watch and Canon buttons. */
.fd-ratings-card .fd-skel-rate { height: 22px; width: 78%; }
.fd-ratings-card .fd-skel-acts { height: 33px; }
/* Blocks that stand for a whole control or avatar take its corners. */
.mnr-seat-av.skel, .friend-av.skel, .gpage-photo.skel { border-radius: var(--radius-sm); }
.mnr-primary.skel { border-radius: var(--radius); }
.skel-mn { min-height: 70px; }
.lib-search.skel { border-radius: var(--radius); }
.lib-filter.skel { border-radius: var(--radius); }

/* Poster tiles give under a tap: a quick press-in, so a tap reads as landing before the sheet or
   reel opens (owner, 2026-09-28). */
.hc-card, .tastemix-tile, .lib-card, .rpick, .take, .people-face { transition: transform .12s var(--ease); }
.hc-card:active, .tastemix-tile:active, .lib-card:active, .rpick:active, .take:active, .people-face:active { transform: scale(.97); }

/* Turning a save on pops like a star does (dstarPop): the hero card's watchlist +, the sheet's
   Watchlist button and the quick-rate button once a tap marks the film. The components add
   .pop only on that tap, so nothing pops when saved state loads (owner, 2026-09-28). The hero
   card's + starts off on every render, so its .on is always a tap; its quick-rate twin is not. */
@keyframes savePop { 0% { transform: scale(1); } 50% { transform: scale(1.12); } 100% { transform: scale(1); } }
.dsc-hero-icon.on:not(.qr-btn), .fa-watch.pop, .qr-btn.pop { animation: savePop .18s var(--ease); }

/* Posters fade in once loaded instead of popping in (owner, 2026-09-28): the library grid and
   every .lib-poster grid, Taste Mixes, the weekly carousel and Tonight's lane rows. Hidden only
   while html[data-pf] is set and the image has no data-in stamp; PosterFade.tsx sets both and
   explains why a poster can never be left invisible. */
.lib-poster > img, .tastemix-tile > img, .hc-card > .dsc-hero-img, .tn-gposter > img { transition: opacity .2s var(--ease); }
html[data-pf] :is(.lib-poster, .tastemix-tile, .tn-gposter) > img:not([data-in]),
html[data-pf] .hc-card > .dsc-hero-img:not([data-in]) { opacity: 0; }
/* No blank boxes while posters load (owner-approved mock, 2026-10-23, option A; rule 490): a
   .tcard shows the film's title in the serif on a warm dark glow, and the poster fades in over it.
   Browse's tiles, which have no single title, get the glow alone. */
.tcard { position: relative; overflow: hidden; }
/* Named with each host's own class: their buttons reset background later in this file. */
.tcard, .pk-poster-tap.tcard, .sp-mpo.tcard, .sp-po.tcard { background: radial-gradient(120% 90% at 30% 20%, #2a1d22, #121214 70%); }
.tcard-t { position: absolute; inset: 0; display: grid; place-items: center; padding: 6px; text-align: center; overflow: hidden;
  font-family: var(--serif); font-weight: 500; font-size: 11px; line-height: 1.15; color: var(--ink); }
.tcard > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; transition: opacity .3s var(--ease); }
html[data-pf] .tcard > img:not([data-in]) { opacity: 0; }
/* Sized to the poster, which shrinks when a card sits above it: a long title stays inside the frame. */
.pk-poster-tap.tcard { container-type: inline-size; }
.pk-poster .tcard-t { padding: 10%; font-size: clamp(13px, 11cqi, 26px); line-height: 1.1; } /* type scale exception: rank numerals or ticket stub */
.sp-po.tcard { display: block; }
.bh-mood .bh-mood-bg > * { background: radial-gradient(120% 90% at 30% 20%, #2a1d22, #121214 70%); }


/* Browse's type scale (owner, 2026-09-29: "use consistent font sizes across this module"). It had
   seven sizes, 11.5 to 16px, because the language menu and the Director or actor field are held at
   16px on touch screens (the no-zoom rule at the end of this file) while the buttons beside them
   were 13px. Two tiers now: every control 16px, the same weight, colour and height; everything
   else (the sort, the seen toggle, the count, film titles) 13px. */
.browse :is(.browse-select, .mood-disclosure) { font-size: var(--fs-read); font-weight: 500; color: var(--muted); min-height: 44px; padding-top: 10px; padding-bottom: 10px; }
.browse .browse-person-input { color: var(--ink); }
.browse .browse-person { margin-top: 0; }
.browse .browse-lane-btn.on { color: var(--ink); }
.browse .mood-disclosure { padding-left: 11px; }
.browse .mood-disclosure .mood-q-opt { font-size: var(--fs-read); font-weight: 400; }
/* Six sorts (Highest rated and Most popular joined, 2026-09-30): they fill the row where it is
   wide enough and scroll sideways on a phone, never shrinking or wrapping. */
.browse .browse-sort { overflow-x: auto; scrollbar-width: none; -webkit-overflow-scrolling: touch; }
.browse .browse-sort::-webkit-scrollbar { display: none; }
.browse .browse-sort .mood-seg { font-size: var(--fs-meta); padding: 9px 12px; flex: 1 0 auto; white-space: nowrap; }
.browse :is(.browse-bar, .browse-count, .browse-seen, .lib-title) { font-size: var(--fs-meta); }
.browse :is(.browse-count, .browse-seen) { font-weight: 500; }

/* Lately (app/_components/LatelyCard.tsx): in the profile's section frame (.hero-lower), so it
   lines up with "Where your taste sits" and gets the same hairline above it. */
.lately-wrap { margin-top: 0; }
.lately { display: flex; flex-direction: column; gap: var(--sp-16); min-width: 0; }
.lately-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: -8px; }
.lately-head .sec { margin: 0; }
.lately-span { font-size: var(--fs-label); color: var(--faint); }
.lately-run-t, .lately-month-t, .lately-shift, .lately-extras { margin: 0; font-size: var(--fs-ui); line-height: 1.45; color: var(--muted); }
.lately-run-t b, .lately-month-t b, .lately-shift b { color: var(--ink); font-weight: 600; }
.lately-extras { font-size: var(--fs-meta); margin-top: -8px; color: var(--faint); }
.lately-shift { font-size: var(--fs-ui); }
.lately-more { align-self: flex-start; font-size: var(--fs-meta); font-weight: 600; }
.lately-h { font-size: var(--fs-label); letter-spacing: .1em; text-transform: uppercase; font-weight: 700; color: var(--faint); margin-bottom: 10px; }
.lately-posters { display: flex; gap: 8px; margin-top: 12px; overflow-x: auto; scrollbar-width: none; }
.lately-posters::-webkit-scrollbar { display: none; }
.lately-poster { flex: 0 0 auto; width: 62px; aspect-ratio: 2 / 3; border-radius: 6px; overflow: hidden; padding: 0; border: 1px solid var(--line); background: var(--panel-2); cursor: pointer; }
.lately-poster.big { width: 76px; }
.lately-poster img { width: 100%; height: 100%; object-fit: cover; display: block; }
.lately-poster span { display: block; padding: 4px; font-size: var(--fs-label); line-height: 1.25; color: var(--muted); text-align: left; }
.lately-tiles { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.lately-tile { border: 1px solid var(--line); border-radius: var(--radius); background: var(--panel); padding: 12px 10px 10px; display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.lately-tile b { font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; line-height: 1; color: var(--ink); }
.lately-tile span { font-size: var(--fs-label); line-height: 1.25; color: var(--muted); }
.lately-tile b small { font-size: var(--fs-ui); margin-left: 1px; }
.lately-lanes { display: flex; flex-wrap: wrap; gap: 6px; }
.lately-lane { display: inline-flex; align-items: center; gap: 7px; padding: 6px 11px; border: 1px solid var(--line-2); border-radius: 999px; font-size: var(--fs-meta); font-weight: 500; color: var(--ink); text-decoration: none; max-width: 100%; }
.lately-lane span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lately-lane i { font-style: normal; font-size: var(--fs-label); color: var(--faint); }
.lately-lane i.lately-new { color: var(--accent-2); font-weight: 600; }
.lately-lane:hover { border-color: var(--accent-2); }
.lately-bars { display: grid; grid-template-columns: repeat(12, 1fr); gap: 5px; height: 78px; align-items: end; }
.lately-bar { appearance: none; border: 0; background: none; padding: 0; height: 100%; display: flex; flex-direction: column; justify-content: flex-end; align-items: stretch; gap: 5px; cursor: pointer; min-width: 0; }
.lately-bar em { font-style: normal; font-size: var(--fs-label); font-weight: 600; color: var(--ink); text-align: center; line-height: 1; min-height: 11px; }
.lately-bar i { display: block; border-radius: 3px 3px 1px 1px; background: var(--line-2); transition: background .15s; }
.lately-bar.on i { background: var(--accent-2); }
.lately-bar span { font-size: var(--fs-label); color: var(--faint); text-align: center; line-height: 1; }
.lately-bar.on span { color: var(--ink); }
.lately-month-t { font-size: var(--fs-ui); margin-top: 10px; }
.lately-montages { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.lately-montage { min-width: 0; appearance: none; text-align: left; cursor: pointer; display: flex; flex-direction: column; gap: 3px;
  padding: 11px 13px 12px; border-radius: var(--radius); border: 1px solid var(--line-2); background: var(--panel); color: var(--ink); font: inherit;
  box-shadow: inset 3px 0 0 var(--accent-2); }
.lately-montage:hover { border-color: var(--accent-2); }
.lately-montage-k { font-size: var(--fs-label); letter-spacing: .12em; text-transform: uppercase; font-weight: 700; color: var(--accent-2); }
.lately-montage-t { font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; line-height: 1.15; }
.lately-montage-s { font-size: var(--fs-label); color: var(--muted); }
.recap { display: flex; flex-direction: column; gap: var(--sp-16); }
.recap-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(72px, 1fr)); gap: 8px; }
.recap-stat { border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 8px; display: flex; flex-direction: column; align-items: center; gap: 2px; }
.recap-stat b { font-family: var(--ui); font-size: var(--fs-heading); font-weight: 600; color: var(--ink); line-height: 1.1; font-variant-numeric: tabular-nums; }
.recap-stat span { font-size: var(--fs-label); color: var(--muted); text-align: center; }
.recap-posters { margin-top: 0; }
.recap-facts { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; }
.recap-facts li { display: flex; justify-content: space-between; gap: 12px; padding: 10px 0; border-top: 1px solid var(--line); font-size: var(--fs-ui); }
.recap-facts li span { color: var(--muted); flex: 0 0 auto; }
.recap-facts li b { color: var(--ink); font-weight: 600; text-align: right; }
/* Tonight: the run hint above the mode row. */
.tn-run { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 10px; margin: 2px 0 10px; font-size: var(--fs-meta); color: var(--muted); }
.tn-run-t b { color: var(--ink); font-weight: 600; }
.tn-run-acts { display: inline-flex; gap: 6px; }

/* The deck's end slide after a failed load: "Try again" leads, "Done" steps back. */
.reel-cta.reel-cta-ghost { background: transparent; color: var(--ink); }

/* Film DNA's explanation card, wider on a laptop (owner, 2026-09-29): at 380px its "For you" line
   wrapped to three short lines with the rest of the card empty around it. Phones keep 380. */
@media (min-width: 900px) { .dna-radar-detail { max-width: 560px; } }

/* This week's genres show on desktop only (owner, 2026-09-29). */
.dsc-hero-genres { display: none; }
@media (min-width: 900px) { .dsc-hero-genres { display: inline; } }

/* ONE BUTTON FAMILY (owner, 2026-09-29: "should we have consistent buttons across all features?
   The see details buttons are different on these different features"). Tonight's row is the model
   (soft dark fill, hairline border, 14px corners, 46px tall, accent icons, label centred): the
   same look for See details, Trailer, Want to watch, Rate and Haven't seen it in the Taste Mix /
   New releases viewer and in "Have you seen these?". The one main action on a screen stays the
   cream fill (Tonight's Where to watch, a deck's Done). */
.dreel-choice, .dreel-skip,
.reel-actions .trailer-btn, .reel-actions .reel-icon {
  appearance: none; display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  min-height: var(--btn-h); padding: 0 14px; border-radius: var(--radius-field) !important; cursor: pointer;
  background: rgba(255,255,255,.05); border: 1px solid var(--line-2); color: var(--ink);
  font: inherit; font-size: var(--fs-ui); font-weight: 600; line-height: 1;
  transition: border-color .14s, background .14s, transform .1s; }
.dreel-choice:hover:not(:disabled), .dreel-skip:hover,
.reel-actions .trailer-btn:hover, .reel-actions .reel-icon:hover { border-color: var(--faint); background: rgba(255,255,255,.09); }
.dreel-choice:active:not(:disabled), .dreel-skip:active,
.reel-actions .trailer-btn:active, .reel-actions .reel-icon:active { transform: scale(.98); }
.reel-actions .trailer-btn svg { color: var(--accent-2); opacity: 1; flex: none; }
.reel-actions .trailer-btn svg { width: 16px; height: 16px; }
/* Details (owner, 2026-09-30, option A): a small chip under the title in both viewers, not a
   full-width button. Tells people the film opens; the poster opens it too. */
.details-chip { appearance: none; display: inline-flex; align-items: center; justify-content: center; gap: 6px; align-self: center;
  height: var(--chip-h); padding: 0 12px; margin: 2px auto 10px; border-radius: var(--btn-r); cursor: pointer;
  background: rgba(255,255,255,.05); border: 1px solid var(--line-2); color: var(--ink);
  font: inherit; font-size: var(--fs-meta); font-weight: 600; line-height: 1; transition: border-color .14s, background .14s; }
.details-chip:hover { border-color: var(--faint); background: rgba(255,255,255,.09); }
.details-chip svg { width: 14px; height: 14px; color: var(--accent-2); flex: none; }
.reel-info .details-chip { margin-top: 10px; margin-bottom: 0; }
/* The deck's two answers for a film not seen, side by side. */
.dreel-choice:disabled:not(.on) { opacity: .45; cursor: default; }
/* Saved (owner, 2026-09-30: a border alone was not clear): blue fill, border and label. */
.reel-actions .reel-icon.on, .dreel-choice.on {
  background: var(--accent-soft); border-color: var(--accent); color: var(--accent-2); }

/* Reduced motion, everywhere (owner, 2026-09-28): many animations had no reduce rule of their own
   (the tab fade, sheet-up, drawer-in, the movie night ceremony and its endless reel spins,
   mnPulse, hstatPulse, gwlSkel, splash-in, friendRowOut, mn-dice-roll). Cut every animation and
   transition to an instant, single run: end states still apply, so nothing is left hidden or
   half-moved, and scripts waiting on animationend or transitionend still hear it. */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
    scroll-behavior: auto !important;
  }
}

/* iOS zooms the page into any text field under 16px when it is focused, and never zooms back out
   (owner, 2026-09-28: "I don't want the app to zoom in when I click search"). The plain
   `input { font-size: var(--fs-read) }` above loses to every class that sets a smaller size (the Director or
   actor field was 13px), so on touch screens this one wins. Keep it the last rule in this file
   (invariant 81): add new rules above it. */
@media (pointer: coarse) {
  input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="button"]):not([type="submit"]),
  textarea, select { font-size: max(16px, 1em) !important; }
}

