.browse-dd-kind { font-size: var(--fs-meta); color: var(--faint); flex: 0 0 auto; }
.browse-controls { display: flex; gap: 8px; align-items: stretch; }
.browse-sortwrap { position: relative; flex: 1 1 auto; min-width: 0; display: flex; }
.browse-soft { appearance: none; display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  min-height: 44px; padding: 0 14px; border-radius: var(--radius-field); cursor: pointer; white-space: nowrap;
