@keyframes browse-flash { 0%, 40% { background: var(--accent-soft); color: var(--accent-2); box-shadow: 0 0 0 4px var(--accent-soft); } 100% { background: transparent; box-shadow: 0 0 0 4px transparent; } }
@media (prefers-reduced-motion: reduce) { .browse-count.is-flash, .bp-sub.is-flash { animation: none; color: var(--accent-2); } }
.mnr-ages { margin-top: 16px; }
/* Browse's header: the eyebrow over a serif title (Tonight's own header keeps its small caps). */
.browse-modal .modal-hd h2 { font-family: var(--serif); font-size: var(--fs-heading); font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--ink); }

/* Browse filters: a sheet from the bottom on phones, a centred popup on wide screens. */
@media (min-width: 700px) {
