.fdisc-aud-i span { font-size: var(--fs-label); color: var(--muted); line-height: 1.4; }
.fdisc-aud-i.on { background: var(--select-fill); box-shadow: inset 0 0 0 1.5px var(--select-edge); }
.fdisc-aud-i:disabled { opacity: .55; cursor: default; }
/* Not seen yet (rule 574, mockups/discussion-unseen.png B): the takes blurred under one choice. */
.fdisc-veil { filter: blur(7px); opacity: .55; pointer-events: none; user-select: none; max-height: 60vh; overflow: hidden; }
.fdisc-veil-wrap { position: relative; min-height: 260px; }
.fdisc-gate { position: absolute; inset: 0; z-index: 2; display: flex; flex-direction: column; align-items: center; justify-content: flex-start; gap: 10px; text-align: center; padding: 64px 16px 0; }
.fdisc-gate p { margin: 0; font-size: var(--fs-meta); line-height: 1.45; color: var(--muted); max-width: 260px; }
.fdisc-gate b { display: block; font-size: var(--fs-ui); color: var(--ink); margin-bottom: 2px; }
.fdisc-gate-btn { appearance: none; border: 1px solid var(--line-2); background: var(--panel-2); color: var(--ink); font: 600 var(--fs-ui)/1 var(--sans); border-radius: var(--btn-r); padding: 10px 16px; cursor: pointer; }
.fdisc-scroll { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 0 16px; }
.fdisc-empty, .fdisc-note { color: var(--faint); font-size: var(--fs-meta); padding: var(--sp-24) 0; text-align: center; margin: 0; }
.fdisc-empty-panel { padding: var(--sp-16) 0; }
.fdisc-note { padding: 12px 0; }
.fdisc-take { display: flex; gap: 12px; padding: 14px 0; border-bottom: 1px solid var(--line); }
.fdisc-av { flex: none; width: 34px; height: 34px; font-size: var(--fs-meta); object-fit: cover; }
.fdisc-av.fdisc-av-sm { width: 24px; height: 24px; font-size: 10px; } /* type scale exception: initials or a glyph in a fixed box */
.fdisc-tb, .fdisc-rep-b { flex: 1; min-width: 0; }
.fdisc-top { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.fdisc-nm { font-weight: 700; font-size: var(--fs-ui); color: var(--ink); text-decoration: none; }
.fdisc-nm:hover { text-decoration: underline; text-underline-offset: 3px; }
.fdisc-st { color: var(--accent-2); font-size: var(--fs-meta); }
.fdisc-dt { color: var(--faint); font-size: var(--fs-label); }
.fdisc-tx { margin: 4px 0 0; font-size: var(--fs-ui); line-height: 1.5; color: var(--ink); white-space: pre-wrap; overflow-wrap: anywhere; }
.fdisc-spoiler { appearance: none; display: flex; flex-direction: column; align-items: flex-start; gap: 4px; margin-top: 6px; padding: 0; background: none; border: 0; cursor: pointer; font: inherit; max-width: 100%; }
.fdisc-spoiler-bar { display: block; max-width: 100%; background: var(--line); color: transparent; border-radius: 4px; padding: 2px 8px; font-size: var(--fs-ui); white-space: nowrap; overflow: hidden; user-select: none; }
.fdisc-spoiler-lbl { font-size: var(--fs-label); color: var(--faint); }
.fdisc-acts { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.fdisc-rx { appearance: none; display: inline-flex; align-items: center; gap: 4px; min-height: 28px; padding: 0 8px; border-radius: var(--radius-card);
  border: 1px solid var(--line-2); background: rgba(255,255,255,.05); color: var(--ink); font: inherit; font-size: var(--fs-meta); cursor: pointer; }
.fdisc-addrx { appearance: none; display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; border-radius: var(--radius-card);
  background: none; border: 1px solid var(--line); color: var(--faint); cursor: pointer; padding: 0; }
.fdisc-addrx:hover { color: var(--ink); border-color: var(--line-2); }
.fdisc-pick { display: inline-flex; gap: 2px; padding: 2px; border: 1px solid var(--line-2); border-radius: 12px; background: var(--panel-2); }
.fdisc-pick-e { appearance: none; background: none; border: 1px solid transparent; border-radius: 8px; font-size: var(--fs-read); line-height: 1; padding: 4px 6px; cursor: pointer; }
.fdisc-pick-e:hover { background: rgba(255,255,255,.06); }
.fdisc-pick-e.on { background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); }
.fdisc-rx span { font-size: var(--fs-label); font-weight: 600; color: var(--muted); }
.fdisc-rx.on { background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); opacity: 1; }
.fdisc-rx.on span { color: var(--ink); font-weight: 600; }
.fdisc-reply, .fdisc-morereps, .fdisc-link { appearance: none; background: none; border: 0; padding: 0; font: inherit; font-size: var(--fs-meta); font-weight: 600; color: var(--muted); cursor: pointer; }
.fdisc-reply { margin-left: 6px; }
.fdisc-thread { margin-top: 10px; border-left: 2px solid var(--line); padding-left: 12px; display: flex; flex-direction: column; gap: 8px; }
.fdisc-rep { display: flex; gap: 8px; }
.fdisc-rep .fdisc-nm { font-size: var(--fs-meta); }
.fdisc-rep .fdisc-tx { margin-top: 1px; font-size: var(--fs-meta); }
.fdisc-morereps { align-self: flex-start; font-size: var(--fs-meta); }
.fdisc-menu-wrap { position: relative; margin-left: auto; }
.fdisc-more { appearance: none; background: none; border: 0; color: var(--faint); font-size: var(--fs-label); letter-spacing: 1px; padding: 2px 4px; cursor: pointer; }
.fdisc-more:hover { color: var(--ink); }
.fdisc-menu { position: absolute; right: 0; top: 100%; z-index: 2; display: flex; flex-direction: column; min-width: 190px; padding: 4px;
  background: var(--bg); border: 1px solid var(--line); border-radius: 8px; box-shadow: 0 10px 24px rgba(0,0,0,.5); }
.fdisc-menu button { appearance: none; background: none; border: 0; text-align: left; padding: 8px 10px; border-radius: 6px; font: inherit; font-size: var(--fs-meta); color: var(--ink); cursor: pointer; }
.fdisc-menu button:hover { background: rgba(255,255,255,.06); }
.fdisc-menu button.danger { color: var(--danger); }
.fdisc-comp { flex: none; border-top: 1px solid var(--line); padding: 10px 16px calc(12px + env(safe-area-inset-bottom)); display: flex; flex-direction: column; gap: 8px; }
.fdisc-comp-mine { font-size: var(--fs-meta); color: var(--muted); text-align: center; }
.fdisc-comp-quiet { color: var(--faint); font-size: var(--fs-meta); text-align: center; }
.fdisc-comp-hd { display: flex; justify-content: space-between; font-size: var(--fs-label); color: var(--muted); }
.fdisc-comp-row { display: flex; align-items: flex-end; gap: 8px; }
.fdisc-input { flex: 1; min-width: 0; min-height: 34px; max-height: 120px; box-sizing: border-box; resize: none; field-sizing: content;
  background: var(--bg); border: 1px solid var(--line-2); border-radius: var(--radius-field); padding: 6px 12px; color: var(--ink); font: inherit; font-size: var(--fs-read); line-height: 1.3; outline: none; }
.fdisc-input:focus { border-color: var(--faint); }
.fdisc-post { appearance: none; flex: none; min-height: 34px; padding: 0 16px; border: 0; border-radius: var(--radius-field); background: var(--ink); color: var(--bg);
  font: inherit; font-size: var(--fs-ui); font-weight: 700; cursor: pointer; }
.fdisc-post:disabled { opacity: .5; cursor: default; }
.fdisc-post:active:not(:disabled) { transform: scale(.98); }
.fdisc-tog { display: inline-flex; align-items: center; gap: 8px; font-size: var(--fs-label); color: var(--faint); cursor: pointer; align-self: flex-start; }
.fdisc-tog input { position: absolute; opacity: 0; pointer-events: none; }
.fdisc-tog-i { width: 28px; height: 16px; border-radius: 999px; background: var(--line-2); position: relative; transition: background .15s; }
.fdisc-tog-i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--faint); transition: transform .15s, background .15s; }
.fdisc-tog input:checked + .fdisc-tog-i { background: var(--select-deep); }
.fdisc-tog input:checked + .fdisc-tog-i::after { transform: translateX(12px); background: var(--ink); }
.fdisc-tog input:focus-visible + .fdisc-tog-i { outline: 2px solid var(--accent-2); outline-offset: 2px; }
.fdisc-err { margin: 0; font-size: var(--fs-meta); color: var(--danger); }
/* Discussion v1 A (owner-approved 2026-11-05, mockups/journeys/discussion-v1.html; rule 1123): no
   dashed box around the empty panel and a smaller poster; a new take's field carries the viewer's
   rating as a straight cream stamp at its left; Friends ▾ and Spoiler on one 26px line, set in to
   the field's text. The red dash sits under "Discussion" in the kicker (rules 1107, 1127). */
.fdisc-empty-panel .empty-panel { border: 0; padding: var(--sp-8) var(--sp-16); }
.fdisc-empty-panel .empty-posters-one, .fdisc-empty-panel .empty-posters-one .empty-poster { width: 34px; height: 51px; }
.fdisc-empty-panel .empty-title { margin-top: var(--sp-12); font-size: var(--fs-heading); }
.fdisc-empty-panel .empty-line { margin-top: var(--sp-8); font-size: var(--fs-ui); }
.fdisc-field { flex: 1; min-width: 0; display: flex; align-items: center; background: var(--bg); border: 1px solid var(--line-2); border-radius: var(--radius-field); }
.fdisc-field:focus-within { border-color: var(--faint); }
.fdisc-field .fdisc-input { border: 0; background: none; }
.fdisc-field.has-stamp .fdisc-input { padding-left: 8px; }
.fdisc-stamp { flex: none; margin-left: 12px; font: 600 var(--fs-meta)/1 var(--serif); color: var(--ink); background: var(--bg); border: 1.5px solid color-mix(in srgb, var(--ink) 55%, transparent); border-radius: 3px; padding: 3px 5px 2px; }
.fdisc-opts { height: 26px; gap: 14px; padding-left: 13px; }
.fdisc-aud-pill { height: 26px; padding: 0 9px 0 8px; border-radius: 8px; gap: 5px; }

/* Movie night, owner-approved mockup (2026-09-30, rules 122 and 125): faces in a grid of four, the
   room's live mood tally, the vote as Tonight's slim alternate rows, THE ROOM chat. */
.mnr-seats.mnr-seats-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px 8px; justify-items: center; max-width: 360px; }
.mnr-seats-grid .mnr-seat { width: 100%; max-width: 72px; }
.mnr-seats-grid .mnr-seat-name { max-width: 100%; }
.mnr-seat-more { cursor: pointer; }
.mnr-seat-more .friend-av { background: var(--panel-2) !important; border: 1px solid var(--line-2); color: var(--muted); font-family: var(--sans); font-size: var(--fs-meta); font-weight: 700; }
.mnr-tally-card { margin-top: 14px; padding: 10px 12px 12px; border: 1px solid var(--line); border-radius: 12px; background: var(--panel); }
.mnr-tally-k { display: flex; align-items: center; justify-content: space-between; gap: 10px; font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em;
  text-transform: uppercase; font-weight: 700; color: var(--faint); margin-bottom: 8px; min-height: 18px; }
.mnr-tally-k .mnr-each { font-family: var(--sans); letter-spacing: 0; text-transform: none; padding: 0; }
.mnr-tally { display: flex; flex-wrap: wrap; gap: 6px; }
.mnr-tchip { font: 600 var(--fs-meta)/1 var(--sans); padding: 6px 10px; border-radius: 999px; background: var(--accent); color: var(--bg); border: 0; }
.mnr-tchip small { font-size: var(--fs-label); opacity: .8; margin-left: 4px; font-weight: 700; }
.mnr-tchip.mine, .tn-tag.on.mine { box-shadow: inset 0 0 0 1.5px var(--ink); }
.mnr-tally-set { color: var(--faint); margin-top: 4px; }
.mnr-each-list { margin-top: 10px; display: flex; flex-direction: column; gap: 8px; border-top: 1px solid var(--line); padding-top: 10px; }
.mnr-each-row { display: flex; align-items: center; gap: 10px; }
.mnr-each-who { flex: none; width: 72px; font-size: var(--fs-meta); font-weight: 600; color: var(--ink); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mnr-status.mnr-won { margin: 4px 0 0; }
.mnr-thread-list { display: flex; flex-direction: column; gap: 2px; }
.mnr-thread-empty { font-size: var(--fs-meta); color: var(--faint); padding: 8px 0; }
.mnr-msg-av { width: 26px !important; height: 26px !important; flex: none; font-size: var(--fs-label); }
.mnr-msg-rated { display: inline-block; font-size: var(--fs-label); border: 1px solid var(--line-2); border-radius: 999px; padding: 1px 7px; color: var(--accent-2); margin-right: 6px; vertical-align: 1px; }
.mnr-msg-t { color: var(--ink); }
.mnr-sys { font-size: var(--fs-label); color: var(--faint); text-align: center; padding: 4px 0; }
/* The composer, like iMessage (rule 230): one pill field with a round blue ↑ inside its right end. */
.mnr-compose { display: flex; gap: 8px; margin-top: 8px; }
.chat-pill { flex: 1; min-width: 0; display: flex; align-items: center; gap: 6px; border: 1px solid var(--line-2); border-radius: 22px; background: var(--panel); padding: 4px 4px 4px 14px; }
.chat-pill:focus-within { border-color: var(--chat-me); }
.mnr-compose-in { flex: 1; min-width: 0; height: 34px; border: 0; background: none; color: var(--ink); font: inherit; font-size: var(--fs-read); padding: 0; outline: none; }
.mnr-compose-go { flex: none; width: 32px; height: 32px; padding: 0; border-radius: 50%; border: 0; background: var(--chat-me); color: #fff; display: grid; place-items: center; cursor: pointer; }
.mnr-compose-go:disabled { opacity: .4; cursor: default; }
/* The room's Chat button (owner, 2026-09-30: "a little more noticeable, maybe slightly larger"):
   46px like a main button, a bubble icon, and the "on" blue once there is something new, with the
   count in a cream badge that pops each time it goes up. */
.mnr-chat-pill { position: fixed; right: 16px; bottom: calc(16px + env(safe-area-inset-bottom)); z-index: 60; display: inline-flex; align-items: center; gap: 8px;
  height: 46px; padding: 0 var(--sp-16) 0 15px; border-radius: 999px; background: #232326; border: 1px solid var(--faint); color: var(--ink); font: 700 var(--fs-ui)/1 var(--sans); cursor: pointer;
  box-shadow: 0 8px 24px rgba(0,0,0,.5); transition: transform .12s ease; }
.mnr-chat-pill:active { transform: scale(.97); }
.mnr-chat-pill.is-new { background: #1d2a38; border-color: var(--accent); }
.mnr-chat-pill b { min-width: 22px; height: 22px; padding: 0 6px; display: inline-flex; align-items: center; justify-content: center; margin-right: -6px;
  background: var(--ink); color: var(--bg); border-radius: 999px; font: 800 var(--fs-meta)/1 var(--sans); font-variant-numeric: tabular-nums; animation: mnrBadgePop .32s ease; }
@keyframes mnrBadgePop { 0% { transform: scale(.6); } 60% { transform: scale(1.15); } 100% { transform: scale(1); } }
@media (prefers-reduced-motion: reduce) { .mnr-chat-pill b { animation: none; } }
.mnr-chat-scrim { position: fixed; inset: 0; z-index: 70; background: rgba(0,0,0,.45); display: flex; align-items: flex-end; justify-content: center; }
.mnr-chat-drawer { width: 100%; min-height: 50vh; max-height: 72vh; display: flex; flex-direction: column; background: var(--panel); border-top: 1px solid var(--line-2);
  border-radius: var(--radius-drawer) var(--radius-drawer) 0 0; padding: 6px 16px calc(14px + env(safe-area-inset-bottom)); }
.mnr-chat-drawer .mnr-thread-list { flex: 1; min-height: 120px; overflow-y: auto; }
.mnr-chat-grab { align-self: center; width: 40px; height: 5px; border-radius: 3px; background: var(--line-2); border: 0; padding: 0; margin: 4px 0 8px; cursor: pointer; }
.mnr-chat-h { display: flex; align-items: center; justify-content: space-between; padding-bottom: 6px; border-bottom: 1px solid var(--line); margin-bottom: 6px; }
@media (min-width: 700px) {
  .mnr-chat-scrim { align-items: flex-end; justify-content: flex-end; padding: 16px; background: rgba(0,0,0,.25); }
  .mnr-chat-drawer { width: 380px; height: min(620px, calc(100vh - 32px)); max-height: none; border: 1px solid var(--line-2); border-radius: var(--radius-drawer); padding-bottom: 14px; }
  .mnr-chat-grab { display: none; }
}

/* The public film page opened from a share link (?from=<handle>, invariant 127). */
.fd-gate-shared { margin: 0 0 10px; font-size: var(--fs-ui); line-height: 1.45; color: var(--ink); }
.fd-gate-shared b { font-weight: 700; }
.fd-gate-match { color: var(--accent-2); font-weight: 700; }

/* Share sheet: a close ×, and the apps in their own brand marks (owner, 2026-09-30). */
.share-sheet-film { position: relative; padding-right: 44px; }
.share-sheet-x { position: absolute; top: 0; right: 0; }
/* A drawer's × sits in the drawer's own top-right corner, never the screen's (owner-approved 2026-11-06;
   rule 1155). A × that is the panel's own child (Films that define you, Film DNA's strand, a post's
   comments) had no positioned ancestor but the full-screen backdrop, so it drew at the top right of the
   screen, over the page and far from a centred desktop sheet. The panel holds it now, 16 in from its top
   and right edges as the people sheet's (.fp-close) and the archetype sheet's, and it rides the swipe
   down with the panel (rule 1141). A × inside a header row stays in that row. */
.share-sheet:has(> .share-sheet-x) { position: relative; }
.share-sheet > .share-sheet-x { top: var(--sp-16); right: var(--sp-16); z-index: 2; }
.lp-sheet-h .share-sheet-x { position: static; flex: none; margin-left: auto; }
.share-tile-i.share-brand { border: 0; }
/* The brands' own discs, as on a home screen (rule 717; the iPhone's BrandFill): Messages' green,
   Instagram's gradient, TikTok and X on black with the app's outline. */
.share-brand-msg { background: linear-gradient(180deg, #5bf675, #0cbd2a); }
.share-brand-ig { background: radial-gradient(circle at 30% 107%, #feda75 0%, #fa7e1e 25%, #d62976 50%, #962fbf 75%, #4f5bd5 100%); }
.share-brand-x, .share-brand-tt { background: #000; box-shadow: inset 0 0 0 1px var(--line-2); }

/* THE GROUP'S THREAD (invariant 130): movie night's room chat on the group page, plus film cards
   sent from the share sheet. Cards keep 8px corners; the card's actions are Compact buttons. */
.gth { margin-top: 14px; }
.gth-list { gap: 4px; padding-bottom: 14px; }
/* The newest row lands above the sticky message bar and its fade, not under them (the last
   Reply was cut off, owner 2026-09-30). */
.gth-end { scroll-margin-bottom: calc(96px + env(safe-area-inset-bottom)); }
.gth-sys-film { appearance: none; background: none; border: 0; padding: 0; font: inherit; color: var(--muted); text-decoration: none; cursor: pointer; }
.gth-sys-film:hover { color: var(--ink); }
.gth-card { position: relative; margin-top: 6px; box-sizing: border-box; width: 100%; }
.gth-card-ph { display: block; object-fit: cover; border-radius: 4px; background: var(--line); font-size: var(--fs-label); color: var(--faint); padding: 6px; overflow: hidden; }
/* No tab bar on a group page: the Thread tab ends at its composer, which keeps the home-bar inset. */
.gth-act { appearance: none; display: inline-flex; align-items: center; justify-content: center; min-height: 34px; padding: 0 12px; border-radius: var(--radius-card);
  border: 1px solid var(--line-2); background: var(--panel-2, var(--panel)); color: var(--ink); font: 600 var(--fs-meta)/1 var(--sans); cursor: pointer; }
.gth-act.on { background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); color: var(--ink); }
.gth-act:disabled { opacity: .6; cursor: default; }
.gth-replying { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: var(--fs-meta); color: var(--muted); margin-top: 8px; }
/* The composer is a solid band at the very bottom: it used to float 8px up with nothing behind
   it, so the thread showed through and under it on a phone (owner, 2026-09-30). */
.gf-st-avg { font-style: normal; font-size: var(--fs-label); color: var(--faint); }
.gth-compose { position: sticky; bottom: 0; z-index: 2; background: var(--bg); padding: 10px 0 calc(10px + env(safe-area-inset-bottom)); margin-top: 8px;
  box-shadow: 0 -14px 14px -2px var(--bg); }
/* Members' logs in the thread (invariant 130): digest rows, standout lines, reactions, the Logs switch. */
.gth-top { display: flex; justify-content: flex-end; margin-bottom: 6px; }
.gth-log-mini { display: flex; flex-direction: column; align-items: center; gap: 2px; width: 34px; }
.gth-log-mini img, .gth-log-mini .gth-card-ph { display: block; width: 34px; height: 51px; object-fit: cover; border-radius: 3px; background: var(--line); font-size: 7px; padding: 2px; } /* type scale exception: initials or a glyph in a fixed box */
.gth-log-stars { font-size: var(--fs-label); color: var(--accent-2); white-space: nowrap; }
.gth-log-list { display: flex; flex-direction: column; gap: 6px; width: 100%; max-width: 440px; padding: 6px 0; }
.gth-log-film { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px; font-size: var(--fs-meta); }
.gth-log-ft .yr { color: var(--faint); font-size: var(--fs-label); }
.share-sheet-note { width: 100%; height: 40px; border-radius: var(--radius-field); border: 1px solid var(--line-2); background: var(--panel); color: var(--ink); font: inherit; font-size: var(--fs-read); padding: 0 12px; margin: 0 0 10px; box-sizing: border-box; }

/* Group chat rows (ChatRows; INVARIANTS 125, 130): mine right in an accent bubble, theirs left in a
   panel bubble with their name over a run; system lines centred and quiet; time lines between gaps. */
.chat-list { gap: 2px; }
.chat-time { text-align: center; font-size: var(--fs-label); color: var(--faint); padding: 10px 0 4px; }
.chat-sys { text-align: center; padding: 2px 12px; }
.chat-sys .mnr-sys { display: inline; padding: 0; }
/* iMessage (owner-approved mockup feed-imessage, 2026-10-02; rule 230): theirs grey on the left
   with their face beside a run's last bubble, mine blue on the right with no face. A run groups
   tight; the tail bubble gets the tail corner, a bubble inside a run a softer top corner. */
.chat-row { display: flex; align-items: flex-end; gap: 8px; }
.chat-row.head { margin-top: 8px; }
.chat-row.mine { flex-direction: row-reverse; }
.chat-av { flex: none; width: 28px; }
.chat-av .mnr-msg-av { width: 28px !important; height: 28px !important; }
.chat-row.mine .chat-av { display: none; }
.chat-col { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; min-width: 0; max-width: min(78%, 440px); }
.chat-row.mine .chat-col { align-items: flex-end; }
.chat-name { font-size: var(--fs-label); font-weight: 600; color: var(--faint); padding: 0 12px 1px; }
.chat-bubble { padding: 8px 12px; border-radius: 18px; background: var(--chat-them); font-size: var(--fs-ui); line-height: 1.3; color: var(--ink); overflow-wrap: anywhere; max-width: 100%; }
.chat-row.theirs:not(.head) .chat-bubble { border-top-left-radius: 8px; }
.chat-row.theirs.tail .chat-bubble { border-bottom-left-radius: 5px; }
.chat-row.mine .chat-bubble { background: var(--chat-me); color: #fff; }
.chat-row.mine:not(.head) .chat-bubble { border-top-right-radius: 8px; }
.chat-row.mine.tail .chat-bubble { border-bottom-right-radius: 5px; }
.chat-row.mine .chat-bubble .mention { color: #fff; text-decoration: underline; }
.chat-bubble .mnr-msg-rated { margin: 0 6px 0 0; }
.chat-row.mine .chat-bubble .mnr-msg-rated { color: rgba(255,255,255,.75); }
.chat-row .gth-card { margin-top: 0; width: 100%; }
.chat-row .chat-col:has(> .chat-logcard) { max-width: min(88%, 440px); }
/* Compact log pills (invariant 130): one slim line per member per log day, on their side. */
.chat-row .chat-col:has(> .gth-pill-wrap) { max-width: min(80%, 420px); }
.chat-row.mine .chat-col:has(> .gth-pill-wrap) { align-items: flex-end; }
.gth-pill-wrap { display: flex; flex-direction: column; gap: 6px; max-width: 100%; }
.gth-pill { appearance: none; display: inline-flex; align-items: center; gap: 8px; max-width: 100%; padding: 5px 10px 5px 5px; border-radius: 12px; border: 1px solid var(--line); background: var(--panel); color: var(--muted); font: 400 var(--fs-meta)/1.25 var(--sans); cursor: pointer; text-align: left; }
.chat-row.mine .gth-pill { border-color: var(--accent); background: var(--accent-soft); }
.gth-pill:hover { border-color: var(--line-2); }
.gth-pill-t { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gth-pill-t b { color: var(--ink); font-weight: 600; }
.gth-pill-p { display: block; flex: none; width: 26px; height: 39px; object-fit: cover; border-radius: 3px; background: var(--line); }
.gth-pill-strip { display: flex; gap: 3px; flex: none; }
.gth-pill-s { flex: none; font-size: var(--fs-label); color: var(--accent-2); white-space: nowrap; font-weight: 400; }
b.gth-pill-s, b.gth-log-stars { font-weight: 700; color: var(--ink); }
.gth-pill-more, .gth-pill-rx { flex: none; font-size: var(--fs-label); color: var(--faint); white-space: nowrap; }
.gth-pill-wrap .gth-log-list { padding: 2px 4px 0; }
.gth-logs-sw { display: inline-flex; align-items: center; gap: 8px; font-size: var(--fs-label); color: var(--muted); cursor: pointer; }
.pm-switch.gth-sw { width: 34px; height: 20px; }
.pm-switch.gth-sw .pm-switch-knob { width: 14px; height: 14px; }
.pm-switch.gth-sw.on .pm-switch-knob { transform: translateX(14px); }
.gpage-rule { height: 0; border-top: 1px solid var(--line); margin: var(--sp-24) 0; }
.gpage-rule + .gpage-tabs { margin-top: 0; }
/* The group's faces: at most five, overlapping by 8px with a ring of the page between, then +N,
   and the member count beside them (owner, 2026-09-30). */
.gpage-faces { display: inline-flex; align-items: center; }
.gpage-faces .gpage-av { position: relative; border-radius: var(--radius-sm); border: 0; box-shadow: 0 0 0 2px var(--bg); }
.gpage-faces .gpage-av + .gpage-av { margin-left: -8px; }
.gpage-faces .gpage-av-more { z-index: 0; font-size: var(--fs-label); }
@media (max-width: 640px) { .gpage-avatars .gpage-av-count { display: inline; } }

/* @mentions (invariant 134): the picker above a composer, and a mention in text. */
.mention-wrap { position: relative; flex: 1; min-width: 0; display: flex; }
.mention-wrap > input, .mention-wrap > textarea { flex: 1; min-width: 0; }
.mention-list { position: absolute; left: 0; right: 0; bottom: calc(100% + 6px); z-index: 5; display: flex; flex-direction: column; padding: 4px;
  background: var(--panel-2); border: 1px solid var(--line-2); border-radius: 12px; box-shadow: 0 10px 28px rgba(0,0,0,.45); max-height: 240px; overflow-y: auto; }
.mention-opt { appearance: none; display: flex; align-items: center; gap: 10px; width: 100%; padding: 7px 8px; border: 0; border-radius: 8px; background: none;
  color: var(--ink); font: inherit; font-size: var(--fs-ui); text-align: left; cursor: pointer; }
.mention-opt.on, .mention-opt:hover { background: rgba(255,255,255,.07); }
.mention-av { flex: none; width: 26px; height: 26px; font-size: var(--fs-label); object-fit: cover; }
.mention-nm { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mention-h { color: var(--faint); font-size: var(--fs-label); }
.mention-note { flex: none; color: var(--faint); font-size: var(--fs-label); }
.mention { color: var(--accent-2); font-weight: 600; text-decoration: none; }
.mention:hover { text-decoration: underline; text-underline-offset: 3px; }

/* Social's group list as a list of chats (invariant 135). */
.comm-group-card { padding: 12px; }
.comm-group-card .friend-meta { flex: 1; min-width: 0; }
.comm-g-faces { display: flex; }
.comm-g-faces img, .comm-g-faces i { width: 24px; height: 24px; border-radius: var(--radius-sm); border: 0; box-shadow: 0 0 0 2px var(--panel-2); margin-left: -8px; object-fit: cover;
  display: grid; place-items: center; font: 700 10px/1 var(--sans); font-style: normal; color: var(--bg); box-sizing: border-box; } /* type scale exception: initials or a glyph in a fixed box */
.comm-g-faces > :first-child { margin-left: 0; }
.comm-g-faces i.more { background: var(--line-2); color: var(--ink); }

/* The Report tab's period title and Share button, and the sharing setting (invariants 135, 136). */
/* "Our taste" / "This month": larger, with room above and below (owner-approved mockup A, 2026-09-30). */
.grp-share-btn { display: inline-flex; align-items: center; gap: 6px; height: 34px; padding: 0 12px; border-radius: 12px; border: 1px solid var(--line-2);
  background: var(--panel); color: var(--ink); font: 600 var(--fs-meta)/1 var(--sans); cursor: pointer; }
.grp-share-btn svg { color: var(--accent); }
.grp-sharing { display: flex; align-items: center; gap: 12px; padding: 14px 0; margin-top: 10px; border-top: 1px solid var(--line); }
.grp-sharing-t { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.grp-sharing-t b { font-size: var(--fs-ui); }
.grp-sharing-t span { font-size: var(--fs-meta); color: var(--muted); }
.grp-sharing .pm-switch:disabled { opacity: .45; cursor: not-allowed; }
.share-sheet-grp { display: grid; place-items: center; font-family: var(--serif); font-weight: 600; color: var(--bg); }
.share-sheet-card.share-sheet-card-story { aspect-ratio: 4 / 5; width: auto; max-width: 260px; height: min(40vh, 325px); margin-left: auto; margin-right: auto; }

/* Add friends picker: the "Not friends yet" divider and the @handle beside a display name. */
.mn-people-h { margin: 10px 0 4px; }
.mn-person-handle { color: var(--muted); font-weight: 400; }

/* "Our taste" on the Report tab and the public /g/<id>/taste page (invariant 142): the archetype
   mix bar, Film DNA bars (public page), the films that define the group, how in sync it is. */
.gtaste { display: flex; flex-direction: column; gap: 10px; margin: 14px 0 6px; }
.gtaste-mix { display: flex; flex-direction: column; gap: 6px; margin-top: 10px; }
.gtaste-bar { display: flex; height: 8px; border-radius: 4px; overflow: hidden; background: var(--line); }
.gtaste-bar i { display: block; height: 100%; }
.gtaste-mixl { display: flex; justify-content: flex-start; column-gap: 14px; row-gap: 4px; flex-wrap: wrap; font-size: var(--fs-label); color: var(--faint); }
.gtaste-mixl span { white-space: nowrap; display: inline-flex; align-items: center; }
.gtaste-mixl i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; }
.gtaste-k { font: 600 var(--fs-label)/1 var(--sans); letter-spacing: .14em; text-transform: uppercase; color: var(--faint); margin-top: 14px; }
.gtaste-films { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; max-width: 360px; }
.gtaste-film { appearance: none; padding: 0; border: 1px solid var(--line-2); border-radius: var(--radius-sm); background: var(--panel); overflow: hidden; aspect-ratio: 2 / 3; cursor: pointer; }
.gtaste-film img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gtaste-film span { display: block; padding: 4px; font-size: var(--fs-label); color: var(--muted); }
/* Group thread log pills: posters open the film; the expanded list stays inside the pill's width. */
.gth-pill-pb { appearance: none; flex: none; padding: 0; border: 0; background: none; cursor: pointer; line-height: 0; border-radius: 3px; }
.gth-pill-wrap .gth-log-list { max-width: 320px; gap: 8px; }
.gth-pill-wrap .gth-log-film { flex-direction: column; align-items: stretch; gap: 4px; }
.gth-log-row { display: flex; align-items: center; gap: 8px; min-width: 0; }
.gth-log-row .gth-log-ft { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-align: left; }
.gth-log-row .gth-log-stars { flex: none; margin-left: auto; font-size: var(--fs-label); }
.gth-pill-wrap .fdisc-acts { margin-top: 0; padding-left: 30px; gap: 4px; }
/* Share sheet group tiles (Sent state and "+ New group" included) are rounded squares (invariant 142). */
.share-tile-i.share-tile-av, .share-tile-i.share-tile-sq { border-radius: var(--radius-sm); }
/* A friend in Send to is a round face; groups stay rounded squares (rule 567). */
.share-tile-i.share-tile-av.share-tile-dm { border-radius: var(--radius-av); object-fit: cover; }

/* Most divisive (owner, 2026-09-30: "cut off, wasting empty space"): each side's label sits on its
   own line, the handles wrap instead of truncating, and the card uses its height. */
.gf-div .gf-side { flex-wrap: wrap; row-gap: 4px; margin-top: 12px; }
.gf-div .gf-side .gf-k { width: 100%; }
.gf-div .gf-names { white-space: normal; overflow: visible; display: block; -webkit-line-clamp: unset; }
.gf-div .gf-poster { width: 96px; height: 144px; }
.gf-div .gf-spread { margin-top: 14px; }

/* The weekly rhythm (LatelyCard.tsx WeeklyRhythm, INVARIANTS 145): private, owner only. */
.rhythm { border: 1px solid var(--line); background: var(--panel); border-radius: var(--radius); padding: 14px; min-width: 0; }
/* The Friday nudge in Activity (StreakNudge.tsx). */

/* ON YOUR WATCHLISTS (invariant 148; owner-approved mockup A, 2026-09-30): films on at least two
   members' own watchlists, as a poster strip above the group list. Counts only ("You + 2"). */
.grp-ov { margin-bottom: var(--sp-24); }
.grp-ov-strip { display: flex; align-items: stretch; gap: 12px; overflow-x: auto; scrollbar-width: none; padding: 2px 2px 6px; margin-top: 8px; }
.grp-ov-tile { flex: 0 0 118px; display: flex; flex-direction: column; }
.grp-ov-open { display: flex; flex-direction: column; gap: 3px; padding: 0; background: none; border: 0; text-align: left; color: inherit; cursor: pointer; font: inherit; }
.grp-ov-poster { width: 118px; aspect-ratio: 2 / 3; object-fit: cover; border-radius: var(--radius-sm); border: 1px solid var(--ink); filter: var(--grade); display: block; }
.grp-ov-noposter { display: grid; place-items: center; padding: 8px; font: 600 var(--fs-meta)/1.2 var(--serif); color: var(--faint); background: var(--panel-2); text-align: center; }
.grp-ov-who { align-self: flex-start; margin-top: 6px; font: 700 var(--fs-label) var(--sans); letter-spacing: .04em; color: var(--accent-2); background: var(--accent-soft); border: 1px solid var(--accent); border-radius: 999px; padding: 3px 9px; cursor: pointer; }
.grp-ov-who:hover { background: rgba(91,143,196,.24); }
/* Same look, a tap area of about 37px (owner, 2026-10-02): the 21px chip sat 6px under the poster,
   so taps opened the film. An invisible 8px halo above the poster's edge takes the tap. */
.grp-ov-who { position: relative; z-index: 1; }
.grp-ov-who::after { content: ""; position: absolute; inset: -8px -10px; }
.grp-ov-t { font: 600 var(--fs-ui)/1.2 var(--serif); color: var(--ink); margin-top: 3px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.grp-ov-meta { font-size: var(--fs-label); color: var(--faint); }
.grp-ov-meta b { color: var(--accent-2); font-weight: 600; }
.grp-ov-seen { font-size: var(--fs-label); color: var(--faint); min-height: 14px; margin-bottom: 6px; }
/* Every tile's button on one line, however long the title (owner, 2026-09-30: "unbalanced"). */
.grp-ov-add { margin-top: auto; height: 34px; border-radius: var(--radius-card); background: rgba(255,255,255,.05); border: 1px solid var(--line-2); color: var(--ink);
  font: 600 var(--fs-meta) var(--sans); cursor: pointer; display: grid; place-items: center; }
.grp-ov-add:hover { border-color: var(--faint); background: rgba(255,255,255,.09); }
.grp-ov-add.on { background: var(--select); border-color: var(--select); color: var(--bg); cursor: default; }

/* Who has it on their watchlist (invariant 148): the members who saved it first, then the rest faded. */
.gwl-who-list { display: flex; flex-direction: column; }
.gwl-who-row { display: flex; align-items: center; gap: 12px; padding: 8px 0; border-bottom: 1px solid var(--line); }
.gwl-who-row.is-not { opacity: .55; }
.gwl-who-b { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.gwl-who-b b { font-size: var(--fs-ui); font-weight: 600; color: var(--ink); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gwl-who-b span { font-size: var(--fs-label); color: var(--faint); }
.gwl-who-pct { display: flex; flex-direction: column; align-items: flex-end; }
.gwl-who-pct b { font-size: 16px; font-weight: 600; color: var(--accent-2); }
.gwl-who-pct i { font-style: normal; font-size: 11px; letter-spacing: .12em; text-transform: uppercase; color: var(--faint); }
.gwl-who-acts { margin-top: 14px; }
.gwl-who-acts .btn { width: 100%; }
/* Compact (owner, 2026-09-30: "a little more compact"): 24px faces, 38px columns. */
.gwl-face-av { display: grid; place-items: center; border-radius: 6px; border: 1px solid rgba(255,255,255,.3); object-fit: cover; font: 600 var(--fs-meta) var(--serif); color: var(--bg); flex: none; }
.gwl-face-s { font-size: var(--fs-label); line-height: 1.2; font-weight: 700; color: var(--accent-2); }

/* SERIES & SPECIALS at the bottom of Films and Watchlist (invariant 114; owner-approved mockup,
   2026-09-30): closed by default, a count, one line, then the posters with what each one is. */
.wl-series { margin-top: var(--sp-24); padding-top: 14px; border-top: 1px solid var(--line); }
.wl-series-h { width: 100%; display: flex; align-items: center; justify-content: space-between; background: none; border: 0; padding: 4px 0; cursor: pointer; color: var(--ink); font: inherit; }
.wl-series-k { font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; font-weight: 700; color: var(--muted); display: inline-flex; align-items: center; gap: 8px; }
.wl-series-k b { font-size: var(--fs-label); letter-spacing: 0; color: var(--faint); border: 1px solid var(--line-2); border-radius: 999px; padding: 1px 7px; font-weight: 600; }
.wl-series-chev { color: var(--faint); font-size: var(--fs-card); }
.wl-series-note { margin: 4px 0 12px; font-size: var(--fs-meta); color: var(--faint); }
.wl-series-grid .lib-poster { position: relative; }
.wl-series-tag { position: absolute; left: 6px; bottom: 6px; font-size: var(--fs-label); font-weight: 700; letter-spacing: 0; text-transform: none; color: var(--ink);
  background: rgba(11,11,13,.82); border: 1px solid var(--line-2); border-radius: var(--radius-sm); padding: 2px 6px; }

/* Our watchlist, layout A (owner-approved mockup, 2026-09-30): poster, title, a quiet line, the group's
   number on the right, everyone's face across, Remove behind •••. */
.gwl-r-title { appearance: none; border: 0; padding: 0; background: none; text-align: left; cursor: pointer; font: 600 var(--fs-card)/1.2 var(--serif); color: var(--ink); }
.gwl-r-title span { font: 400 var(--fs-meta) var(--sans); color: var(--faint); }
.gwl-r-pct { appearance: none; background: none; border: 1px solid transparent; border-radius: var(--radius-sm); padding: 2px 4px; display: flex; flex-direction: column; align-items: flex-end; align-self: start; cursor: pointer; font: inherit; }
.gwl-r-pct b { font-size: 20px; font-weight: 600; color: var(--accent-2); text-decoration: underline dotted; text-underline-offset: 3px; text-decoration-thickness: 1px; } /* type scale exception: match % numerals */
.gwl-r-pct i { font-style: normal; font-size: 11px; letter-spacing: .12em; text-transform: uppercase; color: var(--faint); }
.gwl-r-pct.is-wait b { text-decoration: none; color: var(--faint); }
.gwl-r-more { position: absolute; right: 0; top: 56px; }
.gwl-r-dots { appearance: none; background: none; border: 0; padding: 4px; color: var(--faint); font-size: var(--fs-meta); letter-spacing: 1px; cursor: pointer; }
.gwl-r-menu { position: absolute; right: 0; top: 26px; z-index: 5; background: var(--bg); border: 1px solid var(--line-2); border-radius: var(--radius-field); padding: 4px; box-shadow: 0 10px 24px rgba(0,0,0,.5); }
.gwl-r-menu { display: flex; flex-direction: column; }
.gwl-r-menu button { appearance: none; background: none; border: 0; padding: 9px 12px; font: 600 var(--fs-meta) var(--sans); color: #e28b8b; white-space: nowrap; cursor: pointer; border-radius: 8px; text-align: left; }
.gwl-r-menu button.is-go { color: var(--ink); }
.gwl-r-menu button:disabled { opacity: .6; cursor: default; }
.gwl-r-menu button:hover { background: rgba(255,255,255,.06); }

/* Press and hold (rule 152): a message, take or reply held for a moment dims the page, shows the
   item on its own with the five reactions above and its actions below. Report lives only here. */
.hold-able { -webkit-user-select: none; user-select: none; -webkit-touch-callout: none; }
.hold-scrim { position: fixed; inset: 0; z-index: 1100; background: rgba(0,0,0,.6); backdrop-filter: blur(3px); -webkit-backdrop-filter: blur(3px); }
.hold-box { position: fixed; display: flex; flex-direction: column; align-items: flex-start; gap: 8px; }
.hold-box.is-mine { align-items: flex-end; }
.hold-rx { display: flex; gap: 2px; padding: 5px 6px; background: var(--panel); border: 1px solid var(--line-2); border-radius: 999px; box-shadow: 0 10px 30px rgba(0,0,0,.5); }
.hold-rx-e { appearance: none; border: 0; background: none; width: 42px; height: 42px; border-radius: 50%; font-size: var(--fs-heading); line-height: 1; cursor: pointer; }
.hold-rx-e:hover { background: rgba(255,255,255,.06); }
.hold-rx-e.on { background: var(--select-fill); box-shadow: inset 0 0 0 1.5px var(--select-edge); }
.hold-preview { max-width: 100%; pointer-events: none; }
.hold-preview .chat-bubble, .hold-preview .hold-card { box-shadow: 0 10px 30px rgba(0,0,0,.55); }
.hold-card { display: block; max-width: 100%; padding: 10px 12px; border-radius: 12px; background: var(--panel); border: 1px solid var(--line-2); font-size: var(--fs-ui); line-height: 1.4; color: var(--ink); overflow-wrap: anywhere; }
.hold-card b { display: block; font-size: var(--fs-label); color: var(--muted); font-weight: 600; margin-bottom: 3px; }
.hold-acts { display: flex; flex-direction: column; min-width: 210px; background: var(--panel); border: 1px solid var(--line-2); border-radius: var(--radius-field); overflow: hidden; box-shadow: 0 10px 40px rgba(0,0,0,.6); }
.hold-act { appearance: none; border: 0; background: none; text-align: left; padding: 12px 16px; font: 500 var(--fs-ui)/1.2 var(--sans); color: var(--ink); cursor: pointer; }
.hold-act + .hold-act { border-top: 1px solid var(--line); }
.hold-act:hover { background: var(--panel-2); }
.hold-act.is-danger { color: #db858a; }
/* Reactions under a message, as under a take: only those with counts, yours in blue; tap toggles. */
.msg-rx { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 2px; }
.msg-rx .fdisc-rx { min-height: 24px; padding: 0 7px; font-size: var(--fs-meta); }
.chat-row.mine .msg-rx { justify-content: flex-end; }
.report-quote { display: inline-block; max-width: 100%; }
.report-reasons { display: flex; flex-direction: column; gap: 8px; }
.report-reason { flex: none; text-align: left; padding: 11px 14px; }
.report-block { display: flex; align-items: center; gap: 10px; margin-top: 14px; font-size: var(--fs-meta); color: var(--muted); }
.report-actions { margin-top: 16px; }
.chat-hold { max-width: 100%; display: flex; flex-direction: column; }
.chat-row.mine .chat-hold { align-items: flex-end; }
.gth-card-hold { width: 100%; max-width: 440px; }
/* Double tap: the ❤️ pops over the item and fades (rule 152). */
.hold-able { position: relative; touch-action: manipulation; }
.hold-heart { position: absolute; left: 50%; top: 50%; font-size: var(--fs-title); line-height: 1; pointer-events: none; transform: translate(-50%, -50%) scale(.4); opacity: 0;
  animation: holdHeart .7s ease-out forwards; filter: drop-shadow(0 2px 6px rgba(0,0,0,.5)); }
@keyframes holdHeart { 0% { opacity: 0; transform: translate(-50%, -50%) scale(.4); } 25% { opacity: 1; transform: translate(-50%, -50%) scale(1.15); } 60% { opacity: 1; transform: translate(-50%, -60%) scale(1); } 100% { opacity: 0; transform: translate(-50%, -85%) scale(.9); } }
@media (prefers-reduced-motion: reduce) { .hold-heart { animation-duration: .01s; } }
.mnr-chat-note { font-size: var(--fs-label); color: var(--faint); text-align: center; margin: 8px 0 2px; }

/* Our watchlist, mockup B (owner, 2026-09-30: "do your suggestions"): sort chips, the Up next card,
   then compact rows with one face stack each. */
.gwl-chips-row { display: flex; gap: 8px; flex-wrap: wrap; margin: 12px 0 14px; }
.gwl-chipbtn { appearance: none; padding: 7px 13px; border-radius: 999px; border: 1px solid var(--line-2); background: none; font: 600 var(--fs-meta)/1 var(--sans); color: var(--muted); cursor: pointer; }
.gwl-chipbtn.on { background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); color: var(--ink); }
@media (max-width: 700px) { .gwl-chipbtn { font-size: var(--fs-ui); padding: 9px 14px; } }
.gwl-next-card { position: relative; display: flex; gap: 14px; padding: 14px; margin: 4px 0 16px; border: 1px solid var(--line-2); border-radius: 12px; background: var(--panel); box-shadow: 4px 4px 0 var(--shadow); }
.gwl-next-card .gwl-stack { margin: 9px 0 12px; }
.gwl-next-card .gwl-r-more { position: absolute; top: 10px; right: 10px; }
.gwl-stack { appearance: none; border: 0; background: none; padding: 0 0 0 3px; display: inline-flex; cursor: pointer; }
.gwl-stack-f { margin-left: -3px; border-radius: var(--radius-sm); box-shadow: 0 0 0 2px var(--bg); display: inline-flex; }
.gwl-next-card .gwl-stack-f { box-shadow: 0 0 0 2px var(--panel); }
.gwl-stack-f .gwl-face-av { font-size: var(--fs-label); border-radius: 6px; }
.gwl-stack-f.is-seen { opacity: .38; }
.gwl-rows { display: flex; flex-direction: column; }
.gwl-c { display: flex; gap: 12px; align-items: flex-start; padding: 12px 0; border-top: 1px solid var(--line); }
.gwl-c-poster { appearance: none; border: 0; padding: 0; background: none; cursor: pointer; flex: none; }
.gwl-c-poster img, .gwl-c-poster .act-av { display: block; width: 46px; height: 69px; object-fit: cover; border-radius: 4px; border: 1px solid rgba(239,232,218,.55); filter: var(--grade); }
.gwl-c-main { flex: 1; min-width: 0; }
.gwl-c-sub { font-size: var(--fs-meta); color: var(--muted); margin: 3px 0 7px; }
.gwl-c-side { display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }
.gwl-c-side .gwl-r-more { position: relative; right: auto; top: auto; }
.gpage-err { margin: 10px 0 0; display: flex; justify-content: space-between; align-items: center; gap: 10px; }

/* Joining a group by its invite link, the invite link and the group name (rule 156). */
.gjoin { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 10px; padding: var(--sp-24) var(--sp-16) var(--sp-24); margin-top: 14px;
  border: 1px solid var(--line); border-radius: var(--radius); background: var(--panel); }
.gjoin-eyebrow { font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; color: var(--muted); }
.gjoin-photo { width: 72px; height: 72px; border-radius: var(--radius-sm); object-fit: cover; display: flex; align-items: center; justify-content: center;
  font-family: var(--serif); font-size: var(--fs-title); color: var(--bg); }
.gjoin-name { font-family: var(--serif); font-size: var(--fs-title); line-height: 1.1; margin: 2px 0 0; }
.gjoin-members { display: flex; align-items: center; gap: 10px; }
.gjoin-count { font-size: var(--fs-meta); color: var(--muted); }
.gjoin-sub { font-size: var(--fs-meta); line-height: 1.45; color: var(--muted); margin: 4px 0 0; max-width: 34ch; }
.gjoin-btn { margin-top: 8px; min-width: 180px; }
.ginvite { display: flex; flex-direction: column; gap: 8px; padding: 14px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); margin: 12px 0 0; }
.ginvite-t { display: flex; flex-direction: column; gap: 2px; font-size: var(--fs-ui); }
.ginvite-t span { font-size: var(--fs-meta); color: var(--muted); }
.ginvite-url { font-size: var(--fs-meta); color: var(--ink); background: var(--panel-2); border: 1px solid var(--line); border-radius: var(--radius-sm);
  padding: 8px 10px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ginvite-acts { display: flex; gap: 8px; flex-wrap: wrap; }
.ginvite-acts .btn { flex: 1 1 0; min-width: 0; }
.ginvite-acts .ginvite-reset { color: var(--muted); }
.gname-k { font-size: var(--fs-label); letter-spacing: .08em; text-transform: uppercase; color: var(--muted); }
/* Edit group (rule 162): the profile's Edit profile button, opposite Back; one sheet. */
/* Edit group matches the Back pill beside it: same 34px height, type and radius (owner 2026-09-30). The
   row carries the spacing Back used to, so the two sit on one centre line. */
.gpage-toprow { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: var(--sp-16) 0 var(--sp-24); }
.gpage-toprow > .backlink { margin: 0; }
.btn.gpage-edit { display: inline-flex; align-items: center; gap: 6px; min-height: var(--chip-h); padding: 0 12px; border-radius: var(--radius-pill); font-size: var(--fs-meta); font-weight: 600; line-height: 1; background: rgba(255,255,255,.05); color: var(--ink); border: 1px solid var(--line-2); }
.btn.gpage-edit:hover { border-color: var(--ink); }
.gedit { display: flex; flex-direction: column; }
.gedit .gname-k { margin-top: 14px; }
.gedit .input { margin-top: 6px; }
.gedit-photo { display: flex; align-items: center; gap: 14px; }
.gedit-photo .gpage-photo { width: 72px; height: 72px; font-size: var(--fs-title); }
.gedit-photo-acts { display: flex; flex-direction: column; align-items: flex-start; gap: 6px; }
.gedit-photo-remove { color: var(--muted); font-size: var(--fs-meta); }
.gedit-actions { display: flex; gap: 8px; margin-top: 16px; }
.gedit-actions .btn { flex: 1 1 0; }

/* The import finished card at the top of the owner's profile (rule 168). */

/* Weekly streak on the profile header (INVARIANTS 145): a small labelled card (owner-picked option A)
   that hugs its content; on a narrow phone the posters drop below the words. */
.wstreak { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; margin: 10px 0 0; padding: 8px 12px; background: var(--panel); border: 1px solid var(--line-2); border-radius: 12px; cursor: pointer; font: inherit; color: var(--ink); text-align: left; max-width: 100%; box-sizing: border-box; }
.wstreak-ico { color: var(--accent); flex: none; }
.wstreak-txt { display: flex; flex-direction: column; min-width: 0; }
.wstreak-n { font-size: var(--fs-ui); font-weight: 600; line-height: 1.25; white-space: nowrap; }
.wstreak-u { font-size: var(--fs-label); color: var(--faint); margin-top: 1px; line-height: 1.3; }
.wstreak-po { display: inline-flex; gap: 3px; align-items: center; }
@media (max-width: 480px) { .wstreak-po { flex-basis: 100%; padding-left: var(--sp-24); } }
.wstreak-slot { display: block; width: 18px; height: 27px; border-radius: 2px; object-fit: cover; background: var(--line); flex: none; box-sizing: border-box; }
.wstreak-slot.on { background: var(--accent); }
.wstreak-slot.now { background: transparent; border: 1px dashed var(--accent); }
.wstreak-slot.big { width: 100%; height: auto; aspect-ratio: 2 / 3; border-radius: 4px; }
.wstreak-slot.big.now { border-width: 2px; }
.wstreak-detail { padding: 4px 0 8px; }
.wstreak-weeks { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 6px; margin: 4px 0 10px; }
.wstreak-weeks div { min-width: 0; text-align: center; font-size: var(--fs-label); color: var(--faint); white-space: nowrap; }
.wstreak-weeks span { display: block; margin-top: 4px; }
.wstreak-open { display: block; width: 100%; padding: 0; border: 0; background: none; border-radius: 4px; cursor: pointer; }
.wstreak-open:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.wstreak-best { display: flex; justify-content: space-between; gap: 10px; flex-wrap: wrap; border-top: 1px solid var(--line); padding-top: 8px; font-size: var(--fs-label); color: var(--faint); }
.wstreak-note { margin: 8px 0 0; font-size: var(--fs-meta); line-height: 1.45; color: var(--muted); }
/* Desktop: the streak sits bottom right of the header, under Edit profile / Share, its bottom
   edge level with the name, handle and bio block. Mobile keeps it under the handle. */
/* Superseded (owner, 2026-09-30): the streak now sits under the bio at every width, and Sharpen
   your profile follows it full width; the header is a plain column again. */
.ph-id > .wstreak { margin-top: 10px; }

/* Phones (owner, 2026-09-30, the header mockup): the profile's buttons get their own full-width row
   under the name, handle, streak and bio, instead of squeezing in beside the avatar or the name. */
@media (max-width: 699px) {
  .profile-header { display: flex; flex-direction: column; }
  .profile-header > .ph-top { display: contents; }
  .profile-header .hero-avatar-wrap { order: 0; align-self: flex-start; }
  .profile-header > .ph-id { order: 1; }
  .profile-header .ph-actions-top { order: 2; width: 100%; margin-top: 12px; }
  .ph-name-row { flex-wrap: wrap; }
  .ph-actions-inline { width: 100%; margin-top: 12px; }
  .ph-actions-top .btn, .ph-actions-inline .btn { flex: 1; min-height: 34px; }
}

/* Group photo badge = the profile photo's pencil badge (owner, 2026-09-30). */
.gpage-photo-cam { width: 26px; height: 26px; right: -6px; bottom: -6px; border-radius: var(--radius-sm); background: var(--panel-2); border: 1px solid var(--line-2); color: var(--accent-2); box-shadow: 0 6px 14px -4px rgba(0,0,0,.7); }

.gjoin-eyebrow b { color: var(--ink); font-weight: 600; letter-spacing: .04em; text-transform: none; }
.gjoin-later { margin-top: 2px; color: var(--muted); font-size: var(--fs-meta); }
.ginvited-sub { color: var(--muted); }
.mnr-inviter { color: var(--ink); font-weight: 600; letter-spacing: .04em; text-transform: none; }

/* ============================================================================================
   ONE BANNER SYSTEM (owner-approved 2026-09-30, invariant 174; app/_components/Banner.tsx).
   One shell: --panel, 1px --line-2, 8px corners. Optional eyebrow (10px tracked caps, --faint)
   with a 7px context dot: blue = you, red = movie night, green = done. Serif title 18px/600,
   body 13px/1.45 --muted. At most one cream Main and one Secondary, both Compact (34px, 10px
   corners). Never a blue fill. The x (30px, top right) only when it closes without an answer.
   A Prompt (text), B Nudge (56px media), C Alert (one line, 22px status circle).
   Named exceptions: CanonBanner, the WelcomeTour sheet, empty states, toasts.
   ============================================================================================ */
.bnr { position: relative; display: flex; gap: 14px; align-items: flex-start; margin: 0 0 16px; padding: 14px 16px;
  background: var(--panel); border: 1px solid var(--line-2); border-radius: var(--radius); color: var(--ink); }
.bnr-closable .bnr-body { padding-right: 24px; }
.bnr-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.bnr-ey { display: flex; align-items: center; gap: 7px; margin-bottom: 2px; font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em;
  text-transform: uppercase; font-weight: 700; color: var(--faint); line-height: 1.2; }
.bnr-dot { flex: none; width: 7px; height: 7px; border-radius: 50%; background: var(--accent); }
.bnr-dot-night { background: var(--shadow); box-shadow: 0 0 0 1px rgba(224,82,92,.55); }
.bnr-dot-done { background: var(--ok); }
.bnr-dot.is-live { animation: bnrPulse 1.8s ease-out infinite; }
@keyframes bnrPulse { 0% { box-shadow: 0 0 0 0 rgba(224,82,92,.6); } 70% { box-shadow: 0 0 0 7px rgba(224,82,92,0); } 100% { box-shadow: 0 0 0 0 rgba(224,82,92,0); } }
.bnr-t { font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; line-height: 1.25; color: var(--ink); overflow-wrap: anywhere; }
.bnr-p { font-size: var(--fs-meta); line-height: 1.45; color: var(--muted); }
.bnr-p b { color: var(--ink); font-weight: 600; }
.bnr-row { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 8px; }
.bnr-media { flex: none; width: 56px; line-height: 0; }
.bnr-media img, .bnr-poster { display: block; width: 56px; aspect-ratio: 2 / 3; border-radius: var(--radius-sm); border: 1px solid var(--line-2);
  object-fit: cover; background: var(--panel-2); filter: var(--grade); }
.bnr-media img.bnr-icon { aspect-ratio: 1; height: 56px; filter: none; border-radius: var(--radius-field); }
.bnr-x { position: absolute; top: 8px; right: 8px; width: 30px; height: 30px; display: grid; place-items: center; padding: 0;
  border: 0; border-radius: var(--radius-card); background: transparent; color: var(--faint); font: 400 var(--fs-card)/1 var(--sans); cursor: pointer; }
.bnr-x:hover { color: var(--ink); background: rgba(255,255,255,.06); }
/* Buttons: the button system's Compact size. Main is cream; secondary takes the Compact rule above. */
.bnr-main { min-height: var(--chip-h); padding: 0 14px; border-radius: var(--radius-pill); border: 1px solid var(--ink); background: var(--ink); color: var(--bg);
  font: 700 var(--fs-meta) var(--sans); line-height: 1; cursor: pointer; text-decoration: none; }
.bnr-main:hover:not(:disabled) { filter: brightness(1.05); }
.bnr-main:active:not(:disabled), .bnr-sec:active:not(:disabled) { transform: scale(.98); }
.bnr-main:disabled, .bnr-sec:disabled { opacity: .5; cursor: default; }
.bnr-sec { appearance: none; font-family: var(--sans); }
.bnr-sec.danger { color: var(--danger); }

/* C. Alert: one line, a 22px status circle, an optional trailing action or x. */
.bnr-alert { position: relative; display: flex; align-items: center; gap: 10px; margin: 12px 0; padding: 10px 14px; min-height: 44px;
  border: 1px solid var(--line-2); border-radius: var(--radius); background: transparent; font-size: var(--fs-ui); line-height: 1.35; color: var(--ink); text-align: left; }
.bnr-alert .bnr-x { position: static; flex: none; margin: -6px -8px -6px 0; }
.bnr-ic { flex: none; width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; font: 800 var(--fs-meta)/1 var(--sans); color: var(--bg); }
.bnr-alert-info .bnr-ic { background: var(--accent); }
.bnr-alert-warn .bnr-ic { background: var(--warn); }
.bnr-alert-success .bnr-ic { background: var(--ok); }
.bnr-alert-error .bnr-ic { background: var(--err); }
.bnr-alert-t { flex: 1; min-width: 0; }
.bnr-alert-a { flex: none; margin-left: auto; }
.bnr-alert-a .linkbtn, .bnr-alert-a a { color: var(--muted); font-weight: 600; font-size: var(--fs-meta); text-decoration: none; white-space: nowrap; }
.bnr-alert-t a { color: var(--accent-2); font-weight: 600; text-decoration: none; }
@media (prefers-reduced-motion: reduce) { .bnr-dot.is-live { animation: none; } }

/* Uses. */
.bnr.dyw { align-items: center; }
.dyw .bnr-p { color: var(--ink); }
.bnr.is-done { opacity: .85; transition: opacity .3s; }
.impdone-n { color: var(--ink); }
.impdone-n span { color: var(--muted); }
/* Movie night live card: the faces stand in for the poster. */
.mn-open-faces { display: grid; grid-template-columns: repeat(2, 26px); gap: 4px; width: 56px; }
.mn-open-face { position: relative; display: block; line-height: 0; }
.mn-open-faces .friend-av { width: 26px; height: 26px; min-width: 26px; font-size: var(--fs-label); display: grid; place-items: center; object-fit: cover; }
.mn-open-face.here::after { content: ""; position: absolute; right: -1px; bottom: -1px; width: 8px; height: 8px; border-radius: 50%; background: var(--ok); box-shadow: 0 0 0 2px var(--panel); }
.mn-open-more { grid-column: span 2; font-size: var(--fs-label); color: var(--muted); line-height: 1.4; }
/* Web app banner: phones only, an overlay above the tab bar after a moment of value. When Tonight's
   button is in that strip it sits at the top instead (.is-top), so it never covers the button. */
.hs-tip-overlay { position: fixed; left: 12px; right: 12px; bottom: calc(60px + env(safe-area-inset-bottom, 0px)); z-index: 49;
  animation: hsTipIn .22s var(--ease) both; }
.hs-tip-overlay.is-top { top: calc(12px + env(safe-area-inset-top, 0px)); bottom: auto; z-index: 61; }
.hs-tip.bnr { margin: 0; box-shadow: 0 12px 32px -8px rgba(0,0,0,.8); }
@keyframes hsTipIn { from { opacity: 0; transform: translateY(10px); } }
@media (prefers-reduced-motion: reduce) { .hs-tip-overlay { animation: none; } }
@media (min-width: 760px) { .hs-tip-overlay { display: none; } }
.hs-steps { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.hs-steps span { display: inline-flex; align-items: center; gap: 6px; padding: 4px 8px; border: 1px solid var(--line-2); border-radius: var(--radius); font-size: var(--fs-label); color: var(--muted); }
.hs-steps svg { color: var(--accent-2); }
/* Profile setup on the shell's tokens (its own padding, not the banner's). */
.su.bnr { display: flex; align-items: center; gap: 12px; padding: 10px 10px 10px 12px; margin: 12px 0 2px; }

/* Own profile: Share matches Edit profile (owner, 2026-10-01: like Instagram/Letterboxd); Follow on
   others' profiles stays the cream main action. */
.ph-actions .btn.ph-share, .ph-actions .btn.ph-share:hover { background: transparent; color: var(--ink); border: 1px solid var(--line-2); filter: none; }
.ph-actions .btn.ph-share:hover { border-color: var(--ink); }

/* Expanded logs: one clean line per film; hold for reactions, Reply or Open (owner-picked mockup A,
   2026-10-01). Reaction chips appear under a film only once someone has reacted. */
.gth-pill-wrap .gth-log-film { gap: 2px; padding: 3px 0; -webkit-user-select: none; user-select: none; cursor: default; }
.gth-log-rx { padding-left: 32px; }
.gth-log-rx .msg-rx { margin: 0; }

/* Watchlist faces (owner-picked mockup A, 2026-10-01): a seen face goes grey and further back; a face
   that has not seen it is full colour, on top, with a blue ring. Half-faded faces read as unclear. */
.gwl-stack-f { position: relative; }
.gwl-stack-f.is-seen { opacity: .32; filter: grayscale(1); }
.gwl-stack-f:not(.is-seen) { z-index: 1; box-shadow: 0 0 0 2px var(--bg), 0 0 0 4px var(--accent-2); }
.gwl-next-card .gwl-stack-f:not(.is-seen) { box-shadow: 0 0 0 2px var(--panel), 0 0 0 4px var(--accent-2); }
.gpage-topacts { display: inline-flex; gap: 8px; margin-left: auto; }
/* The list holds the screen's width: an unwrapped long title made it as wide as the title and the
   stars ran off the edge; now the title ends in an ellipsis and the stars stay. */
.gth-pill-wrap .gth-log-list { width: min(440px, calc(100vw - 110px)); max-width: 100%; }
.gth-pill-wrap .gth-log-film { min-width: 0; max-width: 100%; flex-wrap: nowrap; }
.gth-log-row .gth-log-ft { flex: 1 1 auto; }

/* Edit group and Share sit where a profile's Edit profile and Share do: opposite Back on a wide screen,
   a full-width row of two under the description on a phone (owner, 2026-10-01). */
.gpage-acts-phone { display: none; }
@media (max-width: 699px) {
  .gpage-acts-wide { display: none; }
  .gpage-acts-phone { display: flex; gap: 8px; margin-top: 14px; }
  .gpage-acts-phone .btn.gpage-edit { flex: 1; min-height: 40px; justify-content: center; font-size: var(--fs-ui); }
}

/* The re-import nudge's icon (rule 184): the banner's 56px media slot as a square glyph tile. */
.bnr-glyph { display: grid; place-items: center; width: 56px; height: 56px; border-radius: var(--radius-field); border: 1px solid var(--line-2);
  background: var(--panel-2); color: var(--accent-2); font: 400 var(--fs-heading)/1 var(--sans); }
.pm-lb-h { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
.pm-last-import { font-family: var(--sans); font-size: var(--fs-label); letter-spacing: 0; text-transform: none; font-weight: 400; color: var(--muted); white-space: nowrap; }

/* Streak (rule 145): one stat in the handle row beside the follower counts, the film strip and
   "N-week streak" in an oxblood pill so it reads as earned (owner picked mockup B, 2026-10-01:
   "needs to pop more"). The posters are in the sheet it opens. */
.ph-handle-row .wstreak { display: inline-flex; align-items: center; gap: 7px; width: auto; margin: 0; padding: 4px 11px 4px 7px;
  background: rgba(122, 31, 39, .28); border: 1px solid rgba(196, 74, 86, .55); border-radius: 999px; font: inherit; color: var(--ink);
  cursor: pointer; white-space: nowrap; align-self: center; }
.ph-handle-row .wstreak-n { font-size: var(--fs-ui); font-weight: 600; color: var(--ink); }
/* The pill is centred on the handle and counts beside it (owner, 2026-10-02): with the row on
   baseline the text sat at the top of the pill's taller line and the pill read low. */
.ph-handle-row:has(.wstreak) { align-items: center; }
.ph-handle-row .wstreak:hover { border-color: rgba(214, 96, 108, .85); }
.wstreak-flame { display: block; flex: none; }

/* Someone's profile under its Back button (owner, 2026-10-01: "Why is there such a big empty space
   between back button and the profile pic"): the Back's own margin is the gap, as on a group page;
   the profile's top margin and the header's top padding used to stack onto it (~50px on a phone). */
.backlink + .identity-stage, .back-row + .identity-stage { margin-top: 0; }
.backlink + .identity-stage > .profile-header { padding-top: 0; }

/* The one confirm dialog (lib/confirm.ts, ConfirmHost; owner 2026-10-01: a Montage popup, not the
   browser's). The modal surface and keyline, serif title, Cancel + the action from the button system. */
.cfm-back { position: fixed; inset: 0; z-index: 2000; display: grid; place-items: center; padding: var(--sp-24);
  background: rgba(0,0,0,.62); animation: tabFade .16s var(--ease); }
.cfm { width: min(400px, 100%); background: var(--panel); border: 1px solid var(--line-2); border-radius: var(--radius-field);
  padding: var(--sp-24) var(--sp-16) var(--sp-16); box-shadow: 0 24px 60px -20px rgba(0,0,0,.8); }
.cfm-t { margin: 0; font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; line-height: 1.25; color: var(--ink); overflow-wrap: anywhere; }
.cfm-p { margin: 8px 0 0; font-size: var(--fs-meta); line-height: 1.5; color: var(--muted); }
.cfm-row { display: flex; gap: 10px; margin-top: var(--sp-24); }
.cfm-row .btn { flex: 1; min-height: 44px; font-size: var(--fs-ui); font-weight: 600; }

/* On both your watchlists (rule 179, owner picked mockup B 2026-10-01): one number for the pair in
   blue, "88% for you both", with both splits small under it. */
.pwl-both { display: block; margin-top: 3px; font-size: var(--fs-label); line-height: 1.3; color: var(--muted); }
.mx-film .pwl-both b { display: inline; margin: 0; font-size: inherit; letter-spacing: 0; color: var(--accent-2); font-weight: 600; font-variant-numeric: tabular-nums; }
/* The two splits wrap onto two lines so the friend's number always shows (mockup B; no nowrap). */
.pwl-split { display: block; margin-top: 1px; font-size: var(--fs-label); line-height: 1.3; color: var(--faint); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
/* The streak sheet holds one row of posters and two lines: it fits them instead of the full height. */
.modal-sheet.wstreak-sheet { height: auto; }

/* The oxblood spine is 8px, down from 14px (owner, 2026-10-01: "make the oxblood spine a little less
   wide"): the profile hero, the reveal card and the group hero, with the text pulled in by the same
   6px. The share card (opengraph-image.tsx) keeps its own, sized for a thumbnail. */
.hero::before, .reveal-card::before, .grp-hero::before { width: 8px; }
.hero { padding-left: 38px; }
.reveal-card { padding-left: 32px; }
.grp-hero { padding-left: 38px; }
@media (max-width: 760px) { .hero { padding-left: var(--sp-24); } }
@media (max-width: 640px) { .grp-hero { padding-left: 24px; } .grp-hero::before { width: 8px; } }
@media (max-width: 300px) {
  .hero { padding-left: 14px; }
  .hero::before { width: 6px; }
}

/* Movie night invite, signed out (owner picked mockup C, 2026-10-01): it fills the screen. The
   room up top, how the night works in the middle, the ways in at the bottom (margin-top: auto).
   --mnr-welcome-top is the app bar and page padding above it, so the page doesn't scroll. */
.mnr.mnr-welcome { --mnr-welcome-top: 160px; display: flex; flex-direction: column; min-height: calc(100svh - var(--mnr-welcome-top)); padding-top: 12px; }
.mnr-welcome .mnr-head { margin-bottom: var(--sp-24); }
.mnr-welcome .mnr-title { font-size: 32px; } /* type scale exception: the invite's room name a size up (movienight-invite-v2 A, rule 1107) */
.mnr-welcome .mnr-seats { margin-bottom: 4px; }
.mnr-welcome-count { font-size: var(--fs-meta); color: var(--muted); margin: 6px 0 0; }
.mnr-how-h { margin: var(--sp-24) 0 14px; padding-top: var(--sp-24); border-top: 1px solid var(--line); }
.mnr-how { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; }
.mnr-how li { display: grid; grid-template-columns: 26px 1fr; gap: 12px; align-items: start; font-size: var(--fs-meta); line-height: 1.45; color: var(--muted); }
.mnr-how b { display: block; color: var(--ink); font-weight: 600; font-size: var(--fs-ui); }
/* The iPhone's number (HowItWorks): a filled cream disc, the number in the page colour (rule 1103). */
.mnr-how-n { width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; line-height: 1; color: var(--bg); background: var(--ink); }
/* Movie Night: "Share the result" (rule 1073, mockups/journeys/movienight-share-v1). The row sits under
   the decided ticket's buttons with the card's own thumbnail; the drawer shows the card as a Story or a
   Post with Share, Save image and Copy link. /mn is the landing its link opens. */
.mns-row { display: flex; align-items: center; gap: var(--sp-12); width: 100%; margin-top: var(--sp-12); padding: 10px 12px;
  border: 1.5px solid var(--ink); border-radius: 14px; background: var(--panel); color: var(--ink); text-align: left; font: inherit; cursor: pointer; }
.mns-row:active { transform: scale(.99); }
.mns-row > svg { color: var(--muted); flex: none; }
.mns-thumb { width: 40px; height: 71px; border-radius: 5px; object-fit: cover; background: var(--bg); outline: 1px solid var(--line-2); flex: none; }
.mns-row-t { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.mns-row-t b { font-family: var(--serif); font-size: var(--fs-ui); font-weight: 600; }
.mns-row-t span { font-size: var(--fs-meta); color: var(--muted); }
.mns-prev { display: flex; flex-direction: column; align-items: center; width: 100%; }
.mns-seg { margin: 0 auto 12px; }
.mns-card { display: block; border-radius: 12px; background: var(--bg); outline: 1px solid var(--line); max-width: 100%; }
.mns-card-post { width: 260px; aspect-ratio: 4 / 5; }
.mns-card-story { width: 200px; aspect-ratio: 9 / 16; }
.mns-card-none { display: grid; place-items: center; padding: var(--sp-16); text-align: center; font-size: var(--fs-meta); color: var(--muted); }
.mns-acts { display: flex; gap: var(--sp-8); margin-top: var(--sp-16); }
.mns-acts .btn { flex: 1; display: inline-flex; align-items: center; justify-content: center; gap: 6px; margin: 0; }
/* Rule 1234: the Pitch drawer's three buttons on one line each at 44, 10 at the sides, as the iPhone's
   SecondaryButtonStyle(pad: 10) (they wrapped to two lines in a 60-tall pill at 390). */
.mns-acts .btn { min-width: 0; min-height: var(--btn-h); padding: 0 10px; white-space: nowrap; }
.mns-note { margin: 10px 0 0; text-align: center; font-size: var(--fs-meta); color: var(--muted); }
/* Movie Night: How was it? (rule 1084, mockups/journeys/movienight-howwasit-v1). Right after the pick
   "Rate it after you watch"; back on the link the room asks first (the rating drawer's pair and the
   deck's stars); then the room's result and, for the host, "Ask the room how it was". Blue is the
   accent; a miss reads in cream. */
.hwi-later { display: flex; gap: var(--sp-12); align-items: flex-start; margin-top: var(--sp-12); padding: 14px; border: 1px solid var(--line-2); border-radius: 16px; background: var(--panel); }
.hwi-later-ic { width: 36px; height: 36px; border-radius: 50%; display: grid; place-items: center; flex: none; color: var(--accent-2); border: 1px solid var(--accent); background: color-mix(in srgb, var(--accent) 14%, transparent); }
.hwi-later-t { min-width: 0; }
.hwi-later-t b { display: block; font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; color: var(--ink); }
.hwi-later-t p { margin: 4px 0 0; font-size: var(--fs-meta); line-height: 1.45; color: var(--muted); }
.hwi-lk { margin-top: 8px; padding: 0; font-size: var(--fs-meta); font-weight: 600; color: var(--accent-2); background: none; border: 0; cursor: pointer; }
/* After the night, under the ticket (layout C, rule 1249; mockups/journeys/room-rate-v2): no card,
   "How was it?", your row with the film page's stars, the others sealed until yours is in. One red on the
   screen, the ticket's edge: no poster here, nothing else red. */
.hwi { margin: 0 0 var(--sp-16); scroll-margin-top: 72px; }
.hwi-q { margin: 0; font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; line-height: 1.1; color: var(--ink); }
.hwi-you { display: flex; gap: var(--sp-12); align-items: flex-start; padding: 12px 0 6px; }
.hwi-you-b { flex: 1; min-width: 0; }
.hwi-nm { font-size: var(--fs-ui); font-weight: 600; color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hwi-you .hwi-nm { margin-bottom: 8px; }
.hwi-av { width: 32px; height: 32px; flex: none; border-radius: var(--radius-av); overflow: hidden; display: inline-flex; align-items: center; justify-content: center; font-family: var(--serif); font-weight: 600; font-size: var(--fs-ui); color: #14161a; background: var(--line-2); }
.hwi-av img { width: 100%; height: 100%; object-fit: cover; }
.hwi-av.dim { opacity: .38; }
.hwi-stars { touch-action: pan-y; }
.hwi-hint { margin-top: 8px; font-size: var(--fs-meta); color: var(--faint); }
.hwi-val { display: flex; flex-direction: column; gap: 2px; margin-top: 8px; font-size: var(--fs-meta); color: var(--muted); }
.hwi-v { font-size: var(--fs-ui); font-weight: 600; color: var(--accent-2); }
.hwi-rw { display: flex; align-items: center; gap: var(--sp-12); padding: 8px 0; }
.hwi-tag { font-size: var(--fs-label); color: var(--faint); white-space: nowrap; }
.hwi-change { padding: 0; font-size: var(--fs-label); font-weight: 600; color: var(--accent-2); background: none; border: 0; cursor: pointer; }
.hwi-rt { margin-left: auto; display: inline-flex; align-items: center; gap: 8px; font-size: var(--fs-ui); font-weight: 600; color: var(--ink); white-space: nowrap; }
.hwi-seal { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 8px; border: 1px dashed var(--line-2); color: var(--muted); font-size: var(--fs-meta); font-weight: 600; }
.hwi-notyet { font-size: var(--fs-meta); font-weight: 500; color: var(--faint); }
.hwi-mini { display: inline-flex; gap: 2px; }
.fa-star-mini { width: 13px; height: 13px; font-size: 14px; line-height: 13px; text-align: center; color: var(--line-2); } /* type scale exception: star glyphs */
.fa-star-mini.on { color: var(--accent-2); }
.fa-star-mini.half { background: linear-gradient(90deg, var(--accent-2) 50%, var(--line-2) 50%); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
.hwi-meta { margin: 10px 0 0; font-size: var(--fs-meta); color: var(--muted); }
.hwi-meta b { color: var(--ink); font-weight: 600; }
.hwi-err { margin: 8px 0 0; font-size: var(--fs-meta); color: var(--ink); }
.hwi-res { padding: 0 0 8px; }
.hwi-big { margin: 0; font-family: var(--serif); font-size: var(--fs-title); font-weight: 600; line-height: 1.1; color: var(--ink); }
.hwi-n { color: var(--accent-2); }
.hwi-resub { margin: 6px 0 0; font-size: var(--fs-meta); color: var(--muted); }
.hwi-ok { color: var(--accent-2); font-weight: 600; }
.hwi-mu { color: var(--ink); font-weight: 600; }
.hwi-ask-link { display: inline-flex; align-items: center; gap: 7px; min-height: 44px; margin-top: 4px; padding: 0; font: inherit; font-size: var(--fs-ui); font-weight: 600; color: var(--accent-2); background: none; border: 0; cursor: pointer; }
.mnr .mnr-head.mnr-after { margin: 2px 0 12px; }
.mnr-after-h { margin: 0; font-family: var(--ui); font-size: var(--fs-meta); font-weight: 400; line-height: 1.4; color: var(--muted); }
.hwi-ask { display: flex; align-items: center; gap: var(--sp-12); width: 100%; text-decoration: none; margin: 0 0 var(--sp-16); padding: 12px; border: 1px solid var(--line-2); border-radius: 14px; background: var(--panel); color: var(--ink); text-align: left; font: inherit; cursor: pointer; }
.hwi-ask > svg { color: var(--muted); flex: none; }
.hwi-ask-ic { width: 36px; height: 36px; border-radius: 50%; border: 1px solid var(--line-2); display: grid; place-items: center; flex: none; }
.hwi-ask-t { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.hwi-ask-t b { font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; }
.hwi-ask-t span { font-size: var(--fs-meta); color: var(--muted); }
.mn-land { display: flex; flex-direction: column; gap: var(--sp-16); }
.mn-land-eye { font-family: var(--label); font-size: var(--fs-label); font-weight: 600; letter-spacing: 1.4px; text-transform: uppercase; color: var(--accent-2); }
.mn-land-h { margin: 0; }
.mn-land-p { margin: 0; color: var(--muted); line-height: 1.5; }
.mn-land-go { margin-top: var(--sp-8); width: 100%; }
.mn-land-err { margin: 0; color: var(--muted); font-size: var(--fs-meta); }
.mnr-welcome-in { margin-top: auto; padding-top: var(--sp-24); }
.mnr-welcome-in > .mnr-lede { margin: 0 0 16px; }
@media (min-width: 701px) {
  .mnr.mnr-welcome { min-height: 0; }
  .mnr-welcome-in { margin-top: 0; }
}

/* The landing's way in (option A, owner 2026-10-01): one solid primary button, then the import as
   a smaller secondary row under it. */
/* Hero spacing (owner, 2026-11-05, landing-v5): 12px between the button and the Letterboxd door, 16px
   to "or Explore the 14 archetypes", 14px to the chevron. The button is the offset shadow's width
   narrower than the door, so the oxblood shadow ends flush with the door's right edge and never
   sticks out past the column. */
.onboard-start { display: flex; flex-direction: column; gap: 12px; }
.onboard-start .onboard-start-btn { width: calc(100% - 6px); align-self: flex-start; min-height: var(--btn-h); font-size: var(--fs-ui); font-weight: 600; background: var(--ink); color: var(--bg); border: 1px solid var(--ink); box-shadow: var(--shadow-offset); }
.onboard-start .onboard-start-btn:hover { filter: brightness(.95); }
.onboard-import-row { appearance: none; cursor: pointer; font: inherit; text-align: left; width: 100%; display: flex; align-items: center; gap: 11px;
  padding: 10px 12px; border-radius: var(--radius); background: rgba(20,20,23,.72); border: 1px solid var(--line-2); color: var(--ink); }
.onboard-import-row:hover { border-color: var(--faint); }
.onboard-import-row-ic { flex: none; width: 32px; height: 32px; display: grid; place-items: center; }
.onboard-import-row-ic .lb-dots { width: 32px; height: 32px; } /* Letterboxd's own round badge, no tile behind it (owner, 2026-10-01) */
.onboard-import-row-m { flex: 1; min-width: 0; }
.onboard-import-row-t { display: block; font-size: var(--fs-ui); font-weight: 700; white-space: nowrap; }
.onboard-import-row-s { display: block; font-size: var(--fs-meta); color: rgba(255,255,255,.66); margin-top: 1px; line-height: 1.35; white-space: nowrap; }
/* Each line of the door holds to one line: the time goes on screens too narrow for it (the import panel says it too). */
@media (max-width: 359px) { .onboard-import-row-time { display: none; } }

/* "Share this match" carries the share icon like every other share button (owner, 2026-10-01). */
.compat-share-btn { display: inline-flex; align-items: center; gap: 8px; }

/* Streak placement A (owner, 2026-10-01): on a phone the pill wraps to its own line, 12px under the
   counts and about 22px over Follow; 4px down puts it midway. Wider screens keep it inline. */
@media (max-width: 480px) {
  /* Even spacing (owner, 2026-10-21: "spacing is bad for streak"): 12px over it (the row gap) and
     12px under it to the bio; the -4px pulled the bio up against it. */
  .ph-handle-row .wstreak { margin: 0; }
  .ph-bio { margin-top: 12px; }
}

/* The visitor's invite on a profile (CompareCta) is a Banner prompt (rule 174), under the header
   and again at the end of the profile (owner, 2026-10-01). */
.visit-bnr { margin: var(--sp-16) 0 var(--sp-24); }
.visit-bnr-end { margin: var(--sp-24) 0 var(--sp-8); }

/* The sign-in popup (AuthGateModal) is a standard PortalModal sheet sized to its form. */
.modal-sheet.auth-sheet { height: auto; max-width: 460px; }
.auth-sheet-body { padding: 4px 0 8px; }

/* A sheet is a centred card on a wide screen (701px up), so it loses the drag handle, which only
   means something on a phone (rule 146), and the short popups take the dialog's card (rule 185:
   --line-2 keyline, 16px corners) instead of a sheet's flat bottom. The sign-in form fills it. */
@media (min-width: 701px) {
  .modal.modal-sheet .modal-sheet-handle { display: none; }
  .modal.modal-sheet.auth-sheet, .modal.modal-sheet.wstreak-sheet { border: 1px solid var(--line-2); border-radius: var(--radius-drawer); padding-top: var(--sp-24); padding-bottom: var(--sp-24); }
}
.auth-sheet .signin-form { max-width: none; }

/* StatusScreen (audit 2026-10-01): not found, errors, expired links, unsubscribe. The movie night
   "gone" screen's type: tracked eyebrow, serif title, one muted line, cream main + outlined second. */
.status-screen { max-width: 480px; margin: 0 auto; padding: 56px 0 40px; display: flex; flex-direction: column; align-items: flex-start; gap: 10px; }
.status-screen .status-title { margin: 0; line-height: 1.08; text-wrap: balance; }
.status-body { margin: 0; font-size: var(--fs-ui); line-height: 1.5; color: var(--muted); max-width: 42ch; }
.status-acts { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 14px; }
.status-acts .btn { width: auto; min-height: 44px; padding: 0 var(--sp-16); display: inline-flex; align-items: center; text-decoration: none; }
@media (max-width: 480px) { .status-screen { padding-top: 40px; } .status-acts { width: 100%; } .status-acts .btn { flex: 1; justify-content: center; } }

/* About: the page is 760px wide, its lead held to 600px. */
.stage.center:has(> .about-parts) { max-width: 760px; }
.stage.center:has(> .about-parts) > .lead { max-width: 600px; margin-left: auto; margin-right: auto; }

/* THE DOCKED CHAT BAR (ChatDock; owner-approved mockup 2026-10-01, rule 209): the group feed and a
   movie night room's chat, docked along the bottom as the latest line and what's new; a tap or a
   swipe up opens the drawer (.mnr-chat-drawer). Pages that carry it leave room at the foot
   (.has-cdock) so nothing hides behind it. A computer gets it bottom-right at the drawer's width. */
.cdock-wrap { position: fixed; left: 0; right: 0; bottom: 0; z-index: 60; padding: 18px 12px calc(12px + env(safe-area-inset-bottom));
  background: linear-gradient(180deg, rgba(11,11,13,0), rgba(11,11,13,.9) 40%); pointer-events: none; }
.cdock { pointer-events: auto; width: 100%; max-width: 720px; margin: 0 auto; display: flex; align-items: center; gap: 10px; height: 56px; padding: 0 12px 0 10px;
  border: 1px solid var(--line-2); border-radius: var(--radius-field); background: var(--panel); color: var(--ink); font: inherit; text-align: left; cursor: pointer;
  box-shadow: 0 -6px 24px rgba(0,0,0,.45); transition: transform .12s ease, border-color .2s ease; }
.cdock:active { transform: scale(.99); }
.cdock.is-new { border-color: rgba(143,179,217,.6); background: #151c26; }
.cdock-lead { flex: none; width: 32px; height: 32px; border-radius: var(--radius-card); display: inline-flex; align-items: center; justify-content: center; overflow: hidden;
  background: var(--panel-raised); font: 600 var(--fs-meta)/1 var(--serif); }
.cdock-lead img { width: 100%; height: 100%; object-fit: cover; }
.cdock-ico { width: 18px; height: 18px; color: var(--accent-2); }
.cdock-tx { flex: 1; min-width: 0; font-size: var(--fs-meta); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cdock-tx b { color: var(--ink); font-weight: 600; }
.cdock-tx.is-ph { color: var(--faint); }
.cdock-n { flex: none; background: var(--accent); color: #fff; border-radius: 999px; font: 600 var(--fs-label)/1 var(--sans); padding: 5px 8px; animation: mnrBadgePop .32s ease; }
.cdock-up { flex: none; color: var(--faint); }
@media (prefers-reduced-motion: reduce) { .cdock-n { animation: none; } }
.cdock-scrim[hidden] { display: none; }
.cdock-h { gap: 10px; }
.cdock-h > :first-child { min-width: 0; }
.has-cdock, .mnr:has(> .cdock-wrap) { padding-bottom: calc(96px + env(safe-area-inset-bottom)); }
@media (min-width: 700px) {
  .cdock-wrap { left: auto; right: 16px; bottom: 16px; padding: 0; width: 380px; background: none; }
  .has-cdock, .mnr:has(> .cdock-wrap) { padding-bottom: 96px; }
}
/* The group feed inside its drawer: the list scrolls, the composer stays at the foot. */
.cdock-drawer .gth { flex: 1; min-height: 0; display: flex; flex-direction: column; margin-top: 0; }
.cdock-drawer .gth-list { flex: 1; min-height: 0; overflow-y: auto; }
.cdock-drawer .gth-compose { position: static; background: none; padding: 8px 0 0; }
.cdock-drawer .gth-top { margin-bottom: 2px; }
.cdock-title { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.cdock-title b { font: 600 var(--fs-card)/1.2 var(--serif); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cdock-title span { font-size: var(--fs-label); color: var(--muted); }
/* The feed and the room get a tall drawer on a phone (the mockup's ~90%): a chat wants the room. */
@media (max-width: 699px) { .cdock-drawer { min-height: 60vh; max-height: 88vh; height: 88vh; } }
.cdock-drawer .gth-list { display: flex; flex-direction: column; }
.cdock-drawer .gth-list > :first-child { margin-top: auto; }

/* The reveal's leaning line (rule 217) and the first picks' reason chips (rule 218). */
.rpick-why { display: inline-block; margin-top: 6px; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: var(--fs-label); font-weight: 700; letter-spacing: .02em; padding: 2px 8px; border-radius: 999px; border: 1px solid var(--line-2); color: var(--ink); }
.rpick-why.is-lead { border-color: color-mix(in srgb, var(--accent-2) 55%, transparent); color: var(--accent-2); }

/* A question card in the taste test's reel (mockup A1, 2026-10-02): the film card's shape with the
   accent edge so it reads as different; the picked state is rule 215's. Clear of the forming card. */
.ttq-slide { justify-content: center; }
.ttq-card { position: relative; z-index: 1; width: 100%; max-width: 520px; flex: 1 1 auto; min-height: 0; margin: 6px 0 14px;
  padding: var(--sp-24) var(--sp-16) var(--sp-16); border: 1px solid var(--accent); border-radius: var(--radius); background: rgba(14, 21, 32, 0.94);
  display: flex; flex-direction: column; overflow-y: auto; }
.ttq-card .tt-qprompt { text-align: left; margin: 8px 0 4px; }
.ttq-card .tt-qhint { text-align: left; margin-bottom: 14px; }
.ttq-card .tt-qopts { margin-bottom: 14px; }
.ttq-next { margin-top: auto; width: 100%; flex: none; }
.ttreel-overlay.has-ttform .ttq-slide { padding-bottom: calc(86px + env(safe-area-inset-bottom)); }

/* The reveal (mockups A1 and B1, 2026-10-02): the name at once, why it is you, an early read of
   the leans as words, picks with no %, a friend, then the save. */
.rv.rv-still *, .rv.rv-still { animation: none !important; }
.rv-name-skel { width: 62%; height: clamp(40px, 12vw, 52px); margin-left: auto; margin-right: auto; border-radius: var(--radius-sm); }
.rv-because { font-size: var(--fs-meta); color: var(--muted); margin: 10px 8px 0; line-height: 1.4; }
.rv-because b { color: var(--ink); font-weight: 600; }
.rv .rv-because { animation: rvUp 500ms ease 1300ms both; }
/* The why sits a little further from the tagline than the tagline from the name (owner, 2026-10-30,
   mockup ios-reveal-why A1); the streak under it is a small caps label in the accent. */
.rv > .rv-because { margin-top: var(--sp-16); }
.rv-streak.rv-streak-label { font-size: var(--fs-label); font-weight: 600; letter-spacing: .14em; text-transform: uppercase; margin-top: 8px; }
.rv .rv-streak-label { animation: rvUp 500ms ease 1400ms both; }
.rv-leans { margin: 24px 0 0; text-align: left; }
.rv-leans-head { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; }
.rv-leans-eye, .rv-leans-early { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .16em; text-transform: uppercase; font-weight: 600; color: var(--eyebrow); }
.rv-leans-early { color: var(--faint); }
.rv-leans-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
.rv-leanword { display: inline-flex; align-items: center; min-height: 32px; padding: 0 12px; border-radius: var(--radius-sm); border: 1px solid var(--line-2); font-size: var(--fs-meta); color: var(--ink); background: var(--panel); }
.rv-leanword.is-top { border-color: var(--accent); background: var(--accent-soft); }
.rv-leans-sub { font-size: var(--fs-label); color: var(--faint); margin-top: 8px; }
.rv .rv-picks .rpicks-eye { text-align: left; }
.rpick-title-skel { height: 10px; margin-top: 6px; border-radius: 3px; }
.rpick-saved { font-style: italic; color: var(--faint); }
.rpick.is-locked .rpick-saved { filter: none; user-select: auto; white-space: normal; }
.rv-friend { display: flex; align-items: center; gap: 12px; width: 100%; max-width: 440px; margin: 24px auto 0; padding: 12px 14px; text-align: left;
  border: 1px solid var(--line-2); border-radius: var(--radius); background: var(--panel); color: var(--ink); font: inherit; cursor: pointer; }
.rv-friend .friend-av { flex-basis: 40px; width: 40px; height: 40px; font-size: var(--fs-ui); }
.rv-friend-m { display: flex; flex-direction: column; min-width: 0; }
.rv-friend-l { font-size: var(--fs-ui); font-weight: 600; }
.rv-friend-s { font-size: var(--fs-label); color: var(--faint); margin-top: 2px; }
@media (hover: hover) { .rv-friend:hover { border-color: var(--accent); } }
.reveal-save-import { margin-top: 14px; font-size: var(--fs-meta); }

/* The top bar's Sign in, signed out (owner, 2026-10-02): the Compact button, the same 34px as the
   search pill beside it, never wider than its word. */
.btn.ghost.topbar-signin { height: var(--chip-h); width: auto; }

/* The landing's first screen (owner, 2026-10-02): the CTA module sits dead centre of the visible
   screen, both ways, on every size, and "Once you're in" only peeks (its rule and the very top of
   its eyebrow). svh is the screen with the browser's bars showing, so iOS Safari's toolbar never
   hides or moves it. The hero box ends --landing-peek above the fold and its top padding is the same
   amount, so the module's centre is the screen's. */
:root { --landing-peek: 20px; }
.wrap-landing .onboard-cine:not(.onboard-cine-form) {
  min-height: calc(100vh - var(--landing-peek)); min-height: calc(100svh - var(--landing-peek)); justify-content: center; }
.wrap-landing .onboard-cine:not(.onboard-cine-form) .onboard-cine-fg,
.wrap-landing .onboard-cine:not(.onboard-cine-form):has(.onboard-more) .onboard-cine-fg { padding-top: var(--landing-peek); padding-bottom: 0; }
.wrap-landing .onboard-cine:not(.onboard-cine-form) .onboard-cine-hero { margin: 0 auto; text-align: center; }
.wrap-landing .onboard-cine:not(.onboard-cine-form) .onboard-cine-sub { margin-left: auto; margin-right: auto; }
.wrap-landing .onboard-pillars { margin-top: 0; padding-top: 14px; }

/* "Once you're in", five reasons (owner, 2026-11-06, mockups/journeys/landing-v1-a.html and -b.html
   "Proposed"): one picture and one line each, no tiles and no rules between them. Desktop: five
   across, the pictures in one 250px band so the captions line up. Phones: stacked, each picture only
   as tall as itself. One red below the hero: the oxblood offset behind the match poster; the bottom
   button has no shadow. */
.onboard-moments { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px; max-width: 1040px; margin: var(--sp-24) auto 0; }
@media (min-width: 900px) { .onboard-moments { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: var(--sp-16); } .onboard-moment-vis { height: 250px; } }
.onboard-moment { text-align: center; min-width: 0; }
.onboard-moment-vis { display: flex; flex-direction: column; align-items: center; justify-content: center; }
.onboard-moment-cap { font: 400 var(--fs-heading)/1.25 var(--read); color: var(--ink); margin: var(--sp-16) 0 0; text-wrap: balance; }
.onboard-moment-cap2 { font: 400 var(--fs-read)/1.35 var(--read); color: var(--muted); margin: 4px 0 0; text-wrap: balance; }
.onboard-moment-arch { font: 600 var(--fs-display)/1 var(--serif); color: var(--ink); letter-spacing: -.01em; text-wrap: balance; }
@media (min-width: 900px) { .onboard-moment-arch { font-size: var(--fs-title); } }
.onboard-moment-arch small { display: block; white-space: nowrap; font: 700 var(--fs-label)/1 var(--sans); letter-spacing: .2em; text-transform: uppercase; color: var(--faint); margin-bottom: 10px; }
.onboard-moment-dna { display: flex; align-items: flex-end; justify-content: center; gap: 5px; height: 34px; margin-top: var(--sp-16); }
.onboard-moment-dna i { width: 6px; border-radius: 3px; background: var(--accent); }
.onboard-moment-dna i:nth-child(even) { background: var(--accent-2); opacity: .55; }
.onboard-moment-rated { display: flex; justify-content: center; gap: var(--sp-8); margin-top: var(--sp-16); }
.onboard-moment-rated span { display: flex; flex-direction: column; align-items: center; gap: 4px; }
.onboard-moment-rated img { display: block; width: 36px; aspect-ratio: 2 / 3; object-fit: cover; border-radius: 4px; background: var(--panel-2); outline: 1px solid rgba(239,232,218,.18); outline-offset: -1px; }
.onboard-moment-rated b { font: 600 var(--fs-label)/1 var(--sans); color: var(--accent-2); font-variant-numeric: tabular-nums; }
.onboard-moment-po { position: relative; display: block; flex: none; width: 150px; aspect-ratio: 2 / 3; border-radius: var(--radius-sm); overflow: hidden; background: var(--panel-2);
  outline: 1px solid rgba(239,232,218,.18); outline-offset: -1px; }
.onboard-moment-po img { display: block; width: 100%; height: 100%; object-fit: cover; }
.onboard-moment-po.is-sig { overflow: visible; box-shadow: var(--shadow-offset); outline-color: rgba(239,232,218,.5); }
.onboard-moment-po.is-sig img { border-radius: var(--radius-sm); }
.onboard-moment-po.is-md { width: 96px; }
.onboard-moment-po.is-xs { width: 56px; border-radius: 4px; }
/* The app's poster stamp (rules 419, 1016): black back, light-blue border and number, tilted, bottom left; larger here as display art. */
.onboard-moment-stamp, .onboard-moment-pct { background: var(--bg); border: 2px solid var(--accent); color: var(--accent-2); font: 500 var(--fs-title)/1 var(--serif);
  padding: 5px 9px 3px; border-radius: 3px; transform: rotate(-3deg); font-variant-numeric: tabular-nums; }
.onboard-moment-stamp { position: absolute; left: 10px; bottom: 10px; transform-origin: left bottom; box-shadow: 0 3px 10px rgba(0,0,0,.6); }
.onboard-moment-stamp.is-s { font-size: var(--fs-meta); left: 4px; bottom: 5px; padding: 2px 4px 1px; border-width: 1.5px; }
.onboard-moment-pct { font-size: var(--fs-display); padding: 7px 12px 4px; }
.onboard-moment-pitch { width: 300px; max-width: 100%; text-align: left; }
.onboard-moment-field { border: 1px solid var(--line-2); background: var(--panel); border-radius: 12px; padding: 12px 14px; font: 400 var(--fs-read)/1.35 var(--read); color: var(--ink); }
.onboard-moment-flab { display: block; font: 700 var(--fs-label)/1 var(--sans); letter-spacing: .16em; text-transform: uppercase; color: var(--faint); margin-bottom: 6px; }
.onboard-moment-caret { display: inline-block; width: 1.5px; height: 17px; background: var(--accent-2); vertical-align: -3px; margin-left: 1px; }
.onboard-moment-row { display: flex; justify-content: center; gap: var(--sp-8); margin-top: var(--sp-12); }
@media (min-width: 900px) { .onboard-moment-pitch { width: 100%; } }
.onboard-moment-tn { display: flex; flex-direction: column; align-items: center; gap: var(--sp-16); }
.onboard-moment-tn .tab-tonight-pill { width: 50px; height: 38px; border-radius: 14px; }
.onboard-moment-blend { display: flex; flex-direction: column; align-items: center; }
.onboard-moment-pair { display: flex; align-items: center; justify-content: center; gap: 14px; }
.onboard-moment-av { flex: none; display: inline-flex; align-items: center; justify-content: center; width: 60px; height: 60px; border-radius: var(--radius-av);
  font: 600 var(--fs-title)/1 var(--sans); box-shadow: 0 0 0 2px var(--bg); }
.onboard-moment-names { display: flex; justify-content: space-between; width: 100%; max-width: 230px; margin-top: var(--sp-8); font: 500 var(--fs-meta)/1 var(--sans); color: var(--faint); }
.onboard-moment-names span { width: 60px; text-align: center; }
@media (min-width: 900px) {
  .onboard-moment-arch small { letter-spacing: .12em; }
  .onboard-moment-blend .onboard-moment-pair { gap: var(--sp-8); }
  .onboard-moment-blend .onboard-moment-av { width: 52px; height: 52px; font-size: var(--fs-heading); }
  .onboard-moment-blend .onboard-moment-pct { font-size: var(--fs-title); }
  .onboard-moment-names { max-width: 196px; }
  .onboard-moment-names span { width: 52px; }
}
.onboard-moments-cta { max-width: 320px; margin: 40px auto var(--sp-8); }
.onboard-start.onboard-moments-cta .onboard-start-btn { width: 100%; box-shadow: none; }
/* Phones: the ghosted names keep to the band between the header and the centred module. */
@media (max-width: 759px) {
  .wrap-landing .onboard-cine:not(.onboard-cine-form) .onboard-cine-names { height: max(0px, calc(111svh - 502px)); }
}
@media (max-width: 759px) and (max-height: 640px) { .wrap-landing .onboard-cine:not(.onboard-cine-form) .onboard-cine-names { display: none; } }

/* The film's match box, first under the hero (mockup E1, 2026-10-02; rule 223), and the crowd's
   average as one small muted line under the facts. */
.fd-hero-note { font-size: var(--fs-label); color: var(--faint); margin-top: 6px; }
.fd-matchbox { margin: 14px 0 4px; padding: 14px 16px; border: 1px solid var(--line-2); border-radius: var(--radius); background: var(--panel); }
.fd-matchbox-v { font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; color: var(--ink); margin: 0 0 10px; line-height: 1.25; }
.fd-matchbox-cta { width: 100%; }
.fd-matchbox-bar { height: 4px; border-radius: 2px; background: var(--line); overflow: hidden; }
.fd-matchbox-bar i { display: block; height: 100%; background: var(--accent); border-radius: 2px; }
.fd-matchbox-s { font-size: var(--fs-label); color: var(--faint); margin-top: 8px; }
.fd-matchbox-link { color: var(--muted); font-weight: 600; text-decoration: none; }

/* An ended or dead movie-night link (mockup F1, 2026-10-02; rule 224): the three steps, then the two
   ways on at the foot where a thumb reaches, the same height. */
.mnr-ended { display: flex; flex-direction: column; min-height: calc(100svh - 150px); }
.mnr-ended-actions { margin-top: auto; padding-top: 16px; display: flex; flex-direction: column; gap: var(--sp-8); }
.mnr-ended-actions .mnr-primary { margin-top: 0; }
.mnr-ended-alt { display: flex; width: 100%; align-items: center; justify-content: center; min-height: var(--btn-h); font-size: var(--fs-ui); text-decoration: none; }

/* The cinema archetype at the top of the Taste tab (profile v2.1; rule 225), then named folds. */
.pst { margin: 14px 0 12px; }
.pst-eye { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .16em; text-transform: uppercase; font-weight: 600; color: var(--eyebrow); }
.pst-name { font-family: var(--serif); font-size: var(--fs-title); font-weight: 600; line-height: 1.05; color: var(--ink); margin-top: 4px; }
.pfolds { margin-top: 6px; }
.pfold { border-top: 1px solid var(--line); }
.pfold:last-of-type { border-bottom: 1px solid var(--line); }
.pfold-h { appearance: none; width: 100%; display: flex; align-items: baseline; justify-content: space-between; gap: 12px; padding: 16px 2px; background: none; border: 0; cursor: pointer; font: inherit; color: var(--ink); text-align: left; }
.pfold-t { font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; }
.pfold-hint { flex: none; font-size: var(--fs-meta); color: var(--faint); display: inline-flex; gap: 6px; align-items: baseline; max-width: 45%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pfold-chev { color: var(--accent-2); }
.pfold-b { padding: 0 2px var(--sp-16); }
.pfold-p { font-size: var(--fs-meta); color: var(--muted); line-height: 1.5; margin: 0 0 12px; }
.pfold-stat { font-size: var(--fs-meta); color: var(--faint); margin: 4px 2px 10px; }
.pfold-empty { font-size: var(--fs-meta); color: var(--faint); margin: 16px 2px; }
.pfold-posters { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
@media (min-width: 700px) { .pfold-posters { grid-template-columns: repeat(6, minmax(0, 1fr)); } }
.pfold-poster { appearance: none; background: none; border: 0; padding: 0; cursor: pointer; text-align: left; color: var(--muted); font: inherit; font-size: var(--fs-label); }
.pfold-poster img { display: block; width: 100%; aspect-ratio: 2 / 3; object-fit: cover; border-radius: var(--radius-sm); border: 1px solid var(--line-2); margin-bottom: 6px; }
.pfold-deep { display: flex; gap: 12px; align-items: center; }
.pfold-deep img { width: 72px; margin: 0; }

/* Person pages (owner, 2026-10-02: "the page is kinda dull"): the portrait sits on the oxblood
   offset shadow the primary buttons use. The Unseen/Seen/All toggle's chosen segment fills the
   pill to its edge, no inset ("otherwise it looks clunky"). */
.tp-portrait { box-shadow: 4px 4px 0 var(--shadow); border-color: var(--ink); margin: 0 4px 4px 0; }
@media (max-width: 900px) { .tp-portrait { width: 104px; height: 104px; } }
/* A person's header row (rule 718, owner 2026-11-03: "profile pic should be on the same line as their
   name"): the 68px photo, a rounded square (rule 142) on a 3px oxblood offset, beside the name (Title 28)
   with the role · years line under it; the stats below. The iPhone's TagPageScreen header, one for one. */
.tp-head.is-person { flex-direction: column; align-items: flex-start; gap: var(--sp-16); }
.tp-person { display: flex; align-items: center; gap: var(--sp-16); min-width: 0; max-width: 640px; }
.tp-head.is-person .tp-person .tp-portrait { width: 68px; height: 68px; border-radius: var(--radius-field); box-shadow: 3px 3px 0 var(--shadow); margin: 0 3px 3px 0; align-self: center; }
.tp-person-id { min-width: 0; display: flex; flex-direction: column; gap: var(--sp-4); }
.tp-person-id .tp-h1 { margin: 0; overflow-wrap: anywhere; }
.tp-person-line { font-size: var(--fs-meta); color: var(--muted); line-height: 1.35; }
.tp-head.is-person .tp-person .tp-portrait.skel { box-shadow: none; }
.tp-seg { padding: 0; gap: 0; overflow: hidden; }
.tp-seg .seg-btn { border-radius: 999px; padding: 8px 16px; }
/* Tag and person pages: a rule between sections (owner, 2026-10-02: "we need dividers between
   sections"), the header and its stats, the neighbours or similar directors, the ranked films. */
.tp-neighbours, .tp-neighbours.tp-similar, .tp-lane-head { border-top: 1px solid var(--line-2); padding-top: 24px; margin-top: 24px; }
.tp-neighbours + .tp-neighbours { border-top: 0; padding-top: 0; margin-top: var(--sp-16); }
/* A person page's role tabs (owner, 2026-10-09, option A): the profile's Taste / Films / Watchlist
   bar with a count on each, under the header; its underline is the rule, so what follows it adds
   none of its own. One row that scrolls sideways on a phone rather than wrapping; a side with more
   tabs past the edge fades out (the rule stays whole, it sits on the wrapper). */
.tp-roles { margin: 24px 0 0; border-bottom: 1px solid var(--line-2); }
.tp-roles-row { margin: 0; gap: var(--sp-24); flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; }
.tp-roles-row::-webkit-scrollbar { display: none; }
.tp-roles-row.fade-r { -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 36px), transparent); mask-image: linear-gradient(90deg, #000 calc(100% - 36px), transparent); }
.tp-roles-row.fade-l { -webkit-mask-image: linear-gradient(90deg, transparent, #000 36px); mask-image: linear-gradient(90deg, transparent, #000 36px); }
.tp-roles-row.fade-l.fade-r { -webkit-mask-image: linear-gradient(90deg, transparent, #000 36px, #000 calc(100% - 36px), transparent); mask-image: linear-gradient(90deg, transparent, #000 36px, #000 calc(100% - 36px), transparent); }
.tp-roles .id-tab { white-space: nowrap; flex: none; }
.tp-role-n { margin-left: 6px; font-weight: 400; letter-spacing: 0; color: var(--faint); }
.tp-roles .id-tab.on .tp-role-n { color: var(--muted); }
.tp-roles + .tp-neighbours, .tp-roles + .tp-lane-head { border-top: 0; margin-top: 0; padding-top: var(--sp-24); }
/* The same space above a rule as below it: nothing before one adds its own bottom gap. */
.tp-head .tp-stats { padding-bottom: 0; }
.tp-similar-row { padding-bottom: 0; }
.tp-lane-head { flex-direction: column; align-items: flex-start; flex-wrap: nowrap; gap: 10px; margin-bottom: 14px; }
.tp-lane-head .tp-seg { margin: 0; align-self: flex-start; }
.tp-lane-head .tile-cap { margin: 0; }
/* Less air between the name (or its blurb) and the stats under it (owner, 2026-10-02). */
.tp-head-text > :last-child { margin-bottom: 0; }
@media (max-width: 900px) { .tp-head .tp-stats { padding-top: 0; margin-top: 2px; } }
.tp-neighbours .match-tags { margin-bottom: 0; }

/* ── Profile v2.1 (owner-approved mockup, 2026-10-02; rule 225) ───────────────────────────────────
   One layout for your own profile and anyone else's: the header (and someone's match card), then
   the tabs straight under it, then the open tab. The Taste tab opens on the cinema archetype, which
   keeps the oxblood spine down its left edge, 8px as on the archetype card before it (owner,
   2026-10-02); then v1's stats, lanes, defining films, Canon, Film DNA with % and where the taste
   sits, then the folds. On a wide screen the header is one band; the Taste tab stays one column
   (owner, 2026-10-02: "one strip"). */
.pv2 { display: block; }
.pv2-head, .pv21-col { min-width: 0; }
/* Header E (owner, 2026-11-06: "E, yes to screenshot card"; mockups/journeys/profile-header-v3 E;
   rule 1219), your own profile and someone's, every width. The photo left, a 72px rounded square
   (84 until the owner's "a little too big", 2026-11-06) with one thin 1.5px ink line inside its edge
   (owner, 2026-11-06: "I liked the little white outline"; an inset outline, so the size and the row's
   centring stay put; the loading placeholder has none); your own keeps the small pencil; beside it the name in the UI face, bold at the
   card size, two lines at most, over three figures: films, followers, following, the number bold
   over its word. Under the photo, at the same left edge as the tabs and the archetype (the page's
   16px gutter, no inset of its own): the @handle muted, the bio in ink, the streak and goal as small
   neutral pills (28 tall, the meta text; the streak's reel keeps its colours, the pill loses its red),
   then two equal buttons, 34 tall, soft grey rounded rectangles. No serif in the header: Bodoni is
   the archetype's below. */
.pv2-head .profile-header.phe { display: block; padding: 0 0 4px; border-bottom: 0; margin: 0; }
.phe-top { display: flex; align-items: center; gap: var(--sp-16); min-width: 0; }
.phe .hero-avatar-wrap { flex: none; align-self: center; }
.phe .hero-avatar { width: 72px; height: 72px; border: 0; border-radius: var(--radius-av); font-size: var(--fs-title); outline: 1.5px solid var(--ink); outline-offset: -1.5px; }
.phe .hero-avatar.skel { outline: 0; }
.phe .hero-avatar-edit { right: -4px; bottom: -4px; width: 24px; height: 24px; border-color: var(--bg); }
.phe-side { flex: 1 1 auto; min-width: 0; container: phe-side / inline-size; }
.phe .ph-name { font-family: var(--ui); font-size: var(--fs-card); font-weight: 700; line-height: 1.25; letter-spacing: 0; color: var(--ink);
  white-space: normal; overflow: hidden; overflow-wrap: anywhere; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; line-clamp: 2; }
/* The three figures sit left with one fixed gap (owner, 2026-11-06: "Make them uniform, but smaller. It's too
   spread out", then "a little farther apart now, but not as far as it used to be"; rule 1219): 32 between,
   not stretched to the width; 24 under 380 or when the side column is too narrow for 32 (three "12.4k"
   figures need about 222 with 32), 16 under 360 or when 24 would not fit, so "12.4k" still fits at 320.
   Each figure is at least 44 tall to tap. */
.phe-stats { display: flex; flex-wrap: nowrap; justify-content: flex-start; gap: var(--sp-32); margin-top: 6px; }
@media (max-width: 379px) { .phe-stats { gap: var(--sp-24); } }
@container phe-side (max-width: 235px) { .phe-stats { gap: var(--sp-24); } }
@media (max-width: 359px) { .phe-stats { gap: var(--sp-16); } }
@container phe-side (max-width: 219px) { .phe-stats { gap: var(--sp-16); } }
.phe .phe-stat { appearance: none; display: flex; flex: 0 1 auto; flex-direction: column; align-items: flex-start; justify-content: center; min-width: 0; min-height: 44px; margin: 0; padding: 0; border: 0; background: none;
  font: inherit; color: var(--ink); text-align: left; cursor: pointer; }
.phe .phe-stat:disabled { cursor: default; opacity: 1; }
.phe .phe-stat b { margin: 0; font-family: var(--ui); font-size: var(--fs-read); font-weight: 500; line-height: 1.3; color: var(--ink); font-variant-numeric: tabular-nums; white-space: nowrap; }
.phe .phe-stat span { max-width: 100%; font-family: var(--ui); font-size: var(--fs-meta); font-weight: 400; line-height: 1.3; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.phe .phe-stat:not(:disabled):hover span { color: var(--ink); }
.phe > .ph-id { margin-top: var(--sp-12); }
/* Header v4 (rule 1230): the name and Founding member on one row; no handle line under the photo. */
.phe-name-row { display: flex; align-items: center; gap: var(--sp-8); min-width: 0; }
.phe-name-row .ph-name { flex: 0 1 auto; }
.phe-name-row .founding-badge { flex: none; margin-left: 0; }
.phe .ph-together + .ph-bio { margin-top: 6px; }
.phe > .ph-id:has(> .ph-streak:first-child) .ph-streak { margin-top: 0; }
/* The wireframe's pills (PageSkeletons, rule 1230): the streak's and the goal's 28px. */
.phe .phe-skel-pill { display: inline-block; width: 120px; height: 28px; border-radius: var(--radius-pill); }
.phe .phe-skel-pill + .phe-skel-pill { width: 96px; }
.phe .ph-handle-row { display: flex; align-items: center; gap: var(--sp-8); flex-wrap: wrap; margin: 0; min-width: 0; }
.phe .ph-handle-row:empty { display: none; }
.phe .ph-handle { min-width: 0; max-width: 100%; font-family: var(--ui); font-size: var(--fs-meta); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.phe .ph-handle-row .founding-badge { margin-left: 0; }
.phe .ph-together { margin-top: 6px; }
/* The bio in the UI face, as the iPhone's (owner, 2026-11-04: "I don't like the font used for the bio"), not the reading serif. */
.phe .ph-bio { margin: 2px 0 0; max-width: 480px; line-height: 1.45; font-family: var(--ui); font-size-adjust: none; }
.phe .ph-handle-row:empty + .ph-bio { margin-top: 0; }
.phe .ph-streak { margin-top: var(--sp-12); gap: 6px; }
.phe .ph-streak .wstreak, .phe .ph-streak .wstreak.is-ended { height: 28px; padding: 0 11px 0 7px; background: transparent; border: 1px solid var(--line-2); }
.phe .ph-streak .wstreak:hover { border-color: var(--faint); }
.phe .ph-streak .wstreak-n { font-size: var(--fs-meta); }
.phe .ph-streak .wstreak-flame { width: 22px; height: 14px; }
.phe .gchip, .phe .gchip-t small { font-size: var(--fs-meta); }
.phe .gchip-ring { width: 14px; height: 14px; }
.phe .gchip-plus { width: 13px; height: 13px; }
.phe .ph-actions { display: flex; gap: var(--sp-8); width: 100%; margin: var(--sp-16) 0 0; }
.pv2-head .phe .ph-actions .btn { flex: 1 1 0; min-width: 0; height: 34px; min-height: 34px; padding: 0 12px; border: 0;
  border-radius: 9px !important; /* the one rounded-rectangle pair (rule 1219): over the pill rule of 598's :is(.btn, …) */
  background: rgba(255, 255, 255, .1); color: var(--ink); font-size: var(--fs-ui); font-weight: 600; filter: none; }
.pv2-head .phe .ph-actions .btn:hover { background: rgba(255, 255, 255, .14); border-color: transparent; filter: none; }
/* Follow stays the cream one until you follow (FollowButton), then grey "✓ Following" like the pair
   (the iPhone's too), not the select tint of the "On" rule above, whose !important it has to meet. */
.pv2-head .phe .ph-actions .btn.ghost.is-on { background: rgba(255, 255, 255, .1) !important; border-color: transparent !important; box-shadow: none; }
.pv2-head .phe .ph-actions-inline .btn:not(.ghost) { background: var(--ink); color: var(--bg); }
.pv2-head .phe .ph-actions-inline .btn:not(.ghost):hover { background: var(--ink); filter: brightness(1.06); }
.phe .ph-actions .sim-toggle { border-radius: 9px; }
.phe .ph-actions .sim-toggle:not(.on) { border: 0; background: rgba(255, 255, 255, .1); }
.phe .ph-actions-inline .pa-skel .btn { flex: 1 1 0; }
.phe > .ph-actions-top + .ph-actions-inline { margin-top: var(--sp-8); }
/* A wide screen keeps the phone's order; the photo row and the buttons stop at 480px. */
@media (min-width: 760px) {
  .phe-top, .phe .ph-actions { max-width: 480px; }
}
.pv2-head > .match-pill, .pv2-head > .visit-cta, .pv2-head > * + .match-pill { margin-top: var(--sp-16); margin-bottom: 0; }
.pv2 > .id-tabbar { margin: var(--sp-24) 0 0; border-bottom: 1px solid var(--line); }

/* The archetype on the profile, unboxed (owner, 2026-10-30): no spine, no panel; the name is the hero. */
.pv2-top { margin: var(--sp-24) 0 0; padding: 0; }
.pv2-top .pst-name { font-size: var(--fs-display); line-height: 1; margin-top: 6px; letter-spacing: -.01em; }
.pv2-top .dev-pill { margin-top: 10px; }
.pv2-streaks { margin-top: 8px; }
.pv2-top .hero-mix { margin-top: 10px; }
.pv2-top .hero-blend-bar { height: 6px; padding: 0; gap: 2px; background: none; }
.pv2-links { gap: 16px; margin-top: 10px; }
/* The archetype's eyebrow, name and streak words on the oxblood spine, as the archetype sheet's
   (owner, 2026-10-31, mockups/archetype-spine-ios.html A). */
.pv2-archhead { position: relative; padding-left: 16px; }
.pv2-archhead::before { content: ""; position: absolute; left: 0; top: 2px; bottom: 2px; width: 4px; border-radius: 2px; background: var(--shadow); }
/* The mix bar and "Your mix ›" under it are one button that opens How you got it (owner,
   2026-10-31, mockups/archetype-mix-bar.html A). */
.pv2-mixwrap .pv2-links { margin-top: 12px; }
.pv2-mixwrap .sec-info, .pv2-mixwrap .sec-info-link { display: block; width: 100%; }
.pv2-mixwrap .sec-info-link { text-align: left; padding: 0; white-space: normal; color: var(--muted); font-weight: 400; }
.pv2-mixwrap .sec-info-link .hero-mix { display: block; margin: 0; max-width: none; }
.pv2-mixwrap .sec-info-link .hero-blend-bar { display: flex; height: 6px; padding: 0; gap: 2px; background: none; }
.pv2-mixline { display: flex; justify-content: space-between; align-items: center; margin-top: 8px; font-size: var(--fs-meta); color: var(--muted); }
.pv2-links .hml-link { font-weight: 600; }
.pv2-top .hero-blurb-wrap { margin-top: 12px; }
.pv2-top .hero-blurb { font-size: var(--fs-ui); line-height: 1.55; color: var(--ink); }
.pv2-taste { padding-top: 2px; }

/* v1's sections in the Taste tab: each has its heading and hairline. Films that define them at v1's
   140px, a row that swipes (owner, profile v2.1); the reason on hold, or hover on a wide screen. */
.pv2-taste .hero-facts { margin-top: var(--sp-24); }
.pv2-taste .sigframe { width: 140px; }
.pv2-taste .sigreel { margin-right: -16px; padding-right: 16px; overflow-x: auto; scrollbar-width: none; }
.pv2-taste .sigreel::-webkit-scrollbar { display: none; }
.pv2-taste .sigframe-poster { -webkit-touch-callout: none; user-select: none; -webkit-user-select: none; }
.pv2-taste .hero-defines { padding-bottom: var(--sp-16); }
.pv2-taste .hero-defines + .hero-canon { margin-top: 0; }
.pv2-taste .hero-canon { margin-bottom: 4px; }
/* The Film DNA rule sits centred between the Canon card and its heading (owner, 2026-10-02): 27px
   above it, as below (22px padding, then the heading's text 5px into its row beside the info
   button). One column on every screen now, so on desktop too. */
.pv2-taste .pv21-col > .hero-canon:last-child { margin-bottom: 27px; }
/* With no films that define them and no Canon (a taste test), the stats and lanes end the column:
   the same 27px above the Film DNA rule, not the rule against the last lane (owner, 2026-10-07). */
.pv2-taste .pv21-col > .hero-facts:last-child { margin-bottom: 27px; }
/* Film DNA: the lean's panel reads left-aligned (owner, profile v2.1); the radar and its % stay
   centred. The same panel on the group page. */
.dna-radar-detail { text-align: left; }
.dna-radar-detail .dna-detail-hint { justify-content: flex-start; }
.pv21-compare { display: block; margin: 12px auto 0; font-size: var(--fs-meta); font-weight: 600; color: var(--accent-2); }

/* The overlay (Compare with your shape, and the taste match page): their shape filled, yours a thin
   cream outline over it. */
.pv2-dna { align-items: stretch; }
.pv2-dna .dna-radar-wrap { margin-top: 4px; }
.dna-radar-you { fill: none; stroke: var(--ink); stroke-width: 1.25; stroke-linejoin: round; }
.dna-radar-dot.is-you { fill: var(--ink); }
.pv2-dna .dna-radar-label.is-active { color: var(--accent-2); font-weight: 600; }
.pv2-chips { display: flex; gap: 8px; justify-content: center; flex-wrap: wrap; margin: 0 0 6px; }
.pv2-chip { appearance: none; display: inline-flex; align-items: center; gap: 7px; height: var(--chip-h); padding: 0 12px; border: 1px solid var(--line-2); border-radius: 999px;
  background: none; font: inherit; font-size: var(--fs-meta); font-weight: 600; color: var(--ink); cursor: pointer; }
.pv2-chip.off { color: var(--faint); }
.pv2-chip.off .pv2-sw { opacity: .3; }
.pv2-sw { width: 14px; height: 10px; border-radius: 2px; }
.pv2-sw.is-them { background: color-mix(in srgb, var(--accent-2) 35%, transparent); border: 1.5px solid var(--accent-2); }
.pv2-sw.is-you { border: 1.5px solid var(--ink); }
.pv2-join { text-align: center; font-size: var(--fs-label); color: var(--muted); margin: 0 0 6px; }
.pv2-detail { max-width: none; text-align: left; margin-top: 8px; padding: 12px 14px; background: var(--panel); border-color: var(--line); }
.pv2-detail .dna-detail-name { font-size: var(--fs-heading); margin-top: 8px; }
.pv2-detail .dna-detail-note { font-family: var(--read); font-size: var(--fs-ui); line-height: 1.5; margin-top: 10px; }
.pv2-detail .dna-detail-note span { color: var(--accent-2); font-weight: 700; letter-spacing: .14em; }
.pv2-cmp { font-size: var(--fs-meta); color: var(--muted); margin: 10px 0 0; padding-top: 8px; border-top: 1px dashed var(--line); }
.pv2-cmp b { color: var(--ink); font-weight: 600; }
.pv2-detail .dna-films { margin-top: 8px; }

/* The named folds, closed until asked. In a fold, a tile drops its own box and heading. */
.pv2-taste .trait-grid { gap: 0; margin: var(--sp-24) 0 0; border-top: 1px solid var(--line); }
.pv2-taste .pfold { border-top: 0; border-bottom: 1px solid var(--line); }
.pv2-taste .pfold-h { align-items: center; padding: 15px 0; gap: 10px; justify-content: flex-start; }
.pv2-taste .pfold-t { font-size: var(--fs-read); font-weight: 500; }
.pv2-taste .pfold-hint { font-size: var(--fs-meta); max-width: none; flex: 0 1 auto; min-width: 0; }
.pv2-taste .pfold-chev { margin-left: auto; color: var(--muted); transition: transform var(--dur) var(--ease); }
.pv2-taste .pfold.is-open .pfold-chev { transform: rotate(90deg); }
.pv2-taste .pfold-b { padding: 0 0 16px; }
.pfold .tile { border: 0; padding: 0; background: none; }
.pfold .decades-tile > .tile-h, .pfold .wl > .tile-h { display: none; }
.pfold .hidden-list li { color: var(--ink); }
.pv2-tension { margin: 0 0 12px; }
.pfold .pv2-tension .tile-sub { margin: 0 0 4px; }
.pv2-tension-line { font-family: var(--read); font-size: var(--fs-read); line-height: 1.5; font-style: normal; color: var(--ink); margin: 0; }
.pfold .deepcut img { width: 74px; border-radius: var(--radius-sm); border: 1px solid var(--line-2); filter: var(--grade); }
.pfold .deepcut-t { font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; }
.pfold .deepcut .tile-sub { margin: 0 0 4px; }

/* Hot takes (owner, 2026-10-02): a fold like the others that starts open, all four takes. */
.pv21-hotfold .tile-cap { margin: 0 0 10px; }

/* Top rated genres. */
.pv2-genre-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.pv2-genre { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 12px; align-items: baseline; }
.pv2-genre-n { font-size: var(--fs-ui); color: var(--ink); }
.pv2-genre-v { font-size: var(--fs-label); color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.pv2-genre-v b { color: var(--ink); font-weight: 600; }
.pv2-genre-bar { grid-column: 1 / -1; height: 4px; border-radius: 2px; background: var(--line); overflow: hidden; }
.pv2-genre-bar i { display: block; height: 100%; border-radius: 2px; background: var(--you); }
.pv2-more { display: flex; justify-content: center; margin: var(--sp-16) 0 6px; }

/* Wide screens (desktop b, owner, profile v2.1): the header is one band, who on the left and the
   buttons (and someone's match card) on the right; the tabs run full width under it. "Sharpen your
   profile" runs under the avatar across the whole band, from the avatar's left edge to the right
   edge of Share (owner, 2026-10-02). The page is Discover's width (1040px) and the Taste tab is one
   column, the phone's order, the full width of it (owner, 2026-10-02: "one strip", "same width as
   discover"; rules 55, 225). */
@media (min-width: 1000px) {
  .wrap:has(.pv2) { max-width: 1040px; }
  /* Header E (rule 1219): the header is the phone's at every width, so no band grid here. */
  /* The taste match runs the full width under the name, follower counts and Follow, its left edge
     on the photo's (owner, 2026-10-14: "should go under the user's name and followers/following";
     "left aligned with the profile pic and empty space shouldn't look weird"). */
  .pv2-head > .match-pill, .pv2-head > .visit-cta, .pv2-head > * + .match-pill, .pv2-head > .visit-bnr { grid-column: 1 / -1; grid-row: auto; justify-self: stretch; width: auto; margin: var(--sp-16) 0 0; }
  .pv2 > .id-tabbar { margin-top: var(--sp-24); }
  .pv2-taste { max-width: none; }
  .pv2-taste .sigreel { margin-right: 0; padding-right: 0; overflow: visible; }
  .pv2-taste .sigreel-track, .pv2-taste .sigreel-frames { width: 100%; }
  .pv21-hotfold .takes-row { max-width: 640px; }
  /* Capped, not stretched to the 1040px column (owner, 2026-10-02: five across had grown to 290px
     posters and 320px faces): Films that define them at 164px, the People faces at 132px, both
     left-aligned with their phone gaps and labels (rule 225). */
  .pv2-taste .sigframe { width: 164px; }
  .pv2-taste .faces-row { grid-template-columns: repeat(5, 132px); }
}
/* A little more room between the quiz's progress bar and a question card (owner, 2026-10-02). */
.ttq-card { margin-top: 16px; }

/* The reveal's way into what the archetype means (rule 222): the tag is a button with a chevron,
   the archetype in the streak line is underlined; both open ArchetypeSheet. */
.rv-tag-link { appearance: none; background: none; border: 0; cursor: pointer; display: block; margin-left: auto; margin-right: auto; padding: 0; font: inherit; font-family: var(--serif); font-style: italic; color: var(--muted); }
.rv-tag-chev { font-family: var(--sans); font-style: normal; color: var(--accent-2); }
@media (hover: hover) { .rv-tag-link:hover { color: var(--ink); } }
.rv-streak-link { appearance: none; background: none; border: 0; padding: 0; cursor: pointer; font: inherit; color: inherit; text-decoration: underline dotted; text-underline-offset: 3px; }
.arch-sheet { align-items: stretch; text-align: left; gap: 0; }
/* The archetype sheet's head sits at the sheet's margin, no oxblood spine (owner, 2026-10-31: "we
   dont want the oxblood spine right on the archetype section"). */
.arch-sheet-head { position: relative; padding-right: 44px; padding-left: 14px; }
.arch-sheet-head::before { content: ""; position: absolute; left: 0; top: 2px; bottom: 2px; width: 4px; border-radius: 2px; background: var(--shadow); }
/* The one close control, the ✕ circle at the top right (owner, 2026-10-31). */
.arch-sheet { position: relative; }
.arch-sheet .arch-sheet-x { position: absolute; top: var(--sp-16); right: var(--sp-16); z-index: 2; }
.arch-sheet-eye { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .16em; text-transform: uppercase; color: var(--faint); font-weight: 700; }
.arch-sheet-name { font-family: var(--serif); font-size: var(--fs-title); font-weight: 600; color: var(--ink); line-height: 1.1; margin-top: 4px; }
.arch-sheet-tag { font-family: var(--serif); font-style: italic; font-size: var(--fs-read); color: var(--muted); margin-top: 2px; }
.arch-sheet-desc { font-size: var(--fs-meta); line-height: 1.5; color: var(--muted); margin: 14px 0 12px; }
.arch-sheet-all { align-self: flex-start; margin-top: 14px; color: var(--accent-2); font-weight: 600; }

/* iMessage chat (rule 230): reactions as tapbacks on the bubble's top corner, swipe right to reply,
   a reply's quote above it with a thread line down to it, "N Replies" under the original. */
:root { --chat-me: var(--accent); --chat-them: #26262c; }
.chat-tbwrap { position: relative; max-width: 100%; display: flex; flex-direction: column; }
.chat-row.mine .chat-tbwrap { align-items: flex-end; }
.chat-tbwrap.has-tb { margin-top: 14px; }
.msg-rx.msg-tb { position: absolute; top: -20px; right: -16px; z-index: 1; margin: 0; flex-wrap: nowrap; gap: 0; padding: 1px 4px; border-radius: 14px; background: #2f2f36; border: 2px solid var(--bg); }
.chat-row.mine .msg-rx.msg-tb { right: auto; left: -16px; }
.chat-row:has(> .chat-col > .chat-replies) .chat-av { margin-bottom: var(--sp-24); }
.msg-rx.msg-tb .fdisc-rx { min-height: 22px; padding: 0 3px; border: 0; background: none; font-size: var(--fs-meta); gap: 3px; }
.msg-rx.msg-tb .fdisc-rx span { font-size: var(--fs-meta); }
.msg-rx.msg-tb .fdisc-rx.on span { color: var(--ink); }
.swipe-able { touch-action: pan-y; transition: transform .2s ease-out; }
.chat-swipe-ico { position: absolute; left: -26px; top: 50%; transform: translateY(-50%); font-size: var(--fs-read); color: var(--muted); pointer-events: none; }
.chat-rq { appearance: none; position: relative; display: block; max-width: min(260px, 100%); margin: 8px 4px 6px; padding: 5px 10px; border: 1px solid var(--line-2); border-radius: 14px; background: none; color: var(--faint); font: 400 var(--fs-meta)/1.3 var(--sans); text-align: left; cursor: pointer; }
.chat-rq-t { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.chat-rq b { color: var(--muted); font-weight: 600; }
.chat-thread { position: absolute; bottom: -8px; width: 10px; height: 8px; border: 0 solid var(--line-2); pointer-events: none; }
.chat-row.mine .chat-thread { right: 16px; border-right-width: 2px; }
.chat-row.theirs .chat-thread { left: 16px; border-left-width: 2px; }
.chat-replies { appearance: none; border: 0; background: none; padding: 2px 12px 0; font: 600 var(--fs-meta)/1.2 var(--sans); color: #9db8de; cursor: pointer; }
.chat-flash .chat-bubble, .chat-flash .gth-card { animation: chatFlash 1.2s ease-out; }
@keyframes chatFlash { 0%, 30% { box-shadow: 0 0 0 3px rgba(157, 184, 222, .55); } 100% { box-shadow: 0 0 0 3px transparent; } }
/* Watch logs as slim bubbles: grey for theirs, blue for mine. */
.chat-row .gth-pill { border: 0; border-radius: 18px; background: var(--chat-them); padding: 6px 12px 6px 6px; font-size: var(--fs-meta); }
.chat-row .gth-pill:hover { border: 0; filter: brightness(1.08); }
.chat-row.mine .gth-pill { background: var(--chat-me); color: rgba(255,255,255,.8); }
.chat-row.mine .gth-pill-t b, .chat-row.mine b.gth-pill-s { color: #fff; }
.chat-row.mine .gth-pill-s, .chat-row.mine .gth-pill-more, .chat-row.mine .gth-pill-rx { color: rgba(255,255,255,.8); }
.chat-row .gth-pill-s { color: #9db8de; }

/* The profile's way into what the archetype means (rule 228, as on the reveal): the name carries the
   reveal's chevron, the archetypes in the close-behind line are in the link colour, and the
   description opens the same sheet. The oxblood spine is untouched. */
.pst-name-link { appearance: none; background: none; border: 0; padding: 0; cursor: pointer; display: block; text-align: left; font-family: var(--serif); }
.pst-name-chev { font-family: var(--sans); font-size: .55em; font-weight: 600; color: var(--accent-2); vertical-align: .18em; }
/* The name's last word and its › never part (owner, 2026-11-06: "Animation Devotee" filled the line and the ›
   wrapped alone; rule 1237): they sit in one unbreakable span, the › after a no-break space. */
.pst-name-end { white-space: nowrap; }
@media (hover: hover) { .pst-streak-link:hover { text-decoration: underline; } }
.pst-streak-link { appearance: none; background: none; border: 0; padding: 0; cursor: pointer; font: inherit; color: var(--muted); }
.hero-blurb-link { cursor: pointer; }
/* "Delivered" under my newest message, iMessage's quiet status line (rule 230). */
.chat-status { font-size: var(--fs-label); font-weight: 600; color: var(--faint); padding: 2px 4px 0; }
.chat-status-btn { appearance: none; background: none; border: 0; cursor: pointer; font-family: var(--sans); text-align: right; }
/* Search waits for the page it opens (owner, 2026-10-02): a thin bar runs along its top and the
   results hold still until the new page replaces it. */
.gs-leaving { position: absolute; top: 0; left: 0; right: 0; height: 2px; overflow: hidden; z-index: 3; }
.gs-leaving::before { content: ""; position: absolute; top: 0; bottom: 0; left: -40%; width: 40%; background: var(--accent-2); animation: gsLeaving 1s ease-in-out infinite; }
@keyframes gsLeaving { from { left: -40%; } to { left: 100%; } }
@media (prefers-reduced-motion: reduce) { .gs-leaving::before { animation: none; left: 0; width: 100%; opacity: .6; } }
.gs-modal.is-leaving .gs-combo { pointer-events: none; opacity: .75; transition: opacity .15s; }
/* Why you enjoyed it in its profile fold looks as it did as a tile (owner, 2026-10-02: "I liked the
   old why you enjoyed it when the posters selected has the oxblood shadow"): keylined posters, the
   chosen one lifted on the oxblood shadow, the film's title in the serif. */
.why-loved-fold .wl-posters { display: flex; gap: 10px; overflow: visible; padding: 2px 6px 6px 0; }
.why-loved-fold .wl-poster { width: 96px; border-radius: var(--radius-sm); border: 1px solid var(--line-2); background: var(--panel-2); box-shadow: none;
  transition: border-color var(--dur) var(--ease), box-shadow var(--dur) var(--ease), transform var(--dur) var(--ease); }
.why-loved-fold .wl-poster img { filter: var(--grade); }
.why-loved-fold .wl-poster:hover { border-color: var(--ink); }
.why-loved-fold .wl-poster.on { border-color: var(--ink); box-shadow: 4px 4px 0 var(--shadow); transform: translate(-2px, -2px); }
.why-loved-fold .wl-title { font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; line-height: 1.15; color: var(--ink); margin-bottom: 8px; }
.why-loved-fold .wl-fb-btn { background: none; border: 1px solid var(--line-2); border-radius: 2px; color: var(--ink); }
.why-loved-fold .wl-fb-btn:hover { border-color: var(--ink); background: none; }
@media (max-width: 760px) {
  .why-loved-fold .wl-posters { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .why-loved-fold .wl-poster { width: auto; }
}
/* The profile's Taste sections sit an even 24px either side of each divider (owner, 2026-10-02:
   "make the height from axes to divider above the uniform amount"): Film DNA ends 24px above the
   line, "Where your taste sits" starts 24px under it and ends 24px above the folds' line. It was
   46 / 23 / 55 (a 22px margin and a 28px one stacked on the padding). */
.pv2-taste .dna-strip { padding-bottom: 24px; }
.pv2-taste .hero-lower { margin-top: 0; padding-top: 24px; padding-bottom: 24px; }
.pv2-taste .trait-grid { margin-top: 0; }

/* Film DNA's scale (owner, 2026-10-02; rule 225): a linear radar from 5% at the centre to 20% at the
   edge. No even-split ring or key (owner, 2026-10-02: "remove"). */
/* The lean card: the rank left-aligned like the text under it, both arrows together on the right. */
.dna-radar-detail .dna-detail-nav { justify-content: space-between; text-align: left; }
.dna-detail-steps { display: flex; gap: 8px; flex: none; }
/* Archetype names read as names, not links (owner, 2026-10-02): ink, even in the reveal's blue
   streak line, with a dotted underline and a quiet chevron. Blue stays for the actions ("How you got X", "See all 14"). */
.pst-streak-link, .rv-streak-link { color: var(--ink); text-decoration: underline dotted; text-decoration-color: color-mix(in srgb, currentColor 45%, transparent); text-underline-offset: 3px; }
@media (hover: hover) { .pst-streak-link:hover, .rv-streak-link:hover { text-decoration-color: currentColor; } }
.pst-name-chev, .rv-tag-chev { color: var(--faint); }

/* A read with no name yet (rule 239): under 5 films rated or seen, "Your taste so far" takes the
   name's place a size down, and the pill is the way to a name. */
.rv-name.rv-name-sofar { font-size: clamp(34px, 9vw, 48px); } /* type scale exception: the reveal's archetype name */
.dev-pill.dev-pill-btn { appearance: none; background: none; cursor: pointer; font: inherit; font-size: var(--fs-meta); color: var(--ink); }
@media (hover: hover) { .dev-pill.dev-pill-btn:hover { border-color: var(--ink); } }

/* Taste Mix names you can read (owner-approved mockup A, 2026-10-02): a deeper fade that is near-black
   behind the words, starting higher on a "Because you…" tile (its eyebrow takes two lines), and a soft
   shadow on the words, so a white poster or the poster's own lettering never sits under the name. */
.tastemix-tile-fade { background: linear-gradient(180deg, rgba(6,8,13,0) 30%, rgba(6,8,13,.55) 52%, rgba(6,8,13,.92) 72%, rgba(6,8,13,.98) 100%); }
.tastemix-tile-fade.is-because { background: linear-gradient(180deg, rgba(6,8,13,0) 14%, rgba(6,8,13,.6) 40%, rgba(6,8,13,.93) 60%, rgba(6,8,13,.98) 100%); }
.tastemix-tile:not(.tastemix-tile-mood) > .tastemix-tile-body .tastemix-tile-title,
.tastemix-tile:not(.tastemix-tile-mood) > .tastemix-tile-body .tastemix-tile-label { text-shadow: 0 1px 2px rgba(0,0,0,.9), 0 0 10px rgba(0,0,0,.6); }
.tastemix-tile:not(.tastemix-tile-mood) > .tastemix-tile-body .tastemix-tile-label { color: #cfcac0; }

/* Movie night's last nights as a poster strip (owner-approved mockup A, 2026-10-02): a row you swipe,
   86px posters, the title on one line, the date, then Rate it or your stars; the last tile is
   "See all N". */
.mnh-strip { display: flex; gap: 10px; overflow-x: auto; scrollbar-width: none; padding: 4px 2px 6px; margin: 2px 0 0; scroll-snap-type: x proximity; }
.mnh-strip::-webkit-scrollbar { display: none; }
.mnh-tile { flex: 0 0 86px; width: 86px; display: flex; flex-direction: column; scroll-snap-align: start; }
.mnh-tile-lead { display: flex; flex-direction: column; color: inherit; text-decoration: none; min-width: 0; }
.mnh-tile-poster { width: 86px; height: 129px; border-radius: var(--radius-sm); border: 1px solid var(--line-2); object-fit: cover; display: flex; align-items: center; justify-content: center; background: var(--panel-2); filter: var(--grade); }
.mnh-tile-title { margin-top: 6px; font-size: var(--fs-meta); font-weight: 600; color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mnh-tile-date { margin-top: 2px; font-size: var(--fs-label); color: var(--faint); }
/* Who you watched with (owner, 2026-10-02): up to three faces, or two and "+N". */
.mnh-tile-with { display: flex; align-items: center; gap: 5px; margin-top: 5px; min-height: 20px; }
.mnh-tile-with .grp-shelf-faces img, .mnh-tile-with .grp-shelf-faces span { width: 20px; height: 20px; font-size: 10px; } /* type scale exception: initials or a glyph in a fixed box */
.mnh-tile-more-n { font-size: var(--fs-label); font-weight: 600; color: var(--muted); }
.mnh-tile-rate { align-self: flex-start; margin-top: 3px; padding: 0; font-size: var(--fs-label); font-weight: 600; }
.mnh-tile-mine { margin-top: 3px; font-size: var(--fs-label); color: var(--muted); }
.mnh-tile-more { flex: 0 0 64px; height: 129px; appearance: none; background: none; border: 1px dashed var(--line-2); border-radius: var(--radius-sm); color: var(--accent-2); font: inherit; font-size: var(--fs-meta); font-weight: 600; cursor: pointer; line-height: 1.4; }
@media (hover: hover) { .mnh-tile-more:hover { border-color: var(--accent-2); } }

/* Communities' sections have real headings (owner, 2026-10-02): "Groups" in the serif title style,
   "+ New group" on its right, 22px under the tab bar. */
.tabview:has(> .comm) { padding-top: 0; }
.comm > .comm-head:first-child { margin-top: 0; }

/* The archetype sheet's defining films a size up (owner, 2026-10-02: "can be slightly larger"):
   four 56px posters, not 40px; the other archetype lists keep theirs. */
.arch-sheet .arche-posters { gap: 8px; }
.arch-sheet .arche-poster { flex: 0 1 56px; }

/* Save screen after a Letterboxd import: what saving keeps (owner, 2026-10-02). */
.account-sync-note { position: relative; max-width: 400px; margin: -16px auto 24px; font-size: var(--fs-ui); font-weight: 600; color: var(--ink); }

/* The one Sort and Filters bar (SortFilter.tsx; owner, 2026-10-02: "a standardized filter across
   all features"; rule 244) on Browse and every lane, theme, director and actor page: the Compact
   size (rule 120: 34px, 10px corners, 13px text), Sort, the arrow and Filters one height, Sort only
   as wide as its label, left-aligned. On a tag page, phone: their own row under the Unseen / Seen /
   All toggle; 700px and up, on the toggle's row right after it. */
.sf-bar { width: auto; justify-content: flex-start; align-items: center; }
.sf-bar .browse-sortwrap { flex: 0 0 auto; }
.sf-bar .browse-soft { min-height: var(--chip-h); height: var(--chip-h); padding: 0 12px; border-radius: var(--radius-pill); font-size: var(--fs-meta); }
.sf-bar .browse-sortbtn { flex: 0 0 auto; }
.sf-bar .browse-dir { flex: 0 0 34px; width: 34px; padding: 0; font-size: var(--fs-ui); }
/* Someone else's Films tab (rule 269): the shared Sort and Filters, left-aligned above the count. */
.sf-bar.pf-ctrls { margin: 0 0 10px; }
.pf-ctrls + .tp-chips { margin: 0 0 10px; }
.tp-ctrls { align-self: stretch; display: flex; flex-direction: column; align-items: flex-start; gap: 10px; }
.tp-ctrls .tp-seg { align-self: flex-start; }
.tp-lane-head .tp-chips { margin: 0; }
/* A capped theme asking the server again: the old grid dims, as Browse's does. */
.tp-grid.is-stale { opacity: .3; pointer-events: none; transition: opacity .15s ease; }
@media (min-width: 700px) {
  .tp-ctrls { flex-direction: row; align-items: center; justify-content: flex-start; gap: 12px; }
  .tp-ctrls .tp-seg { align-self: center; }
}

/* The group report's folding sections after its DNA (owner-approved mockup, 2026-10-02): a ruled
   row with the serif title, a one-line preview and faces or posters, and a round arrow. */
.grp-fold { border-bottom: 1px solid var(--line); }
.grp-fold-week { border-top: 1px solid var(--line); margin-top: 24px; }
.grp-fold-h { display: flex; align-items: center; gap: 10px; }
.grp-fold-btn { flex: 1; min-width: 0; display: flex; align-items: center; gap: 10px; padding: 16px 0; background: none; border: 0; color: var(--ink); font: inherit; text-align: left; cursor: pointer; }
.grp-fold-t { flex: 1; min-width: 0; }
.grp-fold-t b { display: block; font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; letter-spacing: -.01em; line-height: 1.15; }
.grp-fold-p { display: block; margin-top: 3px; font-size: var(--fs-meta); color: var(--faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.grp-fold-chev { flex: none; width: 28px; height: 28px; border-radius: 50%; border: 1px solid var(--line-2); background: none; color: var(--muted); display: inline-flex; align-items: center; justify-content: center; cursor: pointer; padding: 0; }
.grp-fold-chev svg { transition: transform .18s ease; }
.grp-fold.is-open .grp-fold-chev svg { transform: rotate(180deg); }
.grp-fold-posters { display: inline-flex; gap: 4px; flex: none; }
.grp-fold-posters img { width: 22px; height: 33px; border-radius: 3px; object-fit: cover; display: block; }
.grp-fold-body { padding-bottom: var(--sp-16); }
.grp-fold-body > .grp-sups, .grp-fold-body > .gsections { margin-top: 0; }
@media (prefers-reduced-motion: reduce) { .grp-fold-chev svg { transition: none; } }

/* The feed bar grown into a preview of the new lines (owner-approved mockup 3B, 2026-10-02). */
.cdock-peek { pointer-events: auto; width: 100%; max-width: 720px; margin: 0 auto; padding: 12px 14px; border: 1px solid rgba(143,179,217,.6);
  border-radius: var(--radius-field); background: #151c26; color: var(--ink); box-shadow: 0 -6px 24px rgba(0,0,0,.45); }
.cdock-peek-h { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.cdock-peek-h b { font-size: var(--fs-ui); font-weight: 600; }
.cdock-peek-later { font-size: var(--fs-meta); color: var(--faint); }
.cdock-peek-row { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 8px; }
.cdock-peek-lead { width: 26px; height: 26px; border-radius: 50%; font-size: var(--fs-label); }
.cdock-peek-row p { flex: 1; min-width: 0; margin: 3px 0 0; font-size: var(--fs-meta); line-height: 1.35; color: var(--muted); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.cdock-peek-row p b { color: var(--ink); font-weight: 600; }
.cdock-peek-acts { display: flex; gap: 8px; margin-top: 4px; }
.cdock-peek-acts .btn { flex: 1; height: var(--btn-h); min-height: var(--btn-h); border-radius: 999px; font-size: var(--fs-ui); }

/* A film's About text: three lines and More, like the archetype description (owner, 2026-10-02);
   the theme tags stay under it. */
.fd-overview.is-clamped { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.fd-overview.is-faded { cursor: pointer; -webkit-mask-image: linear-gradient(to bottom, #000 calc(100% - 1.6em), rgba(0,0,0,.35)); mask-image: linear-gradient(to bottom, #000 calc(100% - 1.6em), rgba(0,0,0,.35)); }
.fd-overview-more { margin-top: 6px; }

/* Browse: how the lanes and themes combine, said between the chips and under the count
   (owner, 2026-10-02: "Needs to be more clear that lanes and themes aren't combined"). */
.browse-join { align-self: center; font-size: var(--fs-meta); font-weight: 600; color: var(--muted); }
.browse-joinnote { margin: -2px 0 12px; font-size: var(--fs-meta); color: var(--faint); }
.browse-joinnote.is-fallback { color: var(--accent-2); }

/* Settings → Streaming services (rule 248): the region picker and JustWatch's credit. */
.pm-watch-region { display: flex; align-items: center; gap: 8px; width: 100%; font-size: var(--fs-meta); color: var(--muted); margin-bottom: 4px; }
.pm-watch-region select { background: transparent; color: var(--ink); border: 1px solid var(--line); border-radius: 8px; padding: 4px 8px; font: inherit; }
.pm-watch-credit { width: 100%; font-size: var(--fs-label); color: var(--faint); margin-top: 4px; }

/* Browse → Who's watching (rule 248; owner-approved mock 2026-10-02). */
.browse-who-chip { display: inline-flex; align-items: center; gap: 7px; padding-left: 5px; }
.browse-who-chip img, .browse-who-chip i { width: 22px; height: 22px; border-radius: var(--radius-av); object-fit: cover; flex: none;
  display: inline-flex; align-items: center; justify-content: center; font-style: normal; font-size: var(--fs-label); font-weight: 700;
  background: var(--accent-soft); color: var(--ink); }
.browse-who-lenses { display: flex; flex-direction: column; gap: 6px; margin-top: 10px; }
.browse-who-lens { text-align: left; border: 1px solid var(--line); border-radius: 12px; padding: 9px 12px; background: transparent; color: var(--ink); font: inherit; cursor: pointer; }
.browse-who-lens b { display: block; font-size: var(--fs-ui); font-weight: 600; }
.browse-who-lens small { display: block; font-size: var(--fs-label); color: var(--faint); margin-top: 2px; }
.browse-who-lens.on { border-color: var(--select-edge); background: var(--select-fill); box-shadow: var(--select-ring); }
.browse-faces { position: absolute; left: 6px; bottom: 6px; display: flex; }
.browse-faces img, .browse-faces i { width: 18px; height: 18px; border-radius: var(--radius-av); object-fit: cover; margin-left: -5px; border: 2px solid var(--bg);
  display: inline-flex; align-items: center; justify-content: center; font-style: normal; font-size: 9px; font-weight: 700; background: var(--accent); color: var(--bg); } /* type scale exception: initials or a glyph in a fixed box */
.browse-faces > :first-child { margin-left: 0; }
/* Stacked in the bottom-left corner, one chip per person (owner, 2026-10-02). */
.browse-split { position: absolute; left: 5px; bottom: 5px; max-width: calc(100% - 10px); display: flex; flex-direction: column; align-items: flex-start; gap: 3px; font-size: var(--fs-label); font-weight: 700; font-variant-numeric: tabular-nums; }
.browse-split span { background: rgba(0, 0, 0, 0.75); border-radius: 4px; padding: 2px 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.browse-split .hi { color: #b9e0a0; }
.browse-split .lo { color: #e0a0a0; }

/* Filters (rule 248, owner-approved mock): one of a few as a segmented control, and a quiet hint. */
.browse-seg { display: flex; border: 1px solid var(--line); border-radius: 999px; overflow: hidden; margin: 4px 0 8px; }
.browse-seg button { flex: 1; background: transparent; border: 0; color: var(--ink); font: inherit; font-size: var(--fs-ui); font-weight: 600; padding: 8px 6px; cursor: pointer; }
.browse-seg button + button { border-left: 1px solid var(--line); }
.browse-seg button.on { background: var(--ink); color: var(--bg); }
.browse-fs-hint { align-self: center; font-size: var(--fs-meta); color: var(--faint); padding: 0 4px; }
.browse-fs-edit { min-height: var(--chip-h); font-size: var(--fs-meta); }

/* Share sheets: what the Instagram tile just did ("Card copied. In Instagram, paste it into your story."). */
.share-ig-note { margin: 8px 0 0; font-size: var(--fs-meta); color: var(--muted); }

/* Browse search chips (owner-approved mock, 2026-10-02): All, Lanes, Themes, Directors, Actors, Crew. */
.browse-dd-scopes { display: flex; gap: 6px; padding: 4px 10px 10px; overflow-x: auto; scrollbar-width: none; border-bottom: 1px solid var(--line); margin-bottom: 4px; }
.browse-dd-scopes::-webkit-scrollbar { display: none; }
.browse-dd-scope { flex: none; border: 1px solid var(--line-2); border-radius: 999px; padding: 5px 11px; background: transparent; color: var(--muted); font: inherit; font-size: var(--fs-meta); font-weight: 600; cursor: pointer; white-space: nowrap; }
.browse-dd-scope small { font-size: var(--fs-meta); font-weight: 500; opacity: 0.7; margin-left: 4px; }
.browse-dd-scope.on { background: var(--ink); color: var(--bg); border-color: var(--ink); }
/* Who's watching on lane, theme and person pages: the two numbers sit at the top, clear of the title. */
.tp-card .browse-split { top: 6px; bottom: auto; }
/* Who's watching wraps onto a second line on a phone, as on iOS (FlowLayout), rather than running
   off the edge in the occasion row's one-line scroll (2026-11-02). */
.tn-both { display: inline-flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }
.tn-both-chip { font-size: var(--fs-meta); font-weight: 600; padding: 2px 8px; border: 1px solid var(--line); border-radius: 999px; color: var(--ink); }

/* Settings → Streaming services: each chip leads with the service's logo (owner, 2026-10-02). */
.pm-avoid-chip:has(.pm-svc-logo) { display: inline-flex; align-items: center; gap: 8px; padding-left: 6px; }
.pm-svc-logo { width: 22px; height: 22px; border-radius: 6px; object-fit: cover; flex: none; }

/* On a phone the last-tapped button keeps :hover until the next tap elsewhere, and Canon's hover
   outranked its "on" fill, so a tapped star looked unfilled until a refresh (owner, 2026-10-03).
   The on state always wins; hover only shows on devices that really hover. */
.fa-canon.on, .fa-canon.on:hover:not(:disabled) { border-color: var(--shadow); background: var(--shadow); color: var(--ink); }
@media (hover: none) {
  .fa-canon:not(.on):hover:not(:disabled) { border-color: rgba(160,50,58,.75); color: #e9b3b7; }
  .fd-ratings-btns .fa-watch:not(.on):hover:not(:disabled) { background: rgba(255,255,255,.05); border-color: var(--line-2); }
}

/* The season's Taste Mix (owner picked tile B, 2026-10-04): a pumpkin edge and "Until Oct 31" in
   the same colour, so it reads as here for a while, not one more mix. */
.tastemix-tile.is-seasonal { border-color: #d98a3a; }
.tastemix-tile.is-seasonal:not(.tastemix-tile-mood) > .tastemix-tile-body .tastemix-tile-label { color: #e8a25a; }

/* Starting out (rule 283): Tonight's moods on the page, the "+ N more" chip, the mixes' line. */
.tn-moods-open { margin-top: var(--sp-16); }
.mood-chip.mood-chip-more { border-style: dashed; color: var(--accent); }
.dsc-mix-more { margin-top: 10px; }

/* First-use explainers (rule 285, TermTip.tsx): option A's one-line tip under a heading, then an (i). */
.term-tip { display: flex; gap: var(--sp-8); align-items: flex-start; justify-content: space-between; margin: var(--sp-8) 0; padding: 8px 10px; border: 1px solid var(--accent-2); border-radius: var(--radius); background: color-mix(in srgb, var(--accent-2) 12%, transparent); font-size: var(--fs-meta); line-height: 1.45; color: var(--ink); text-align: left; text-transform: none; letter-spacing: normal; font-weight: 400; }
.term-tip-x { appearance: none; background: none; border: 0; padding: 0 2px; cursor: pointer; font: inherit; color: var(--muted); line-height: 1.45; }
.term-tip-x:hover { color: var(--ink); }
.term-head { display: inline-flex; align-items: center; gap: 6px; }

/* Film DNA against the typical viewer (rule 285): the delta leads, the share small, a tick for typical. */
.dna-vs { margin: var(--sp-8) 0 0; }
.dna-vs-bar { position: relative; height: 6px; margin: 6px 0 6px; border-radius: 3px; background: var(--line); }
.dna-vs-bar > i { position: absolute; left: 0; top: 0; bottom: 0; border-radius: 3px; background: var(--accent-2); }
.dna-vs-bar > u { position: absolute; top: -3px; width: 2px; height: 12px; margin-left: -1px; background: var(--ink); text-decoration: none; }
.dna-vs-m { font-size: var(--fs-meta); color: var(--muted); }

/* How we did as a top banner (rule 287, mockup B): the poster and the headline open the film. */
.hwd-bnr-poster { appearance: none; display: block; padding: 0; border: 0; background: none; cursor: pointer; line-height: 0; }
.hwd-bnr-t { appearance: none; padding: 0; border: 0; background: none; color: inherit; font: inherit; text-align: left; cursor: pointer; }
.hwd-bnr .bnr-p b { color: var(--ink); }
.hwd-bnr-rec { color: var(--faint); }
.hwd-bnr-more { font-size: var(--fs-meta); font-weight: 600; color: var(--muted); }

/* Someone's profile: Follow and ••• hold their place while the viewer's follow state loads (rule 288). */
.pa-skel { display: contents; }

/* Page and list wireframes (app/_components/PageSkeletons.tsx, rule 288). */
.skel-rows { display: flex; flex-direction: column; gap: 14px; padding: 8px 0; }
.skel-row { display: flex; align-items: center; gap: 12px; }
.skel-row-pic { flex: none; width: 40px; height: 40px; border-radius: var(--radius-av); }
.skel-row-pic.is-poster { height: 60px; border-radius: var(--radius-sm); }
.skel-row-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 8px; font-size: var(--fs-ui); line-height: 1.3; }
.skel-head { margin: var(--sp-8) 0 var(--sp-16); }
.skel-para { margin: var(--sp-16) 0 0; font-size: var(--fs-ui); line-height: 1.6; }
.skel-film-row { display: flex; align-items: flex-end; gap: var(--sp-16); margin-top: -48px; padding: 0 16px; position: relative; }
.skel-film-text { display: flex; flex-direction: column; gap: 8px; padding-bottom: 6px; }
.tp-portrait.skel, .fd-hero-poster.skel { box-shadow: none; border-color: transparent; }
.hero-avatar.skel { border-color: transparent; }
.hero-avatar.skel { background: var(--skel-fill); background-size: 200% 100%; box-shadow: none; }

/* A heading with its (i) (rule 285): the row carries the heading's spacing, the heading none of its
   own, so the (i) centres on the words and the section keeps its usual gap (owner, 2026-10-07:
   "spacing and alignment suck with the i"). The (i) at the caps' scale, not a 22px button. */
.term-head { display: inline-flex; align-items: center; gap: 8px; }
.dsc-sec > .term-head { display: flex; margin: 0 0 12px; }
.term-head > .dsc-hero-eyebrow, .term-head > .cv-eyebrow { margin: 0; }
.term-head .sec-info-btn { width: 18px; height: 18px; }
.term-head .sec-info-btn svg { width: 12px; height: 12px; }

/* Canon's first-use tip spans the modal under the heading row (owner, 2026-10-07). */
.cv-tip { flex: none; padding: 0 var(--sp-24); }
.cv-tip .term-tip { margin: 0 0 16px; }

/* Film DNA's share under the bar: the share, then the typical viewer, each its own line at text
   size (owner, 2026-10-07: "20% and typical view subtext line is super crammed"). */
.dna-vs-bar { margin-bottom: 10px; }
.dna-vs-m { font-size: var(--fs-meta); line-height: 1.45; color: var(--muted); }
.dna-detail-share .dna-vs-m b { font-size: inherit; font-weight: 700; color: var(--ink); font-family: inherit; letter-spacing: normal; }

/* How your ratings line up: a row of each group's best-known films with both ratings, See all in
   place (owner, 2026-10-08). */
.mx-lg { margin-top: 14px; }
.mx-lg-h { display: flex; align-items: baseline; gap: 8px; }
.mx-lg-h .mx-line-k { margin-top: 0; }
.mx-lg-all { margin-left: auto; background: none; border: 0; padding: 0; font: inherit; font-size: var(--fs-meta); color: var(--accent-2); cursor: pointer; }
.mx-lg-strip { display: flex; gap: 8px; overflow-x: auto; overflow-y: hidden; overscroll-behavior-x: contain; margin: 8px -16px 0 0; padding-right: 16px; scrollbar-width: none; }
.mx-lg-strip::-webkit-scrollbar { display: none; }
.mx-lg-strip .mx-lg-film { flex: none; width: 76px; }
.mx-lg-more { display: block; width: 100%; margin-top: 12px; }
.mx-lg-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(76px, 1fr)); gap: 12px 8px; margin-top: 8px; }
.mx-lg-film { display: block; text-decoration: none; color: inherit; min-width: 0; }
.mx-lg-film > img, .mx-lg-film .mx-film-ph { width: 100%; aspect-ratio: 2 / 3; object-fit: cover; border-radius: 4px; border: 1px solid var(--line-2); filter: var(--grade); }
.mx-lg-film > img { display: block; }
.mx-lg-film .mx-film-ph { display: grid; }
.mx-lg-r { display: block; font-size: var(--fs-label); line-height: 1.3; color: var(--faint); margin-top: 4px; }
.mx-lg-r b { color: var(--ink); font-weight: 600; }

/* Film DNA side by side: each strand's share for both people, folded until opened (owner,
   2026-10-08). Their colour is the radar's filled shape, yours its cream outline. */
.mx-dna-pct { margin-top: 12px; border-top: 1px solid var(--line); }
.mx-dna-pct > summary { list-style: none; cursor: pointer; padding: 12px 0 2px; font-size: 14px; color: var(--accent-2); } /* type scale exception: match % numerals */
.mx-dna-pct > summary::-webkit-details-marker { display: none; }
.mx-dna-pct > summary::after { content: "›"; display: inline-block; margin-left: 8px; transition: transform .15s; }
.mx-dna-pct[open] > summary::after { transform: rotate(90deg); }
.mx-dna-leg { display: flex; gap: 14px; font-size: var(--fs-label); color: var(--muted); margin: 8px 0 2px; }
.mx-dna-leg i { display: inline-block; width: 10px; height: 10px; border-radius: 2px; margin-right: 5px; vertical-align: -1px; }
.mx-dna-row { display: grid; grid-template-columns: 118px 1fr 44px; column-gap: 10px; align-items: center; padding: 9px 0; border-bottom: 1px solid var(--line); }
.mx-dna-l { font-size: var(--fs-ui); color: var(--ink); }
.mx-dna-bars { display: flex; flex-direction: column; gap: 3px; }
.mx-dna-bars i { display: block; height: 6px; border-radius: 3px; }
.mx-dna-v { display: flex; flex-direction: column; text-align: right; font-size: var(--fs-meta); line-height: 1.25; font-variant-numeric: tabular-nums; }
.mx-dna-gap { grid-column: 1 / 4; font-size: var(--fs-label); color: var(--faint); margin-top: 2px; }
.mx-dna-pct .them { background: var(--accent-2); color: var(--accent-2); }
.mx-dna-pct .you { background: var(--ink); color: var(--ink); }
.mx-dna-v .them, .mx-dna-v .you, .mx-dna-gap.them, .mx-dna-gap.you { background: none; }
.mx-dna-note { font-size: var(--fs-label); color: var(--faint); margin: 10px 0 0; }

/* The ⓘ beside the film's "for you" (owner, 2026-10-09): small, so the stat keeps its size. */
.fd-stat-l.term-head { gap: 4px; }
.fd-stat-l .sec-info-btn { width: 16px; height: 16px; }

/* Filters sheet sections (rule 296): Tonight, The film, Feel, Your list, each under a small accent
   label; a row that narrows the list shows its value in the accent colour, and the cream button
   says how many rows are on. Rows sit a little tighter so the headers cost almost no height. */
.browse-fs-group + .browse-fs-group { margin-top: 14px; }
.browse-fs-gh { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; color: var(--accent-2); font-weight: 700; padding: 8px 2px 0; }
.browse-fs-group .browse-fs-row { min-height: 46px; }
.browse-fs-group .browse-fs-sec:last-child { border-bottom: 0; }
.browse-fs-group.lead .browse-fs-sec:last-child { border-bottom: 1px solid var(--line); }
.browse-fs-v.on { color: var(--ink); font-weight: 600; }
.browse-show-n { font-weight: 400; opacity: .7; }

/* Browse: the retry beside "Could not load films." */
.err .retry-btn { margin-left: 8px; }

/* "/" boots with the signed-out landing in the server HTML (HomeShell BOOT_GATE): it stays for a
   visitor with nothing to restore; anyone else sees the boot loader, as before. */
main:not([data-boot="app"]) .boot-loader { display: none; }
main[data-boot="app"] .boot-landing { display: none !important; }

/* "In theaters" / "New" on a poster tile (rule 301): top-left, opposite the match %. */
.rel-tag { position: absolute; left: 7px; top: 7px; z-index: 1; font-size: 11px; font-weight: 600; letter-spacing: 0; text-transform: none;
  border-radius: var(--radius-sm); padding: 3px 6px; line-height: 1.2; pointer-events: none; }
.rel-tag.is-new { background: var(--ink); color: var(--bg); }
.rel-tag.is-theater { background: var(--accent-2); color: var(--bg); }

/* Films that define (SigReel) on iOS: a CSS filter on an image inside a sideways-scrolling row made
   Safari paint some posters only in part (a vertical cut) or not at all, on others' profiles
   (owner, 2026-10-09, "still happening"). The strip drops the print grade and gets its own
   compositing layer; the hover lift and border apply only where there is a real hover, so a tap no
   longer leaves a white frame behind. */
.sigframe-poster img { filter: none; }
.sigreel { transform: translateZ(0); -webkit-transform: translateZ(0); }
@media (hover: none) {
  .sigframe-poster:hover { border-color: var(--line-2); transform: none; box-shadow: none; }
}
/* A tap on someone else's signature film shows it landed, like every other poster (owner, 2026-10-09). */
.sigframe-poster.is-link:active { transform: scale(.97); }

/* About, layout A (owner, 2026-10-09): numbered serif parts, full-width words, thin rules, no icons. */
.about-parts { max-width: 560px; margin: var(--sp-24) auto 0; text-align: left; }
.about-part { padding: var(--sp-24) 0 0; }
.about-part:first-child { padding-top: 0; }
.about-part-h { font-family: var(--serif); font-weight: 600; font-size: var(--fs-heading); line-height: 1.2; margin: 0 0 8px; color: var(--ink); }
.about-part-p { font-size: var(--fs-ui); line-height: 1.55; color: var(--muted); margin: 0; }
.about-note { max-width: 560px; margin: 24px auto 0; }
.about-start { display: flex; align-items: center; justify-content: center; max-width: 560px; min-height: var(--btn-h); margin: 16px auto 0; font-size: var(--fs-ui); font-weight: 600;
  background: var(--ink); color: var(--bg); border: 1px solid var(--ink); box-shadow: var(--shadow-offset); }

/* Picks (owner-approved mockup 2026-10-10, mockups/picks-browse-v7.png; rule 319): Discover's
   one-at-a-time feed. Tags in the film page's tag style, then a vertical snap track whose slides
   fill the space down to the tab bar. */
/* Tight under the top bar: the tabs are the page's heading (owner, 2026-10-10: the gap read as wasted). */
.dsc-views.subtabs { margin: -6px 0 0; padding-top: 0; }
.tabview:has(> .dsc-views) { padding-top: 0; }
@media (max-width: 759px) { .dsc-views.subtabs { margin-top: 2px; } }
.dsc-views .subtab { font-size: var(--fs-meta); }
.picks { margin: 0; max-width: 100%; overflow-x: hidden; }
.picks .pk-tags, .picks .pk-slide { padding-left: 0; padding-right: 0; }
.pk-tags { display: flex; gap: 6px; padding: 10px 16px 4px; overflow-x: auto; scrollbar-width: none; }
.pk-tags::-webkit-scrollbar { display: none; }
.pk-tags .match-tag { flex: none; appearance: none; cursor: pointer; color: var(--muted); }
.pk-tags .match-tag.on { color: var(--ink); border-color: var(--ink); }
.pk-track { overflow-y: auto; overflow-x: hidden; touch-action: pan-y; scroll-snap-type: y mandatory; overscroll-behavior-y: contain; scrollbar-width: none; }
.pk-track::-webkit-scrollbar { display: none; }
/* A mouse drags the cards (PicksFeed): no image ghost or text selection in the way, and the snap
   lets go while the card follows the pointer. */
@media (pointer: fine) { .pk-track { cursor: grab; } .pk-track img { -webkit-user-drag: none; user-select: none; } }
.pk-track.is-dragging { scroll-snap-type: none; cursor: grabbing; user-select: none; }
.pk-slide { position: relative; width: 100%; min-width: 0; overflow: hidden; scroll-snap-align: start; scroll-snap-stop: always; display: flex; flex-direction: column; padding: 10px 16px 0; min-height: 420px; }
/* The poster takes whatever height the slide has left, up to a cap, and sits right on top of the
   title: the gaps around it are fixed, never the leftovers (owner, 2026-10-10). */
.pk-art { flex: 1 1 auto; min-height: 0; display: flex; align-items: flex-end; justify-content: center; padding: 6px 8px 16px 0; }
.pk-poster { position: relative; border: 1px solid var(--ink); background: var(--panel); padding: 0; height: 100%; max-height: 360px;
  aspect-ratio: 2 / 3; border-radius: 4px; overflow: hidden; box-shadow: 8px 8px 0 var(--shadow); }
.pk-poster-tap { appearance: none; display: block; width: 100%; height: 100%; padding: 0; border: 0; background: none; cursor: pointer; }
.pk-poster img { display: block; width: 100%; height: 100%; object-fit: cover; }
/* No press shrink: it fought the swipe on iPhone (see the tap-feedback rule). */
/* The trailer takes the card (as in the decks): it fills the slide, whole and uncropped, and the
   poster, info and answers fade out under it until it stops. */
.pk-tv { position: absolute; inset: 0; z-index: 3; animation: pkTvIn .45s ease both; }
.pk-tv .reel-trailer-bg.deck-trailer-bg { position: absolute; inset: 0; display: grid; place-items: center; background: #000; }
.pk-tv-x { position: absolute; top: 10px; right: 10px; z-index: 4; width: 34px; height: 34px; border-radius: 50%; border: 1px solid rgba(239,232,218,.3);
  background: rgba(11,11,13,.7); color: var(--ink); font-size: var(--fs-card); line-height: 1; cursor: pointer; }
.pk-slide > .pk-art, .pk-slide > .pk-info, .pk-slide > .pk-stub, .pk-slide > .pk-hint { transition: opacity .45s ease; }
.pk-slide.is-playing > .pk-art, .pk-slide.is-playing > .pk-info, .pk-slide.is-playing > .pk-stub, .pk-slide.is-playing > .pk-hint { opacity: 0; pointer-events: none; }
@keyframes pkTvIn { from { opacity: 0; } to { opacity: 1; } }
/* × top right; mute and expand together at the bottom right, both against the card's corners
   (the frame is static so the mute places against the whole trailer area, not the 16:9 box). */
.pk-tv .reel-trailer-frame.deck-trailer-frame { position: static; }
.pk-tv .deck-trailer-mute { top: auto; bottom: 12px; right: 56px; width: 34px; height: 34px; }
.pk-tv-full { position: absolute; bottom: 12px; right: 12px; z-index: 4; width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center;
  border: 1px solid rgba(239,232,218,.3); background: rgba(11,11,13,.7); color: var(--ink); cursor: pointer; }
.pk-tv.is-full { position: fixed; inset: 0; z-index: 1000; background: #000; }
.pk-tv.is-full .pk-tv-x { top: calc(10px + env(safe-area-inset-top, 0px)); }
.pk-tv.is-full .pk-tv-full, .pk-tv.is-full .deck-trailer-mute { bottom: calc(14px + env(safe-area-inset-bottom, 0px)); }
.pk-poster-ph { display: grid; place-items: center; height: 100%; padding: 12px; font-family: var(--serif); font-size: var(--fs-heading); color: var(--ink); text-align: center; }
.pk-info { flex: none; padding: 10px 2px 0; }
.pk-head { position: relative; min-width: 0; }
.pk-head.has-stat { padding-right: 84px; }
.pk-title { min-width: 0; margin: 0; overflow-wrap: break-word; font-family: var(--serif); font-weight: 600; font-size: var(--fs-title); line-height: 1.05; letter-spacing: -.01em; color: var(--ink); }
/* The match as the film page shows it (.fd-stat): serif, accent blue, a small %, "for you" under. */
.pk-stat { position: absolute; top: 1px; right: 0; text-align: right; }
.pk-stat-n { font-family: var(--serif); font-size: 28px; line-height: 1; color: var(--accent); font-variant-numeric: tabular-nums; }
.pk-stat-u { font-family: var(--sans); font-variation-settings: normal; font-size: var(--fs-ui); font-weight: 600; margin-left: 2px; }
.pk-stat-l { font-size: var(--fs-label); color: var(--muted); font-weight: 500; margin-top: 3px; white-space: nowrap; }
.pk-meta { margin-top: 3px; font-size: var(--fs-meta); color: var(--faint); }
/* How widely seen it is (rule 558): last of the facts, a shade lighter so it isn't lost. */
/* Where to watch it, ending the meta line as text (owner, 2026-10-28, mockups/picks-where-inline.png): your service in the match blue, in theaters in a muted red. */
.pk-where { color: var(--accent-2); font-weight: 500; text-decoration: none; }
a.pk-where:active { opacity: .7; }
.pk-where.is-theater { color: #e0a9a9; }
/* One line, always (owner, 2026-10-10): the server keeps only a short one-sentence tagline; this is the guard. */
/* The tagline whispers under the title: Bodoni italic, smaller and quieter (owner, 2026-10-10). */
.pk-tagline { margin: 6px 0 0; font-family: var(--serif); font-style: italic; font-weight: 500; font-size: var(--fs-read); line-height: 1.3; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pk-hint { margin: 12px 0 0; text-align: center; font-family: var(--label); font-size: var(--fs-label); letter-spacing: .16em; text-transform: uppercase; font-weight: 600; color: var(--faint); }
/* The answers on a ticket stub: three equal parts, torn lines between, notches at the ends. */
.pk-stub { position: relative; flex: none; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); height: 60px; margin: 16px 8px 14px 0;
  background: var(--cream); color: var(--cream-ink); border-radius: 8px; box-shadow: 6px 6px 0 var(--shadow); }
.pk-stub::before, .pk-stub::after { content: ""; position: absolute; top: 50%; width: 14px; height: 14px; margin-top: -7px; border-radius: 50%; background: var(--bg); }
.pk-stub::before { left: -7px; }
.pk-stub::after { right: -7px; }
.pk-stub button { appearance: none; background: none; border: 0; padding: 0 6px; display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 5px; font: inherit; font-size: 13px; font-weight: 600; line-height: 1; color: inherit; cursor: pointer; white-space: nowrap; }
.pk-stub button + button { border-left: 2px dashed #b9b0a0; }
.pk-stub button svg { display: block; width: 18px; height: 18px; flex: none; }
.pk-stub button.on { color: var(--shadow); }
.pk-stub button:active { background: rgba(20,18,16,.06); }
.pk-end-in { margin: auto; text-align: center; display: grid; gap: 14px; justify-items: center; }
.pk-end-t { margin: 0; font-family: var(--serif); font-weight: 600; font-size: var(--fs-heading); color: var(--ink); }

/* Browse (owner-approved mockup 2026-10-10, mockups/picks-browse-v7.png; rule 321): each mix is one
   plain row: its name (serif) and count, then posters you swipe sideways, each with its match on a
   cream stub. Only the ranked watchlist differs (its numbers). */
.bx-rows { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--sp-24); margin-top: 6px; }
.bx-head { appearance: none; background: none; border: 0; padding: 0; width: 100%; display: flex; align-items: baseline; gap: 8px; text-align: left; cursor: pointer; color: var(--ink); font: inherit; flex-wrap: wrap; }
.bx-name { font-family: var(--serif); font-weight: 600; font-size: var(--fs-heading); line-height: 1.15; min-width: 0; }
.bx-count { flex: 1; font-size: var(--fs-meta); color: var(--faint); white-space: nowrap; }
.bx-go { color: var(--faint); font-size: var(--fs-card); }
.bx-why { margin: 2px 0 0; font-size: var(--fs-meta); color: var(--faint); }
.bx-strip { display: flex; gap: 10px; margin: 10px calc(-1 * var(--bx-bleed)) 0; padding: 0 var(--bx-bleed) 4px; scroll-padding-inline: var(--bx-bleed); overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x proximity; scrollbar-width: none; }
.bx-strip::-webkit-scrollbar { display: none; }
.bx-po { position: relative; flex: none; width: 104px; aspect-ratio: 2 / 3; padding: 0; border: 1px solid var(--line-2); border-radius: 4px; overflow: hidden; background: var(--panel); cursor: pointer; scroll-snap-align: start; }
.bx-po img { display: block; width: 100%; height: 100%; object-fit: cover; }
.bx-po:active { transform: scale(.97); }
.bx-po-ph { display: grid; place-items: center; height: 100%; padding: 8px; font-family: var(--serif); font-size: var(--fs-meta); color: var(--ink); text-align: center; }
/* The match on a small ticket stub: cream, notched at both ends, like the Picks answers. */
.bx-stub { position: absolute; left: 6px; bottom: 6px; background: var(--cream); color: var(--cream-ink); font-size: 11px; font-weight: 600; line-height: 1; padding: 4px 8px; border-radius: 2px;
  -webkit-mask: radial-gradient(circle 3px at 0 50%, transparent 98%, #000) left / 51% 100% no-repeat, radial-gradient(circle 3px at 100% 50%, transparent 98%, #000) right / 51% 100% no-repeat;
  mask: radial-gradient(circle 3px at 0 50%, transparent 98%, #000) left / 51% 100% no-repeat, radial-gradient(circle 3px at 100% 50%, transparent 98%, #000) right / 51% 100% no-repeat; }
.wlrank-n { position: absolute; left: 6px; top: 2px; z-index: 2; font-family: var(--serif); font-weight: 600; font-size: 26px; line-height: 1; color: var(--ink); text-shadow: 0 1px 6px rgba(0,0,0,.85); pointer-events: none; } /* type scale exception: rank numerals or ticket stub */

/* Search (owner-approved, 2026-10-10; rule 321): a Filters button beside the box, and the Browse
   shortcuts in the film page's tag style. */
.gs-filter { position: absolute; top: 20px; right: 64px; z-index: 2; width: 44px; height: 44px; display: grid; place-items: center;
  border: 1px solid var(--line-2); border-radius: 12px; background: var(--panel); color: var(--muted); cursor: pointer; }
.gs-filter:active { transform: scale(.96); }
.gs-combo:has(> .gs-filter) .dsc-lookup-bar.ig-search { margin-right: 104px; }
.gs-browse-chips .gs-browse-chip.match-tag { height: auto; padding: 6px 10px; margin: 0; font-family: var(--sans); font-size: var(--fs-label); letter-spacing: 0;
  text-transform: none; font-weight: 600; color: var(--muted); background: none; border: 1px solid var(--line-2); border-radius: 2px; }
.gs-browse-chips .gs-browse-chip.match-tag.lead { color: var(--ink); border-color: var(--ink); }
.bx-tags { padding-left: 0; padding-right: 0; margin: 2px 0 6px; }
/* "Like X": the loved film leads the row, greyed, marked "You loved", then an arrow to its matches. */
.bx-src { flex: none; display: grid; grid-template-columns: auto auto; grid-template-rows: auto auto; align-items: center; column-gap: 8px; }
.bx-src-po { grid-row: 1; grid-column: 1; width: 72px; aspect-ratio: 2 / 3; border: 1px dashed var(--faint); border-radius: 4px; overflow: hidden; filter: grayscale(.6) brightness(.75); }
.bx-src-po img { display: block; width: 100%; height: 100%; object-fit: cover; }
.bx-src-l { grid-row: 2; grid-column: 1; margin-top: 6px; text-align: center; font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; font-weight: 600; color: var(--faint); white-space: nowrap; }
.bx-src-ar { grid-row: 1; grid-column: 2; color: var(--faint); font-size: var(--fs-card); }
/* This week, for you in Browse: the wide cinematic card (the still fills it, ink edge, red offset). */
/* This week runs edge to edge like the rows under it, a touch bigger, and snaps inside the gutter
   so the card's left edge is never cut (owner, 2026-10-10). */
.dsc-browse .hc-card { flex: 0 0 calc(100% - 14px); aspect-ratio: 3 / 2; max-height: none; border: 1px solid var(--ink); box-shadow: 6px 6px 0 var(--shadow); }
.dsc-browse .hero-carousel { margin: 0 calc(-1 * var(--bx-bleed)); padding: 2px var(--bx-bleed) 10px; scroll-padding-inline: var(--bx-bleed); }
/* Your watchlist, ranked in Browse: one sideways row, each poster carrying a big outlined rank. */
.dsc-browse .wlrank .lib-grid { display: flex; gap: 12px; overflow-x: auto; margin: 0 calc(-1 * var(--bx-bleed)); padding: 4px var(--bx-bleed) 6px; scroll-padding-inline: var(--bx-bleed); scrollbar-width: none; overscroll-behavior-x: contain; }
.dsc-browse .wlrank .lib-grid::-webkit-scrollbar { display: none; }
.dsc-browse .wlrank .lib-card.wlrank-card { flex: none; width: 112px; }
.dsc-browse .wlrank-n { left: 4px; top: auto; bottom: -6px; font-size: 64px; color: transparent; -webkit-text-stroke: 1.5px var(--ink); text-shadow: none; transform: translateZ(0); pointer-events: none; } /* type scale exception: rank numerals or ticket stub */
/* No filter on the numerals: Safari dropped stroked text with a drop-shadow filter from a scrolling row. */
.dsc-browse .wlrank-badge { display: none; }
