.mnv-pc { position: absolute; right: 7px; top: 7px; z-index: 1; background: rgba(11, 11, 13, .78); color: var(--accent-2); font-weight: 700; font-size: var(--fs-meta); padding: 3px 7px; border-radius: var(--radius-poster); }
.mnv-pc.lg { font-family: var(--serif); font-size: var(--fs-heading); padding: 6px 10px; text-align: right; line-height: 1; } .mnv-pc.lg small { display: block; font-family: var(--sans); font-size: var(--fs-label); font-weight: 500; color: var(--muted); }
.mnv-ov { position: absolute; left: 0; right: 0; bottom: 0; z-index: 1; display: flex; flex-direction: column; align-items: flex-start; padding: 34px 9px 9px; background: linear-gradient(transparent, rgba(8, 8, 10, .92) 55%); text-align: left; }
.mnv-ov .mnr-faces { margin-bottom: 5px; }
.mnv-ot { font-family: var(--serif); font-weight: 600; font-size: var(--fs-ui); line-height: 1.1; color: var(--ink); } .mnv-ot small { font-family: var(--sans); font-size: var(--fs-label); font-weight: 400; color: var(--muted); }
.mnv-od { font-size: var(--fs-label); color: var(--muted); margin-top: 2px; }
.mnv-who { display: flex; align-items: center; gap: 5px; margin-bottom: 6px; } .mnv-who em { font-style: normal; font-size: var(--fs-label); color: var(--muted); }
.mnv-shelf { --mnl-h: clamp(200px, calc(100dvh - 470px), 400px); }
.mnv-big { border-radius: 8px; box-shadow: 0 10px 30px rgba(0, 0, 0, .6); border-color: rgba(239, 232, 218, .6); }
.mnv-big .mnv-ov.big { padding: 60px 14px 14px; } .mnv-big .mnv-ov.big .mnv-ot { font-size: var(--fs-heading); }
