button.pk-stat::before { content: ""; position: absolute; inset: -14px -12px -14px -22px; }

@media (min-width: 1000px) { .picks button.pk-stat { position: relative; } }
/* Picks' card wireframe while films load: the poster, the title and meta lines, the stub. */
.pk-skel .pk-poster.skel { border: 0; box-shadow: none; background: var(--skel-fill); background-size: 200% 100%; }
.pk-skel-t { height: 26px; width: 62%; }
