/* Every film: its sort as controls under the Title. */
.dsc-browse .bh + .bx-more { margin-top: var(--sp-32); }
.bx-more .bx-head-static { margin-bottom: 0; }
.bx-sortrow { display: flex; gap: 8px; margin: var(--sp-12) 0 0; }
/* Signed out, the doors stay on the page as links (rule 340), in the same type. */
.bh-genres button, .bh-genres a, .bh-decades button, .bh-decades a { height: var(--chip-h); display: inline-flex; align-items: center; padding: 0 12px; border-radius: var(--radius-pill);
  border: 1px solid var(--line-2); background: none; font: 600 var(--fs-meta)/1 var(--sans); color: var(--ink); }

/* ── Film page and sheet (rule 415) ─────────────────────────────────────────────────────────── */
/* The film takes the whole screen: the backdrop to the top edge on a member's page (no app
   header, FilmPage .fp-bleed), Back and Share floating on it as round buttons. */
.fp-page { position: relative; }
.fp-float { position: absolute; top: 12px; left: 12px; z-index: 6; }
.fd-hero-float { position: absolute; top: 12px; right: 12px; z-index: 3; }
/* Back and Share floating on the backdrop are the dark icon circle (.icirc.on-image, owner, 2026-10-31). */
.fp-page:has(.fd-page-back) .fp-float { display: none; }
.fp-page .fd-page-back { position: absolute; top: 12px; left: 12px; z-index: 6; margin: 0; max-width: calc(100% - 88px); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  background: rgba(11,11,13,.7); border-color: rgba(255,255,255,.14); -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px); }
.fp-page .fd-hero { height: 292px; aspect-ratio: auto; max-height: none; min-height: 0; margin-top: 0; }
@media (max-width: 699px) { .fp-page .fd-hero { width: 100vw; margin-left: calc(50% - 50vw); margin-right: 0; border-radius: 0; } }
