.fd-herowrap > .fd-hero-body > .fd-hero-poster { flex: none; width: 108px; height: 162px; aspect-ratio: auto; border: 1px solid var(--ink); border-radius: 6px; box-shadow: 6px 6px 0 var(--shadow); }
.fd-herowrap > .fd-hero-body > .fd-hero-text { flex: 1 1 auto; min-width: 0; width: auto; max-width: 620px; padding: 0 0 2px; }
.fd-herowrap .fd-title { margin: 0 0 6px; font: var(--t-title); letter-spacing: -.01em; overflow-wrap: break-word; }
.fd-herowrap .fd-orig-title { margin: -2px 0 6px; font: italic 500 var(--fs-card)/22px var(--serif); color: #cfc8ba; }
.fd-herowrap .fd-hero-facts { display: block; margin: 0 0 2px; padding: 0; border: 0; font: var(--t-caption); letter-spacing: 0; text-transform: none; color: var(--muted); }
.fd-herowrap .fd-hero-director { display: block; margin: 0; font: var(--t-caption); color: var(--muted); }
.fd-herowrap .fd-hero-director-v { font: 500 var(--fs-meta)/18px var(--sans); color: var(--ink); }
.fd-herowrap .fd-hero-note { margin-top: 2px; font: var(--t-caption); color: var(--faint); }
/* The match sits under the title block, from its left edge (owner, 2026-10-21: "spacing is horrible": it floated right). */
.fd-herowrap .fd-hero-stats { position: static; display: flex; flex-direction: row; justify-content: flex-start; align-items: center; gap: 8px; margin: 12px 0 0; padding: 0; }
.fd-herowrap .fd-hero-stats .fd-stat-l { margin: 0; font: var(--t-caption); color: var(--muted); }
/* Lanes: a section of their own under one Label (owner, 2026-10-21); genres stay in the meta line. */
.fd-lanesec { margin: var(--sp-24) 0 0; padding: 0; border: 0; }
.fd-lanesec > .fd-hero-tags { display: flex; flex-wrap: wrap; gap: 8px; margin: var(--sp-8) 0 0; }
/* Theme and tag chips wear the lane chip, in sentence case (rule 454): the film's Themes tab, a tag
   page's neighbouring lanes, the lanes two people share, a profile's lanes. */
.fd-lanesec > .fd-hero-tags .match-tag, .fd-lanesec > .fd-hero-tags .match-tag:nth-child(n+4),
.fd-infopanel .fd-themes .match-tag, .tp-neighbours .match-tags .match-tag, .mx-chips .mx-chip, .pv2-taste .hero-lanes-list .hero-lane { display: inline-flex; align-items: center; height: 28px; max-width: 100%; padding: 0 10px;
  border: 1px solid var(--line-2); border-radius: 6px; background: none; font: 500 var(--fs-meta)/1 var(--sans); letter-spacing: 0; text-transform: none; color: var(--muted);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.fd-lanesec > .fd-hero-tags a.match-tag:hover, .fd-infopanel .fd-themes a.match-tag:hover, .tp-neighbours .match-tags a.match-tag:hover,
