/* The room's How was it? (rule 1249) draws the film page's own row: the same size, gap and colours. */
.hwi .fa-stars { gap: 4px; touch-action: pan-y; }
.hwi .fa-star-wrap, .hwi .fa-star { width: 30px; height: 30px; }
.hwi .fa-star { font-size: 32px; line-height: 30px; color: var(--line-2); } /* type scale exception: star glyphs */
.hwi .fa-star.on { color: var(--accent-2); }
.hwi .fa-star.half { background: linear-gradient(90deg, var(--accent-2) 50%, var(--line-2) 50%); -webkit-background-clip: text; background-clip: text; }
.fd-ratings-card .fa-lb-rating { margin-left: auto; font: var(--t-caption); color: var(--muted); }
.fd-ratings-card .fa-watches { justify-content: space-between; margin: 8px 0 0; font: var(--t-caption); color: var(--muted); }
.fd-ratings-card .fd-ratings-btns { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin-top: 8px; }
.fd-ratings-btns .fa-watch, .fd-ratings-btns .fa-canon { min-width: 0; min-height: var(--btn-h); height: var(--btn-h); padding: 0 6px; gap: 6px; border-radius: var(--btn-r) !important;
  font: var(--t-callout); white-space: nowrap; }
.fd-ratings-btns .fa-watch svg { width: 18px; height: 18px; flex: none; }
.fd-ratings-btns .fa-canon:not(.on) { background: rgba(255,255,255,.06); border-color: var(--line-2); color: var(--ink); }
.fd-ratings-btns .fa-canon:not(.on) .fa-canon-star { color: var(--red); }
/* Friends is a hairline row, not a second keylined box. */
.fd-ratings-card .fp-fr::before, .fd-ratings-card .fp-fr::after { content: none; }
.fd-ratings-card .fp-fr-h { align-items: baseline; gap: 4px 8px; }
.fd-ratings-card .fp-fr-n, .fd-ratings-card .fp-fr-likein { font: var(--t-caption); color: var(--muted); }
.fd-ratings-card .fp-fr-likein b { font-size: var(--fs-meta); }
/* About / Cast / Crew / Details: sentence-case underline tabs; the synopsis reads at 16/24. */
.fd-infopanel .fd-infotabs { gap: 24px; margin: 0 0 var(--sp-12); padding: 0; }
.fd-infopanel .fd-infotab { height: 40px; padding: 0; margin-bottom: -1px; font: 500 var(--fs-ui)/20px var(--sans); letter-spacing: 0; text-transform: none; color: var(--faint); border-bottom: 2px solid transparent; }
.fd-infopanel .fd-infotab.on { color: var(--ink); border-bottom-color: var(--select); }
.fd-infopanel .fd-overview { font: 400 var(--fs-read)/24px var(--sans-read); font-size-adjust: .45; color: rgba(239,232,218,.86); }
.fd-grid { margin-top: var(--sp-24); }
@media (max-width: 759px) { main.wrap.fp-bleed { padding-top: 0; } }

/* Film sheet head, option 3 (owner-approved mock, 2026-10-21, mockups/film-sheet-match-layouts.png; rule 417):
   poster with Trailer on its right, the title full width under them, then the match in its own row. */
.fd-herowrap > .fd-hero-stack { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; margin: -108px 0 0; padding: 0; min-height: 0; }
.fd-herowrap > .fd-hero-stack > .fd-hero-poster { flex: none; width: 108px; height: 162px; aspect-ratio: auto; border: 1px solid var(--ink); border-radius: 6px; box-shadow: 6px 6px 0 var(--shadow); }
.fd-hero-aside { display: flex; align-items: flex-end; padding-bottom: 2px; }
.fd-hero-aside .trailer-btn { height: var(--btn-h); padding: 0 16px; border-radius: 999px; background: var(--cream); color: var(--cream-ink); border: 0; font: var(--t-callout); }
.fd-hero-aside .trailer-btn svg { color: var(--cream-ink); }
.fd-herowrap > .fd-hero-text-full { margin: var(--sp-16) 0 0; padding: 0; width: auto; max-width: 620px; }
.fd-herowrap .fd-hero-text-full .fd-hero-stats { display: block; margin: 14px 0 0; }
.fd-herowrap > .fd-hero-stats-full { display: block; margin: 14px 0 0; max-width: 620px; }
/* A wide screen (owner, 2026-10-29, mockups/film-match-desktop.html A): the match and the trailer
   sit in a rail beside the title, top-aligned with it, instead of the match under the synopsis
   and the trailer alone at the far right. The trailer keeps its own pill size. */
@media (min-width: 900px) {
  .fd-herowrap-rail { display: grid; grid-template-columns: minmax(0, 1fr) 300px; grid-template-rows: auto auto auto auto 1fr; column-gap: 40px; }
  .fd-herowrap-rail > * { grid-column: 1 / -1; }
  .fd-herowrap-rail > .fd-hero-stack { display: contents; }
  .fd-herowrap-rail > .fd-hero-stack > .fd-hero-poster { grid-column: 1; grid-row: 2; margin-top: -108px; }
  .fd-herowrap-rail > .fd-hero-text-full { grid-column: 1; grid-row: 3 / span 3; max-width: 620px; }
  /* Trailer on top, the match or "Why you liked it" under it (owner, 2026-10-30: "put trailer button
     above the why you liked/didnt modal"). */
  .fd-herowrap-rail > .fd-hero-stack > .fd-hero-aside { grid-column: 2; grid-row: 3; align-self: start; padding: 0; margin-top: var(--sp-16); }
  .fd-herowrap-rail > .fd-hero-stats-full { grid-column: 2; grid-row: 4; margin: 12px 0 0; max-width: none; }
  .fd-herowrap-rail:not(:has(> .fd-hero-stats-full)) > .fd-hero-stack > .fd-hero-aside { grid-row: 3; margin-top: var(--sp-16); }
  .fd-herowrap-rail .fd-hero-stats-full .fd-matchrow:not(.fd-matchrow-seen) { flex-wrap: wrap; align-items: flex-end; row-gap: 10px; padding: 16px; }
  .fd-herowrap-rail .fd-hero-stats-full .fd-matchrow:not(.fd-matchrow-seen) .fd-matchrow-n { flex-basis: 100%; font-size: 44px; } /* type scale exception: match % numerals */
  .fd-herowrap-rail .fd-hero-stats-full .fd-matchrow:not(.fd-matchrow-seen) .fd-matchrow-u { font-size: var(--fs-card); }
  .fd-herowrap-rail .fd-hero-stats-full .fd-matchrow-go { padding: 0; }
}
.fd-matchrow { display: flex; align-items: center; gap: 12px; padding: 12px 14px; border: 1px solid var(--line-2); border-radius: 12px; background: #101319; }
.fd-matchrow-n { flex: none; font-family: var(--serif); font-weight: 500; font-size: var(--fs-title); /* 28, as the iPhone (rule 1062) */ line-height: 1; color: var(--accent-2); font-variant-numeric: tabular-nums; } /* type scale exception: match % numerals */
.fd-matchrow-u { font-size: var(--fs-ui); margin-left: 1px; }
.fd-matchrow-t { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; font: var(--t-caption); color: var(--muted); }
.fd-matchrow-t b { display: inline-flex; align-items: center; gap: 4px; font: 500 var(--fs-ui)/18px var(--sans); color: var(--ink); }
.fd-matchrow-go { flex: none; appearance: none; border: 0; background: none; padding: 8px 0 8px 8px; cursor: pointer; font: 500 var(--fs-ui)/1 var(--sans); color: var(--muted); }
.fd-matchrow-go { display: inline-flex; align-items: center; gap: 2px; }
.fd-matchrow-chev { flex: none; }
.fd-matchrow.is-early .fd-matchrow-n, .why-drawer-hd.is-early .fd-matchrow-n { color: var(--muted); }
.why-drawer-t b:has(.fd-early-tag) { display: inline-flex; align-items: center; gap: 6px; }
.fd-early-tag { font: 500 var(--fs-label)/1 var(--sans); color: var(--muted); border: 1px solid var(--line-2); border-radius: 6px; padding: 3px 6px; white-space: nowrap; }

/* Why it fits as a drawer (owner-approved mock, 2026-10-21, mockups/film-sheet-why-drawer.png; rule 418). */
.fd-matchrow { cursor: pointer; }
.why-drawer { max-height: 86vh; overflow-y: auto; }
.why-drawer-hd { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; }
.why-drawer-hd .fd-matchrow-n { font-size: 40px; }
.why-drawer-t { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; font: var(--t-caption); color: var(--muted); }
.why-drawer-t b { font: 500 var(--fs-read)/20px var(--sans); color: var(--ink); }
.why-drawer .fd-whypanel { background: none; padding: 0; border-radius: 0; }
/* "Where it might lose you" keeps its red, now framed in it. */
.why-drawer .fd-caveat { margin-top: 14px; padding: 0 0 0 12px; border: 0; border-left: 2px solid var(--shadow); border-radius: 0; background: none; }
.why-drawer-like { margin-top: var(--sp-16); }
/* Room under and right of each poster for its oxblood offset shadow (the row scrolls, so it clips). */
.why-drawer-posters { display: flex; gap: 10px; margin-top: 8px; overflow-x: auto; scrollbar-width: none; padding: 0 6px 6px 0; }
.why-drawer-posters::-webkit-scrollbar { display: none; }
.why-drawer-poster { flex: none; width: 92px; appearance: none; border: 0; background: none; padding: 0; cursor: pointer; text-align: left; color: var(--ink); font: inherit; }
.why-drawer-po { position: relative; display: block; width: 92px; aspect-ratio: 2 / 3; border-radius: 4px; overflow: hidden; background: var(--panel-2); }
.why-drawer-po img { width: 100%; height: 100%; object-fit: cover; display: block; }
.why-drawer-name { display: block; margin-top: 10px; font: var(--t-caption); color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* The match is a blue number (owner, 2026-10-21: "switch the rest to the blue number too";
   mockups/match-blue-number.png; rule 419). Picks, Tonight's pick and the decks: the Bodoni number in
   the accent blue, its label under it, no ticket. On a poster: a small blue stamp on a dark backing,
   tilted a touch, so it reads on any art. Social: a plain blue number. */
.picks .pk-stat, .pk-stat, .tnp-pct { background: none; color: inherit; padding: 0; border-radius: 0; text-align: right; -webkit-mask: none; mask: none; }
.picks .pk-stat-n, .pk-stat-n { font: 500 36px/.9 var(--serif); letter-spacing: 0; font-variant-numeric: tabular-nums; color: var(--accent-2); } /* type scale exception: rank numerals or ticket stub */
.picks .pk-stat-u, .pk-stat-u { font-size: var(--fs-read); margin-left: 1px; }
.picks .pk-stat-l, .pk-stat-l { margin-top: 4px; font: 400 var(--fs-label)/1 var(--sans); color: var(--muted); opacity: 1; }
@media (min-width: 1000px) { .picks .pk-stat-n { font-size: 48px; } .picks .pk-stat-u { font-size: var(--fs-heading); } } /* type scale exception: rank numerals or ticket stub */
.pf-grid .wlrank-badge, .tnp-alt-poster .wlrank-badge, .phold-po .wlrank-badge, .bx-stub {
  -webkit-mask: none; mask: none; background: var(--bg); border: 1.5px solid var(--accent); color: var(--accent-2); box-shadow: none;
  font: 500 var(--fs-read)/1 var(--serif); padding: 3px 6px 2px; border-radius: 2px; transform: rotate(-3deg); transform-origin: left bottom; } /* type scale exception: rank numerals or ticket stub */
/* The last two posters still in the old cream tag (owner, 2026-10-30: "same match score formatting
   across iOS and the web"): the ranked watchlist outside Browse and the walkthrough's "Every film,
   scored for you" art wear the same stamp, bottom left. */
.wlrank .wlrank-badge {
  -webkit-mask: none; mask: none; background: var(--bg); border: 1.5px solid var(--accent); color: var(--accent-2); box-shadow: none;
  font: 500 var(--fs-read)/1 var(--serif); padding: 3px 6px 2px; border-radius: 2px; transform: rotate(-3deg); transform-origin: left bottom; /* type scale exception: rank numerals or ticket stub */
  top: auto; right: auto; left: 5px; bottom: 5px; }

/* Your people's faces: their match is the poster stamp too (owner, 2026-10-21: "still the white ticket"; rule 419). */
.people-pct { -webkit-mask: none; mask: none; background: rgba(11,11,13,.9); border: 1.5px solid #7fa6d6; color: #b3cdec; font: 600 12px/1.3 var(--serif); /* type scale exception: match % numerals */
  padding: 0 5px; border-radius: 2px; transform: translateX(-50%) rotate(-3deg); box-shadow: none; }

/* The Find tile carries the search icon, not a plus (owner, 2026-10-21). */
.people-find-av svg { width: 24px; height: 24px; }

/* The hold is felt (owner, 2026-10-21: "it doesn't feel like I'm clicking something"; rule 422): the poster
   sinks over the hold's 450ms, then the menu pops in. A grid's rating is the blue stamp too. */
[data-hold] { transition: transform .2s ease; }
[data-hold].is-pressing { transform: scale(.94); transition: transform .45s cubic-bezier(.2,.8,.2,1); }
.hold-scrim { animation: phold-fade .18s ease both; }
.phold-in { animation: phold-pop .22s cubic-bezier(.2,.9,.3,1.2) both; }
@keyframes phold-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes phold-pop { from { opacity: 0; transform: scale(.9); } to { opacity: 1; transform: scale(1); } }
@media (prefers-reduced-motion: reduce) { [data-hold].is-pressing { transform: none; } .hold-scrim, .phold-in { animation: none; } }
.pf-grid .lib-rating { -webkit-mask: none; mask: none; background: var(--bg); border: 1.5px solid var(--accent); color: var(--accent-2); box-shadow: none;
  font: 500 var(--fs-read)/1 var(--serif); padding: 3px 6px 2px; border-radius: 2px; transform: rotate(-3deg); transform-origin: left bottom; }
/* One line between the Friends row and About, not two (owner, 2026-10-21; rule 423): the info panel's own
   top rule doubled the Friends line's bottom one. */
/* The seen film's drawer leads with your rating (rule 424). */
.why-drawer-hd .why-drawer-rating .fd-matchrow-u { font-size: var(--fs-heading); margin-left: 2px; }

/* The Why drawer's close sits in its header row, not pinned to the sheet's corner (owner, 2026-10-21; rule 427). */
.why-drawer-hd .share-sheet-x { position: static; flex: none; margin-left: auto; }

/* The held poster's menu opens under the finger: nothing in it can be selected or called out, so the
   press that opened it never highlights a word (owner, 2026-10-21; rule 428). */
.phold, .phold *, .hold-scrim { -webkit-touch-callout: none; -webkit-user-select: none; user-select: none; }

/* The synopsis under the title, two lines then More (owner, 2026-10-21; rule 430). */
.fd-hero-synopsis { margin-top: 12px; }
.fd-hero-synopsis .fd-overview { font: 400 var(--fs-ui)/22px var(--sans-read); font-size-adjust: .45; color: rgba(239,232,218,.86); max-width: none; }
.fd-hero-synopsis .fd-overview.is-clamped { -webkit-line-clamp: 2; }
.fd-hero-synopsis .fd-overview-more { margin-top: 4px; }

/* Lanes under "Directed by", small chips with no Label; the plot a little further below (owner, 2026-10-21; rule 432). */
.fd-lanesec.fd-lanesec-top { margin: 10px 0 0; }
.fd-lanesec-top > .fd-hero-tags { margin: 0; gap: 6px; }
.fd-lanesec-top + .fd-hero-synopsis { margin-top: 14px; }

/* Share on the film sheet's backdrop lines up under the × (owner, 2026-10-21; rule 433). The backdrop
   bleeds exactly the sheet's side padding (on a phone it bled 28px past an 18px padding, so it ran
   off screen and took Share with it), and Share's centre sits on the ×'s: padding + 16px (half the
   32px ×) - 20px (half the 40px Share). */
.tonight-modal.fd-modal .fd-hero-float { right: 24px; }
@media (max-width: 700px) {
  .tonight-modal.modal-sheet:has(.fd-herowrap) .fd-hero { margin-left: -18px; margin-right: -18px; }
  .tonight-modal.fd-modal .fd-hero-float { right: 14px; }
}

/* The film sheet's loading wireframe, shaped like the loaded sheet (owner, 2026-10-21; rule 434). */
.fd-skel .fd-skel-trailer { display: block; width: 104px; height: var(--btn-h); border-radius: 999px; }
.fd-skel .fd-hero-aside { display: flex; align-items: flex-end; justify-content: flex-end; }
.fd-skel .fd-skel-chip { display: inline-block; width: 11em; height: var(--chip-h); border-radius: 6px; }
.fd-skel .fd-skel-matchrow { display: block; height: 66px; border-radius: 12px; }
.fd-skel .fd-ratings-btns { display: flex; gap: 8px; }
.fd-skel .fd-skel-btn { flex: 1; height: var(--btn-h); border-radius: var(--btn-r); }
.fd-skel .fa-star { color: var(--line-2); }
.fd-skel .fd-skel-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }

/* The film sheet's sections read as sections (owner-approved mock, 2026-10-21,
   mockups/film-sheet-sections-spacing.png; rule 435): the same 16px at every section edge, one
   clearer line between sections, and inside a section its rows' lines go faint and sit tighter.
   Labels unchanged. */
.fd .fd-infopanel .fd-infotabs { margin-bottom: 12px; }
.fd .fd-infopanel .fd-themes { margin-top: 0; }
.fd section.fp .fp-head { margin: 0 0 8px; }
.fd section.fp .fp-head .sec { margin: 0; padding: 0; }
.fd section.fp .fp-with { margin-top: 0; }
.fd .fd-watch .fd-wt-row { border-bottom-color: rgba(255,255,255,.06); }

/* Info popups as a compact card (owner-approved mock, 2026-10-21, mockups/info-popup-options.png, A; rule 436):
   narrower, the term in the title serif, tight padding, one "Got it", no offset shadow. */
.info-modal { width: min(400px, 100%); padding: var(--sp-16) var(--sp-16) var(--sp-12); border-radius: 12px; box-shadow: 0 18px 40px rgba(0,0,0,.6); }
@media (max-width: 520px) { .info-modal { width: calc(100% - 40px); padding: var(--sp-16) var(--sp-16) var(--sp-12); } }
.info-modal-hd { margin-bottom: 6px; }
.info-modal .info-modal-hd .sec-info-pop-title { font: 500 var(--fs-heading)/1.2 var(--serif); letter-spacing: 0; text-transform: none; color: var(--ink); }
.info-modal > p, .info-modal > div > p { font-size: var(--fs-ui); line-height: 1.5; color: rgba(239,232,218,.86); }
.info-modal > p:first-of-type { margin-top: 0; }
.info-modal > p:last-of-type { margin-bottom: 0; }
.info-modal-ft { display: flex; justify-content: flex-end; margin-top: 10px; }
.info-modal-ok { color: var(--accent-2); font-size: var(--fs-ui); font-weight: 500; padding: 6px 0; }

/* A lane, theme or person page's match is the blue poster stamp, as on every other grid (owner, 2026-10-21; rule 437). */
.tp-card .wlrank-badge:not(.bs-badge) { -webkit-mask: none; mask: none; background: var(--bg); border: 1.5px solid var(--accent); color: var(--accent-2); box-shadow: none;
  font: 500 var(--fs-read)/1 var(--serif); padding: 3px 6px 2px; border-radius: 2px; transform: rotate(-3deg); transform-origin: left bottom; top: auto; right: auto; left: 6px; bottom: 6px; } /* type scale exception: rank numerals or ticket stub */

/* "In theaters" never runs under the watchlist ribbon (owner, 2026-10-21; rule 439): the tag stops short
   of the ribbon's corner and wraps to two lines on a narrow tile. */
.rel-tag { max-width: calc(100% - 40px); white-space: normal; font-size: 9px; letter-spacing: .04em; } /* type scale exception: poster badge in a fixed box */

/* The Why drawer of a film you've seen: what we'd predicted before you rated it (owner, 2026-10-22; rule 446). */
.why-drawer-pred b { font: 500 var(--fs-read)/1 var(--serif); color: var(--accent-2); }

/* The group page in the app's own type and controls (owner-approved mock, 2026-10-22,
   mockups/group-watchlist-aligned.png; rule 449): the blue serif number for every match, "Saved by"
   as a blue link, "+ Group list" and the sorts as the standard 32px chip, the filled search field. */
.grp-ov-meta b { font: 500 var(--fs-card)/1 var(--serif); color: var(--accent-2); margin-right: 3px; }
.grp-ov-who { appearance: none; background: none; border: 0; padding: 2px 0 0; margin: 0; height: auto; border-radius: 0; color: var(--accent-2); letter-spacing: 0;
  font: 500 var(--fs-meta)/1.3 var(--sans); text-align: left; cursor: pointer; display: block; }
.grp-ov-add { height: var(--chip-h); padding: 0 12px; border-radius: var(--radius-pill); border: 1px solid var(--line-2); background: transparent;
  color: var(--ink); font: 600 var(--fs-meta)/1 var(--sans); margin-top: 8px; width: auto; align-self: flex-start; display: inline-flex; align-items: center; }
.grp-ov-add.on { color: var(--bg); border-color: var(--select); background: var(--select); }
.grp-ov-add { white-space: nowrap; }
.gwl-chipbtn { height: var(--chip-h); padding: 0 12px; border-radius: var(--radius-pill); border: 1px solid var(--line-2); background: transparent;
  color: var(--ink); font: 600 var(--fs-meta)/1 var(--sans); }
.gwl-chipbtn.on { background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); color: var(--ink); }
.gwl-add .ig-search { background: var(--panel-2); border-color: transparent; border-radius: 12px; min-height: 44px; }
.gwl-r-pct { text-decoration: none; }
.gwl-r-pct b { font: 500 28px/.9 var(--serif); color: var(--accent-2); border: 0; text-decoration: none; }
.gwl-r-pct b em { font-style: normal; font-size: 14px; } /* type scale exception: match % numerals */
.gwl-r-pct i { font: 400 11px/1 var(--sans); letter-spacing: 0; text-transform: none; color: var(--muted); }

/* The group film's why as a bottom drawer (owner-approved mock, 2026-10-22, mockups/group-why-drawer.png; rule 450). */
.gwd .gwd-lab { margin-top: 14px; font: 700 var(--fs-label)/1.2 var(--sans); letter-spacing: .18em; text-transform: uppercase; color: var(--accent-2); }
.gwd .gwd-lab-quiet { color: var(--faint); margin-top: var(--sp-16); }
.gwd .gwd-read p { margin: 6px 0 0; font: 400 var(--fs-ui)/1.5 var(--sans-read); color: var(--ink); }
.gwd-m { display: flex; gap: 11px; align-items: flex-start; padding: 10px 0; border-top: 1px solid rgba(255,255,255,.06); }
.gwd-lab + .gwd-m { border-top: 0; }
.gwd-av { width: 32px; height: 32px; border-radius: var(--radius-av); object-fit: cover; flex: none; display: inline-flex; align-items: center; justify-content: center; font: 600 var(--fs-meta)/1 var(--sans); }
.gwd-mb { flex: 1; min-width: 0; }
.gwd-mb b { font: 600 var(--fs-ui)/1.3 var(--sans); }
.gwd-why { font: 400 var(--fs-meta)/1.4 var(--sans); color: var(--muted); margin-top: 2px; }
.gwd-tags { margin-top: 3px; font: 500 var(--fs-meta)/1.4 var(--sans); }
.gwd-tag.is-fit, .gwd-tag.is-note { color: var(--accent-2); }
.gwd-tag.is-miss { color: #d98a90; }
.gwd-sc { flex: none; text-align: right; }
.gwd-sc b { display: block; font: 500 var(--fs-heading)/1 var(--serif); color: var(--accent-2); }
.gwd-sc b small { font-size: var(--fs-meta); }
.gwd-sc i { display: block; font: 400 var(--fs-label)/1.3 var(--sans); font-style: normal; color: var(--muted); }
.gwd-next { display: flex; gap: 10px; align-items: center; margin-top: 8px; }
.gwd-next-open { flex: none; padding: 0; border: 0; background: none; cursor: pointer; display: block; }
.gwd-next-po { width: 38px; height: 56px; border-radius: 3px; object-fit: cover; flex: none; background: var(--panel-2); display: inline-flex; align-items: center; justify-content: center; font: 600 var(--fs-label)/1 var(--sans); color: var(--muted); }
.gwd-next-b { flex: 1; min-width: 0; }
.gwd-next-b b { font: 500 var(--fs-read)/1.2 var(--serif); }
.gwd-next-b .yr { font: 400 var(--fs-label)/1 var(--sans); color: var(--faint); }
.gwd-next-b div { font: 400 var(--fs-meta)/1.35 var(--sans); color: var(--muted); margin-top: 2px; }
.gwd .gwd-open { width: 100%; margin-top: 16px; min-height: var(--btn-h); border-radius: var(--btn-r); background: var(--cream); color: var(--cream-ink); border-color: var(--cream); }

/* ============================================================================================
   READING TEXT (owner, 2026-10-22; rule 443). Sentences someone reads, not controls: synopses,
   explanations, (i) panel bodies, archetype and lane blurbs, Film DNA notes, pick reasons and why
   lines, empty states, bios, takes, the About, Privacy and Terms pages. They are Newsreader
   (--read); everything else stays the system UI voice (--ui). Plain selectors (never :is(), which
   would lend every entry the heaviest one's weight), so a more specific rule elsewhere that sets
   Bodoni still wins. Controls inside a reading block keep the UI voice. Newsreader's x-height
   (.43 of its size) is lower than the system font's (about .52), so at the same px it read a size
   smaller; font-size-adjust .45 draws it about 1px larger (16px reads as 17) without moving the
   line heights or the sizes the rest of the file sets.
   ============================================================================================ */
.t-body, .lead, .summary, .why, .fa-said,
.ppview-bio, .ppview-blurb, .ppview-mixsummary, .ppview-line, .pm-bio, .ph-bio, .hero-blurb,
.mx-surprise-line, .mx-share-gate p, .mx-side p, .compat-div, .compat-surprise-line,
.weekpick-reason, .dsc-hero-desc, .hrec-reason, .dsc-starter-p, .dsc-build-p, .recs-soon-body,
.fl-confirm-body, .modal-sub, .cfm-p, .hideask-p, .bnr-p, .status-body, .wt-body, .rcpt-sub,
.gwl-read p, .gwl-why-text, .gwd-why, .gpage-desc, .grp-masthead-why, .grp-hero-why, .grp-solo-p, .gjoin-sub,
.mn-why, .mn-pick-why, .mn-pick-blurb, .thx-why, .thx-cer-why, .thx-lane-why, .thx-lane-blurb, .thx-gate-why,
.tn-ticket-why, .tn-occasion-note, .mnr-lede, .mnr-card-p, .thx-guestcta-p,
.friends-hero-body, .fp-div, .friend-hint-line, .activity-empty, .fp-cta-sub,
.acct-keepnote-s, .onboard-pillars-lede, .onboard-cine-sub, .signin-msg, .oauth-inapp-msg,
.tabview-sub, .asell-sub, .tabsell-sub, .lockid-oneline, .reveal-card-line, .reveal-save-sub,
.dna-sub, .dna-detail-hint, .sig-why-text, .sec-info-pop p, .info-modal > p, .info-modal > div > p,
.fd-why-text, .fd-overview, .fd-watch-empty, .fd-gate-lead, .fp-take-q, .fdisc-tx,
.why-loved-tile .wl-exp, .wl-empty, .lib-empty, .cv-empty-p, .browse-empty, .pfold-p, .wstreak-note, .rhythm-sub,
.arche-sub, .arche-desc, .arch-why-intro, .arch-why-also p, .arch-sheet-desc, .tp-blurb, .reel-reason,
.about-part-p, .legal p, .legal-list li, .short-read-s { font-family: var(--read); font-size-adjust: .45; }
.pv2-detail .dna-detail-note, .dna-radar-detail .dna-detail-note { font-family: var(--read); font-size-adjust: .45; }
.legal p.legal-updated { font: var(--t-caption); font-size-adjust: none; letter-spacing: normal; text-transform: none; color: var(--faint); }
:where(.t-body, .lead, .summary, .why, .modal-sub, .gpage-desc, .fd-overview, .legal p, .info-modal > p, .sec-info-pop p, .fd-why-text)
  :where(button, input, select, textarea, .btn, .chip, .linkbtn) { font-family: var(--ui); }

/* The one bottom drawer (owner-approved mock, 2026-10-22, mockups/drawers-sweep.png; rule 451). */
.share-sheet.bd { padding-top: 8px; }
.share-sheet.bd-tall { max-height: 92vh; }
.bd-handle { width: 36px; height: 4px; border-radius: 2px; background: var(--line-2); margin: 0 auto 12px; }
@media (min-width: 700px) { .bd-handle { display: none; } }
.bd-hd { display: flex; align-items: center; gap: 8px; margin-bottom: 12px; }
.bd-t { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.bd-t b { font: 500 var(--fs-heading)/1.15 var(--serif); color: var(--ink); }
.bd-t span { font: 400 var(--fs-meta)/1.35 var(--sans); color: var(--muted); }
.bd-t span.bd-k { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bd .info-lede, .bd .bd-lede { margin: 0 0 12px; font: 400 var(--fs-ui)/1.45 var(--sans); color: var(--muted); }
.bd-x { flex: none; width: 32px; height: 32px; border-radius: var(--radius-sm); border: 1px solid var(--line-2); background: none; color: var(--muted);
  font-size: var(--fs-card); line-height: 1; display: inline-flex; align-items: center; justify-content: center; cursor: pointer; }
.bd .bd-lab { margin: 14px 0 6px; font: 700 var(--fs-label)/1.2 var(--sans); letter-spacing: .18em; text-transform: uppercase; color: var(--faint); }
.bd .bd-p { margin: 0; font: 400 var(--fs-ui)/1.5 var(--sans-read); color: rgba(239,232,218,.86); }
.bd .bd-btn { width: 100%; min-height: var(--btn-h); border-radius: var(--btn-r); margin-top: 10px; display: flex; align-items: center; justify-content: center;
  font: 600 var(--fs-ui)/1 var(--sans); background: none; border: 1px solid var(--line-2); color: var(--ink); cursor: pointer; }
.bd .bd-btn.cream { background: var(--cream); color: var(--cream-ink); border-color: var(--cream); }
.bd .bd-btn.danger { color: var(--danger); border-color: rgba(217,138,144,.45); }
.bd .bd-two { display: flex; gap: 8px; }
.bd .bd-two .bd-btn { flex: 1; }

/* Canon and the archetypes keep their own look and rise from the bottom as tall drawers on a phone (rule 451). */
@media (max-width: 699px) {
  .modal-overlay.bd-rise { align-items: flex-end; padding: 0; }
  .modal.bd-rise-panel { width: 100%; max-width: none; max-height: 92vh; margin: 0; border-radius: var(--radius-drawer) var(--radius-drawer) 0 0; border-bottom: 0; box-shadow: none;
    animation: sheet-up .22s var(--ease); padding-top: 8px; padding-bottom: calc(18px + env(safe-area-inset-bottom)); overflow-y: auto; }
  .modal.cv-modal.bd-rise-panel { padding-top: 8px; padding-left: 0; padding-right: 0; }
}
@media (min-width: 700px) { .bd-rise-panel > .bd-handle { display: none; } }

/* The older drawers (friend preview, add people, new group, join the night, hide this film) in the
   same look as the rest (owner-approved mock, 2026-10-22, mockups/drawers-sweep.png, 8-10; rule 451):
   a handle, the title in the serif, the boxed ×, the blue serif match, the cream main button. */
.fp-sheet { padding-top: var(--sp-24); border-radius: var(--radius-drawer) var(--radius-drawer) 0 0; }
.fp-sheet::before { content: ""; position: absolute; top: 8px; left: 50%; width: 36px; height: 4px; margin-left: -18px; border-radius: 2px; background: var(--line-2); }
@media (min-width: 560px) { .fp-sheet { border-radius: var(--radius-drawer); } .fp-sheet::before { display: none; } }
.fp-close { top: 16px; right: 16px; width: 32px; height: 32px; padding: 0; border: 1px solid var(--line-2); border-radius: var(--radius-sm);
  font-size: var(--fs-card); display: inline-flex; align-items: center; justify-content: center; }
.fp-sheet .mn-title { font: 500 var(--fs-heading)/1.15 var(--serif); text-align: left; padding-right: 44px; }
.fp-sheet .mn-sub { text-align: left; }
.fp-name { font: 500 var(--fs-heading)/1.15 var(--serif); }
.fp-score { font-family: var(--serif); font-weight: 500; }
.fp-score em { font-weight: 500; }
.fp-sheet .fp-primary, .hideask .fp-primary { background: var(--cream); color: var(--cream-ink); border-color: var(--cream); }
.hideask-h { font-weight: 500; padding-right: 0; }

/* The film's title fills its first line before wrapping (owner, 2026-10-22: "why doesn't the title first
   line fit more of the first line"; rule 452): balance split it into equal halves; pretty only keeps a
   lone word off the last line. */
.fd-herowrap .fd-title { text-wrap: pretty; }

/* How we did in the Why drawer's header (rule 454): the verdict mark, then "We said 64% · Called it". */
.why-drawer-said { display: inline-flex; align-items: center; gap: 6px; }
.why-drawer-said svg, .why-drawer-said > span:first-child { flex: none; width: 16px; height: 16px; }

/* More contrast under the film's title (owner-approved mock B, 2026-10-22, mockups/film-head-type-options.png,
   with the plot upright and the director's name not in italics; rule 455): the facts as a small spaced
   label, the director's name in the title serif. */
.fd-herowrap .fd-hero-facts { font: 600 var(--fs-label)/1.4 var(--sans); letter-spacing: .14em; text-transform: uppercase; color: var(--faint); }
.fd-herowrap .fd-hero-director { margin-top: 6px; }
.fd-herowrap .fd-hero-director-v { font: 500 var(--fs-card)/1.2 var(--serif); color: var(--ink); letter-spacing: 0; }

/* The movie night invite as one centred column on a wide screen (owner, 2026-10-22: "why is this not
   centered"; rule 456): it sat flush left in the page's wide column, with the sign-in buttons capped
   narrower than the text above them. */
.mnr.mnr-welcome { width: 100%; max-width: 520px; margin-left: auto; margin-right: auto; }
.mnr-welcome .mnr-signin .signin-form { max-width: none; }
.mnr-welcome .mnr-quiet-link { display: block; margin-left: auto; margin-right: auto; }

/* Movie night's vote: the marquee and the tickets (owner-approved mock, 2026-10-22,
   mockups/movie-night-vote-mix.png; rule 458). */
.mnm { margin-top: 14px; }
.mnm-marquee { position: relative; height: 250px; border-radius: var(--radius-field); overflow: hidden; background: var(--panel-2); border: 1px solid var(--line-2); }
.mnm-marquee.mine { border-color: var(--accent-2); }
.mnm-stub { position: relative; width: 70px; flex: none; border: 0; border-left: 2px dashed var(--line-2); background: none; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 4px; cursor: pointer; color: var(--ink); }
.mnm-stub::before, .mnm-stub::after { content: ""; position: absolute; left: -9px; width: 16px; height: 16px; border-radius: 50%; background: var(--bg); border: 1px solid var(--line-2); }
.mnm-stub::before { top: -9px; } .mnm-stub::after { bottom: -9px; }
.mnm-stub b { font: 500 21px/1 var(--serif); color: var(--accent-2); } /* type scale exception: rank numerals or ticket stub */
.mnm-stub b small { font-size: 11px; }
.mnm-stub i { font: 700 11px/1 var(--sans); font-style: normal; letter-spacing: .14em; text-transform: uppercase; color: var(--faint); }
/* What the room asked for, as one quiet line under the vote. */
.mnr-tally-card { background: none; border: 0; border-top: 1px solid var(--line); border-radius: 0; padding: 12px 0 0; }
.mnr-tally-line { margin-top: 6px; font: 400 var(--fs-meta)/1.45 var(--sans); color: var(--muted); }
.mnr-tally-line .mine { color: var(--ink); font-weight: 600; }

/* Tonight's backups as ticket stubs, matching movie night's vote screen (rule 459). */
.tnp-alts.tnp-stubs { display: flex; flex-direction: column; gap: 10px; }
.tnp-stubs .tnp-alt { display: flex; align-items: stretch; height: 84px; border-radius: var(--radius-field); background: #16161a; border: 1px solid var(--line-2); overflow: hidden; }
.tnp-stubs .tnp-alt-poster { position: relative; width: 56px; height: auto; flex: none; aspect-ratio: auto; border-radius: 0; align-self: stretch; }
.tnp-stubs .tnp-alt-poster img, .tnp-stubs .tnp-alt-poster .hrec-poster-ph { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.tnp-stubs .tnp-alt-b { flex: 1; min-width: 0; display: flex; flex-direction: column; justify-content: center; padding: 8px 12px; }
.tnp-stubs .tnp-alt-title { margin: 0; font: 500 var(--fs-card)/1.15 var(--serif); color: var(--ink); }
.tnp-stubs .tnp-alt-fit, .tnp-stubs .tnp-alt-sub { display: block; margin-top: 6px; font-size: var(--fs-meta); line-height: 1.2; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tnp-stubs .tnp-alt-sub { color: var(--muted); }
.tnp-stubs .tnp-alt-seen { display: block; margin-top: 4px; font-size: var(--fs-meta); line-height: 1.2; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tnp-stubs .tnp-alt-seen b { font-weight: 600; color: var(--ink); }
.tnp-stubs .tnp-alt-seen .tnp-sep { color: var(--faint); }
.tnp-alt-stub { position: relative; width: 66px; flex: none; border-left: 2px dashed var(--line-2); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; }
.tnp-alt-stub::before, .tnp-alt-stub::after { content: ""; position: absolute; left: -9px; width: 16px; height: 16px; border-radius: 50%; background: var(--bg); border: 1px solid var(--line-2); }
.tnp-alt-stub::before { top: -9px; } .tnp-alt-stub::after { bottom: -9px; }
.tnp-alt-stub b { font: 500 21px/1 var(--serif); color: var(--accent-2); } /* type scale exception: rank numerals or ticket stub */
.tnp-alt-stub b small { font-size: 11px; }
.tnp-alt-stub i { font: 700 11px/1 var(--sans); font-style: normal; letter-spacing: .14em; text-transform: uppercase; color: var(--faint); }

/* Friends: counts and the chevron on one line, "taste like yours" as its own line under them (rule 461). */
.fp-fr-h .fp-fr-likein { flex-basis: 100%; order: 9; margin-top: 2px; white-space: normal; }

/* The pinned phone header paints its background out to the screen edges, so full-bleed posters
   scrolling under it never show in the page gutters beside it (owner, 2026-10-23; rule 466).
   Side shadows, not a wider box or a clip: those would scroll sideways or clip its menus. */
@media (max-width: 759px) {
  .wrap:not(.wrap-landing):not(.wrap-signin) > .topbar { box-shadow: -64px 0 0 var(--bg), 64px 0 0 var(--bg); }
}

/* Profile figures (rule 467): three of them, the numbers as before, plain sentence-case labels. */
.pv2-taste .hero-facts .hstat .l { font: 400 var(--fs-meta)/1.3 var(--sans); letter-spacing: 0; text-transform: none; color: var(--muted); white-space: nowrap; }
.pv2-taste .hero-facts .hstat .l .l2 { display: block; color: var(--faint); font-size: var(--fs-label); margin-top: 2px; }
/* Against the crowd (rule 1247; owner, 2026-11-06, mockups/journeys/third-figure-v1.html option A): the
   third figure, a button when it opens Unpopular opinions, looking like the other two. Three share a
   320px row: the columns pad less, and a label may take two lines rather than spill. */
.pv2-taste .hero-facts .hstat-tap { appearance: none; background: none; border: 0; border-radius: 0; font: inherit; color: inherit; cursor: pointer; }
.pv2-taste .hero-facts .hero-stats.is-three .hstat { padding-left: 4px; padding-right: 4px; }
.pv2-taste .hero-facts .hero-stats.is-three .hstat .l { white-space: normal; }
/* Nothing spills at 320px (rule 1248; owner, 2026-11-06, mockups/journeys/built-avg320-after-320-*.png):
   under 375px the average's small line, when it has both parts, takes two lines ("from 1,078 ratings" /
   "crowd 3.7", the dot dropped), and 10,000 hours or more beside two other figures drops to the
   heading size. 375px and up are as before. */
@media (max-width: 374px) {
  .pv2-taste .hero-facts .hstat .l .l2-part { display: block; }
  .pv2-taste .hero-facts .hstat .l .l2-sep { display: none; }
  .pv2-taste .hero-facts .hero-stats.is-three .hstat .n.n-long { font-size: var(--fs-heading); line-height: 28px; }
}

/* Film sheet's three buttons, quieter (rule 467): smaller text, one icon style, cream when on,
   Canon keeps its red. */
.fd-ratings-btns .fa-watch, .fd-ratings-btns .fa-canon { height: var(--btn-h); min-height: var(--btn-h); border-radius: var(--radius-field) !important; font: 500 var(--fs-ui)/1 var(--sans); gap: 6px; }
.fd-ratings-btns .fa-watch svg, .fd-ratings-btns .fa-canon svg { width: 16px; height: 16px; flex: none; }
.fd-ratings-btns .fa-watch.on, .fd-ratings-btns .fa-watch.on:hover:not(:disabled) { background: var(--cream); border-color: var(--cream); color: var(--cream-ink); }
.fd-ratings-btns .fa-canon:not(.on) .fa-canon-star { color: var(--red); }

/* The profile's three figures go back to the serif they had (owner, 2026-10-23: "put the number
   back to how it was"; rule 467 amends 419 for this row only). */
.pv2-taste .hero-facts .hstat .n { font-family: var(--serif); font-weight: 500; font-size: var(--fs-title); line-height: 1; }
.pv2-taste .hero-facts .hstat .n .u { font-size: var(--fs-read); }

/* Mix names in Made for you match the Browse by rows: one weight and size for both lists of
   things to open (owner, 2026-10-23; rule 469). */
.bh .bh-mood b { font: 400 var(--fs-read)/22px var(--ui); color: var(--ink); }

/* Browse: the first section sits closer under "Can't decide?" (owner, 2026-10-23, mockups/browse-mix-font.png; rule 471). */
.bh .bh-decide + .bh-sec { margin-top: var(--sp-24); }

/* The archetype card's two links wrap to a second line rather than cut the second one off
   (owner, 2026-10-23: "links are cutoff"; rule 472). */
.hero-blend-tail { flex-wrap: wrap; row-gap: 8px; }
.hero-blend-tail .hml-link { overflow: visible; text-overflow: clip; }

/* A member's film page hides the top bar on phones only (rule 415's full-bleed backdrop); on a
   computer the brand and menu stay (owner, 2026-10-23: "where's the Montage logo and settings";
   rule 474). */
@media (max-width: 759px) { main.wrap.fp-bleed > .topbar { display: none; } }

/* The streak pill under the bio (rule 475): the same pill it was in the handle row. */
.ph-streak { margin-top: 12px; display: flex; align-items: center; gap: 8px; flex-wrap: nowrap; min-width: 0; }
.ph-streak:empty { display: none; }
.ph-streak .wstreak { display: inline-flex; align-items: center; gap: 7px; width: auto; margin: 0; padding: 0 11px 0 7px; height: 28px; box-sizing: border-box; flex: none;
  background: rgba(122, 31, 39, .28); border: 1px solid rgba(196, 74, 86, .55); border-radius: 999px; font: inherit; color: var(--ink);
  cursor: pointer; white-space: nowrap; }
.ph-streak .wstreak-n { font-size: var(--fs-ui); font-weight: 600; color: var(--ink); }
.ph-streak .wstreak:hover { border-color: rgba(214, 96, 108, .85); }
/* The owner's quiet "Streak ended" pill, for the day the ended line is due (rule 617). */
.ph-streak .wstreak.is-ended, .wstreak.is-ended { background: transparent; border-color: var(--line-2); }
.wstreak.is-ended .wstreak-n { color: var(--muted); font-weight: 500; }
.wstreak.is-ended .wstreak-flame { opacity: .55; }

/* Tonight's stub posters stay painted on iPhone (owner, 2026-10-23: "why don't these render ... when
   I scroll up and back down they disappear again"; rule 476). WebKit drops images that carry a
   filter inside a rounded, clipped box after a scroll; no filter, their own layer, plain decoding. */
.tnp-stubs .tnp-alt-poster { transform: translateZ(0); isolation: isolate; background: var(--panel-2); }
.tnp-stubs .tnp-alt-poster img { filter: none; }

/* The ticket stub's serial fits on one line inside the stub (owner, 2026-10-23: "the serial number
   is messed up": "Night Nº 22" wrapped across the perforation; rule 481). */
.nt-stub { width: 92px; padding: 0 6px; box-sizing: border-box; }
.nt-no { white-space: nowrap; font-size: var(--fs-label); letter-spacing: .04em; text-align: center; }
.nt-adm { letter-spacing: .16em; }

/* Picks' "Because you loved" line: the lead-in grey, the films in the accent blue and tappable, no
   underline: the blue is what says tap (owner, 2026-10-24; rule 491). */
.pk-why { color: var(--muted); }
.pk-why b, .pk-why-film { font: inherit; font-style: normal; font-weight: 500; color: var(--accent-2); }
.pk-why-film { appearance: none; background: none; border: 0; padding: 0; margin: 0; cursor: pointer;
  /* Underlined so the titles read as links (owner, 2026-11-02; iOS the same). */
  text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; text-decoration-color: color-mix(in srgb, var(--accent-2) 45%, transparent); }
.pk-why-film:hover { text-decoration-color: var(--accent-2); }

/* Poster images fill their frame by position, not by percentage height: iPhone Safari left
   "height: 100%" unresolved inside an aspect-ratio box and drew a wide image at its own shape, a
   strip at the top (owner, 2026-10-24: "film posters aren't rendering always"; rule 493). */
.why-drawer-po img, .fd-strip-poster img, .tnp-alt-poster img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.fd-strip-poster { position: relative; }

/* A poster still downloading is not shown half-drawn (a strip at the top): it fades in once
   loaded, over the frame's panel colour (rule 493). */
.why-drawer-po img { transition: opacity .2s var(--ease); }
.why-drawer-po img:not([data-in]) { opacity: 0; }

/* The library's Sort, arrow and Filters at the Compact size the shared bar uses (rule 120: 34px,
   13px text), and a quieter film count (owner, 2026-10-24: "the filters and # films text feels too
   large"; rule 494). */
.lib-fbar { gap: 8px; }
.lib-fbar .browse-soft { min-height: var(--chip-h); height: var(--chip-h); padding: 0 12px; border-radius: var(--radius-pill); font-size: var(--fs-meta); }
.lib-fbar .lib-sortsel { flex: 0 1 auto; }
.lib-fbar .browse-dir { flex: 0 0 34px; width: 34px; padding: 0; font-size: var(--fs-ui); }
.lib-active .browse-chip { font-size: var(--fs-meta); }
.lib-count-row > span:first-child { font-size: var(--fs-read); }

/* Hot takes: their face beside their rating, so nothing truncates (rule 495). */
.gap-k .gap-who { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
.gap-av { width: 18px; height: 18px; border-radius: var(--radius-av); object-fit: cover; flex: none; display: inline-block; }
.gap-av-ph { display: inline-grid; place-items: center; background: var(--panel-2); border: 1px solid var(--line-2); color: var(--muted); font: 600 var(--fs-label)/1 var(--sans); letter-spacing: 0; }

/* How you got your archetype, ranked (rule 498). */
.arch-why-ranked .arch-why-bar { display: flex; gap: 3px; height: 6px; margin: 2px 0 6px; }
.arch-why-ranked .arch-why-bar i { border-radius: 2px; }
.arch-why-ranked .arch-why-list { list-style: none; margin: 0; padding: 0; }
.arch-why-ranked .arch-why-row { display: flex; gap: 14px; padding: 14px 0; border: 0; border-top: 1px solid var(--line); background: none; border-radius: 0; }
.arch-why-ranked .arch-why-row:first-child { border-top: 0; }
.arch-why-ranked .arch-why-n { flex: none; width: 16px; font: 500 var(--fs-heading)/1 var(--serif); color: var(--faint); }
.arch-why-ranked .is-lead .arch-why-n { color: #c44a56; }
.arch-why-ranked .arch-why-body { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.arch-why-ranked .arch-why-top { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.arch-why-ranked .arch-why-name { font: 500 var(--fs-heading)/1.1 var(--serif); color: var(--ink); }
/* The one taste model's one-time note to the owner (rule 587). */
.read-sharper { display: flex; align-items: center; gap: 10px; margin: 6px 0 2px; font: 400 var(--fs-meta)/1.35 var(--read); color: var(--muted); }
.read-sharper-x { appearance: none; background: none; border: 0; padding: 4px; cursor: pointer; color: var(--muted); font-size: var(--fs-label); line-height: 1; }
/* The one taste model's sheet (rule 587): names open their archetype page. */
.arch-why-link { appearance: none; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; color: inherit; font: inherit; text-align: left; }
.arch-why-ranked button.arch-why-name { font: 500 var(--fs-heading)/1.1 var(--serif); color: var(--ink); }
.arch-why-also .arch-why-link b { color: var(--ink); }
.arch-why-ranked .arch-why-role { border: 0; background: none; padding: 0; font: 700 var(--fs-label)/1 var(--sans); letter-spacing: .14em; text-transform: uppercase; color: var(--muted); }
/* The older pill rule (.arch-why-row.is-lead .arch-why-role) is more specific: without the background
   and border reset the label was blue on blue, a "random blue bar" (owner, 2026-10-31). */
.arch-why-ranked .is-lead .arch-why-role { color: var(--accent-2); background: none; border: 0; padding: 0; }
.arch-why-ranked .arch-why-reason { display: block; margin-top: 3px; font: 400 var(--fs-ui)/1.35 var(--read); color: var(--ink); }
.arch-why-ranked .arch-why-also { margin: 4px 0 0; padding-top: 12px; border-top: 1px solid var(--line); font: 400 var(--fs-meta)/1.4 var(--read); color: var(--muted); }
.arch-why-ranked .arch-why-also b { font: 500 var(--fs-ui) var(--serif); color: var(--ink); }
/* How you got <Archetype>, in plain words (owner, 2026-11-04, mockups/journeys/how-you-got-v3): no
   numbers or dividers; a square in the bar's colour, the name in the serif with its tag at the right
   (the archetype's in the blue), the kind of film in the reading face, the comparison under it. */
.arch-why-v3 .arch-why-bar { margin: 2px 0 0; }
.arch-why-v3 .arch-why-row { display: grid; grid-template-columns: 10px 1fr; gap: 12px; padding: 0; margin-top: 16px; border-top: 0; }
.arch-why-v3 .arch-why-dot { width: 10px; height: 10px; border-radius: 2px; margin-top: 7px; }
.arch-why-v3 .arch-why-top { justify-content: space-between; flex-wrap: nowrap; gap: 10px; }
.arch-why-v3 .arch-why-name, .arch-why-v3 button.arch-why-name { font: 500 var(--fs-card)/1.2 var(--serif); color: var(--ink); text-decoration: underline dotted var(--faint); text-underline-offset: 4px; }
.arch-why-v3 span.arch-why-name { text-decoration: none; }
.arch-why-v3 .arch-why-role { flex: none; font: 600 var(--fs-label)/1 var(--sans); letter-spacing: .14em; }
.arch-why-v3 .arch-why-reason { margin-top: 3px; font: 400 var(--fs-ui)/1.4 var(--read); color: var(--ink); opacity: .9; }
.arch-why-v3 .arch-why-vs { display: block; margin-top: 5px; font: 500 var(--fs-meta)/1.3 var(--sans); color: var(--muted); }
.arch-why-v3 .arch-why-vs.is-up { color: var(--accent-2); }

/* Picked people, lanes and themes under the filter sheet's search (rule 499). */
.lib-fs-picked { margin: 10px 0 0; }

/* The filter sheet's search block: the scope chips flush with the search box, an even 10px under
   it, and one divider below the block instead of two (owner, 2026-10-25: "the spacing is a little
   weird between the search bar and chips"; rule 500). */
.lib-fs-search { padding: 4px 0 14px; }
.lib-fs-search .browse-dd-scopes { padding: 0; margin: 10px 0 0; border-bottom: 0; }
.lib-fs-search .lib-fs-picked { margin-top: 10px; }
.lib-fs-search .lib-fs-hits { margin-top: 10px; }

/* Decades as poster tiles: the decade in the title serif (rule 503). */
.bh-sheet-decade-tiles .bh-mood b { font: 500 var(--fs-card)/1.2 var(--serif); }

/* Browse by's sheets have no hero, so the page's padding-top 0 put the header against the top
   edge (owner, 2026-10-29: "way too close to the top"). */
.bh-sheet.browse-page.modal { padding-top: calc(16px + env(safe-area-inset-top)); }
@media (min-width: 700px) { .bh-sheet.browse-page.modal { padding-top: 32px; } }
/* Collections, spaced out (owner, 2026-10-25: "collections can be more spaced out too"; rule 504):
   a bigger poster, the name in the title serif with its hint under it, more room between rows. */
/* World cinema, a section after the collections (owner, 2026-11-04, mockups/journeys/collections-v2 B;
   rule 1064): its Heading with the shelf count at the right, one line under it, then the shelves in
   the collections' own rows. No rule under the heading (owner, 2026-11-04: "please make sure we are
   not using section lines when unnecessary"; rule 1065): the space says where it starts. */
.bh-world-sh { margin: var(--sp-32) 0 var(--sp-8); }
.bh-world-n { font-size: var(--fs-meta); color: var(--faint); font-variant-numeric: tabular-nums; }
.bh-world-line { margin: 0 0 var(--sp-16); font-size: var(--fs-meta); color: var(--muted); }
/* Collections' rows in the sheet, collections and shelves alike, without hairlines (rule 1065):
   16 between rows, the poster and the space between them separating them. */
/* Signed out, /browse's Collections and World cinema rows go the same way (owner, 2026-11-04: "do 1
   and 2, add posters"; rule 1066): no rule over the list, none under each row, 16 between rows. */


/* More like this wears the poster stamp every other grid uses (rule 419's blue stamp), bottom-left
   (owner, 2026-10-25: "this doesn't use the new match % design"; rule 508). */
.fd-strip-poster .fd-strip-match { right: auto; left: 6px; bottom: 6px; -webkit-mask: none; mask: none; background: var(--bg); border: 1.5px solid var(--accent); color: var(--accent-2); box-shadow: none;
  font: 500 var(--fs-read)/1 var(--serif); padding: 3px 6px 2px; border-radius: 2px; transform: rotate(-3deg); transform-origin: left bottom; }
/* The poster stamp, easier to read (owner, 2026-11-04, mockups/journeys/open-proposals-v1.png 1; rule 1016):
   a solid black back, a bigger number in the film page's blue, the % at 60%, and under 55% it greys out. */
.stamp-u { font-size: .5em; margin-left: 1px; }
/* B, the bigger stamp (owner, 2026-11-04, mockups/journeys/match-stamp-options.png B, "don't turn it
   grey"; rule 1016): the same tilted ticket stamp, the number at 18 ("slightly smaller"), a 2px light-blue border and a soft
   drop shadow so it lifts off any art. Every match the same blue, weak or strong. */
.pf-grid .wlrank-badge, .tnp-alt-poster .wlrank-badge, .phold-po .wlrank-badge, .bx-stub, .wlrank .wlrank-badge,
.pf-grid .lib-rating, .tp-card .wlrank-badge:not(.bs-badge), .fd-strip-poster .fd-strip-match {
  font: 600 var(--fs-card)/1 var(--serif); border: 2px solid var(--accent-2); padding: 3px 7px 2px; border-radius: 3px;
  transform: rotate(-4deg); box-shadow: 0 3px 10px rgba(0,0,0,.6);
  /* A, one step smaller (owner, 2026-11-04, mockups/journeys/stamp-size-v2; rule 1057): 15, was 18. */
  font-size: calc(var(--fs-card) * 5 / 6); padding: 2px 5px 1px; border-width: 1.5px; }
/* On 4-across grids the stamp steps down to 14 (owner, 2026-11-04, mockups/journeys/tag-header-stamp-v1
   B; rule 1046): padding 2px 5px 1px and a 1.5px border, the same tilt and blue. 14 is the card step
   scaled by 7/9 rather than a raw size (the poster-stamp exception, rule 670). 2- and 3-across keep 18.
   4-across: the profile's grids under 700px, Browse's grids, a lane or theme page from 601 to 900px,
   Tonight's alternates. */
.bx-grid .bx-gi:not(.big) .bx-stub, .tnp-alts .tnp-alt-poster .wlrank-badge {
  font-size: calc(var(--fs-card) * 2 / 3); padding: 2px 4px 1px; border-width: 1.5px; /* 12 (rule 1057) */ }
@media (max-width: 699px) {
  .pf-grid .wlrank-badge, .pf-grid .lib-rating { font-size: calc(var(--fs-card) * 2 / 3); padding: 2px 4px 1px; border-width: 1.5px; /* 12 (rule 1057) */ }
}
@media (min-width: 601px) and (max-width: 900px) {
  .tp-grid .tp-card .wlrank-badge:not(.bs-badge) { font-size: calc(var(--fs-card) * 2 / 3); padding: 2px 4px 1px; border-width: 1.5px; /* 12 (rule 1057) */ }
}

/* Rule 511: Start movie night from a film asks who it's with; the room's film offers its neighbours. */
.fp-pick { display: flex; flex-direction: column; margin: 4px 0 0; }
.fp-pick-row { appearance: none; display: flex; align-items: center; gap: 12px; width: 100%; padding: 10px 2px; border: 0; border-bottom: 1px solid var(--line);
  background: none; color: var(--ink); font: 400 var(--fs-ui)/20px var(--ui); text-align: left; cursor: pointer; }
.fp-pick-row:last-child { border-bottom: 0; }
.fp-pick-row .fp-av { width: 32px; height: 32px; flex: none; }
.fp-pick-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fp-pick-match { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 400 var(--fs-label)/16px var(--ui); color: var(--faint); }
.fp-pick-box { flex: none; display: grid; place-items: center; width: 20px; height: 20px; border-radius: 6px; border: 1.5px solid var(--line-2); color: var(--bg); }
.fp-pick-row[data-on] .fp-pick-box { background: var(--select); border-color: var(--select); }
.fp-pick-go { appearance: none; display: block; width: 100%; margin: 16px 0 4px; padding: 12px 16px; border: 0; border-radius: var(--radius-sm);
  background: var(--ink); color: var(--bg); font: 600 var(--fs-ui)/20px var(--ui); cursor: pointer; }
.fp-pick-go:disabled { opacity: .5; cursor: default; }
.mnr-seed-alts { display: flex; flex-direction: column; gap: 8px; margin: 14px 6px 0 0; }
.mnr-seed-alt { appearance: none; width: 100%; padding: 11px 14px; border: 1px solid var(--line); border-radius: var(--radius-sm); background: none;
  color: var(--ink); font: 500 var(--fs-ui)/18px var(--ui); text-align: center; cursor: pointer; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mnr-seed-alt:hover { border-color: var(--muted); }

/* Rule 517: a room opened on its film loads the ticket's shape, not the Weighing count. */
.mnr-seed-skel-t { height: 298px; border-radius: 12px; margin-top: 14px; }
.mnr-seed-skel-b { height: 50px; width: calc(50% - 5px); border-radius: 12px; margin-top: 14px; }

/* Rule 518: Tonight's Where to watch, once the film is chosen. */
.btn.tn-watching.tn-where { margin-top: 10px; }

/* What we said before (owner, 2026-10-28, mockups/film-read-before-after.html option A): one row
   under a seen film's Our read, closed by default; opened, the read we gave before, in grey. */
.why-before { margin-top: 10px; border: 1px solid var(--line-2); border-radius: 12px; overflow: hidden; }
.why-before-top { display: flex; align-items: center; gap: 10px; width: 100%; padding: 11px 14px; background: none; border: 0; color: inherit; text-align: left; font: inherit; }
button.why-before-top { cursor: pointer; }
.why-before-t { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; font: var(--t-caption); color: var(--muted); }
.why-before-t b { font: 600 var(--fs-ui)/18px var(--sans); color: var(--ink); }
.why-before-n { flex: none; font: 500 var(--fs-heading)/1 var(--serif); color: var(--accent-2); font-variant-numeric: tabular-nums; }
.why-before-chev { flex: none; width: 14px; text-align: center; color: var(--faint); }
.why-before-body { padding: 0 14px 14px; border-top: 1px solid var(--line); }
.why-before-body .tile-h { margin: 12px 0 8px; }
.why-before-body .fd-why-text { font-size: var(--fs-meta); color: var(--muted); }
.why-before-body .fd-caveat { color: var(--faint); margin-top: 10px; padding-top: 10px; border-top: 1px solid rgba(255,255,255,.07); }

/* What held it back (rule 544, mockups/read-held-back.png): one quiet line, then five chips. */
.held-back { margin: 10px 0 2px; }
.held-ask { margin: 0; font-size: var(--fs-meta); color: var(--faint); }
.held-ask button { background: none; border: 0; padding: 0; font: inherit; color: var(--accent-2); cursor: pointer; }
.held-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 8px; }
.held-chip { font-size: var(--fs-meta); font-weight: 500; padding: 6px 12px; border: 1px solid var(--line-2); border-radius: 999px; background: none; color: var(--ink); cursor: pointer; }
.held-chip.is-on { background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); color: var(--ink); }
.held-done { font-size: var(--fs-meta); font-weight: 600; padding: 6px 14px; border: 0; border-radius: 999px; background: var(--ink); color: #111; cursor: pointer; }

/* Lately reactions and comments (rule 566, mockups/lately-social.png A and B): on the same line as
   your rating, at the foot of the film's text (owner, 2026-10-29: "don't make a new line"). */
.lp-bar { display: flex; align-items: center; gap: 6px; min-width: 0; flex-wrap: wrap; }
/* Reactions wrap onto a new line, never squeezed into each other (owner, 2026-11-02; iOS the same). */
.lp-chip, .lp-add, .lp-cm, .msg-rx .fdisc-rx { flex: none; white-space: nowrap; }
.lp-pick { position: absolute; left: 0; bottom: calc(100% + 6px); z-index: 5; display: flex; gap: 2px; padding: 4px; border: 1px solid var(--line-2); border-radius: 999px; background: var(--panel); box-shadow: 0 8px 24px rgba(0, 0, 0, .4); }
.lp-pick button { width: 36px; height: 36px; border: 0; border-radius: 50%; background: none; font-size: var(--fs-card); cursor: pointer; }
.lp-pick button.is-mine { background: var(--select-fill); box-shadow: inset 0 0 0 1.5px var(--select-edge); }
.lp-sheet { display: flex; flex-direction: column; max-height: min(80vh, 640px); }
.lp-sheet-h { display: flex; align-items: center; gap: 10px; }
.lp-sheet-h b { flex: 1; font: 500 var(--fs-heading) var(--display); color: var(--ink); }
.lp-list { flex: 1; overflow-y: auto; margin: 10px 0; min-height: 80px; }
.lp-empty { color: var(--muted); font: 400 var(--fs-ui) var(--read); margin: 16px 0; }

/* A friend chat (rule 567, mockups/send-friend.png B): the other person at the top, then the thread. */
.gchat-top { display: flex; align-items: center; gap: 12px; padding: 4px 0 12px; border-bottom: 1px solid var(--line); }
/* Back sits level with the title (owner, 2026-10-29): a back link's own bottom margin lifted it 6px. */
.gchat-top .backlink { margin: 0; }
.gchat-who { display: flex; align-items: center; gap: 10px; min-width: 0; color: var(--ink); text-decoration: none; }
.gchat-who h1 { margin: 0; font: 500 var(--fs-heading) var(--display); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gchat-av { width: 34px; height: 34px; border-radius: var(--radius-av); flex: none; object-fit: cover; display: grid; place-items: center; font: 500 var(--fs-read) var(--display); color: #1b1b1b; }
.gchat-msg { color: var(--muted); font: 400 var(--fs-ui) var(--read); margin: 24px 0; }
.gchat .gth { margin-top: 8px; }
/* Locked while you're not friends (rule 567, mockups/friends-only.png A). */
.gth-locked { margin: 12px 0 8px; padding: 12px 14px; border: 1px solid var(--line-2); border-radius: var(--radius-field); color: var(--muted); font: 400 var(--fs-meta)/1.45 var(--ui); text-align: center; }
.gth-locked b { color: var(--ink); font-weight: 600; }
.gth-locked-btn { display: block; margin: 10px auto 0; }
.gjoin-locked { color: var(--muted); }
/* The chat fills the screen and its box to write sits at the bottom, like any messaging app (owner,
   2026-10-29: "Message bar should be at bottom of screen like normal dms"; rule 567). */
main.wrap:has(> .gchat) { display: flex; flex-direction: column; min-height: 100dvh; }
.gchat { flex: 1; display: flex; flex-direction: column; }
.gchat > .gth { flex: 1; display: flex; flex-direction: column; }
.gchat > .gth > .gth-list { flex: 1; }
.gchat > .gth > .gth-compose, .gchat > .gth > .gth-locked { margin-top: auto; }
/* The message bar sits at the very bottom, as in any messaging app (owner, 2026-10-29: "Still the
   message bar is not at the bottom"): the chat page has no tab bar, so none of its space is kept,
   and the bar stays put while the thread scrolls. */
main.wrap:has(> .gchat) { padding-bottom: 0; }
.gchat > .gth > .gth-compose, .gchat > .gth > .gth-locked { position: sticky; bottom: 0; z-index: 2; background: var(--bg); padding-top: 8px; padding-bottom: calc(10px + env(safe-area-inset-bottom)); }
/* Search in Send to and in Social's groups and chats (owner, 2026-10-29). */
.share-sheet-search { margin-bottom: 8px; }
.share-sheet-none, .comm-search-none { color: var(--muted); font: 400 var(--fs-meta) var(--ui); align-self: center; padding: 8px 0; }
.comm-search { display: block; width: 100%; box-sizing: border-box; height: 40px; margin: 4px 0 10px; padding: 0 14px; border: 1px solid var(--line-2); border-radius: var(--radius-field); background: none; color: var(--ink); font: 400 var(--fs-read) var(--ui); }
.comm-search::placeholder { color: var(--faint); }
/* Friend chats inbox at the end of Social's tab bar (rule 567, mockups/chats-place.png B). */
/* The share icon's size, after it (the portal adds Invite later, so order puts the inbox last). */
.inbox-btn { position: relative; display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 32px; order: 2; border: 0; background: none; color: var(--ink); cursor: pointer; }
.inbox-btn svg { width: 19px; height: 19px; }
.inbox-count { position: absolute; top: -3px; right: -5px; min-width: 17px; height: 17px; padding: 0 4px; box-sizing: border-box; border-radius: var(--btn-r); background: var(--accent-2); color: var(--bg); font: 700 var(--fs-label)/17px var(--ui); text-align: center; }
.gchat-title { margin: 0; font: var(--t-title); color: var(--ink); }
.gchat-list .comm-search { margin-top: 12px; }
.inbox-list { margin-top: 4px; }
.inbox-row { display: flex; align-items: center; gap: 12px; padding: 12px 0; border-bottom: 1px solid var(--line); color: var(--ink); text-decoration: none; }
.inbox-av { width: 44px; height: 44px; border-radius: var(--radius-av); flex: none; object-fit: cover; display: grid; place-items: center; font: 500 var(--fs-card) var(--display); color: #1b1b1b; }
.inbox-t { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.inbox-t b { font: 600 var(--fs-ui) var(--ui); }
.inbox-row.unread .inbox-t b { font-weight: 700; }
.inbox-t span { color: var(--muted); font: 400 var(--fs-meta) var(--ui); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.inbox-tm { align-self: flex-start; margin-top: 3px; color: var(--faint); font: 400 var(--fs-label) var(--ui); }
.inbox-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--accent-2); flex: none; }
/* Unread friend chats: a small blue dot on Social's tab (owner, 2026-10-29: "Dot"; rule 567). */
.tabicon { position: relative; }
.tab-dot { position: absolute; top: -2px; right: -5px; width: 9px; height: 9px; border-radius: 50%; background: var(--accent-2); box-shadow: 0 0 0 2px var(--bg); }
/* Social: the tab row's line is the header's only line (owner, 2026-10-29: "the double divider is
   weird again"), as Picks does with html.pk-head. */
.wrap:has(.subtabs) > .topbar { border-bottom: 0; padding-bottom: 2px; margin-bottom: 0; }
/* A confirmed sequel not out yet, last in the series row (rule 570, mockups/series-upcoming.png):
   the poster a touch dimmer with its date on it, plain "Watchlist" text under it. */
.fsr-soon .fsr-poster { padding: 0; cursor: pointer; }
.fsr-soon .fsr-poster img { opacity: .75; }
.fsr-date { position: absolute; left: 5px; bottom: 5px; padding: 3px 6px; border-radius: 3px; background: rgba(11, 11, 13, .85); color: var(--ink); font: 600 var(--fs-label) var(--ui); }
.fsr-save { display: block; margin-top: 6px; padding: 0; border: 0; background: none; color: var(--muted); font: 500 var(--fs-label) var(--ui); cursor: pointer; text-align: left; }
.fsr-save.on { color: var(--accent-2); cursor: default; }

/* /dev/taste-model (rule 579): the owner's before/after report for the one taste model. */
.tm-meta { color: var(--muted); font-size: var(--fs-meta); margin: 14px 0; }
.tm-rows { display: grid; gap: 14px; }
.tm-row { border: 1px solid var(--line); border-radius: var(--radius-sm); padding: 14px; background: var(--panel); }
.tm-h { display: flex; gap: 8px; align-items: baseline; margin-bottom: 10px; }
.tm-h span { color: var(--muted); font-size: var(--fs-label); }
.tm-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 8px; }
.tm-k { font-size: var(--fs-label); letter-spacing: .12em; text-transform: uppercase; color: var(--muted); font-weight: 600; }
.tm-name { font-family: var(--serif); font-size: var(--fs-heading); margin: 4px 0 2px; }
.tm-diff { color: var(--accent-2); }
.tm-s { font-size: var(--fs-label); color: var(--muted); line-height: 1.45; }
.tm-films { margin: 6px 0 0; padding-left: var(--sp-16); font-size: var(--fs-meta); line-height: 1.5; }
.tm-tag { color: var(--muted); font-size: var(--fs-label); }

/* Film DNA radar, what you look for (FilmDnaRadar9; docs/TASTE-MODEL.md). */
.dna9 svg { display: block; max-width: 520px; margin: 0 auto; }
.dna9-ring { fill: none; stroke: var(--line, #222227); stroke-width: 1; }
.dna9-mid { fill: none; stroke: #5d5b57; stroke-width: 1.5; stroke-dasharray: 4 4; }
.dna9-spoke { stroke: var(--line, #222227); }
.dna9-shape { fill: rgba(91,143,196,.26); stroke: var(--accent-2); stroke-width: 2.5; stroke-linejoin: round; }
.dna9-dot { fill: var(--accent-2); stroke: var(--bg); stroke-width: 2; }
.dna9-dot.is-top { fill: var(--ink); }
/* 14 in chart units: the chart scales down to its card (about 0.8), and labels stay at 11px or more (rule 465). */
.dna9-lab { fill: var(--muted, #a5a19a); font-size: var(--fs-card); }
.dna9-lab.is-top { fill: var(--ink); font-weight: 600; }
/* The profile's radar (rule 592): tap a strand; another person's shape as an outline. */
.dna9-dot[role="button"] { cursor: pointer; }
/* The picked strand reads bold, not underlined (owner, 2026-10-31). */
.dna9-lab.is-active { fill: var(--ink); font-weight: 700; }
.dna9-dot.is-active { stroke: var(--ink); }
.dna9-other { fill: none; stroke: var(--ink); stroke-width: 1.5; stroke-dasharray: 0; opacity: .85; }
.dna9-detail { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--line); }
.dna9-detail-name { margin-top: 6px; font: 500 var(--fs-heading)/1.1 var(--serif); color: var(--ink); }
.dna9-detail-hint { margin: 4px 0 0; font: 400 var(--fs-ui)/1.35 var(--read); color: var(--ink); }
.dna9-detail-you { margin: 8px 0 0; font: 400 var(--fs-meta)/1.4 var(--read); color: var(--muted); }
.dna9-detail-nav { display: flex; align-items: center; justify-content: space-between; }
.dna9-key { display: flex; gap: 6px; align-items: center; font-size: var(--fs-label); color: var(--muted); margin-top: 4px; }
.dna9-key i { display: inline-block; width: 18px; border-top: 1.5px dashed #5d5b57; }
.dna9-key i.is-other { border-top: 1.5px solid var(--ink); }
.dna9-down { font-size: var(--fs-meta); color: var(--muted); margin-top: 8px; }
.dna9-down b { color: var(--ink); font-weight: 600; }
.tm-radars { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 14px; margin: 10px 0; }
.tm-radars .tm-k { margin-bottom: 4px; }

/* Tonight's Streaming on (owner, 2026-10-30: "on tonight can i still look at any service not just my
   own services"; mockups/tonight-any-service.html A): Who's watching's pill, Your services (their
   logos) or Any service, with Edit on the label line; the chips open under it. */
.tn-svc-h { display: flex; align-items: baseline; }
.tn-svc-edit { appearance: none; background: none; border: 0; cursor: pointer; font: inherit; font-size: var(--fs-meta); font-weight: 600; color: var(--muted);
  text-transform: none; letter-spacing: 0; margin-left: auto; padding: 4px 0 4px 12px; }
.tn-svc-seg > .mood-chip { gap: 8px; align-items: center; }
.tn-svc-logos { display: inline-flex; }
.tn-svc-logos img, .tn-svc-logos i { width: 22px; height: 22px; border-radius: var(--radius-sm); border: 2px solid var(--bg); margin-left: -6px; object-fit: cover; }
.tn-svc-logos :first-child { margin-left: 0; }
.tn-svc-seg > .mood-chip.on .tn-svc-logos :is(img, i) { border-color: var(--select-deep); }
.tn-svc-seg > .mood-chip:not(.on) .tn-svc-logos { opacity: .45; }
.tn-svc-logos i { display: grid; place-items: center; background: var(--panel-2); font-style: normal; font-size: var(--fs-label); color: var(--muted); }
.tn-svc-panel { padding: 12px 0 14px; border-bottom: 1px solid var(--line); animation: tn-svc-in .2s ease-out; }
.tn-svc-sub { margin: 0 0 10px; font-size: var(--fs-meta); color: var(--muted); }
.tn-svc-err { color: var(--danger); margin: 10px 0 0; }
/* The list did not come in time (rule 588): the muted line and Try again, the ink word, as the iPhone. */
.tn-svc-retry { appearance: none; background: none; border: 0; cursor: pointer; font: inherit; font-weight: 600; color: var(--ink); padding: 4px 0; }
.tn-svc-chips { display: flex; flex-wrap: wrap; gap: 7px; }
@keyframes tn-svc-in { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }

/* Settings, brand pass (owner-approved review, 2026-10-30): who you are under the title, and Delete
   account last in quiet red with no header. */
.pm-settings .pm-signed-in { padding-bottom: 6px; }
.pm-settings .pm-delete { color: var(--danger); margin-top: var(--sp-16); }
.pm-settings .pm-delete:hover { color: var(--danger); background: none; text-decoration: underline; }

/* Tonight's text buttons read as the iPhone's (owner, 2026-10-30: "yes convert web"; rules 95 and 359):
   ink at 86%, semibold, no arrows. A failed run is one centred title, its line and one Try again. */
.tonight-modal :is(.tn-occasion-note, .tn-just-line, .tn-to-mn, .tn-loosen, .tn-fail, .mn-notice) .linkbtn { color: color-mix(in srgb, var(--ink) 86%, transparent); font-weight: 600; }
.tonight-modal :is(.tn-occasion-note, .tn-just-line, .tn-to-mn, .tn-loosen, .tn-fail) .linkbtn:hover { text-decoration: none; opacity: .7; }
.tn-fail { display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; gap: 8px; min-height: 60vh; padding: 0 8px; }
.tn-fail-t { margin: 0; font-family: var(--serif); font-weight: 500; font-size: var(--fs-heading); color: var(--ink); }
.tn-fail-l { margin: 0; font-size: var(--fs-ui); line-height: 1.45; color: var(--muted); max-width: 30ch; }
.tn-fail .btn.ghost { width: 180px; margin-top: 14px; }
.tn-fail .linkbtn { margin-top: 6px; font-size: var(--fs-ui); }
.tn-notice-retry { margin-left: 10px; }

/* ============================================================================================
   ONE BUTTON SYSTEM AND ONE TYPE SCALE (owner, 2026-10-31, mockups/consistency-system.html: "rest
   of choices look good"; share icon A from mockups/share-icon.html). The iPhone has the same set.
   Last in the file, so it wins over the older one-offs it replaces.
   - Icon circle (.icirc, 36px, --icon-circle): Back (a chevron, no word, aria-label "Back"), •••,
     Share (icon A) and the ✕ of every sheet. Outlined on a plain page (--line-2, white .05); dark
     over a poster or image (.on-image: black .66, a soft shadow).
   - Buttons are pills (--btn-r 999px). Primary: 44px, cream, dark text, 15px semibold, one per
     screen. Secondary: 44px, outlined. Text button: muted, never blue. Chip: the 32px capsule.
     Blue (--accent-2) is only for match %, match stamps and selected or on states.
   ============================================================================================ */
.icirc.icirc { appearance: none; box-sizing: border-box; flex: none; width: var(--icon-circle) !important; height: var(--icon-circle) !important;
  min-width: 0 !important; min-height: 0 !important; max-width: none; padding: 0 !important; display: inline-grid !important; place-items: center;
  border-radius: 50% !important; border: 1px solid var(--line-2) !important; background: rgba(255,255,255,.05) !important; color: var(--ink) !important;
  box-shadow: none; cursor: pointer; text-decoration: none; font: 600 var(--fs-card)/1 var(--ui); letter-spacing: 0; line-height: 1; }
.icirc.icirc:hover { border-color: var(--faint) !important; background: rgba(255,255,255,.09) !important; text-decoration: none; }
.icirc.icirc:active { transform: scale(.96); }
.icirc.icirc:disabled { opacity: .5; cursor: default; }
.icirc.icirc svg { display: block; width: 18px !important; height: 18px !important; margin: 0; color: currentColor !important; }
.icirc.icirc.icirc-x svg { width: 16px !important; height: 16px !important; }
.icirc.icirc.on-image { background: rgba(0,0,0,.66) !important; border-color: transparent !important; box-shadow: 0 0 12px rgba(0,0,0,.35); }
.icirc.icirc.on-image:hover { background: rgba(0,0,0,.8) !important; }
/* Back on a plain page sits at the top left with 12px under it; a Back row puts a menu circle at
   its right (someone's profile, owner, 2026-10-31). */
.backlink.icirc { margin: 0 0 12px; }
.back-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; min-height: var(--icon-circle); margin: 0 0 12px; }
.back-row > .backlink.icirc { margin: 0; }
.back-row-end { display: flex; align-items: center; gap: 8px; }
/* Someone's @handle, the Back row's title (rule 1230): centred on the row, clear of Back and •••. */
.back-row:has(> .back-row-title) { position: relative; }
.back-row-title { position: absolute; left: calc(var(--icon-circle) + 12px); right: calc(var(--icon-circle) + 12px); top: 50%; transform: translateY(-50%);
  margin: 0; font-family: var(--ui); font-size: var(--fs-read); font-weight: 400; line-height: 1.3; color: var(--muted); text-align: center;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; pointer-events: none; }
/* On a computer the Back row's ••• menu drops below the circle. Only there (owner, 2026-11-06: "clicking the three
   dots brings up nothing"; rule 1237): unscoped, these four classes outranked the phone's bottom sheet (three
   classes, max-width 699px) and set its fixed panel's top to 100% + 6px of the screen, under the bottom edge, so a
   tap drew the dimmed catch and no menu. */
@media (min-width: 700px) {
  .back-row-end .pa-anchor .hero-avatar-menu.pa-menu { top: calc(100% + 6px); bottom: auto; right: 0; left: auto; }
}
.back-row + .identity-stage { margin-top: 0; }
.back-row + .identity-stage .pv2-head > .profile-header, .back-row + .identity-stage > .profile-header { padding-top: 0; }
.fp-float .backlink.icirc, .theater-back.icirc, .tonight-back.icirc, .mnv-back.icirc, .modal-back.icirc, .onboard-import-back.icirc { margin: 0; }
.theater-back.icirc, .tonight-back.icirc { margin-bottom: 12px; }
.drawer-head .drawer-back { margin: 0 8px 0 0; }
/* Your own profile's ••• in the top bar, where ☰ is on the other tabs. */
.topbar-more.icirc { color: var(--ink) !important; }

/* Pills: every button, one shape. The film viewer's four tiles keep their tile corners. */
:is(.btn, .reel-cta, .lib-more, .mnr-reroll, .fp-btn, .trailer-btn, .grp-share-btn, .wt-back, .wt-next, .friend-preview-btn, .bnr-main, .bnr-sec,
  .gwd-open, .bd-btn, .share-btn, .compat-share-btn, .fa-watch, .fa-canon, .addhandle-invite, .addhandle-btn, .tn-just-pick):not(.reel-tiles *):not(.icirc) {
  border-radius: var(--btn-r) !important; }
/* Primary and secondary: 44px, 15px semibold. */
.btn { font-size: var(--fs-ui); font-weight: 600; }
/* Icons in buttons and chips take the label's colour: a chosen one is cream on the select tint (rule 1172). */
.btn.ghost svg, .lib-more svg, .chip svg, .fd-cta .trailer-btn svg, .mnr-reroll .reel { color: currentColor; }
.chip.on svg, .btn.ghost.is-on svg { color: var(--ink); }
/* Text buttons: muted, never blue; ink on hover. */
.btn-quiet, .linkbtn, .hml-link, .sec-info-link { color: var(--muted); }
.btn-quiet:hover, .linkbtn:hover, .hml-link:hover, .sec-info-link:hover { color: var(--ink); }

/* "Stories you go for more than most" under Film DNA (owner's pick C, 2026-11-01). */
.dna-traits { margin-top: var(--sp-16); }
.dna-traits-h { font-size: var(--fs-label); font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--muted); }
.dna-traits-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.dna-traits-chips span, .dna-traits-chips a { font-size: var(--fs-meta); color: var(--ink); border: 1px solid var(--line-2); border-radius: 999px; padding: 4px 10px; line-height: 1.4; text-decoration: none; }
.dna-traits-chips a:hover { border-color: var(--muted); }

/* Share bottom right of the Picks poster, opposite Trailer (owner, 2026-11-01). */
.pk-share { position: absolute; right: 18px; bottom: 12px; z-index: 2; }

/* Invite's slot before Chats in the Social bar, laid out as if its icon sat in the bar itself. */
.subtabs-actions { display: contents; }
/* The tab bar's middle Tonight button (owner's pick A, 2026-11-01): the cream moon, the bar's one accent. */
.tab-tonight { justify-content: center; }
.tab-tonight-pill { display: inline-flex; align-items: center; justify-content: center; width: 50px; height: 38px; border-radius: 14px; background: var(--ink); color: var(--bg); }
@media (min-width: 900px) { .tab-tonight-pill { width: 40px; height: 40px; border-radius: 12px; } }
/* Your Canon on the Films tab: one line (owner's pick A, 2026-11-01). */
.hero-canon.is-compact { margin: 0 0 12px; }
.canon-line { display: flex; align-items: center; gap: 8px; width: 100%; height: 40px; padding: 0 12px; border: 1px solid var(--line); border-radius: var(--radius); background: none; color: var(--ink); font: inherit; cursor: pointer; text-align: left; }
.canon-line .canon-entry-star { font-size: var(--fs-ui); }
.canon-line-label { font-size: var(--fs-ui); font-weight: 500; }
.canon-line-n { font-size: var(--fs-meta); color: var(--faint); }
.canon-line-arrow { margin-left: auto; color: var(--faint); font-size: var(--fs-card); }

/* The room's top line: Back on the left, the host's End night on its own at the right (owner, 2026-11-01). */
.theater-backrow { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.theater-end { appearance: none; background: none; border: 0; color: var(--muted); font: inherit; font-size: var(--fs-ui); font-weight: 600; cursor: pointer; padding: 8px 0; }
.theater-end:hover { color: var(--ink); }

/* Film DNA's tapped strand in a bottom drawer (owner, 2026-11-01). */
.dna9-sheet .dna9-detail { margin-top: 0; border-top: 0; padding-top: 4px; }
/* Tonight with Friends or Family: the movie night card under the faces (owner's pick A, 2026-11-01). */
.tn-mn-card { display: flex; align-items: center; gap: 12px; width: 100%; margin: 10px 0 4px; padding: 12px; border: 1px solid var(--line-2); border-radius: var(--radius); background: none; color: var(--ink); font: inherit; text-align: left; cursor: pointer; }
.tn-mn-card:disabled { opacity: .6; cursor: default; }

/* The share sheets in the app's own look (owner, 2026-11-01, mockups/share-sheet-restyle.html), same
   layout: the page black, "Share" over the serif title, serif section heads with a hairline, the card
   as the one oxblood offset, the note a serif line, movie night a pill, Elsewhere as circles (the real
   Messages, Instagram and X icons; Copy link and More outlined). */
.share-sheet { background: var(--bg); border-color: var(--line); }
.share-sheet-eye { display: block; font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; font-weight: 600; color: var(--muted); }
.share-sheet-film b { font-size: var(--fs-heading); font-weight: 500; line-height: 1.15; }
.share-sheet-film span:not(.share-sheet-eye) { font-size: var(--fs-meta); color: var(--muted); }
.share-sheet-film img, .share-sheet-noposter { border: 0; }
/* No hairline under "Your card" or "Elsewhere": the space already separates them (owner on
   mockups/journeys/profile-share-v2, 2026-11-06; rule 1238). */
.share-sheet-k { font-family: var(--serif); font-size: var(--fs-card); font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--ink);
  margin: 16px 0 10px; }
.share-sheet-preview { margin: 14px 6px 6px 0; }
.share-sheet-card { border: 1px solid var(--line); box-shadow: none; max-width: 340px; margin: 0 auto; } /* no red offset on a share card (rule 1010) */
.share-sheet-card-wait { border: 0; max-width: 340px; height: auto; aspect-ratio: 1200 / 630; margin: 0 auto; }
/* A film's share sheet: no oxblood offset on the header's small poster or on the big card; the drawer's
   one red is the dash under the title (owner, 2026-11-06, replacing 2026-11-02's poster offset; rule 1207). */
.share-sheet-film img.share-sheet-poster { box-shadow: none; }
.share-sheet:has(.share-sheet-poster) .share-sheet-card { box-shadow: none; }
.share-sheet-note:not(.share-sheet-search) { height: 38px; border: 0; border-bottom: 1px solid var(--line-2); border-radius: 0; background: none; padding: 0 2px;
  font-family: var(--serif); font-size: var(--fs-card); }
.share-sheet-note:not(.share-sheet-search)::placeholder { font-style: italic; color: var(--faint); }
.share-mn { width: 100%; display: inline-flex; align-items: center; justify-content: center; gap: 8px; background: rgba(255,255,255,.03); }
.share-elsewhere { justify-content: space-between; }
.share-elsewhere .share-tile { flex: 1 0 0; min-width: 0; }
.share-elsewhere .share-tile > span { white-space: nowrap; }
/* Messages, Instagram, TikTok and X keep their own brand discs (.share-brand-*, rule 717): only Copy link,
   Save image and More take the neutral circle. Unscoped, this repainted the brands grey (owner, 2026-11-06:
   "why are the buttons here not the app colors?"; rule 1238), as the compact film drawer already guards. */
.share-elsewhere .share-tile-i.share-tile-sq { border-radius: 50%; }
.share-elsewhere .share-tile-i.share-tile-sq:not(.share-brand) { color: var(--ink); background: rgba(255,255,255,.04); }

/* The walkthrough, full screen, cards you swipe up through (owner, 2026-11-02; rule 605). */
.wt2-lines { list-style: none; margin: 0 0 16px; padding: 0; display: flex; flex-direction: column; gap: 10px; }
.wt2-lines li { position: relative; padding-left: 16px; color: var(--muted); font-size: var(--fs-ui); line-height: 1.4; }
.wt2-lines li::before { content: ""; position: absolute; left: 0; top: .55em; width: 6px; height: 6px; border-radius: 50%; background: var(--accent-2); }
.wt2-lines b { color: var(--ink); font-weight: 600; }
.wt2-done { width: 100%; }
.wt2-lock { vertical-align: -2px; margin-right: 4px; }
.wt2-avoid-sheet h3 { font-family: var(--serif); font-weight: 500; font-size: var(--fs-heading); margin: 0; }
.wt2-avoid-sheet p { color: var(--muted); margin: 4px 0 14px; }
.wt2-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: var(--sp-16); }
.wt2-chips button { appearance: none; background: none; border: 1px solid var(--line-2); border-radius: 999px; padding: 6px 12px; color: var(--ink); font: inherit; font-size: var(--fs-meta); font-weight: 500; cursor: pointer; }
.wt2-chips button.on { background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); color: var(--ink); }

/* The walkthrough, version 8 (owner, 2026-11-04: "yes build it with swipe up"; rule 605 as
   rewritten; mockups/journeys/tour-v3.html): full-screen cards swiped up, one whole page at a time
   (scroll snap, nothing of the next card at rest). The dots stay at the top. Every card's picture
   panel is the same height (the title one line, the sentence two, the foot 50) and is its art's
   size container, so each art fills it. Only the last card has a button. */
.wt-overlay.wt8 { background: var(--panel); flex-direction: column; align-items: stretch; justify-content: flex-start; }
.wt8-top { width: 100%; max-width: 520px; margin: 0 auto; box-sizing: border-box; display: flex; align-items: center; justify-content: space-between; min-height: 36px;
  padding: calc(12px + env(safe-area-inset-top)) var(--gutter, 16px) 0; }
.wt8-dots { display: flex; gap: 6px; align-items: center; height: 20px; }
.wt8-dots span { width: 6px; height: 6px; border-radius: 3px; background: var(--line-2); transition: width .2s var(--ease), background .2s var(--ease); }
.wt8-dots span.on { width: 16px; background: var(--ink); }
.wt8-pages { flex: 1 1 0; min-height: 0; width: 100%; overflow-y: auto; overflow-x: hidden; scroll-snap-type: y mandatory; overscroll-behavior: contain; scrollbar-width: none; }
.wt8-pages::-webkit-scrollbar { display: none; }
.wt8-page { height: 100%; scroll-snap-align: start; scroll-snap-stop: always; max-width: 520px; margin: 0 auto; box-sizing: border-box; display: flex; flex-direction: column;
  padding: 0 var(--gutter, 16px) calc(8px + env(safe-area-inset-bottom)); }
.wt8-art { flex: 1 1 0; min-height: 0; margin: var(--sp-12) 0 var(--sp-16); padding: var(--sp-16); background: var(--bg); border: 1px solid var(--line); border-radius: 16px; overflow: hidden; position: relative; container-type: size; }
.wt8-where { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .13em; text-transform: uppercase; font-weight: 600; color: var(--accent-2); }
.wt8-title { font-family: var(--serif); font-size: var(--fs-title); font-weight: 500; line-height: 1.05; color: var(--ink); margin: 6px 0 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wt8-body { font-family: var(--read); font-size: var(--fs-read); line-height: 1.4; color: var(--muted); margin: 6px 0 0; height: 2.8em; overflow: hidden; }
.wt8-short { display: none; }
@media (max-width: 499px) { .wt8-long { display: none; } .wt8-short { display: inline; } }
.wt8-foot { flex: none; height: var(--btn-h-lg); margin-top: var(--sp-16); display: flex; align-items: center; justify-content: center; }
.wt8-hint, .wt8-chev { appearance: none; background: none; border: 0; font: inherit; cursor: pointer; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; min-width: 64px; min-height: 44px; }
.wt8-hint { font-size: var(--fs-meta); font-weight: 600; color: var(--muted); }
.wt8-hint svg { color: var(--ink); }
.wt8-chev { color: var(--faint); opacity: .7; }
.wt8-hint:focus-visible, .wt8-chev:focus-visible { outline: 2px solid var(--accent-2); outline-offset: 2px; border-radius: 8px; }
.wt8-cta { flex: 1; height: var(--btn-h-lg); padding: 0 var(--sp-16); }
/* The pictures, simplified (owner-approved 2026-11-06, mockups/journeys/walkthrough-v2.html; rule 605):
   each card is a cut-down drawing of the real screen, the one thing it teaches in detail and the rest
   quiet shapes in the places they really sit (.wt8-bar for words, .wt8-block for a poster, .wt8-pill
   for a chip). No italics; one red per screen. */
.wt8-fill { height: 100%; display: flex; flex-direction: column; justify-content: space-between; gap: 12px; }
.wt8-k { font-family: var(--label); font-size: var(--fs-label); letter-spacing: .12em; text-transform: uppercase; font-weight: 600; color: var(--muted); margin: 0; }
.wt8-bar { display: block; flex: none; max-width: 100%; height: 8px; border-radius: 4px; background: #26262B; }
.wt8-bar.is-t { height: 10px; background: #2F2F35; }
.wt8-block { display: block; flex: none; aspect-ratio: 2 / 3; border-radius: 4px; background: #26262B; box-shadow: inset 0 0 0 1px var(--line); }
.wt8-pill { display: inline-flex; align-items: center; height: var(--chip-h); padding: 0 14px; border-radius: 999px; box-shadow: inset 0 0 0 1px var(--line-2); }
.wt8-pill .wt8-bar { height: 7px; }
.wt8-pills { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
/* 1 Picks: the For You card, today's dateline (.pk-dl, rule 1114) 10 over the poster. */
.wt8-picks { justify-content: flex-start; gap: 0; }
.wt8-ptabs { display: flex; align-items: flex-end; gap: 24px; height: 30px; flex: none; overflow: hidden; box-shadow: 0 1px 0 var(--line); }
.wt8-ptabs b { white-space: nowrap; font-size: var(--fs-ui); font-weight: 500; color: var(--ink); padding-bottom: 7px; box-shadow: 0 2px 0 var(--select); }
.wt8-ptabs .wt8-bar { margin-bottom: 12px; }
.wt8-pstage { flex: 1 1 0; min-height: 0; display: flex; justify-content: center; align-items: center; padding: 32px 6px 16px 0; }
.wt8-bigpo { position: relative; flex: none; height: min(100%, 90cqw); aspect-ratio: 2 / 3; border-radius: var(--radius-poster); box-shadow: 6px 6px 0 var(--shadow); }
.wt8-bigpo img { width: 100%; height: 100%; object-fit: cover; display: block; border-radius: var(--radius-poster); outline: 1px solid rgba(239,232,218,.85); outline-offset: -1px; filter: var(--grade); }
.is-locked .wt8-bigpo img { filter: saturate(.5) brightness(.8); }
.wt8-ghost { position: absolute; left: 10px; bottom: 10px; width: min(84px, 40%); height: 28px; border-radius: 14px; background: rgba(11,11,13,.5); box-shadow: inset 0 0 0 1px rgba(239,232,218,.14); }
.wt8-ghost.is-r { left: auto; right: 10px; width: 28px; }
.wt8-pinfo { display: flex; gap: 12px; align-items: flex-start; flex: none; }
.wt8-pinfo-l { flex: 1; min-width: 0; }
.wt8-pt { font: 500 var(--fs-heading)/1.1 var(--serif); color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-bottom: 9px; }
.wt8-why { font: 400 var(--fs-ui)/1.3 var(--serif); font-style: normal; color: var(--muted); margin: 7px 0 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wt8-why u { color: var(--accent-2); text-decoration-color: color-mix(in srgb, var(--accent-2) 45%, transparent); text-underline-offset: 2px; }
.wt8-why.is-unlock { font: 400 var(--fs-meta)/1.3 var(--sans); }
.wt8-why b { color: var(--ink); }
.wt8-stat { flex: none; text-align: right; }
.wt8-stat b { font: 500 var(--fs-title)/1 var(--serif); color: var(--accent-2); }
.wt8-stat b small { font: 600 var(--fs-meta) var(--sans); margin-left: 1px; }
.wt8-stat b.is-locked { color: var(--muted); }
.wt8-stat span { display: block; font-size: var(--fs-meta); font-weight: 500; color: var(--muted); margin-top: 3px; }
.wt8-stub { position: relative; flex: none; display: grid; grid-template-columns: repeat(3, 1fr); height: 56px; margin-top: 14px; border-radius: 9px; background: var(--cream); }
.wt8-stub::before, .wt8-stub::after { content: ""; position: absolute; top: 50%; width: 12px; height: 12px; margin-top: -6px; border-radius: 50%; background: var(--bg); }
.wt8-stub::before { left: -6px; }
.wt8-stub::after { right: -6px; }
.wt8-stub span { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; }
.wt8-stub span + span { border-left: 2px dashed #b9b0a0; }
.wt8-stub i { display: block; width: 14px; height: 14px; border-radius: 4px; background: #CFC6B5; }
.wt8-stub em { display: block; width: 44px; height: 6px; border-radius: 3px; background: #D6CDBC; }
/* 2 Tonight: the drawer the moon opens, over the tab bar with the moon lit. */
.wt8-tn { gap: 0; }
.wt8-dq { font: 500 var(--fs-heading)/1.15 var(--serif); color: var(--ink); margin-top: 5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wt8-seg { height: var(--seg-h); border-radius: 999px; box-shadow: inset 0 0 0 1px var(--line-2); display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; overflow: hidden; margin-top: 10px; }
.wt8-seg span { display: flex; align-items: center; justify-content: center; min-width: 0; }
.wt8-seg span + span { box-shadow: -1px 0 0 var(--line-2); }
.wt8-seg .wt8-bar { height: 7px; }
@container (max-height: 470px) { .wt8-tn-svc { display: none; } }
.wt8-tk { flex: none; margin: 0 5px 0 0; padding: 16px; border-radius: var(--radius-field); background: var(--cream); color: var(--cream-ink); box-shadow: 5px 5px 0 var(--shadow); }
.wt8-tk b { display: block; font-size: var(--fs-read); font-weight: 700; }
.wt8-tk i { display: block; width: 150px; height: 7px; border-radius: 4px; background: #D2C9B8; margin-top: 8px; }
.wt8-tab { flex: none; display: flex; align-items: flex-start; height: 66px; margin: 6px calc(-1 * var(--sp-16)) calc(-1 * var(--sp-16)); padding: 9px 8px 0; background: var(--panel); box-shadow: 0 -1px 0 var(--line); }
.wt8-tab > span { flex: 1; display: flex; flex-direction: column; align-items: center; gap: 6px; }
.wt8-tab > span > i { display: block; width: 20px; height: 20px; border-radius: 6px; background: #2F2F35; }
.wt8-tab .wt8-bar { height: 6px; }
.wt8-tab > .wt8-moon { flex: 0 0 58px; height: 44px; margin: -2px 6px 0; justify-content: center; border-radius: 15px; background: var(--cream); color: var(--bg); box-shadow: 0 0 0 4px rgba(239,232,218,.16), 0 0 0 9px rgba(239,232,218,.06); }
.wt8-moon svg { fill: currentColor; }
/* 3 Pitch: its page answered, as it really is: "Your pitch" with no dash, Start over, Save and Share as
   shapes top right, the pitch's red bar the one red. The chips wear the chosen style (rule 1172:
   --select-fill, the 1.5px --select-edge outline, cream words). */
.wt8-pitch { justify-content: flex-start; gap: 0; --wt8-fr-w: clamp(30px, calc((100cqh - 324px) / 3), 52px); }
.wt8-ph { display: flex; align-items: center; gap: 12px; }
.wt8-pback { pointer-events: none; }
.wt8-pacts { display: flex; align-items: center; gap: 12px; margin-left: auto; }
.wt8-pacts i { display: block; width: 30px; height: 30px; border-radius: 50%; box-shadow: inset 0 0 0 1px var(--line-2); }
.wt8-cut-ml { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: 4px; }
.wt8-pick { display: inline-flex; align-items: center; gap: 7px; height: var(--chip-h); padding: 0 12px 0 10px; border: 1px solid var(--line-2); border-radius: var(--radius-pill); background: rgba(255, 255, 255, .05); color: var(--ink); font-size: var(--fs-meta); font-weight: 600; white-space: nowrap; }
.wt8-pick svg { flex: none; color: var(--muted); }
.wt8-said { position: relative; margin: 16px 0 0; padding-left: 13px; font: 500 var(--fs-heading)/1.2 var(--serif); font-style: normal; color: var(--ink); }
.wt8-said::before { content: ""; position: absolute; left: 0; top: 3px; bottom: 3px; width: 3px; border-radius: 2px; background: var(--red); }
.wt8-chs { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.wt8-cc { display: inline-flex; align-items: center; gap: 6px; height: var(--chip-h); padding: 0 12px; border-radius: 999px; white-space: nowrap; font-size: var(--fs-meta); font-weight: 600; color: var(--ink); background: var(--select-fill); box-shadow: inset 0 0 0 1.5px var(--select-edge); }
.wt8-cc em { font-style: normal; font-size: var(--fs-label); font-weight: 700; color: var(--muted); }
.wt8-cc.is-add { background: none; box-shadow: inset 0 0 0 1px var(--line-2); color: var(--muted); font-weight: 400; }
.wt8-cut { margin-top: 16px; }
.wt8-cut-h { font: 600 var(--fs-heading)/1.15 var(--serif); color: var(--ink); }
.wt8-fr { display: flex; gap: 12px; align-items: center; margin-top: 12px; }
.wt8-fr > span { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.wt8-fr b { font: 500 var(--fs-card)/1.2 var(--serif); color: var(--ink); }
.wt8-fr em { font-style: normal; font-size: var(--fs-meta); font-weight: 600; color: var(--accent-2); }
.wt8-fr .wt8-bar { margin-top: 4px; }
.wt8-pitch.is-locked .wt8-fr em { color: var(--muted); }
@container (max-height: 400px) { .wt8-fr + .wt8-fr { display: none; } }
/* 4 Blend: two faces and one big %. */
.wt8-blend { --wt8-mini-w: clamp(26px, calc((100cqh - 300px) / 4.5), 40px); }
.wt8-blend-h { display: flex; flex-direction: column; align-items: center; text-align: center; }
.wt8-blend-h > b { font: 500 92px/1 var(--serif); color: var(--accent-2); margin-top: 8px; } /* type scale exception: match % numerals */
.wt8-blend-h > b small { font-size: var(--fs-heading); }
@container (max-height: 440px) { .wt8-blend-h > b { font-size: 72px; } .wt8-blend-h > b small { font-size: var(--fs-card); } } /* type scale exception: match % numerals */
.wt8-blend-h > b.is-locked { display: inline-flex; align-items: center; gap: 8px; font-size: var(--fs-display); color: var(--muted); margin-top: 8px; }
.wt8-blend-h > span { font-size: var(--fs-ui); font-weight: 500; color: var(--muted); margin-top: 4px; }
.wt8-blend-h > span em { font-style: normal; font-weight: 700; color: var(--ink); }
.wt8-minis { display: flex; flex-direction: column; gap: 12px; }
.wt8-mini { display: flex; gap: 12px; align-items: center; }
.wt8-mini > span { display: flex; flex-direction: column; gap: 8px; }
.wt8-mini i { display: block; width: 84px; height: 8px; border-radius: 4px; background: rgba(91,143,196,.35); }
.wt8-faces { display: flex; }
.wt8-faces .wt8-face + .wt8-face { margin-left: -16px; }
.wt8-faces.is-s .wt8-face { box-shadow: 0 0 0 2px var(--bg); }
.wt8-faces.is-s .wt8-face + .wt8-face { margin-left: -8px; }
.wt8-faces.is-xs .wt8-face { box-shadow: 0 0 0 2px #1c2634; }
.wt8-faces.is-xs .wt8-face + .wt8-face { margin-left: -6px; }
.wt8-face.is-blank { background: #2F2F35; }
.wt8-face { display: inline-flex; align-items: center; justify-content: center; flex: none; border-radius: var(--radius-av); font-family: var(--serif); font-weight: 600; box-shadow: 0 0 0 3px var(--bg); }
.wt8-ibtn { display: flex; gap: 10px; flex: none; }
.wt8-ibtn .wt8-cta { height: var(--btn-h); }
.wt8-icirc { appearance: none; width: var(--btn-h); height: var(--btn-h); flex: none; border-radius: 50%; border: 1px solid var(--line-2); background: none; color: var(--ink); display: flex; align-items: center; justify-content: center; cursor: pointer; }
/* 5 Movie night: the room's faces and the leading vote. */
.wt8-night { justify-content: flex-start; gap: 0; --wt8-lead-w: clamp(48px, calc((100cqh - 300px) / 2.6), 66px); --wt8-q-w: calc(var(--wt8-lead-w) * 2 / 3); }
.wt8-room-h { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.wt8-night .wt8-pills { margin-top: 14px; }
.wt8-vote { display: flex; gap: 14px; align-items: center; padding: 12px; border-radius: 14px; }
.wt8-vote:not(.is-q) { margin-top: 16px; background: var(--select-fill); border: 1px solid var(--select-edge); box-shadow: var(--select-ring); }
.wt8-vote img { width: var(--wt8-lead-w); aspect-ratio: 2 / 3; object-fit: cover; border-radius: 4px; flex: none; filter: var(--grade); }
.wt8-vote > span { display: flex; flex-direction: column; min-width: 0; }
.wt8-vote b { font: 500 var(--fs-heading)/1.15 var(--serif); color: var(--ink); }
.wt8-vote em { font-style: normal; font-size: var(--fs-ui); font-weight: 600; color: var(--accent-2); margin-top: 5px; }
.wt8-vote small { display: flex; align-items: center; gap: 7px; margin-top: 9px; font-size: var(--fs-meta); font-weight: 500; color: var(--muted); }
.wt8-vote.is-q > span { gap: 8px; }
.wtf-unlock { text-align: center; font-size: var(--fs-meta); color: var(--muted); margin: 14px 0 0; }
.wtf-unlock b { color: var(--ink); }
.wtf-unlock .wt-rate, .wt-mt .wt-rate { display: flex; margin: 4px auto 0; color: var(--ink); }
.wtf-avoid { display: flex; align-items: center; justify-content: space-between; gap: 10px; width: 100%; margin-top: var(--sp-24); padding: 14px 0 0; border: 0; border-top: 1px solid var(--line); background: none; color: var(--ink); font: inherit; text-align: left; cursor: pointer; }
.wtf-avoid b { display: block; font-weight: 600; font-size: var(--fs-ui); }
.wtf-avoid small { color: var(--muted); font-size: var(--fs-meta); }
.wtf-avoid em { font-style: normal; font-weight: 600; font-size: var(--fs-meta); color: var(--accent-2); white-space: nowrap; }

/* Film DNA without the clutter (owner, 2026-11-02, mockups/film-dna-declutter.png; rule 592): no
   rules over, under or inside the section, 40px between sections and 24 inside, each strand's share
   under its name, and the key with the tap hint on one line. */
.dna9-pct { fill: var(--accent-2); font-weight: 600; font-variant-numeric: tabular-nums; }
.dna9-pct.is-other { fill: var(--ink); }
.dna9-pct-sep { fill: var(--faint); font-weight: 400; }
.dna9 .dna9-key { justify-content: center; font-size: var(--fs-meta); color: var(--faint); margin-top: 2px; }
/* The strand labels as buttons (rule 820): over the SVG at its scale (the font size is set inline in
   cqw, so it shrinks with the radar as the SVG text did), each a 44px target with a muted chevron. */
.dna9-box { position: relative; width: 100%; max-width: 520px; margin: 0 auto; container-type: inline-size; }
.dna9-tap-lab { position: absolute; display: flex; flex-direction: column; justify-content: center; min-height: 44px; min-width: 44px;
  padding: 0; border: 0; background: none; font: inherit; font-size: var(--fs-meta); line-height: 1.11; color: var(--muted);
  white-space: nowrap; cursor: pointer; transform: translate(-50%, -50%); }
.dna9-tap-lab.is-start { transform: translate(0, -50%); align-items: flex-start; text-align: left; }
.dna9-tap-lab.is-end { transform: translate(-100%, -50%); align-items: flex-end; text-align: right; }
.dna9-tap-lab.is-middle { align-items: center; text-align: center; }
.dna9-tap-lab.is-top { color: var(--ink); font-weight: 600; }
.dna9-tap-lab.is-active { color: var(--ink); font-weight: 700; }
.dna9-tap-name, .dna9-tap-pct { display: inline-flex; align-items: center; }
.dna9-tap-pct { font-weight: 600; font-variant-numeric: tabular-nums; }
.dna9-tap-pct .is-mine { color: var(--accent-2); }
.dna9-tap-pct .is-other { color: var(--ink); }
.dna9-tap-pct .is-sep { color: var(--faint); font-weight: 400; white-space: pre; }
.dna9-chev { flex: none; margin-left: var(--sp-4); color: var(--muted); }
/* "Read each strand ›" (rule 821): the quiet full-width row under the key, the app's row look. */
.dna9-read { appearance: none; display: flex; align-items: center; justify-content: space-between; gap: var(--sp-12); width: 100%;
  min-height: 44px; margin-top: var(--sp-16); padding: 0 2px; border: 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line);
  background: none; font: 500 var(--fs-ui)/1.2 var(--sans); color: var(--ink); text-align: left; cursor: pointer; }
.dna9-read-chev { flex: none; color: var(--faint); }
.dna9-legend { gap: var(--sp-16); }
.dna9-legend > span { display: inline-flex; align-items: center; gap: 6px; font-weight: 600; }
.dna9-legend > span.is-shape { color: var(--accent-2); }
.dna9-legend > span.is-other { color: var(--ink); }
.dna9-legend > span:last-child { font-weight: 400; }
.dna9-legend i.is-shape { border-top: 3px solid var(--accent-2); border-radius: 2px; }
.dna9 .dna9-down { margin-top: 24px; font-family: var(--read); font-size: var(--fs-ui); line-height: 1.45; }
.pv2-taste .dna9-strip { border-top: 0; padding: 0; margin-top: 40px; }
.pv2-taste .dna9-strip .sec.sec-inline { margin-bottom: 6px; }
.pv2-taste .dna9-strip .dna-sub { margin: 0 0 14px; }
.pv2-taste .dna9-strip .dna-traits { margin: 24px 0 0; padding-top: 0; border-top: 0; max-width: none; }
.pv2-taste .dna9-strip ~ .hero-lower { border-top: 0; margin-top: 40px; padding: 0; }
.pv2-taste .dna9-strip ~ .hero-lower .sec.sec-inline { margin-bottom: 6px; }
.pv2-taste .dna9-strip ~ .hero-lower .hero-axis-note { font-size: var(--fs-meta); margin: 0 0 var(--sp-24); }
.pv2-taste .dna9-strip ~ .hero-lower .hero-axis-row { gap: var(--sp-24); margin-top: 0; }
.pv2-taste:has(.dna9-strip) .trait-grid { margin-top: 40px; }
.mx-dna9 .dna-sub { margin: 0 0 16px; }
.mx-dna9 .pv2-meet { margin-top: var(--sp-24); }

/* The streak drawer, explained (owner, 2026-11-02, mockups/streak-drawer-clear.png; rule 145):
   "Weekly streak" over the strip and "N weeks in a row", the one line, the weeks in one row with
   this run bracketed, the numbers and what counts. */
/* "Weekly streak" on its own line, then the strip and the title side by side in one row (owner,
   2026-11-04, rule 1088: the strip sat over the label), as the iPhone's StreakSheet. */
.wstreak-sheet .modal-title-row { display: grid; grid-template-columns: auto minmax(0, 1fr); column-gap: 12px; align-items: center; }
.wstreak-sheet .modal-title-row > div { display: contents; }
.wstreak-sheet .modal-title-row .modal-eyebrow { grid-column: 1 / -1; grid-row: 1; margin: 0 0 6px; }
.wstreak-sheet .modal-title-row .modal-sub { grid-column: 1 / -1; }
.wstreak-sheet .modal-title-icon { grid-column: 1; grid-row: 2; width: auto; height: auto; margin: 0; border: 0; border-radius: 0; background: none; }
.wstreak-sheet .modal-title-icon .wstreak-flame { width: 34px; height: 23px; }
.wstreak-sheet .modal-title-row h2 { grid-column: 2; grid-row: 2; padding-left: 0; font-size: var(--fs-heading); line-height: 1.1; }
.wstreak-sheet .modal-eyebrow { color: var(--muted); }
.wstreak-what { margin: 2px 0 0; font: 400 var(--fs-read)/1.45 var(--read); color: var(--muted); }
.wstreak-detail .wstreak-weeks { gap: 0 8px; margin: 24px 0 0; }
.wstreak-detail .wstreak-weeks > div { display: flex; flex-direction: column; align-items: center; font-size: var(--fs-label); color: var(--faint); }
.wstreak-detail .wstreak-weeks > div > span { margin-top: 6px; }
.wstreak-detail .wstreak-weeks > div.in-run > span { color: var(--ink); font-weight: 600; }
.wstreak-detail .wstreak-weeks > div.is-open > span { color: var(--accent-2); font-weight: 600; }
.wstreak-detail .wstreak-slot.big { border-radius: var(--radius-poster); outline: 1px solid var(--line-2); outline-offset: -1px; }
.wstreak-detail i.wstreak-slot.big { display: flex; align-items: center; justify-content: center; font-style: normal; font-size: var(--fs-meta); color: var(--faint); background: var(--panel-2); outline-color: var(--line); }
.wstreak-detail i.wstreak-slot.big.on { background: var(--accent-soft); }
.wstreak-detail i.wstreak-slot.big.now { background: transparent; outline: 0; border: 1.5px dashed var(--accent-2); color: var(--accent-2); }
.wstreak-run { grid-row: 2; display: flex; flex-direction: column; align-items: center; margin-top: 8px; min-width: 0; }
.wstreak-run i { display: block; align-self: stretch; height: 8px; margin: 0 6px; border: 1.5px solid var(--accent-2); border-top: 0; border-radius: 0 0 4px 4px; }
.wstreak-run span { margin-top: 3px; font-size: var(--fs-label); font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: var(--accent-2); white-space: nowrap; }
.wstreak-cap { margin: 10px 0 0; font-size: var(--fs-meta); color: var(--faint); }
.wstreak-open-line { margin: var(--sp-24) 0 0; font: 400 var(--fs-read)/1.45 var(--read); color: var(--ink); }
.wstreak-open-line b { font-weight: 600; }
.wstreak-stats { display: flex; margin-top: 24px; }
.wstreak-stats > div { flex: 1; display: flex; flex-direction: column; }
.wstreak-stats b { font: 600 var(--fs-heading)/1.1 var(--serif); color: var(--ink); font-variant-numeric: tabular-nums; }
.wstreak-stats small { font-family: var(--serif); font-size: var(--fs-ui); font-weight: 500; color: var(--muted); }
.wstreak-stats span { margin-top: 4px; font-size: var(--fs-label); font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--faint); }
.wstreak-counts-h { display: flex; align-items: center; justify-content: space-between; width: 100%; min-height: 44px; margin-top: var(--sp-16); padding: 0; border: 0; background: none; cursor: pointer; font: inherit; font-size: var(--fs-label); font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); }
.wstreak-counts-h:active { opacity: .7; }
.wstreak-counts-h svg { transition: transform .2s ease-out; }
.wstreak-counts-h svg.is-open { transform: rotate(180deg); }
.wstreak-counts { list-style: none; margin: 14px 0 0; padding: 0; display: flex; flex-direction: column; gap: 14px; }
.wstreak-counts li { display: flex; align-items: center; gap: 12px; font-size: var(--fs-ui); color: var(--ink); }
.wstreak-counts li svg { flex: none; color: var(--muted); }
.wstreak-not { margin: 16px 0 0; font-size: var(--fs-meta); line-height: 1.45; color: var(--faint); }

/* "Have you seen these?" as a Picks card (rule 610, mockups/seen-deck-picks.png): the deck's own top
   (title, a running "N rated", close) over a Picks track, one card a screen, nothing peeking. */
.sdk-top { flex: none; display: flex; align-items: center; gap: 12px; padding: max(12px, env(safe-area-inset-top, 0px)) 16px 8px; }
.sdk-eyebrow { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-family: var(--label); font-size: var(--fs-label); letter-spacing: .14em; text-transform: uppercase; font-weight: 600; color: var(--muted); }
.sdk-count { flex: none; font-size: var(--fs-meta); color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.sdk-track { flex: 1 1 auto; min-height: 0; width: 100%; max-width: 520px; margin: 0 auto; }
.sdk-track > .pk-slide { height: 100%; }
.sdk-end-s { margin: 0; font-size: var(--fs-meta); color: var(--muted); }

/* "Your take" (owner-approved mockups/journeys/take-prompt.png B; rules 612, 900): step 2 of the
   first "When did you watch it?" drawer. The film pinned on top through both steps (40 x 60 poster,
   cream keyline, oxblood shadow; Bodoni title; your stars in blue), the drawer easing to its new
   height, a headline keyed to the rating, a 16px box three lines tall that grows to about five and
   then scrolls, Friends / Everyone and Spoilers always in place, one line on where it shows, then
   Skip and the cream "Post take" ticket with a notch at each end. */
.tk-sheet { gap: 0; }
.tk-film { display: flex; align-items: center; gap: 12px; margin: 0 -16px; padding: 0 16px 14px; border-bottom: 1px solid var(--line); }
.tk-film-po { display: block; width: 40px; height: 60px; flex: none; object-fit: cover; border-radius: 4px; outline: 1px solid var(--ink); background: var(--panel-2); filter: saturate(.8) contrast(1.05); }
.tk-film-t { min-width: 0; }
.tk-film-title { margin: 0; font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; line-height: 1.1; color: var(--ink); text-align: left; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.tk-film-meta { margin: 5px 0 0; display: flex; align-items: center; gap: 8px; font-size: var(--fs-meta); color: var(--muted); }
.tk-film-stars { color: var(--accent-2); font-size: var(--fs-ui); white-space: nowrap; }
.tk-grow { overflow: hidden; transition: height .28s var(--ease); }
.tk-grow-in { display: flow-root; }
/* The When and take steps fit a small screen: the drawer stops under the status bar and scrolls
   inside itself, its bottom clear of the home indicator (rule 1096). */
.seen-sheet.tk-sheet { max-height: calc(100dvh - max(16px, env(safe-area-inset-top))); overflow-y: auto; overscroll-behavior: contain; }
@media (prefers-reduced-motion: reduce) { .tk-grow { transition: none; } }
.tk-sheet .tk-when { margin: 16px 0 0; border: 0; padding: 0; background: none; }
.tk-sheet .tk-when .fa-ask-q { font-family: var(--serif); font-size: var(--fs-heading); font-weight: 500; line-height: 1.1; margin-bottom: 12px; }
.tk-step { padding-top: 16px; text-align: left; }
.fa-take .tk-step { padding-top: 0; }
.tk-hl { margin: 0 0 12px; font-family: var(--serif); font-size: var(--fs-heading); font-weight: 600; line-height: 1.1; color: var(--ink); }
.tk-box { position: relative; }
.tk-ta { display: block; width: 100%; box-sizing: border-box; resize: none; overflow-y: auto; font: inherit; font-size: var(--fs-read); line-height: 22px; color: var(--ink);
  background: rgba(255,255,255,.03); border: 1px solid var(--line-2); border-radius: var(--radius-field); padding: 12px 14px 24px; }
.tk-ta::placeholder { color: var(--faint); }
.tk-ta:focus { outline: none; border-color: var(--ink); }
/* While the step's mode is read (rule 1131): one wireframe line where the placeholder sits. */
.tk-skel { position: absolute; left: 15px; top: 18px; width: 10em; }
.tk-ta:disabled { opacity: 1; cursor: default; }
.tk-count { position: absolute; right: 12px; bottom: 4px; font-size: var(--fs-label); font-weight: 600; color: var(--warn); font-variant-numeric: tabular-nums; pointer-events: none; }
.tk-opts { display: flex; align-items: center; gap: 10px; margin-top: 10px; }
.tk-seg { display: inline-flex; height: 32px; box-sizing: border-box; border: 1px solid var(--line-2); border-radius: 999px; padding: 2px; background: rgba(255,255,255,.03); }
.tk-seg-btn { appearance: none; cursor: pointer; display: inline-flex; align-items: center; gap: 5px; font: inherit; font-family: var(--label); font-size: var(--fs-meta); font-weight: 600;
  padding: 0 11px; border: 0; border-radius: 999px; background: transparent; color: var(--muted); }
.tk-seg-btn.on { background: var(--ink); color: var(--bg); }
.tk-seg-btn.off { opacity: .45; cursor: default; }
.tk-seg-btn:active:not(:disabled) { transform: scale(.96); }
.tk-spoiler { margin-left: auto; display: inline-flex; align-items: center; gap: 8px; font-size: var(--fs-meta); color: var(--muted); cursor: pointer; }
.tk-where { display: flex; align-items: center; gap: 6px; margin: 10px 0 0; font-size: var(--fs-meta); color: var(--faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tk-where svg { flex: none; }
.tk-foot { display: flex; align-items: center; gap: 10px; margin-top: 14px; }
.tk-skip { appearance: none; cursor: pointer; width: 84px; height: var(--btn-h-lg); flex: none; border: 0; background: none; font: inherit; font-size: var(--fs-ui); font-weight: 600; color: var(--muted);
  transition: transform .06s ease-out, opacity .06s ease-out; }
.tk-post { appearance: none; cursor: pointer; flex: 1; height: var(--btn-h-lg); border: 0; border-radius: 12px; background: var(--ink); color: var(--bg); font: inherit; font-size: var(--fs-ui); font-weight: 600;
  -webkit-mask: radial-gradient(circle 8px at 0 50%, transparent 98%, #000) left / 51% 100% no-repeat, radial-gradient(circle 8px at 100% 50%, transparent 98%, #000) right / 51% 100% no-repeat;
  mask: radial-gradient(circle 8px at 0 50%, transparent 98%, #000) left / 51% 100% no-repeat, radial-gradient(circle 8px at 100% 50%, transparent 98%, #000) right / 51% 100% no-repeat;
  transition: transform .06s ease-out, opacity .06s ease-out; }
.tk-post:disabled { opacity: .4; cursor: default; }
/* The press lands on touch-down (rule 675's feel on the web). */
.tk-skip:active { transform: scale(.96); opacity: .6; }
.tk-post:active:not(:disabled) { transform: scale(.97); opacity: .85; }
/* A take on a Lately post (rule 566): one italic line under the meta; spoilers hidden until tapped. */
.ff-take { display: block; margin-top: 3px; font-style: normal; font-size: var(--fs-meta); color: var(--muted, var(--faint)); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ff-take.full { white-space: normal; font-family: var(--read); font-size: var(--fs-read); color: var(--ink); margin-top: 6px; }
.ff-spoiler { appearance: none; cursor: pointer; font: inherit; font-style: normal; font-size: var(--fs-meta); padding: 0; border: 0; background: transparent; color: var(--faint); text-decoration: underline dotted; }

/* Press feedback (owner, 2026-11-02): every link, chip, row and poster dims a little while pressed,
   on touch screens, as the iPhone's PressableStyle does. Opacity only, so it never fights a
   component's own :active transform. */
@media (hover: none) {
  a, button:not(:disabled), [role="button"], summary { transition: opacity .12s ease; -webkit-tap-highlight-color: transparent; }
  a:active, button:active:not(:disabled), [role="button"]:active, summary:active { opacity: .75; }
}

/* "Directed by A & B" wraps as one sentence (owner, 2026-11-02: the second name hung indented under
   the first as a flex item). The facts variant keeps its flex row. */
.fd-hero-director:not(:has(.fd-hero-facts)) { display: block; }
.fd-hero-director:not(:has(.fd-hero-facts)) .fd-hero-director-v { white-space: normal; }
/* ============================================================   ONE SIZING SYSTEM (owner, 2026-11-02, mockups/proportions-system.png; rule 632)
   The web half of the iPhone's tokens: page names are Title 28 (Display 40 is only for
   identity heroes: an archetype, a match %, a big number); three header patterns; three
   button heights; one chip; one segmented control. Mechanical: layouts stay as they were.
   =================================================================== */
/* A: a tab root's page name, Title 28, 16 below the top bar's rule. */
.page-title { font: var(--t-title); color: var(--ink); margin: var(--sp-16) 0 0; }
/* B: a pushed page's one 44px row: Back circle, Title 28 beside it, actions right; the sub line
   sits under the title, indented 48 (the 36 circle and its 12 gap). */
.page-header { display: flex; align-items: center; gap: var(--sp-12); min-height: var(--header-h); }
.page-header-title { font: var(--t-title); color: var(--ink); margin: 0; flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* C: a drawer: Heading 22 with the 36 close circle right, an optional meta line 4 under it. */
.drawer-title { font: var(--t-heading); }
.drawer-sub { font: var(--t-caption); color: var(--muted); margin-top: var(--sp-4); }
.fd-wt-sheet-title .fd-watch-region { font-family: var(--sans); }
/* Buttons: Large 50, Standard 44 (.btn), Compact 34. */
.btn.btn-lg { min-height: var(--btn-h-lg); }
.btn.btn-sm { min-height: var(--btn-h-sm); padding: 0 var(--sp-12); font-size: var(--fs-meta); }
/* One chip and filter style: 32 tall, 13 semibold, 12 side padding, 8 apart; on is the blue soft
   fill with the blue outline. The mood chips take it too. */
.mood-chips { gap: var(--sp-8); }
.mood-chip, .mood-chip-sm { display: inline-flex; align-items: center; height: var(--chip-h); padding: 0 var(--sp-12);
  font-size: var(--fs-meta); font-weight: 600; color: var(--ink); background: rgba(255,255,255,.05); border: 1px solid var(--line-2); border-radius: var(--btn-r); }
.mood-chip.on { color: var(--ink); background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); font-weight: 600; }
/* The other chip classes still in use are the same chip (rule 632): Browse's and the library's
   filters and their active row, the log sheet's day chips, Browse's refine row (dashed, as the
   iPhone's dashed Chip), Settings' choices, the reveal's held chips, the group watchlist's and
   onboarding's answers, the radar's shape toggles. 32 tall, 13 semibold, pill; on is the select tint
   with its 1.5px outline and cream words (rule 1172), never a solid fill. Each keeps its own side padding. */
:is(.browse-chip, .fa-chip, .bp-refine-chip, .pm-avoid-chip, .held-chip, .gwl-chipbtn, .pv2-chip) {
  display: inline-flex; align-items: center; justify-content: center; height: var(--chip-h); min-height: 0; padding-top: 0; padding-bottom: 0;
  border-radius: var(--btn-r); font: 600 var(--fs-meta)/1 var(--sans); white-space: nowrap; }
:is(.browse-chip, .pm-avoid-chip, .held-chip, .gwl-chipbtn) { color: var(--ink); background: rgba(255,255,255,.05); border-color: var(--line-2); }
:is(.browse-chip, .fa-chip, .bp-refine-chip, .pm-avoid-chip, .held-chip, .gwl-chipbtn):is(.on, .is-on, [aria-pressed="true"]) {
  color: var(--ink); background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); border-style: solid; }
/* One segmented style: 36 tall, full width, panel track, the chosen one solid --select-deep (rule 1172). */
.mood-seg { min-height: var(--seg-h); padding: 0 var(--sp-8); }
.seg-btn { min-height: var(--seg-h); }
/* Our read drawer, option A (owner, 2026-11-02, mockups/our-read-drawer.png): rating and match side by
   side in one ruled strip, the read in Newsreader with a Bodoni drop cap, and the because-row as short
   landscape crops with titles, no shadow. */
.why-strip { flex: 1; min-width: 0; display: flex; border: 1px solid var(--line-2); border-radius: 12px; }
.why-drawer .fd-why-text { font-family: var(--read); font-size: var(--fs-read); line-height: 1.6; }
.why-drawer .fd-why-text.has-dropcap::first-letter { float: left; font: 400 var(--fs-display)/.85 var(--serif); color: var(--accent-2); margin: 6px 8px 0 0; }
.why-drawer-like-h { display: flex; justify-content: space-between; align-items: baseline; }
.why-drawer-like-n { font: var(--t-caption); color: var(--muted); }
.why-drawer .why-drawer-posters { padding: 0; gap: 12px; }
.why-drawer .why-drawer-poster { width: 100px; }
.why-drawer .why-drawer-po { width: 100px; aspect-ratio: 5 / 3; border-radius: 6px; outline: 1px solid var(--line-2); outline-offset: -1px; }
.why-drawer .why-drawer-po img { object-position: center 25%; }
.why-drawer .why-drawer-name { margin-top: 6px; color: var(--ink); }

/* The film's social area as cards (owner, 2026-11-02, mockups/film-social-area.png option A; rule 634):
   Friends (avatar stack, "N saw it · avg", chevron), Watch together with the one filled button, Your
   take inline, Discussion previewing the top take. */
.fp-card-k { display: flex; align-items: center; gap: 8px; font: 600 var(--fs-label)/1 var(--sans); letter-spacing: .14em; text-transform: uppercase; color: var(--muted); margin-bottom: 12px; }
.fp-card-n { margin-left: auto; font: var(--t-caption); letter-spacing: 0; text-transform: none; color: var(--muted); }
.fp-card { appearance: none; width: 100%; display: flex; align-items: center; gap: 12px; padding: 16px; text-align: left; font: inherit; color: var(--ink);
  background: var(--panel); border: 1px solid var(--line); border-radius: 12px; cursor: pointer; }
.fd-ratings-card .fp-fr.fp-card { display: block; background: none; cursor: default; }
.fd-ratings-card .fp-fr.fp-card .fp-fr-h { align-items: center; gap: 12px; flex-wrap: nowrap; padding: 16px; background: var(--panel); border: 1px solid var(--line); border-radius: 12px; }
.fd-ratings-card .fp-fr.fp-card.is-open .fp-fr-h { border-radius: 12px 12px 0 0; }
.fp-card.fp-with { cursor: default; margin-top: 0; font-size: var(--fs-ui); }
.fp-card.fp-with .fp-av { width: 44px; height: 44px; border-radius: var(--radius-av); font-size: var(--fs-read); }
.fp-card .fp-with-also { display: block; font: var(--t-caption); color: var(--muted); }
.fp-mytake .fp-take-av, .fp-disc-top .fp-take-av { width: 28px; height: 28px; border-radius: var(--radius-av); flex: none; font-size: var(--fs-label); object-fit: cover; }
.fp-disc-card { flex-direction: column; align-items: stretch; gap: 12px; }

/* Chats and discussions, option A (owner, 2026-11-02, mockups/chat-uplift.png; rule 635): photo faces
   round, and a send that stays muted until there is text. */
.chat-av .mnr-msg-av, .chat-av img, .chat-av .friend-av { border-radius: var(--radius-av) !important; }
/* The thread's film card, "Grain and the shadow" (owner-approved 2026-11-05, mockups/journeys/dm-card-v4
   option A; rule 1132): Montage's card frame (8, 1px --line-2, --panel) with the film's backdrop as a
   dim, desaturated, grained band fading into it, the poster on it (the oxblood offset on the thread's
   newest card only, one red per screen), the kicker and year · director in muted caps, the Bodoni
   title, the reader's straight blue stamp or "Rated 5★", the note, two pills. The grain is one static
   128px noise tile (/grain.png) blended over the still: nothing is drawn per frame. iPhone: GroupFeed.swift. */
.gth-card.dmc { width: 280px; max-width: 100%; padding: 12px; border: 1px solid var(--line-2); border-radius: var(--radius-card); background: var(--panel); overflow: hidden; isolation: isolate; }
.dmc-band { position: absolute; left: 0; right: 0; top: 0; height: 104px; overflow: hidden; z-index: -1; pointer-events: none; }
.dmc-band img { position: absolute; inset: -10px; width: calc(100% + 20px); height: calc(100% + 20px); object-fit: cover; object-position: center 30%;
  filter: grayscale(.35) saturate(.62) brightness(.5) contrast(1.08) blur(2.5px); }
.dmc-band img.is-poster { object-position: center 25%; filter: grayscale(.35) saturate(.62) brightness(.5) contrast(1.08) blur(9px); }
.dmc-grain { position: absolute; inset: 0; opacity: .8; mix-blend-mode: overlay; background: url(/grain.png) 0 0 / 128px 128px repeat; }
.dmc-band::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(20,20,23,.25) 0%, rgba(20,20,23,.2) 35%, rgba(20,20,23,.78) 74%, var(--panel) 100%),
  radial-gradient(120% 90% at 50% 20%, transparent 55%, rgba(11,11,13,.45) 100%); }
.dmc-body { appearance: none; display: block; width: 100%; padding: 0; border: 0; background: none; color: inherit; font: inherit; text-align: left; cursor: pointer; }
.dmc-g { display: grid; grid-template-columns: 64px 1fr; gap: 12px; }
.dmc-po, .dmc-po.gth-card-ph { display: block; width: 64px; height: 96px; margin-top: 6px; object-fit: cover; border-radius: 6px; background: var(--line); }
.dmc-po.is-newest { box-shadow: 5px 5px 0 var(--shadow); }
.dmc-r { display: block; min-width: 0; padding-top: 6px; }
.dmc-kick { display: block; font: 600 var(--fs-label)/1.15 var(--sans); letter-spacing: 1.3px; text-transform: uppercase; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dmc-t { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; margin-top: 7px; font: 600 var(--fs-card)/1.1 var(--serif); color: var(--ink); }
.dmc-mt { display: block; margin-top: 5px; font: 600 var(--fs-label)/1.2 var(--sans); letter-spacing: 1.2px; text-transform: uppercase; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dmc-ln { display: block; margin-top: 9px; }
/* A film shared from a Lately post (rule 1181): "Emma rated it 4.5★", only to a reader who could see that post. */
.dmc-via { display: block; margin-top: 6px; font-size: var(--fs-meta); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dmc-via b { color: var(--ink); font-weight: 600; }
.dmc-stamp { display: inline-flex; align-items: baseline; padding: 3px 5px 2px; border: 1.5px solid var(--accent-2); border-radius: 3px; background: var(--bg); color: var(--accent-2); font: 600 var(--fs-meta)/1 var(--serif); white-space: nowrap; }
.dmc-stamp small { font-size: .82em; }
.dmc-rated { display: inline-flex; align-items: center; gap: 6px; font: 500 var(--fs-meta) var(--sans); color: var(--muted); white-space: nowrap; }
.dmc-rated b { padding: 3px 5px 2px; border: 1.5px solid rgba(239,232,218,.45); border-radius: 3px; background: var(--bg); color: var(--ink); font: 600 var(--fs-meta)/1 var(--serif); }
.dmc-b { display: flex; gap: 7px; margin-top: 12px; }
.dmc-pb { position: relative; appearance: none; flex: 1 1 0; min-width: 0; height: 34px; padding: 0 10px; border: 0; border-radius: 999px; display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  font: 600 var(--fs-meta)/1 var(--sans); white-space: nowrap; cursor: pointer; }
.dmc-pb::before { content: ""; position: absolute; inset: -5px 0; }
.dmc-pb > span { overflow: hidden; text-overflow: ellipsis; }
.dmc-pb svg { width: 15px; height: 15px; flex: none; }
/* The chat card's second pill never truncates (rule 1164): it is at least as wide as its words and the
   Save pill gives way; at a normal width the two stay equal. The service's logo is a 16 square. */
.dmc-pb.dmc-watch { min-width: max-content; }
.dmc-pb.dmc-watch > span { overflow: visible; }
.dmc-pb.dmc-watch > .dmc-svc { position: relative; flex: none; width: 16px; height: 16px; border-radius: 3px; overflow: hidden; background: var(--panel); color: var(--faint); font: 600 var(--fs-label)/16px var(--sans); text-align: center; }
.dmc-pb.dmc-watch > .dmc-svc img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.dmc-pb.p { background: var(--cream); color: var(--bg); }
.dmc-pb.p.on { background: rgba(91,143,196,.18); color: var(--accent-2); }
.dmc-pb.s { background: rgba(239,232,218,.08); color: var(--ink); }
.dmc-pb:disabled { opacity: .6; cursor: default; }
.mnr-compose-go:disabled { opacity: 1; background: var(--line-2); color: var(--faint); }
.fdisc-rep .fdisc-tx.chat-bubble { display: inline-block; margin-top: 4px; font-size: var(--fs-ui); border-bottom-left-radius: 5px; }
.fdisc-rep .fdisc-av-sm { border-radius: var(--radius-av); }

/* Lately post drawer, option A (owner, 2026-11-02, mockups/lately-polish.png; rule 636): the film and take
   as the header, one flat line-icon action bar with React opening a pill of the five emoji, comments as
   the chats' bubbles, and the chats' composer pinned at the drawer's foot. Feed rows count in line icons. */
.sp-d-head { display: flex; flex-direction: column; gap: 12px; }
.sp-d-top { display: flex; gap: 12px; align-items: flex-start; }
.sp-d-tx { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.sp-d-head .sp-d-who { display: inline-flex; align-items: center; gap: 6px; font: var(--t-caption); color: var(--ink); text-decoration: none; margin: 0; }
.sp-d-head .sp-d-who .sp-av { width: 22px; height: 22px; border-radius: var(--radius-av); }
.sp-d-head .sp-d-who span { color: var(--muted); }
.sp-d-t { font: 400 var(--fs-heading)/1.2 var(--serif); color: var(--ink); }
.sp-d-st { color: var(--accent-2); font-size: var(--fs-ui); }
.sp-d-film { flex: none; }
.sp-d-take { margin: 0; font: 400 var(--fs-read)/1.5 var(--read); color: var(--ink); }
.lp-actions { position: relative; flex-wrap: nowrap; gap: 16px; padding: 8px 0; margin-top: 12px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.lp-act { appearance: none; border: 0; background: none; padding: 0; min-height: 36px; display: inline-flex; align-items: center; gap: 6px; color: var(--ink); font: var(--t-caption); cursor: pointer; }
.lp-act span { color: var(--muted); }
.lp-act.is-mine, .lp-act.is-mine span { color: var(--accent-2); }
.lp-act.is-mine svg path { fill: currentColor; }
.lp-share { margin-left: auto; }
.lp-pick { position: absolute; left: 40px; bottom: calc(100% - 4px); display: flex; gap: 4px; padding: 4px 8px; background: var(--panel-2); border: 1px solid var(--line-2); border-radius: 999px; box-shadow: 0 8px 24px rgba(0,0,0,.45); z-index: 2; }
.lp-pick-e { appearance: none; border: 1px solid transparent; background: none; width: 40px; height: 40px; border-radius: 50%; font-size: var(--fs-heading); cursor: pointer; }
.lp-pick-e.is-mine { background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); }

/* Tonight's Who's watching, option A (owner, 2026-11-02, mockups/tonight-whos-watching.png; rule 637):
   the five friends you watch with most as photo chips with their match, a dashed + Add opening a
   searchable drawer, and "You + N" with their faces beside the label. */
.tn-eyebrow-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.tn-who-sum { display: inline-flex; align-items: center; gap: 6px; font: var(--t-caption); letter-spacing: 0; text-transform: none; color: var(--ink); }
.tn-who-stack { display: inline-flex; }
.tn-who-stack > span + span { margin-left: -8px; }
.tn-who-stack .tn-face { width: 22px; height: 22px; border: 2px solid var(--bg); font-size: var(--fs-label); }
.tn-face { display: inline-grid; place-items: center; border-radius: var(--radius-av); object-fit: cover; background: var(--panel-2); color: var(--faint); font-style: normal; font-weight: 600; }
.tn-who2 { display: flex; gap: 12px; margin-top: 12px; overflow-x: auto; scrollbar-width: none; padding: 2px; }
.tn-who2::-webkit-scrollbar { display: none; }
.tn-who2-chip { flex: none; width: 60px; appearance: none; border: 0; background: none; padding: 0; display: flex; flex-direction: column; align-items: center; gap: 4px; color: var(--ink); cursor: pointer; font: inherit; }
.tn-who2-face { position: relative; width: 58px; height: 58px; display: grid; place-items: center; border-radius: var(--radius-av); border: 2px solid transparent; }
.tn-who2-face .tn-face { width: 52px; height: 52px; font-size: var(--fs-card); }
.tn-who2-chip.on .tn-who2-face { border-color: var(--select); }
.tn-who2-ck { position: absolute; right: -2px; bottom: -2px; width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; background: var(--select); color: var(--bg); border: 2px solid var(--bg); }
.tn-who2-n { font: var(--t-caption); max-width: 60px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tn-who2-chip.on .tn-who2-n { color: var(--ink); font-weight: 600; }
.tn-who2-m { font-size: var(--fs-label); color: var(--muted); }
.tn-who2-add .tn-who2-face { width: 52px; height: 52px; margin: 3px; border: 1px dashed var(--line-2); color: var(--muted); }
.tn-who2-add .tn-who2-n { color: var(--muted); }
.tn-who2-note { margin: 8px 0 0; font: var(--t-caption); color: var(--faint); }
.tn-who2-search { width: 100%; height: 44px; padding: 0 16px; border-radius: 12px; border: 1px solid var(--line-2); background: var(--panel-2); color: var(--ink); font: var(--t-body, 400 var(--fs-ui)/1.3 var(--sans)); margin-bottom: 8px; }
.tn-who2-list .tn-face { width: 40px; height: 40px; flex: none; }
.tn-who2-list .fp-pick-name small { display: block; font: var(--t-caption); color: var(--muted); }

/* The Film DNA drawer, Drawer C (rule 642, mockups/film-panels.png): meta line, receipts, More films (no scale, rule 840). */
.dna9-sheet .dna9-detail-name { margin-top: 0; font: 600 var(--fs-heading)/1.1 var(--serif); padding-right: 48px; }
.dna9-detail-meta { margin-top: var(--sp-4); font: 400 var(--fs-meta)/1.3 var(--sans); color: var(--muted); }
.dna9-cap { font: 600 var(--fs-label)/1 var(--sans); letter-spacing: .12em; text-transform: uppercase; color: var(--faint); }
.dna9-sheet .dna9-detail-hint { margin-top: var(--sp-16); font: 400 var(--fs-read)/1.45 var(--read); }
.dna9-receipts { margin-top: var(--sp-24); }
.dna9-chips { display: flex; flex-wrap: wrap; gap: var(--sp-8); margin-top: var(--sp-8); }
.dna9-more-row { display: flex; gap: var(--sp-8); overflow-x: auto; margin-top: var(--sp-8); scrollbar-width: none; }
.dna9-more-row .dna-film { flex: 0 0 84px; }
.dna9-sheet .dna9-detail-nav { margin-top: var(--sp-24); }
.dna9-sheet .dna-detail-step { font: 600 var(--fs-meta)/1 var(--sans); color: var(--muted); width: auto; padding: 0; background: none; border: 0; }
/* Previous / next strand (rule 843): one line each with the line chevron inline, each side up to half
   the width, the name cut with an ellipsis before it would ever wrap; 44 tall to tap. */
.dna9-sheet .dna9-step { display: inline-flex; align-items: center; justify-content: flex-start; flex: 0 1 auto; gap: 4px; height: auto; min-height: 44px; max-width: 50%; min-width: 0; border-radius: 0; white-space: nowrap; }
.dna9-sheet .dna9-step > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.dna9-sheet .dna9-step > svg { flex: none; }
.dna9-sheet .dna9-step-next { justify-content: flex-end; }

/* Empty states, one recipe (rule 638, mockups/empty-states.png option A): art, Heading 22, one 15px line,
   one cream Standard 44 button; .empty-panel is the section-level dashed panel with a Compact 34 button. */
.empty-state { display: flex; flex-direction: column; align-items: center; text-align: center; padding: var(--sp-32) var(--sp-24); }
.empty-art { display: flex; justify-content: center; }
.empty-title { margin-top: var(--sp-24); font: 600 var(--fs-heading)/1.1 var(--serif); color: var(--ink); }
.empty-line { margin: var(--sp-8) 0 0; max-width: 32ch; font: 400 var(--fs-ui)/1.4 var(--sans); color: var(--muted); }
.empty-btn { margin-top: var(--sp-24); display: inline-flex; align-items: center; justify-content: center; gap: 6px; border-radius: 999px; min-height: var(--btn-h); padding: 0 var(--sp-24); }
.empty-quiet { margin-top: var(--sp-12); appearance: none; background: none; border: 0; padding: 4px; font: 600 var(--fs-meta)/1 var(--sans); color: var(--accent-2); cursor: pointer; }
.empty-note { margin: var(--sp-12) 0 0; font: 400 var(--fs-meta)/1.4 var(--sans); color: var(--muted); }
.empty-posters { position: relative; width: 140px; height: 90px; }
.empty-poster { position: absolute; top: 4px; left: 42px; width: 56px; aspect-ratio: 2 / 3; border-radius: var(--radius-poster); overflow: hidden; background: var(--panel-2); border: 1px solid var(--line-2); }
.empty-poster img { width: 100%; height: 100%; object-fit: cover; display: block; }
.empty-poster:nth-child(1) { transform: translateX(-30px) rotate(-8deg); }
.empty-poster:nth-child(2) { z-index: 1; top: 0; }
.empty-poster:nth-child(3) { transform: translateX(30px) rotate(8deg); }
.empty-faces { display: flex; }
.empty-faces span { width: 36px; height: 36px; margin-left: -8px; border-radius: var(--radius-av); display: grid; place-items: center; background: var(--panel-2); color: var(--muted); font: 600 var(--fs-ui)/1 var(--sans); border: 2px solid var(--bg); }
.empty-faces span:first-child { margin-left: 0; }
.empty-panel { padding: var(--sp-24); border: 1px dashed var(--line-2); border-radius: var(--radius-field); }
.empty-panel .empty-title { margin-top: var(--sp-16); font-size: var(--fs-card); }
.empty-panel .empty-line { margin-top: var(--sp-4); font-size: var(--fs-meta); }
.empty-panel .empty-btn { margin-top: var(--sp-16); min-height: var(--btn-h-sm); padding: 0 var(--sp-16); font-size: var(--fs-meta); }
.empty-panel .empty-poster:not(:nth-child(2)) { opacity: .6; }
.empty-posters-one { width: 44px; height: 66px; }
.empty-posters-one .empty-poster, .empty-panel .empty-posters-one .empty-poster { position: static; display: block; width: 44px; height: 66px; transform: none; opacity: 1; }

/* Settings and the menu as grouped panels with line icons (rule 639, mockups/film-panels.png Settings A). */
.pm-group { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius-field); padding: 0 var(--sp-16); overflow: hidden; }
.pm-group + .pm-group, .pm-group-gap { margin-top: var(--sp-24); }
.pm-group .pm-item { gap: var(--sp-12); min-height: var(--row-h); padding: 0; border-radius: 0; border-bottom: 0; }
/* Hairlines between the panel's rows, and between a row and what folds open under it. */
.pm-group > * + * { border-top: 1px solid var(--line); }
.pm-group .pm-item:hover { background: none; color: var(--ink); }
/* The trailing chevron, not a row's only icon (Delete account's trash sat on the right). */
.pm-group .pm-item .pm-ico:last-child:not(:first-child) { margin-left: auto; color: var(--faint); }
.pm-group .pm-item, .pm-group .pm-pref { font-weight: 400; }
.pm-ico { flex: none; }
.pm-card { display: flex; align-items: center; gap: var(--sp-12); width: 100%; margin-bottom: var(--sp-24); padding: var(--sp-16); text-align: left; font: inherit; color: var(--ink); cursor: pointer;
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius-field); }
.pm-card .pm-avatar { width: 44px; height: 44px; border-radius: var(--radius-av); }
.pm-card-id { display: flex; flex-direction: column; gap: 2px; min-width: 0; flex: 1; }
.pm-card .pm-name { font: 600 var(--fs-card)/1.2 var(--serif); }
.pm-card .pm-handle { font-size: var(--fs-meta); color: var(--muted); }
.pm-card .pm-ico { color: var(--faint); }
.pm-signout-pill { width: 100%; margin-top: var(--sp-24); min-height: var(--btn-h); border-radius: 999px; }
/* The rest of Settings in the same panels (rule 672; rule 639 left these unboxed): Recommendation
   preferences, the Letterboxd sync note and how-to, and the delete confirmation. Rows are 52 with a
   line icon, the value in meta and a chevron; what opens under a row stays inside the panel. */
.pm-group .pm-pref { gap: var(--sp-12); min-height: var(--row-h); padding: 0; border-bottom: 0; font-size: var(--fs-ui); color: var(--ink); }
.pm-group .pm-pref > span:first-of-type { flex: 1; min-width: 0; }
.pm-group .pm-pref .pm-avoid-count { max-width: 45%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--faint); }
/* Settings' Film goal row (rule 1105; FilmGoal.tsx GoalSettingsRow): the value then a faint chevron, as the Account rows. */
.pm-group .pm-goal-row > .pm-ico:last-child { color: var(--faint); }
.pm-group .pm-sec-head { padding-top: 0; align-items: center; }
.pm-group .pm-chev { color: var(--faint); transition: transform var(--dur) var(--ease); }
.pm-group .pm-chev.is-open, .pm-group details[open] > summary .pm-chev { transform: rotate(180deg); }
.pm-group .pm-avoid { padding: var(--sp-12) 0; border-bottom: 0; }
.pm-group .pm-howto-wrap { margin: 0; }
.pm-group .pm-howto-sum { padding: 0; color: var(--ink); font-size: var(--fs-ui); }
.pm-group .pm-howto-sum::after { content: none; }
.pm-group .pm-howto-sum > span { flex: 1; min-width: 0; }
/* A switch row inside a grouped panel (Settings, Notifications: Release reminders, rule 890). */
.pm-group .pm-toggle-row { min-height: var(--row-h); margin: 0; padding: var(--sp-12) 0; }
.pm-group .pm-sync-note, .pm-group .pm-howto { margin: 0 0 var(--sp-12) calc(18px + var(--sp-12)); }
.pm-group > .pm-sync-note { margin: 0; padding: var(--sp-12) 0; }
.pm-group .pm-howto-note { margin-top: 0; }
.pm-settings > .pm-group-gap { margin-top: var(--sp-32); }
.pm-settings .pm-group .pm-delete { margin-top: 0; }
.pm-delete-confirm { display: flex; flex-direction: column; gap: var(--sp-12); padding: var(--sp-16); }
.pm-group.pm-delete-confirm > * + * { border-top: 0; }
.pm-delete-q { margin: 0; font: 400 var(--fs-read)/1.5 var(--read); color: var(--ink); }
.pm-delete-confirm .btn.pm-danger { color: var(--danger); border-color: rgba(232, 115, 127, .6); background: none; }
.pm-delete-confirm .btn.pm-danger:disabled { opacity: .4; }

/* Swipe tabs (rule 640, mockups/film-panels.png Swipe tabs A): one 2px blue underline, the label's width, following the swipe. */
.id-tabbar.has-ind { position: relative; }
.id-tabbar.has-ind .id-tab.on::after { display: none; }
.id-tab-ind { position: absolute; left: 0; bottom: 0; height: 2px; border-radius: 2px; background: var(--accent); pointer-events: none;
  transition: transform .22s var(--ease), width .22s var(--ease); }
.id-tab-ind.dragging { transition: none; }
.pv2 > .id-tabbar.has-ind .id-tab-ind { bottom: -1px; }
/* The group's and the film's tabs swipe too (rule 653): the film's panel tabs trade their border underline for the same line. */
.fd-infotabs.has-ind { position: relative; }
.fd-infotabs.has-ind .fd-infotab.on { border-bottom-color: transparent; }
/* The discussion's Friends / Everyone swipe the same way (rule 1094): the one line follows the finger. */
.fdisc-tabs.has-ind { position: relative; }
.fdisc-tabs.has-ind .fdisc-tab.on { border-bottom-color: transparent; }
/* Picks' tags swipe the same way (rule 812): the one line follows the finger along the scrolling row, and the feed moves with it, the next tab's feed sliding in (SwipePane's motion). */
.picks .pk-tags.has-ind { position: relative; }
.picks .pk-tags.has-ind .match-tag.on:not(.pk-tonight)::after { display: none; }
/* The controlled swipe (rule 925, owner 2026-11-06): useTabSwipe moves the feed and the next one in beside
   it on one JS spring, so no CSS transition or animation may run on the track's transform, and a sideways
   overscroll never reaches the browser's back or forward. */
.pk-track { transition: none; overscroll-behavior-x: none; }
.dna9-steps { width: 100%; justify-content: space-between; }

/* Inbox (rule 641, mockups/inbox.png): a blue unread dot, invites and follows acting inline under the line. */
.act-row { flex-wrap: wrap; }
.act-row.unread { background: none; }
.act-row.unread::before { display: none; }
/* The dot sits at the vertical centre of the whole row, every kind (owner, 2026-11-06, rule 1244); the row keeps
   its right edge clear of it so a button or thumb never runs under it. */
.act-row { padding-right: var(--sp-24); }
.act-dot { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); width: 8px; height: 8px; border-radius: 50%; background: var(--accent-2); }
.act-inline { flex: 1 0 100%; display: flex; gap: var(--sp-8); padding-left: 54px; }
.act-pill { border-radius: 999px; padding: 0 var(--sp-16); display: inline-flex; align-items: center; text-decoration: none; }
.act-following { display: inline-flex; align-items: center; gap: 6px; border-radius: 999px; color: var(--accent-2); background: var(--accent-soft); border-color: var(--accent); cursor: default; }

/* ── Movie night v2 (owner-approved mockups/movie-night-v2.png; rules 643, 644) ────────────── */
/* The step rail, option A: four 4pt bars with their names, above every step's header. */
.mn-rail { list-style: none; margin: 0 0 var(--sp-12); padding: 0; display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--sp-4); }
.mn-rail li { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.mn-rail i { display: block; height: 4px; border-radius: 2px; background: var(--line-2); }
.mn-rail span { font: 600 var(--fs-label)/1.2 var(--sans); color: var(--faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mn-rail li.done i { background: var(--accent); }
.mn-rail li.done span { color: var(--accent-2); }
.mn-rail li.now i { background: var(--cream); }
.mn-rail li.now span { color: var(--ink); }
html.mn-voting .mn-rail { margin-top: 0; }
/* The vote's header: Back, the title, the chat with its unread count. */
.mnv-row .mnv-h { flex: 1; min-width: 0; }
.mnv-chat { appearance: none; position: relative; flex: none; width: 36px; height: 36px; border-radius: 50%; border: 1px solid var(--line-2); background: none; color: var(--ink); display: grid; place-items: center; cursor: pointer; }
.mnv-chat svg { width: 18px; height: 18px; }
.mnv-chat-n { position: absolute; top: -4px; right: -4px; min-width: 18px; height: 18px; padding: 0 5px; border-radius: var(--btn-r); background: var(--accent); color: #fff; font: 700 var(--fs-label)/18px var(--sans); text-align: center; }
.mnv-sub-mine { color: var(--ink); font-weight: 600; }
.mnv-tools { display: flex; align-items: center; justify-content: flex-end; gap: var(--sp-8); margin-top: var(--sp-8); }
.mnv-face img, .mnv-face > span { border-radius: var(--radius-av) !important; }
.mnr-face, .mnr-faces img.mnr-face { border-radius: var(--radius-av) !important; }
/* After you vote: where the room stands, and Change vote. */
.mnc-status { display: flex; align-items: center; justify-content: space-between; gap: var(--sp-12); margin-top: var(--sp-12); padding: var(--sp-12) var(--sp-16); border: 1px solid var(--line-2); border-radius: var(--radius-field); font-size: var(--fs-meta); color: var(--ink); }
.mnc-change { flex: none; color: var(--accent-2); font-weight: 600; font-size: var(--fs-meta); }
/* One card per film. */
.mnc { display: flex; flex-direction: column; gap: var(--sp-12); margin-top: var(--sp-16); }
.mnc-card { display: flex; gap: var(--sp-12); padding: var(--sp-12); border-radius: var(--radius-field); background: var(--panel); border: 1px solid var(--line-2); }
.mnc-card.mine { border-color: var(--accent-2); box-shadow: inset 0 0 0 1px var(--accent-2); }
.mnc-po { flex: none; width: 64px; height: 96px; padding: 0; border: 0; border-radius: var(--radius-poster); overflow: hidden; background: var(--panel-2); cursor: pointer; }
.mnc-po img { width: 100%; height: 100%; object-fit: cover; display: block; }
.mnc-b { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.mnc-top { display: flex; align-items: baseline; gap: var(--sp-8); }
.mnc-t { flex: 1; min-width: 0; font: 500 var(--fs-card)/1.15 var(--serif); color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mnc-pc { flex: none; font: 500 var(--fs-heading)/1 var(--serif); color: var(--accent-2); } .mnc-pc small { font-size: var(--fs-meta); }
.mnc-sub { margin-top: 2px; font-size: var(--fs-label); color: var(--muted); }
.mnc-chips { display: flex; flex-wrap: wrap; gap: var(--sp-8); margin-top: var(--sp-8); }
.mnc-chip { cursor: default; }
/* Whose watchlist it is on (rule 880): one quiet line, 16px faces, blue when it is on yours. */
.mnc-saved { display: flex; align-items: center; gap: 6px; margin-top: var(--sp-4); font-size: var(--fs-label); color: var(--muted); min-width: 0; }
.mnc-saved.mine { color: var(--accent-2); }
.mnc-saved .mnr-faces > * + * { margin-left: -4px; }
.mnc-saved .mnr-face, .mnc-saved .mnr-faces img.mnr-face { width: 16px; height: 16px; border-width: 1px; }
.mnc-foot, .mnc-tally { display: flex; align-items: center; gap: var(--sp-8); margin-top: auto; padding-top: var(--sp-8); }
.mnc-who { flex: 1; display: flex; align-items: center; gap: 6px; font-size: var(--fs-label); color: var(--muted); }
.mnc-vote { flex: none; background: var(--cream); color: var(--cream-ink); border-color: var(--cream); }
.mnc-bar { flex: 1; height: 4px; border-radius: 2px; background: var(--line-2); overflow: hidden; }
.mnc-bar i { display: block; height: 100%; background: var(--accent); border-radius: 2px; transition: width .3s ease; }
.mnc-tally b { font-size: var(--fs-meta); color: var(--ink); min-width: 1ch; text-align: right; }
.mnc-suggest { appearance: none; display: flex; align-items: center; gap: var(--sp-12); width: 100%; min-height: 56px; padding: 0 var(--sp-16); border-radius: var(--radius-field); border: 1px dashed var(--line-2); background: none; color: var(--ink); font: inherit; cursor: pointer; text-align: left; }
.mnc-plus { width: 28px; height: 28px; border-radius: 50%; border: 1px solid var(--line-2); display: grid; place-items: center; flex: none; }
.mnc-plus svg { width: 14px; height: 14px; }
.mnc-suggest-t { flex: 1; font-size: var(--fs-ui); font-weight: 600; }
.mnc-suggest small { font-size: var(--fs-label); color: var(--faint); }
/* The Suggest a film drawer. */
.mns { display: flex; flex-direction: column; gap: var(--sp-12); }
.mns-sub { margin: 0; }
.mns-search { display: flex; align-items: center; gap: var(--sp-8); height: 44px; padding: 0 var(--sp-12); border: 1px solid var(--line-2); border-radius: var(--radius-field); background: var(--panel); }
.mns-search svg { width: 16px; height: 16px; color: var(--muted); flex: none; }
.mns-search input { flex: 1; min-width: 0; border: 0; background: none; color: var(--ink); font: inherit; font-size: var(--fs-ui); outline: none; }
.mns-list { display: flex; flex-direction: column; }
.mns-row { appearance: none; display: flex; align-items: center; gap: var(--sp-12); padding: var(--sp-8) 0; border: 0; border-bottom: 1px solid var(--line); background: none; color: var(--ink); font: inherit; text-align: left; cursor: pointer; }
.mns-row:disabled { opacity: .55; cursor: default; }
.mns-po { width: 40px; height: 60px; border-radius: var(--radius-poster); object-fit: cover; background: var(--panel-2); flex: none; }
.mns-tx { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.mns-tx b { font-size: var(--fs-ui); font-weight: 600; }
.mns-tx small { font-size: var(--fs-label); color: var(--muted); }
.mns-tx em { font-style: normal; font-size: var(--fs-label); color: var(--muted); } .mns-tx em.mns-pc { color: var(--accent-2); font-weight: 600; }
.mns-ck { width: 32px; height: 32px; border-radius: 50%; border: 1px solid var(--line-2); display: grid; place-items: center; flex: none; color: var(--muted); }
.mns-ck svg { width: 14px; height: 14px; }
.mns-ck.on { border-color: var(--select); color: var(--bg); background: var(--select); }
.mns-covers { display: flex; flex-wrap: wrap; align-items: center; gap: var(--sp-8); }
.mns-covers-k { font: 700 var(--fs-label)/1 var(--sans); letter-spacing: .14em; text-transform: uppercase; color: var(--faint); }
.mns-add { width: 100%; justify-content: center; background: var(--cream); color: var(--cream-ink); border-color: var(--cream); }
.mns-note { text-align: center; font-size: var(--fs-label); color: var(--faint); }
.cdock-lead img, .cdock-lead > span { border-radius: var(--radius-av) !important; }
.mnr-chat-title { display: flex; flex-direction: column; gap: var(--sp-4); }
.mnr-chat-title b { font: 500 var(--fs-heading)/1.1 var(--serif); }
.mnr-chat-title small { font-size: var(--fs-meta); color: var(--muted); font-weight: 400; }
.cdock-lead:has(img), .cdock-lead:has(> span) { border-radius: var(--radius-av); }

/* ── Film page v2 (owner-approved mockups/film-page-v2.png; rule 645) ─────────────────────── */
.fd-ratings-head { display: flex; align-items: baseline; justify-content: space-between; gap: var(--sp-12); }
.fd-ratings-head .fa-lb-rating { margin-left: auto; font-size: var(--fs-label); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.fa-watches-inline { margin-left: auto; font-size: var(--fs-label); color: var(--muted); white-space: nowrap; }
.fd-matchrow-rated .fd-matchrow-u { font-size: var(--fs-ui); } /* the ★ at 15, as the % (rule 1062) */
.fd-wt-panel { margin-top: var(--sp-8); padding: 0 var(--sp-16); background: var(--panel); border: 1px solid var(--line-2); border-radius: var(--radius-field); }
.fd-wt-panel .fd-wt-row { min-height: 52px; padding: 0; }
.fd-ratings-head .fa-pop { display: inline-flex; align-items: center; gap: var(--sp-4); }

/* ── Group page v2 (owner-approved mockups/group-page-v2.png; rule 646) ───────────────────── */
.gnext { display: flex; align-items: center; gap: var(--sp-12); margin-top: var(--sp-16); padding: var(--sp-12); background: var(--panel); border: 1px solid var(--line-2); border-radius: var(--radius-field); }
.gnext-po { flex: none; width: 44px; height: 66px; padding: 0; border: 0; border-radius: var(--radius-poster); overflow: hidden; background: var(--panel-2); cursor: pointer; }
.gnext-po img { width: 100%; height: 100%; object-fit: cover; display: block; }
.gnext-b { flex: 1; min-width: 0; }
.gnext-k { font: 700 var(--fs-label)/1.2 var(--sans); letter-spacing: .14em; text-transform: uppercase; color: var(--accent-2); }
.gnext-t { margin-top: 2px; font: 500 var(--fs-card)/1.15 var(--serif); color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gnext-m { font-size: var(--fs-label); color: var(--muted); } .gnext-m b { color: var(--accent-2); }
.gnext-go { flex: none; background: var(--cream); color: var(--cream-ink); border-color: var(--cream); }
