.bl-acts { display: flex; gap: var(--sp-8); margin-top: var(--sp-16); }
.btn.bl-cta { flex: 1; display: inline-flex; align-items: center; justify-content: center; gap: 8px; background: var(--cream); color: var(--cream-ink); min-height: var(--btn-h); }
.btn.bl-bell { flex: 0 0 var(--btn-h); width: var(--btn-h); padding: 0; display: inline-flex; align-items: center; justify-content: center; }
