.bl-po { flex: 0 0 62px; width: 62px; height: 93px; border-radius: var(--radius-poster); overflow: hidden; background: var(--panel-2); display: inline-flex; align-items: center; justify-content: center; }
.bl-po img { width: 100%; height: 100%; object-fit: cover; }
.bl-po i { font: var(--t-card); color: var(--faint); font-style: normal; }
.bl-po.is-lead { box-shadow: var(--shadow-offset); }
.bl-po-sm { flex-basis: 40px; width: 40px; height: 60px; }
.bl-pk-m { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.bl-pk-t { font: var(--t-card); color: var(--ink); }
.bl-pk-t em { font: var(--t-caption); color: var(--faint); font-style: normal; }
.bl-sc { font: 600 var(--fs-meta)/18px var(--sans); color: var(--muted); font-variant-numeric: tabular-nums; }
.bl-sc-you { color: var(--accent-2); }
.bl-sc-row { display: flex; gap: 8px; flex-wrap: wrap; }
.bl-sc-cell { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; }
