.bl-mrow-m b { font: var(--t-callout); }
.bl-mrow-m span { font: var(--t-caption); color: var(--muted); }
.bl-switch { flex: 0 0 44px; height: 26px; border-radius: 13px; background: var(--line-2); position: relative; }
.bl-switch i { position: absolute; top: 3px; left: 3px; width: 20px; height: 20px; border-radius: 50%; background: var(--ink); transition: left var(--dur) var(--ease); }
