.bl-switch.on i { left: 21px; }
.btn.bl-leave { display: inline-flex; align-items: center; justify-content: center; gap: 8px; margin-top: var(--sp-16); }
.btn.bl-wide { width: 100%; display: inline-flex; align-items: center; justify-content: center; gap: 8px; margin-top: var(--sp-12); }
.bl-cap-row { display: flex; align-items: center; gap: var(--sp-12); padding: var(--sp-12) 0; border-top: 1px solid var(--line); }
