.bl-cap-m { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.bl-cap-m b { font: var(--t-callout); color: var(--ink); }
.bl-cap-m span { font: var(--t-caption); color: var(--faint); }
.bl-inv-pk { display: flex; align-items: center; gap: var(--sp-12); padding: 8px 0; border-top: 1px solid var(--line); }
