.bl-cards { display: flex; gap: var(--sp-8); overflow-x: auto; padding-bottom: 4px; scrollbar-width: none; }
.bl-card { flex: 0 0 156px; display: flex; flex-direction: column; gap: 6px; padding: var(--sp-12); border: 1px solid var(--line); border-radius: var(--radius-field); background: var(--panel);
  color: inherit; text-decoration: none; }
