.rpt { max-width: 560px; padding-top: 24px; padding-bottom: 48px; }
.rpt-t { font: 500 var(--fs-title)/1.1 var(--serif); color: var(--ink); margin: 16px 0 0; }
.rpt-s { font: 400 var(--fs-meta)/1.4 var(--sans); color: var(--faint); margin: 4px 0 0; }
.rpt-note { font: 400 var(--fs-meta)/1.4 var(--sans); color: var(--muted); margin: 12px 0 0; }
.rpt-seg { display: flex; height: 36px; margin-top: 14px; border: 1px solid var(--line-2); border-radius: 999px; overflow: hidden; }
.rpt-seg button { flex: 1; border: 0; background: none; color: var(--muted); font: 600 var(--fs-meta)/1 var(--sans); cursor: pointer; }
.rpt-seg button.on { background: var(--cream); color: var(--cream-ink); }
.rpt-empty { font: 400 var(--fs-ui)/1.4 var(--sans); color: var(--faint); margin-top: 24px; }
.rpt-row { border-top: 1px solid var(--line); padding: 14px 0; }
.rpt-row:first-of-type { margin-top: 12px; }
.rpt-h { display: flex; justify-content: space-between; gap: 12px; font: 400 var(--fs-label)/1.4 var(--sans); color: var(--faint); }
.rpt-h a { color: inherit; }
.rpt-h a b { color: var(--ink); font-weight: 600; }
.rpt-h > b { color: var(--danger); font-weight: 600; white-space: nowrap; }
.rpt-q { font: 400 var(--fs-ui)/1.4 var(--sans); color: var(--ink); margin-top: 6px; overflow-wrap: anywhere; }
.rpt-f { font: 400 var(--fs-label)/1.4 var(--sans); color: var(--faint); margin-top: 4px; }
.rpt-a { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
.rpt-a button { height: 32px; padding: 0 14px; border-radius: 999px; border: 1px solid var(--line-2); background: none; color: var(--ink); font: 600 var(--fs-meta)/1 var(--sans); cursor: pointer; }
.rpt-a button.dg { color: var(--danger); }
.rpt-a button:disabled { opacity: .45; cursor: default; }
/* The guess check and the take step's chips (owner-approved 2026-11-04, mockups/journeys/rating-flow-v5;
   rule 1069): one line under the stars just given, grey "We guessed 91% · " then the verdict, blue
   when we called it, cream when we did not (red never). Chips under the headline, the note, then the
   caps "Your take" label straight above the box. No section lines. */
.guess-line { margin: 14px 0 0; font-size: var(--fs-meta); font-weight: 500; line-height: 1.35; }
.guess-line.is-center { text-align: center; }
.guess-g { color: var(--muted); }
.guess-ok { color: var(--accent-2); font-style: normal; }
.guess-mu { color: var(--ink); font-style: normal; }
.tk-film-guess { margin: 6px 0 0; font-size: var(--fs-meta); text-align: left; }
.fa-guess { margin: 8px 0 0; font-size: var(--fs-meta); }
.tk-film { border-bottom: 0; padding-bottom: 0; }
.tk-step .tk-hl { margin-bottom: 0; }
.tk-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
.tk-chips :is(.tk-more, .is-gen):not(.is-on) { color: var(--muted); }
.tk-more { gap: 2px; }
.tk-priv { margin: 6px 0 0; font-size: var(--fs-meta); color: var(--faint); text-align: left; }
.tk-label { margin: 16px 0 6px; font-family: var(--label); font-size: var(--fs-label); font-weight: 600; letter-spacing: 1.4px; text-transform: uppercase; color: var(--faint); text-align: left; }
.tk-ta::placeholder { font-style: italic; }

/* "Watched with" (owner-approved 2026-11-04, mockups/journeys/beli-7-watched-with; WatchedWith.tsx):
   the optional row on the When step, and the film page's Your watches. No lines between parts. */
.ww { margin-top: 16px; text-align: left; }
.ww-hd { margin: 0 0 10px; font-family: var(--serif); font-size: var(--fs-card); font-weight: 500; color: var(--ink); }
.ww-hd span { font-family: var(--sans); font-size: var(--fs-meta); font-weight: 400; color: var(--faint); margin-left: 4px; }
.ww-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.ww-chip { appearance: none; cursor: pointer; display: inline-flex; align-items: center; gap: 7px; padding: 4px 12px 4px 4px; min-height: 32px;
  border: 1px solid var(--line-2); border-radius: 999px; background: none; font: inherit; font-family: var(--label); font-size: var(--fs-meta); font-weight: 600; color: var(--ink); }
.ww-chip.on { border-color: var(--select-edge); background: var(--select-fill); box-shadow: var(--select-ring); }
.ww-chip.ww-more { padding-left: 12px; color: var(--ink); }
/* A person chip (rule 1172): the button inside carries the padding, so all of it toggles; chosen, the ×
   (ChipX) sits after the handle in its own 28px button, 4 from the edge. */
.ww-chip.ww-pchip { padding: 0; cursor: default; }
.ww-chip-b { appearance: none; display: inline-flex; align-items: center; gap: 7px; align-self: stretch; padding: 0 12px 0 4px; border: 0; border-radius: inherit;
  background: none; font: inherit; color: inherit; cursor: pointer; }
.ww-chip.on .ww-chip-b { padding-right: 0; }
.ww-chip.on > .chip-x { margin-right: 4px; }
.chip-x { appearance: none; flex: none; display: inline-grid; place-items: center; width: 28px; height: 28px; padding: 0; border: 0; border-radius: 50%;
  background: none; color: var(--muted); cursor: pointer; }
.chip-x svg { display: block; }
.chip-x:hover { color: var(--ink); }
.ww-face { flex: none; border-radius: var(--radius-av); object-fit: cover; display: inline-flex; align-items: center; justify-content: center; font-size: var(--fs-label); font-weight: 700; }
.ww-night { appearance: none; cursor: pointer; display: flex; align-items: center; gap: 8px; margin-top: 12px; padding: 4px 0; border: 0; background: none;
  font: inherit; font-size: var(--fs-meta); color: var(--muted); text-align: left; }
.ww-night svg { color: var(--muted); flex: none; }
.ww-search { margin: 0 0 10px; }
.ww-search-in { width: 100%; }
.ww-none { margin: 8px 0 0; font-size: var(--fs-meta); color: var(--muted); }
.ww .tk-foot { margin-top: 16px; }
.ww-d { width: 58px; flex: none; font-size: var(--fs-meta); font-weight: 600; color: var(--ink); line-height: 1.2; }
.ww-d small { display: block; font-size: var(--fs-label); font-weight: 400; color: var(--faint); }
.ww-together { display: flex; align-items: center; gap: 10px; margin-top: 8px; padding: 12px; border: 1px solid var(--line); border-radius: 12px;
  background: var(--panel); color: var(--ink); text-decoration: none; font-size: var(--fs-meta); }
.sp-m2 { display: block; color: var(--muted); }
/* Your <year> in film (YearReview.tsx; mockups/journeys/year-in-review-v1.png): the profile row and the card viewer. */
.yr-row { appearance: none; width: 100%; margin-top: 14px; display: flex; gap: 12px; align-items: center; text-align: left; cursor: pointer;
  border: 1px solid var(--line); border-radius: 14px; background: var(--panel); padding: 10px; color: var(--ink); font: inherit; }
.yr-row:hover { border-color: var(--line-2); }
.yr-thumb { width: 54px; height: 96px; border-radius: 6px; background: var(--bg); border-left: 3px solid var(--shadow); padding: 6px 4px; flex: none;
  display: flex; flex-direction: column; font-family: var(--serif); }
.yr-thumb b { font-size: var(--fs-card); font-weight: 600; }
.yr-thumb small { font: 600 var(--fs-label)/14px var(--sans); color: var(--faint); margin-top: 2px; }
.yr-row-t { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.yr-row-h { font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; }
.yr-row-m { font-size: var(--fs-meta); color: var(--muted); }
.yr-row-g { font-size: var(--fs-meta); font-weight: 600; color: var(--accent-2); }
.yr-chev { color: var(--faint); font-size: var(--fs-ui); }
.yr-set { margin-top: 6px; color: var(--accent-2); }
.yr-viewer .drawer-body { display: flex; flex-direction: column; align-items: center; }
.yr-stage { position: relative; width: 100%; max-width: 340px; }
.yr-track { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; overscroll-behavior-x: contain; }
.yr-track::-webkit-scrollbar { display: none; }
.yr-slide { flex: 0 0 100%; scroll-snap-align: center; display: flex; justify-content: center; }
.yr-card { width: 100%; aspect-ratio: 9 / 16; height: auto; border-radius: 12px; border: 1px solid var(--line); display: block; background: var(--bg); }
.yr-card-wait { background: linear-gradient(110deg, var(--panel) 30%, var(--panel-2) 50%, var(--panel) 70%) 0 0 / 300% 100%; animation: yrWait 1.4s linear infinite; }
@keyframes yrWait { to { background-position: -150% 0; } }
.yr-side { position: absolute; top: 0; bottom: 0; width: 28%; background: none; border: 0; cursor: pointer; }
.yr-prev { left: 0; } .yr-next { right: 0; }
.yr-dots { display: flex; gap: 5px; justify-content: center; margin-top: 12px; }
.yr-dots i { width: 6px; height: 6px; border-radius: 3px; background: var(--line-2); display: block; transition: width .2s; }
.yr-dots i.on { width: 16px; background: var(--ink); }
.yr-share-h { margin: 12px 0 0; font-size: var(--fs-meta); color: var(--muted); }
.yr-dest { display: flex; gap: 36px; justify-content: center; margin-top: 10px; }
.yr-dest button { appearance: none; background: none; border: 0; color: var(--muted); font: 500 var(--fs-label)/14px var(--sans); display: flex; flex-direction: column; align-items: center; gap: 5px; cursor: pointer; }
.yr-dest button:disabled { opacity: .5; cursor: default; }
.yr-c { width: 46px; height: 46px; border-radius: 50%; border: 1px solid var(--line-2); background: rgba(255,255,255,.04); display: flex; align-items: center; justify-content: center; color: var(--ink); font-size: var(--fs-card); }

/* The yearly film goal's chip (rule 1105; FilmGoal.tsx; mockups/journeys/profile-goal-v2.html option
   A): on the streak's row, 28 tall like the streak, icon first then the fact; ink and blue only. */
.gchip { appearance: none; box-sizing: border-box; display: inline-flex; align-items: center; gap: 7px; height: 28px; padding: 0 12px 0 8px; margin: 0;
  border-radius: 999px; border: 1px solid var(--line-2); background: rgba(255, 255, 255, .04); color: var(--ink);
  font: 600 var(--fs-ui)/1 var(--sans); white-space: nowrap; flex: none; cursor: pointer; }
button.gchip:hover { border-color: var(--faint); }
.gchip.is-other { cursor: default; }
.gchip-ring { width: 16px; height: 16px; flex: none; display: block; }
.gchip-prog { transform: rotate(-90deg); }
.gchip-t b { font-weight: 600; }
.gchip-t small { font: 500 var(--fs-ui)/1 var(--sans); color: var(--faint); }
.gchip.is-ask { background: transparent; color: var(--muted); font-weight: 500; padding-left: 9px; gap: 5px; }
.gchip-plus { width: 15px; height: 15px; flex: none; }
.gchip.is-met { border-color: rgba(91, 143, 196, .55); background: rgba(91, 143, 196, .10); }
/* The drawer: − / N / +, the four presets, Show on my profile, Set goal (cream), No goal this year. */
.gs-step { display: flex; align-items: center; justify-content: space-between; margin-top: 16px; }
.gs-pm { appearance: none; width: 48px; height: 48px; border-radius: 12px; border: 1px solid var(--line-2); background: rgba(255, 255, 255, .04); color: var(--ink);
  display: flex; align-items: center; justify-content: center; cursor: pointer; }
.gs-pm svg { width: 20px; height: 20px; }
.gs-pm:disabled { opacity: .4; cursor: default; }
.gs-num { text-align: center; }
.gs-num b { display: block; font: 500 var(--fs-display)/1 var(--serif); color: var(--ink); }
/* The number is a field you can type in (rule 1105): the same Bodoni 40, no box, a faint dotted
   underline so it reads as tappable, the caret on focus; no spinner arrows. */
.gs-num-in { display: block; margin: 0 auto; padding: 0 0 2px; min-width: 1ch; box-sizing: content-box; appearance: textfield; -moz-appearance: textfield;
  font: 500 var(--fs-display)/1 var(--serif); color: var(--ink); text-align: center; background: none; border: 0; border-radius: 0;
  border-bottom: 1px dashed var(--line-2); caret-color: var(--accent); outline: none; }
.gs-num-in:focus { border-bottom-color: var(--accent); }
.gs-num-in::-webkit-outer-spin-button, .gs-num-in::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
.gs-num span { font-size: var(--fs-meta); color: var(--faint); }
.gs-pre { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-top: 16px; }
.gs-pre button { appearance: none; height: 36px; border-radius: 8px; border: 1px solid var(--line-2); background: none; color: #C9C4B8; font: 600 var(--fs-card)/1 var(--serif); cursor: pointer; }
.gs-pre button.on { background: var(--select-fill); border-color: var(--select-edge); box-shadow: var(--select-ring); color: var(--ink); }
.goal-pub small { display: block; font-size: var(--fs-meta); color: var(--faint); margin-top: 2px; }
.goal-pub { display: flex; align-items: center; justify-content: space-between; margin-top: 16px; font-size: var(--fs-ui); font-weight: 500; }
.goal-err { margin: 10px 0 0; font-size: var(--fs-meta); color: var(--danger); }
.btn.goal-set { width: 100%; margin-top: 16px; min-height: var(--btn-h); background: var(--cream); color: var(--bg); border-radius: var(--radius-pill); }
.goal-none { display: flex; width: 100%; justify-content: center; margin-top: 6px; }
/* Recut (rule 1077; recut-mock.png, journeys/beli-5-sentence-search.png). Red only as the accent:
   the mic and the rule beside the quoted sentence. Chips are outlined, never filled. */
.recut-free { font-size: var(--fs-meta); color: var(--faint); }
/* The search's "Pitch this instead ›" (rule 1115, journeys/pitch-search-v1): one blue-washed row on
   top with Pitch's mark; the ordinary results follow it. */
.recut-search-row { margin-top: var(--sp-8); border: 1px solid rgba(91, 143, 196, .32); border-radius: var(--radius-card); background: rgba(91, 143, 196, .08); padding: 12px; }
.picker-poster.recut-search-mark { display: grid; place-items: center; color: var(--ink); background: var(--panel-2); } /* the mark in ink, as the iPhone (pitch-icon-v1) */
.recut-search-row .recut-search-a { color: var(--accent-2); font-weight: 600; }
.recut-search-row .picker-year { font-size: var(--fs-meta); line-height: 1.35; white-space: normal; }
.recut-box { position: relative; }
.recut-box textarea { width: 100%; min-height: 110px; padding: 14px 56px 14px 14px; border: 1px solid var(--line-2); border-radius: var(--radius-field); background: var(--panel-2); color: var(--ink); font: inherit; font-size: var(--fs-read); line-height: 1.4; resize: none; }
.recut-mic { position: absolute; right: 10px; bottom: 10px; width: 40px; height: 40px; border-radius: 50%; border: 0; background: var(--panel-raised); color: var(--ink); display: grid; place-items: center; cursor: pointer; }
.recut-mic.is-on { background: var(--red); box-shadow: 0 0 0 6px rgba(200, 35, 58, 0.22); }
.recut-go { width: 100%; margin-top: var(--sp-12); }
.recut-free-under { margin: 8px 0 0; text-align: center; }
/* Pitch: recents, chips that teach and a friend in the sentence (owner-approved 2026-11-05, journeys/pitch-recents-v1
   A + A, rule 1124). The @friend token: with a friend tagged, the textarea's words go transparent over a mirror that
   draws the same words (same font, padding, border width and wrapping) with "@Sam" as the soft blue face-and-name tag;
   the tag adds no width (box-shadow, not padding), so the caret stays on the words. */
.recut-field { position: relative; }
.recut-mirror { position: absolute; inset: 0; z-index: 0; padding: 14px 56px 14px 14px; border: 1px solid transparent; border-radius: var(--radius-field); background: var(--panel-2); color: var(--ink); font-size: var(--fs-read); line-height: 1.4; white-space: pre-wrap; overflow-wrap: break-word; overflow: hidden; pointer-events: none; }
.recut-field.has-tok textarea { position: relative; z-index: 1; display: block; background: transparent; color: transparent; caret-color: var(--ink); overflow-wrap: break-word; }
.recut-tok { color: var(--accent-2); background: rgba(91, 143, 196, .16); border-radius: 6px; box-shadow: 0 0 0 3px rgba(91, 143, 196, .16); }
.recut-tok-at { position: relative; color: transparent; }
.recut-tok-at .ww-face { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); }
.recut-at { color: var(--accent-2); }
.recut-pair { display: flex; align-items: center; gap: 8px; margin: 8px 0 0; font-size: var(--fs-meta); line-height: 1.4; color: var(--muted); }
.recut-pair b { color: var(--ink); font-weight: 600; }
/* Two to four friends (rule 1178): their faces overlapped, each ringed in the page's ground. */
.recut-pair-faces { display: inline-flex; flex: none; }
.recut-pair-faces .ww-face { box-shadow: 0 0 0 1.5px var(--bg); }
.recut-pair-faces .ww-face + .ww-face { margin-left: -6px; }
.recut-pk { margin-top: var(--sp-16); }
.recut-pk .recut-try, .recut-recents .recut-try { margin-top: 0; }
.recut-pk-row { display: flex; align-items: center; gap: 12px; width: 100%; min-height: 56px; padding: 0; border: 0; background: none; color: var(--ink); text-align: left; cursor: pointer; }
.recut-pk-row.is-first { width: calc(100% + 20px); margin: 0 -10px; padding: 0 10px; border-radius: 12px; background: rgba(91, 143, 196, .10); }
.recut-pk-t { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.recut-pk-n { font-size: var(--fs-ui); }
.recut-pk-n span { color: var(--faint); }
.recut-pk-s { font-size: var(--fs-meta); color: var(--muted); }
/* Rule 1182 (journeys/pitch-voice-friends-v1): friends from names. The words it would change, dotted in the box; one line
   under the box with their faces (a count for a name that fits several) and a cream ＋; "Which Jake?" a small popover. */
.recut-nm { border-bottom: 1.5px dotted var(--faint); }
.recut-names { position: relative; margin-top: 10px; }
.recut-names-b { display: flex; align-items: center; gap: 10px; width: 100%; min-height: 46px; padding: 6px 6px 6px 10px; border: 1px solid var(--line-2, var(--line)); border-radius: var(--radius-field); background: rgba(255, 255, 255, .03); color: var(--ink); font: inherit; font-size: var(--fs-ui); font-weight: 500; text-align: left; cursor: pointer; }
.recut-names-faces { display: inline-flex; flex: none; }
.recut-names-faces > * { box-shadow: 0 0 0 2px var(--bg); }
.recut-names-faces > * + * { margin-left: -6px; }
.recut-names-n { width: 26px; height: 26px; border-radius: var(--radius-av); background: var(--panel-2); color: var(--muted); display: inline-flex; align-items: center; justify-content: center; font-size: var(--fs-label); font-weight: 600; }
.recut-names-t { flex: 1; min-width: 0; }
.recut-names-t span { color: var(--faint); font-weight: 400; }
.recut-names-plus { flex: none; width: 34px; height: 34px; border-radius: 8px; background: var(--ink); color: var(--bg); display: inline-flex; align-items: center; justify-content: center; font-size: var(--fs-card); line-height: 1; }
.recut-names-plus.is-on { box-shadow: 0 0 0 2px var(--bg), 0 0 0 4px var(--select); }
.recut-which { position: absolute; z-index: 20; right: 0; top: calc(100% + 6px); width: min(340px, 100%); padding: 12px 14px 6px; border: 1px solid var(--line-2, var(--line)); border-radius: 12px; background: var(--panel); box-shadow: 0 18px 40px rgba(0, 0, 0, .6); }
.recut-which-h { margin: 0; font-family: var(--serif); font-size: var(--fs-card); font-weight: 600; color: var(--ink); }
.recut-which-s { margin: 2px 0 4px; font-size: var(--fs-meta); color: var(--faint); }
.recut-which-row { display: flex; align-items: center; gap: 12px; min-height: 50px; padding: 6px 8px; margin: 0 -8px; width: calc(100% + 16px); border: 0; border-radius: 8px; background: none; color: var(--ink); font: inherit; text-align: left; cursor: pointer; }
.recut-which-row:hover, .recut-which-row:focus-visible { background: rgba(255, 255, 255, .05); outline: none; }
.recut-which-n { font-size: var(--fs-ui); font-weight: 600; }
.recut-pk-ret { margin-left: auto; font-size: var(--fs-meta); font-weight: 500; color: var(--accent-2); }
.recut-recents { margin-top: var(--sp-16); }
.recut-recent { display: flex; align-items: center; height: 44px; }
.recut-recent-s { flex: 1; min-width: 0; display: flex; align-items: center; gap: 12px; height: 44px; padding: 0; border: 0; background: none; color: var(--ink); font-size: var(--fs-ui); text-align: left; cursor: pointer; }
.recut-recent-s svg { flex: none; color: var(--faint); }
.recut-recent-s span { min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.recut-recent-x { flex: none; width: 28px; height: 28px; margin-right: -6px; padding: 0; border: 0; background: none; color: var(--faint); font-size: var(--fs-card); line-height: 1; cursor: pointer; }
.recut-recents + .recut-try { margin-top: var(--sp-16); }
/* Pitch start page A (owner-approved 2026-11-06, journeys/pitch-ask-v1 A; rule 1226): the box, its lines and Action!
   in one panel; each section a Bodoni 22 heading 36 below the last, 12 above its content; Saved cuts and Previous
   takes each one rounded card (no hairlines, the clock at 55%, two lines, the × a 44 target); the ideas 44 tall. */
.recut-askcard { margin-top: 0; padding: 10px; border: 1px solid var(--line); border-radius: 16px; background: var(--panel); }
.recut-askcard .recut-box textarea { border-color: transparent; }
.recut-askcard .recut-go { margin-top: 10px; }
.recut-sec { margin: 36px 0 0; font-family: var(--serif); font-style: normal; font-weight: 600; font-size: var(--fs-heading); line-height: 1.2; color: var(--ink); }
.recut-more > .recut-saved, .recut-more > .recut-recents, .recut-more > .recut-saved + .recut-recents { margin-top: 0; }
.recut-more .recut-saved-h { margin-top: 36px; }
.recut-more .recut-saved-h .recut-sec { margin-top: 0; }
.recut-card { margin-top: var(--sp-12); padding: 4px 0; border-radius: 14px; background: var(--panel); }
.recut-card .recut-recent { height: auto; min-height: 44px; align-items: flex-start; padding: 10px 4px 10px 14px; }
.recut-card .recut-recent-s { height: auto; align-items: flex-start; line-height: 1.4; }
.recut-card .recut-recent-s svg { margin-top: 2px; opacity: .55; }
