.recut-pin-row::-webkit-scrollbar { display: none; }
.recut-pin-row .recut-chip { flex: none; height: var(--chip-h); padding-top: 0; padding-bottom: 0; white-space: nowrap; }
/* The wait: the slim bar (the sentence on one line, its bar grey), then the dim, grained screen. */
.recut-wait .recut-wait-q { margin: 0; padding-left: 12px; border-left-color: var(--line-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; animation: rc-fold .35s ease-out both; }
.recut-wait-screen { position: relative; margin: 14px calc(-1 * var(--rc-side)) -24px; min-height: min(560px, 64dvh); overflow: hidden; background: #0e0e10; animation: rc-fade .4s ease-out both; }
.recut-wait-screen::before { content: ""; position: absolute; left: -60px; right: -60px; top: -72px; height: 460px; background: radial-gradient(closest-side, rgba(239, 232, 218, .07), rgba(239, 232, 218, 0)); }
.recut-wait-grain { position: absolute; inset: -140px; opacity: .06; background: url(/grain.png) 0 0 / 128px 128px repeat; animation: rc-grain .5s steps(6) infinite; }
.recut-wait-c { position: relative; display: flex; flex-direction: column; align-items: center; padding: 96px 16px 32px; text-align: center; }
.recut-wait-cap { margin: 8px 0 0; color: var(--ink); opacity: .86; font-size: var(--fs-ui); line-height: 1.4; animation: rc-cap .35s ease-out both; }
/* Rule 1173: "Rolling…" under the fan, then the film line in Bodoni roman (muted, never italic); the 6s and 12s lines stay plain. */
.recut-wait-roll { margin: var(--sp-16) 0 0; font-family: var(--serif); font-weight: 600; font-size: var(--fs-heading); line-height: 1.15; color: var(--ink); }
.recut-wait-cap.is-film { font-family: var(--serif); font-weight: 500; font-size: var(--fs-card); line-height: 1.35; color: var(--muted); opacity: 1; }
.recut-wait-x { margin-top: 10px; font-size: var(--fs-meta); font-weight: 600; color: var(--accent-2); }
.recut-wait-chips { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; max-width: 340px; margin-top: var(--sp-16); }
.recut-wait-chips .recut-chip { min-height: 34px; padding-top: 0; padding-bottom: 0; animation: rc-chip .35s ease-out both; }
/* The answer develops: the backdrop out of the grain (1.1s), the veil lifting, the bar turning red, the read
   chips flying up (Recut.tsx), the top pick's row, then Steer it, Sorted for you and the rest. */
.recut-veil { position: absolute; left: calc(-1 * var(--rc-side)); right: calc(-1 * var(--rc-side)); top: -8px; bottom: -40px; z-index: 3; pointer-events: none;
  background: linear-gradient(rgba(14, 14, 16, .94), rgba(14, 14, 16, .94)), url(/grain.png) 0 0 / 128px 128px repeat; animation: rc-veil .9s .2s ease-out both; }
.recut-chips .recut-chip.has-flown { position: relative; z-index: 4; }
.recut-ans.is-dev .recut-bk-in { animation: rc-develop 1.1s cubic-bezier(.33, 0, .2, 1) both; }
.recut-ans.is-dev .recut-quote { animation: rc-red .4s .1s ease-out both; }
.recut-ans.is-dev .recut-understood, .recut-ans.is-dev .recut-chips .recut-chip:not(.has-flown) { animation: rc-rise .4s .25s ease-out both; }
.recut-ans.is-dev .recut-steer { animation: rc-rise .4s .7s ease-out both; }
.recut-ans.is-dev .recut-sorted { animation: rc-rise .4s .8s ease-out both; }
.recut-ans.is-dev .recut-list li { animation: rc-rise .42s ease-out both; animation-delay: calc(.9s + var(--i, 0) * 70ms); }
.recut-ans.is-dev .recut-list li:first-child { animation-delay: .45s; }
@keyframes rc-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes rc-fold { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
@keyframes rc-grain { from { background-position: 0 0; } to { background-position: 318px 582px; } }
@keyframes rc-cap { from { opacity: 0; transform: translateY(3px); } to { opacity: .86; transform: none; } }
@keyframes rc-chip { from { opacity: 0; transform: scale(.94); } to { opacity: 1; transform: none; } }
@keyframes rc-veil { from { opacity: 1; } to { opacity: 0; visibility: hidden; } }
@keyframes rc-develop { from { opacity: 0; filter: blur(8px); } to { opacity: 1; filter: blur(0); } }
@keyframes rc-red { from { border-left-color: var(--line-2); } to { border-left-color: var(--red); } }
@keyframes rc-rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
/* Reduce Motion: no fly-ins (Recut.tsx skips them), a still fan (MontageLoader breathes), still grain, a cross-fade. */
@media (prefers-reduced-motion: reduce) {
  .recut-wait-grain { animation: none; }
  .recut-wait .recut-wait-q, .recut-wait-cap, .recut-wait-chips .recut-chip { animation-name: rc-fade; }
  .recut-ans.is-dev .recut-bk-in, .recut-ans.is-dev .recut-understood, .recut-ans.is-dev .recut-chips .recut-chip:not(.has-flown),
  .recut-ans.is-dev .recut-steer, .recut-ans.is-dev .recut-sorted, .recut-ans.is-dev .recut-list li { animation-name: rc-fade; }
  .recut-pin { transform: none; }
  .recut-pg { animation-name: rc-fade; }
}

/* Invite bonuses (rule 1078; journeys/beli-8-invite-reward.png). A thank-you block in the invite
   sheet, never a gate; no section lines, one outlined panel. */
.invite-bonus { margin: 0 0 var(--sp-16); padding: var(--sp-12) var(--sp-16); border: 1px solid var(--line); border-radius: var(--radius-card); text-align: left; }
.invite-bonus-hd { display: flex; justify-content: space-between; align-items: baseline; }
.invite-bonus-k { font-family: var(--label); font-size: var(--fs-label); font-weight: 600; letter-spacing: 1.4px; text-transform: uppercase; color: var(--accent-2); }
.invite-bonus-nd { font-size: var(--fs-meta); color: var(--faint); }
.invite-bonus-p { margin: 8px 0 0; font-size: var(--fs-ui); color: var(--ink); }
.invite-bonus-slots { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: var(--sp-12); }
.invite-slot { display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 10px 4px; border: 1px dashed var(--line-2); border-radius: var(--radius-card); font-size: var(--fs-meta); color: var(--faint); }
.invite-slot.is-in { border-style: solid; border-color: var(--accent); color: var(--ink); }
.invite-slot.is-rating { color: var(--muted); }
.invite-slot-av { display: grid; place-items: center; width: 28px; height: 28px; border-radius: var(--radius-av); overflow: hidden; background: var(--panel-2); color: var(--ink); font-size: var(--fs-meta); }
.invite-slot-av img { width: 100%; height: 100%; object-fit: cover; }
.invite-slot-t { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.invite-bonus-note { margin: var(--sp-12) 0 0; font-size: var(--fs-meta); color: var(--muted); }
.invite-bonus-counts { margin: 6px 0 0; font-size: var(--fs-meta); color: var(--faint); }
.founding-badge { display: inline-flex; align-items: center; margin-left: 8px; padding: 1px 8px; border: 1px solid var(--line-2); border-radius: var(--radius-pill); font-family: var(--label); font-size: var(--fs-label); font-weight: 600; letter-spacing: 1px; text-transform: uppercase; color: var(--muted); }
.invite-bonus-p .founding-badge { margin-left: 0; }
.invite-open-door { margin: var(--sp-12) 0 0; font-size: var(--fs-meta); color: var(--muted); }
.invite-open-door span { color: var(--accent-2); }

/* The compact title bar (owner, 2026-11-04, rule 1095; CollapsedTitleBar.tsx, the iPhone's
   CollapsedTitleBar, rule 1030): pinned by a zero-height sticky anchor, so it takes no room and nothing
   moves when it fades in; solid page colour, the serif title between Back and the right edge, a
   hairline under it. It runs the page's full width (--ctb-bleed: the column's side padding). */
.ctb-anchor { position: sticky; top: 0; z-index: 8; height: 0; }
.ctb { --ctb-bleed: 16px; position: absolute; top: 0; left: calc(-1 * var(--ctb-bleed)); right: calc(-1 * var(--ctb-bleed)); height: 56px;
  display: flex; align-items: center; justify-content: center; padding: 0 64px; box-sizing: border-box;
  background: var(--bg); border-bottom: 1px solid var(--line);
  opacity: 0; transform: translateY(-6px); visibility: hidden; transition: opacity .2s var(--ease), transform .2s var(--ease), visibility 0s linear .2s; }
.ctb.on { opacity: 1; transform: none; visibility: visible; transition-delay: 0s; }
.ctb-back { position: absolute; left: var(--ctb-bleed); top: 50%; transform: translateY(-50%); display: flex; }
.ctb-back .backlink { margin: 0; }
.ctb-t { min-width: 0; font-family: var(--serif); font-size: var(--fs-card); font-weight: 500; color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
@media (prefers-reduced-motion: reduce) { .ctb { transform: none; transition: none; } }
/* A Browse page in its sheet: the bar bleeds by the sheet's 14 like the hero and the pill bar, and the
   pill bar sticks under it while it shows (a door's own page sits inside the margins). */
.browse > .ctb-anchor { margin-bottom: -12px; /* cancels .browse's column gap: the anchor takes no room */ }
.browse .ctb { --ctb-bleed: 14px; }
.bd-page .browse .ctb { --ctb-bleed: 0px; }
.browse.ctb-on .bp-bar { top: 56px; }
/* Lane, theme and person pages (window scroll, under the phone's auto-hiding top bar, which covers it
   while it is out): the bar clears the notch as the top bar does. */
.tp > .ctb-anchor .ctb { --ctb-bleed: var(--bx-bleed, 16px); height: calc(56px + env(safe-area-inset-top)); padding-top: env(safe-area-inset-top); }
.tp > .ctb-anchor .ctb-back { top: calc(50% + env(safe-area-inset-top) / 2); }


/* Rule 1097 (owner-approved mockups/journeys/film-page-v7, v6, v5): the film page's rating section and People you follow.
   The Prediction card under the stars: the serif % in blue, "Our read" small, the result line; the whole card opens Our read. */
.fd-pc { appearance: none; width: 100%; display: flex; align-items: center; gap: 13px; margin: 12px 0 0; padding: 11px 14px 11px 16px; border: 0;
  border-radius: 14px; background: #121821; color: var(--ink); font: inherit; text-align: left; cursor: pointer; }
.fd-pc-pct { flex: none; min-width: 56px; font: 500 var(--fs-title)/1 var(--serif); letter-spacing: -.5px; color: var(--accent-2); white-space: nowrap; font-variant-numeric: tabular-nums; }
.fd-pc-pct small { font-size: var(--fs-ui); margin-left: 1px; }
.fd-pc.is-soft .fd-pc-pct { opacity: .7; }
.fd-pc-t { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.fd-pc-k { font: 600 var(--fs-label)/1.2 var(--label); letter-spacing: .14em; text-transform: uppercase; color: var(--faint); }
.fd-pc-v { display: flex; align-items: center; gap: 6px; min-width: 0; font: 600 var(--fs-ui)/1.2 var(--sans); color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.fd-pc-v .hwd-mark { width: 16px; height: 16px; border: 0; background: rgba(143, 179, 217, .16); }
.fd-pc-v .hwd-mark:not(.on) { background: rgba(239, 232, 218, .1); color: var(--ink); }
.fd-pc-v .hwd-mark svg { width: 11px; height: 11px; stroke-width: 2.2; }
.fd-pc-sub { font-weight: 400; font-size: var(--fs-meta); color: var(--muted); }
.fd-pc-ask { color: var(--accent-2); }
.fd-pc-chev { flex: none; color: var(--faint); }
.fd-ratings-card .fd-pc + .fd-ratings-btns, .fd-ratings-card .fd-pc ~ .fd-ratings-btns { margin-top: 12px; }
/* The one line under the pills: "Your watches N" / "Watched once · date" left, "+ Log a watch" right, centred. */
.ww-line1 { display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 32px; margin-top: 14px; }
.ww-once { min-width: 0; font-size: var(--fs-meta); color: var(--faint); }
.ww-head { appearance: none; background: none; border: 0; padding: 0; font: 600 var(--fs-ui) var(--sans); color: var(--ink); cursor: pointer; white-space: nowrap; }
.ww-head:disabled { cursor: default; opacity: 1; }
.ww-head small { margin-left: 6px; font: 500 var(--fs-meta) var(--sans); color: var(--faint); }
.ww-log-btn { appearance: none; background: none; border: 0; margin-left: auto; padding: 0 0 0 12px; min-height: 32px; font: 600 var(--fs-meta) var(--sans); color: var(--ink); cursor: pointer; white-space: nowrap; }
.ww-list { margin-top: 2px; }
.ww-row { display: flex; align-items: center; gap: 10px; padding: 7px 0; }
.ww-row .ww-d { width: 52px; flex: none; line-height: 1.2; }
.ww-row .ww-d b { display: block; font: 600 var(--fs-meta)/1.2 var(--sans); color: var(--ink); }
.ww-row .ww-d small { display: block; font-size: var(--fs-label); font-weight: 400; color: var(--faint); }
.ww-who { flex: 1; min-width: 0; display: flex; align-items: center; gap: 8px; font-size: var(--fs-meta); color: var(--muted); }
/* Who was there wraps, never "…" (owner, 2026-11-05: "Make sure there's no cutoff text"; rule 1100). */
.ww-who > span:last-child { min-width: 0; overflow-wrap: anywhere; }
.ww-who b { color: var(--ink); font-weight: 500; }
.ww-who .ww-face { box-shadow: 0 0 0 2px var(--bg); }
.ww-stack { display: inline-flex; flex: none; }
.ww-stack .ww-face + .ww-face { margin-left: -6px; }
.ww-solo { width: 22px; height: 22px; flex: none; border-radius: var(--radius-av); background: #1c1c20; display: inline-flex; align-items: center; justify-content: center; color: var(--faint); }
.ww-rt { flex: none; font: 600 var(--fs-meta) var(--sans); color: var(--ink); }
.ww-rt.mu { color: var(--faint); font-weight: 500; }
.ww-seeall { appearance: none; display: inline-flex; align-items: center; gap: 2px; background: none; border: 0; padding: 6px 0 2px; min-height: 32px; font: 600 var(--fs-meta) var(--sans); color: var(--accent-2); cursor: pointer; }
.ww-all .ww-row { padding: 9px 0; }
.ww-all .ww-who .ww-face { box-shadow: 0 0 0 2px var(--panel); }
.ww-note { margin: 8px 0 0; font-size: var(--fs-label); color: var(--faint); }
/* People you follow: Friends version 2 (film-page-v5). */
.fd-s.fd-s.fp2 { padding: 0; }
.fp2-card { padding: 12px 14px; border: 1px solid var(--line); border-radius: 14px; background: var(--panel); }
.fp2-top { appearance: none; width: 100%; display: flex; align-items: baseline; gap: 8px; padding: 0; border: 0; background: none; font: inherit; color: var(--ink); cursor: pointer; text-align: left; }
.fp2-avg { font: 500 var(--fs-title)/1 var(--serif); color: var(--ink); }
.fp2-n { font-size: var(--fs-meta); font-weight: 500; color: var(--muted); }
.fp2-go { margin-left: auto; align-self: center; color: var(--faint); display: inline-flex; }
.fp2-faces { display: flex; justify-content: space-between; margin-top: 11px; }
.fp2-face { appearance: none; display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 0; border: 0; background: none; font: inherit; color: var(--ink); text-decoration: none; cursor: pointer; min-width: 40px; }
.fp2-face .fp-av { width: 32px; height: 32px; font-size: var(--fs-meta); box-shadow: 0 0 0 2px var(--panel); }
.fp2-st { font: 600 var(--fs-label) var(--sans); color: var(--ink); white-space: nowrap; min-height: 14px; display: inline-flex; align-items: center; }
.fp2-st svg { color: var(--muted); }
.fp2-st.mu { color: var(--faint); }
.fp2-more-c { width: 32px; height: 32px; border-radius: 50%; border: 1px solid var(--line-2); display: flex; align-items: center; justify-content: center; font: 600 var(--fs-label) var(--sans); color: var(--muted); }
.fp2-hl { display: flex; align-items: center; gap: 7px; margin-top: 11px; font-size: var(--fs-meta); color: var(--muted); }
.fp2-hl b { color: var(--ink); font-weight: 600; }
.fp2-list { margin-top: 10px; padding-top: 4px; }
.fp2-row { display: flex; align-items: center; gap: 12px; min-height: 44px; text-decoration: none; color: var(--ink); }
.fp2-row .fp-av { width: 32px; height: 32px; font-size: var(--fs-meta); }
.fp2-row-n { flex: 1; min-width: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 2px 8px; font-size: var(--fs-ui); overflow-wrap: anywhere; }
.fp2-row .fp2-st { color: var(--accent-2); font-size: var(--fs-meta); }
/* Rule 1099 (owner-approved mockups/journeys/film-page-v8): Watch with as People you follow's last row, and
   Where to watch as list rows on the page's text edge (option b): logo, name, its kind in grey under it. */
.fp2-ww { appearance: none; width: 100%; display: flex; align-items: center; gap: 10px; margin-top: 14px; padding: 9px 10px; border: 0; border-radius: 12px; background: #1b1b1f; font: inherit; color: var(--ink); text-align: left; cursor: pointer; }
.fp2-card > .fp2-ww:first-child { margin-top: 0; }
.fp2-ww:disabled { opacity: .7; cursor: default; }
.fp2-ww .fp-av { flex: none; width: 30px; height: 30px; font-size: var(--fs-meta); }
.fp2-ww-t { flex: 1; min-width: 0; font: 600 var(--fs-meta) var(--sans); color: var(--ink); overflow-wrap: anywhere; }
.fp2-ww-t small { display: block; margin-top: 1px; font: 400 var(--fs-label) var(--sans); color: var(--faint); }
.fp2-ww-go { flex: none; display: inline-flex; align-items: center; gap: 5px; font: 600 var(--fs-meta) var(--sans); color: var(--accent-2); white-space: nowrap; }
.fd-wt-list.fd-wt-rows { margin-top: 0; padding: 0; background: none; border: 0; }
.fd-wt-list.fd-wt-rows .fd-wt-row { gap: 12px; min-height: 0; padding: 6px 0; border: 0; }
.fd-wt-rows .fd-wt-logo { width: 44px; height: 44px; border-radius: 12px; }
.fd-wt-rows .fd-wt-logo img { border-radius: 12px; }
.fd-wt-rows .fd-wt-logo.is-mine { outline: 0; }
.fd-wt-rows .fd-wt-tick { border-color: var(--bg); }
.fd-wt-txt { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.fd-wt-rows .fd-wt-name { flex: none; font-size: var(--fs-ui); font-weight: 500; }
.fd-wt-k { font-size: var(--fs-meta); color: var(--faint); }
.fd-wt-k b { color: var(--accent-2); font-weight: 600; }
.fd-wt-k.is-preorder { color: #c9b98f; }
.fd-wt-sheet .fd-wt-k { display: none; }
.fd-wt-sheet .fd-wt-tick { border-color: var(--bg); }

/* Character check (owner, 2026-11-05, mockups/journeys/character-check-v1-b.html with the owner's
   picks; rule 1107). The red dash: About's short oxblood mark, small, before a heading, the brand's
   accent on the Blend preview's lanes, a Browse door's kicker, a lane's "Lane · N films", the list
   view's count and Our read's heading; and (rule 1120) the one dash of an info page (before its title)
   and of Settings and the menu (before the drawer's title). One red accent per screen: never on each
   section heading. Never a spine beside a list row or a poster. */
/* Settings' group heads (rule 1120): Bodoni Card 18 in cream (the mock's 20 is off the scale), sentence case, no dash. */
.pm-settings .pm-settings-h { font-family: var(--serif); font-size: var(--fs-card); line-height: 1.2; font-weight: 600; letter-spacing: -.01em; text-transform: none; color: var(--ink); padding-top: var(--sp-24); padding-bottom: var(--sp-8); }
.pm-settings .pm-lb-h { align-items: center; }
.rd::before { content: ""; display: inline-block; flex: none; width: 18px; height: 3px; border-radius: 2px; background: var(--shadow); vertical-align: middle; margin: 0 8px 0 0; position: relative; top: -1px; }
/* Spot on as the blue match stamp, straight (the poster stamp's black, blue border and Bodoni, no tilt). */
.fd-pc-stamp { flex: none; display: inline-block; font: 600 var(--fs-meta)/1 var(--serif); color: var(--accent-2); background: var(--bg); border: 1.5px solid var(--accent-2); border-radius: 3px; padding: 3px 5px 2px; }
/* Social's groups: the names in Bodoni (the style guide: names on profiles and groups are serif), and
   the first "Start one with" card on the oxblood spine. */
.comm-group-card.gl2 .gl2-name { font-family: var(--serif); font-size: var(--fs-card); }
.gl2-sug > .gl2-sc:first-child { position: relative; overflow: hidden; padding-left: calc(var(--sp-12) + 5px); }
.gl2-sug > .gl2-sc:first-child::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 5px; background: var(--shadow); }
/* Movie Night: "Tonight's room" as a small Admit stub, ADMIT and the seated count in the ticket red. */
.mnr-rn-stub { display: inline-flex; align-items: stretch; height: 30px; border: 1px solid var(--ink); border-radius: 6px; background: var(--panel); }
.mnr-rn-stub .mnr-rn-k { display: flex; align-items: center; padding: 0 12px; color: var(--ink); }
.mnr-rn-admit { display: flex; align-items: center; gap: 5px; padding: 0 10px; border-left: 1.5px dashed var(--line-2); font-size: var(--fs-label); font-weight: 700; letter-spacing: .13em; text-transform: uppercase; color: var(--red); }
.mnr-rn-admit b { font: 600 var(--fs-read)/1 var(--serif); letter-spacing: 0; }
/* Settings ends on the header's lockup, centred. */
.pm-foot-brand { display: flex; justify-content: center; margin: var(--sp-40) 0 var(--sp-16); pointer-events: none; }
/* Our read's poster beside the title stays 46 × 69 (rule 989): the "Because you enjoyed" tiles' later
   .why3-poster (64 wide, outlined) had been widening it to 64 × 69, cropped (found in rule 1107's check). */
.why3-hd > .why3-hd-poster { position: static; width: 46px; height: 69px; aspect-ratio: auto; outline: 0; background: var(--line); border-radius: var(--radius-poster); overflow: visible; }

/* The header's order of size (owner, 2026-11-05: "Aren't followers and following text supposed to be
   larger than bio?"; rule 1112), on scale tokens only. Since header E (rule 1219) the figures beside the
   photo carry it (.phe-stat: the number --fs-read medium (500) ink, the word --fs-meta regular muted; only the name
   is bold, owner 2026-11-06, rule 1237; the numbers medium since the owner's "slightly thicker", rules 1219, 1237); the bio stays
   regular --fs-ui in ink. Your profile and someone else's alike; iOS ProfileHeader.figures is the same. */
.profile-header .ph-bio { font-size: var(--fs-ui); font-weight: 400; color: var(--ink); }

/* Drawers v1 (owner, 2026-11-05, mockups/journeys/drawers-v1-a.html and -b.html; rule 1121). Rule A:
   a content drawer's kicker, one short line under its Bodoni title, starts with the red dash (.rd), the
   drawer's one red; section labels stay plain caps. A drawer that already carries red (the spine,
   Pitch's bar, Filters' cream Show) gets no dash. A poster in a drawer takes no oxblood offset, and a
   drawer led by a film has the dash under the film's title (rule 1207). */
.modal-kicker { margin-top: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* Dash placement C1 (owner, 2026-11-05, mockups/journeys/dash-placement-v1.html, "maybe make the line
   slightly longer"; rule 1127): a drawer's dash sits under its heading, not before it; since rule 1253 it is
   the accent tick, half the icon's red (--tick-red), half its blue (--select), as in the emails. .rdu is the
   label (the kicker's part before the first " · ", Our read's heading, Pitch's caps): the dash, 24 x 3,
   3 under its first letters, under the last line when it wraps; .rdu-c centres it under a centred
   heading. Adds 6 to the line; the text starts on the drawer's edge with no indent. Web BottomDrawer's
   sub, PortalModal's kicker and titleDash, Discussion, the strand, Where to watch, Our read; iPhone
   DashUnder / DrawerKicker. */
.rdu { display: inline-block; max-width: 100%; vertical-align: baseline; }
.rdu::after, .rdu-b::after { content: ""; display: block; width: 24px; height: 3px; border-radius: 2px; background: linear-gradient(90deg, var(--tick-red) 50%, var(--select) 50%); margin-top: 3px; }
/* Under the whole heading (owner, 2026-11-06; rule 1254): .rdu-b on a drawer's heading block (BottomDrawer's
   .bd-t, PortalModal's title block, ShareSheetFrame's, Where to watch's, Filters') puts the tick under its
   last line, never between the title and its kicker. 3 under it in the flex columns too. */
.rdu-b::after { flex: none; }
.bd-t.rdu-b::after { margin-top: 1px; }
.fd-wt-sheet-t.rdu-b::after, .browse-fs-t.rdu-b::after { margin-top: -1px; }
.rdu.rdu-c::after { margin-left: auto; margin-right: auto; }
h2.rdu { display: block; }
.bd-t span.bd-k .rdu, .modal-kicker .rdu, .fd-wt-sheet-k .rdu { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; vertical-align: top; }
/* Discussion: 8 more over the tabs, so the kicker's red dash and the tabs' blue rule never touch. */
.fdisc .fdisc-head { padding-bottom: calc(10px + var(--sp-8)); }
/* A drawer led by a film (owner, 2026-11-06; rule 1254): no tick; its poster takes the shelf's subtle oxblood
   offset (2px, 55%; rule 1253): the rating drawers, When did you watch it and its take step, Discussion, the
   Why drawer, the film's and Montage's read's share drawers, a group's who-saved. */
img.seen-sheet-poster, img.tk-film-po, img.ls-sheet-po, img.fdisc-poster, .why3-hd > img.why3-hd-poster, .share-sheet-film img.share-sheet-po-off { box-shadow: 2px 2px 0 color-mix(in srgb, var(--shadow) 55%, transparent); }
/* Film DNA strand: the definition in Bodoni roman, never italic; Receipts and the steps in Bodoni. */
.dna9-detail-hint, .bl-strand-hint { font: 500 var(--fs-card)/1.35 var(--serif); font-style: normal; color: var(--ink); }
.dna9-chips .chip { font-family: var(--serif); font-size: var(--fs-ui); font-weight: 500; }
.dna9-sheet .dna9-step, .bl-strand-nav button { font: 500 var(--fs-card)/1.1 var(--serif); color: var(--ink); }
/* Where to watch, all options: the film as title, the job as the kicker; caps groups; no hairline. */
.fd-wt-sheet-t { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.fd-wt-sheet-t .fd-wt-sheet-title { display: block; font: 600 var(--fs-heading)/1.15 var(--serif); }
.fd-wt-sheet-k { font: 400 var(--fs-meta)/1.35 var(--sans); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.fd-wt-sheet .fd-wt-group { font: 600 var(--fs-label)/1 var(--sans); letter-spacing: .12em; text-transform: uppercase; color: var(--muted); margin-top: 24px; margin-bottom: 4px; }
.fd-wt-mine { display: none; }
.fd-wt-sheet .fd-wt-mine { display: block; font-size: var(--fs-meta); font-weight: 600; color: var(--accent-2); }
.fd-wt-sheet .fd-watch-foot { margin-top: 16px; border-top: 0; padding-top: 0; }
/* Your watches, See all: the dates in Bodoni, a diary's margin. */
.ww-all .ww-d { width: 68px; font: 600 var(--fs-card)/1.15 var(--serif); }
.ww-all .ww-d small { font-family: var(--sans); }
/* Filters: the kicker naming the list (plain), row names in Bodoni, no hairlines, plain caps groups. */
.browse-fs-t { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.browse-fs-kick { font: 400 var(--fs-meta)/1.35 var(--sans); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.browse-fs .browse-fs-k { font-family: var(--serif); font-size: var(--fs-card); font-weight: 500; }
.browse-fs .browse-fs-sec, .browse-fs .browse-fs-group.lead .browse-fs-sec:last-child { border-bottom: 0; }
.browse-fs .browse-fs-gh { color: var(--muted); }
/* Filters with character (owner, 2026-11-06, mockups/journeys/filters-character-v1.html A): the red dash
   under "Filters" (.rdu, the sheet's one red), "· 3 set" in cream on the kicker, and a set row's value as
   a pill in the chosen style (22% blue, the 1.5 edge, cream semibold), the look its chips have open. */
.browse-fs-kick b { color: var(--ink); font-weight: 600; }
.browse-fs .browse-fs-v.on { flex: 0 1 auto; margin-left: auto; box-sizing: border-box; height: 26px; line-height: 23px; padding: 0 10px;
  border-radius: var(--radius-pill); background: var(--select-fill); border: 1.5px solid var(--select-edge); color: var(--ink); font-weight: 600; }
/* The same pill for a set value on Tonight's More filters (closed) and a movie night's Genre and More filters. */
.sel-pill { display: inline-flex; align-items: center; box-sizing: border-box; height: 26px; max-width: 100%; padding: 0 10px; border-radius: var(--radius-pill);
  background: var(--select-fill); border: 1.5px solid var(--select-edge); color: var(--ink); font: 600 var(--fs-meta)/1 var(--sans); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* Watch edit (owner-approved mockups/journeys/watch-edit-v2.html; rule 1129): the pencil that ends
   every watch row, a watch's take under its row, the edit drawer and its plain confirms. */
.ww-pen { appearance: none; flex: none; width: 32px; height: 32px; margin-right: -8px; display: inline-flex; align-items: center; justify-content: center;
  border: 0; border-radius: 8px; background: none; color: var(--faint); cursor: pointer; }
.ww-pen:active { transform: scale(.92); opacity: .7; }
.ww-pen-gap { flex: none; width: 24px; height: 32px; }
.ww-once { display: inline-flex; align-items: center; gap: 2px; }
.ww-once .ww-pen { margin-right: 0; }
.ww-take { margin: -2px 0 6px 62px; }
.ww-all .ww-take { margin-left: 78px; }
.ww-take-t { margin: 0; font: 400 var(--fs-meta)/1.45 var(--serif); color: var(--ink); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.ww-take-t.open { display: block; -webkit-line-clamp: unset; }
.ww-take-sp { font-family: var(--sans); color: var(--faint); }
.ww-take-more { appearance: none; border: 0; background: none; padding: 2px 0; font: 600 var(--fs-label) var(--sans); color: var(--muted); cursor: pointer; }
.tk-last { margin: 8px 0 0; font: 400 var(--fs-meta)/1.45 var(--serif); color: var(--muted); }
.tk-last span { display: block; font: 500 var(--fs-label) var(--sans); color: var(--faint); margin-bottom: 2px; }
.we-body { display: flex; flex-direction: column; gap: 16px; padding-top: 4px; }
.we-sec .ww { margin: 0; }
.we-sec.fa-ask { margin: 0; }
.we-ta { min-height: 66px; padding: 10px 14px; border: 1px solid var(--line-2); border-radius: 12px; background: var(--panel-2); }
.we-take { padding: 12px 14px; border: 1px solid var(--line-2); border-radius: 12px; }
.we-take-t { margin: 0 0 8px; font: 400 var(--fs-ui)/1.45 var(--serif); color: var(--ink); }
.we-take-acts { display: flex; gap: 16px; }
.we-link { appearance: none; border: 0; background: none; padding: 0; min-height: 28px; font: 600 var(--fs-meta) var(--sans); color: var(--muted); cursor: pointer; }
.we-save { flex: none; width: 100%; }
.we-del { appearance: none; align-self: center; border: 0; background: none; padding: 6px 12px; min-height: 36px; font: 600 var(--fs-meta) var(--sans); color: var(--muted); cursor: pointer; }
.we-note { margin: 0 0 14px; font-size: var(--fs-meta); line-height: 1.45; color: var(--muted); }
.we-acts { display: flex; flex-direction: column; gap: 10px; padding-top: 6px; }
.we-btn { flex: none; width: 100%; height: var(--btn-h-lg); border-radius: 12px; font: 600 var(--fs-ui) var(--sans); cursor: pointer; }
/* The confirm's one red: the destructive button, oxblood with cream text. */
.we-red { appearance: none; border: 0; background: var(--shadow); color: var(--ink); }
.we-red:active:not(:disabled) { transform: scale(.97); opacity: .85; }
.we-btn:disabled { opacity: .5; cursor: default; }
.we-cancel { appearance: none; align-self: center; border: 0; background: none; padding: 6px 12px; min-height: 40px; font: 600 var(--fs-ui) var(--sans); color: var(--muted); cursor: pointer; }

/* Pitch sharing (owner-approved 2026-11-05, mockups/journeys/pitch-share-v1; rule 1140). The share
   drawer's header is the Pitch mark, "Share your pitch" with the C1 dash under it and the sentence in
   Bodoni roman; a face you sent to keeps a quiet check. (The header slot left of the ×, .modal-hd-act,
   went with Pitch becoming a page, 91ec9729.) */
.pitch-share-mark { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 8px; color: var(--ink); background: var(--panel-2); }
.share-sheet-film span.share-sheet-sub-serif { display: block; margin-top: 7px; font: 500 var(--fs-ui)/1.3 var(--serif); font-style: normal; color: #d6d0c3; }
.share-pick-ck.is-sent { background: #2a3442; color: var(--accent-2); }
.share-pick-sent { color: var(--accent-2); font-weight: 600; }
.pitch-share-card { margin-top: var(--sp-24); }
.pitch-share-card .mns-acts { width: 100%; }

/* The pitch card in a chat or a group (rule 1140): DM card A's frame (.gth-card.dmc, rule 1132). */
.pmc { display: flex; flex-direction: column; }
.pmc .dmc-kick { padding-top: 4px; }
.pmc-s { display: block; margin-top: 8px; font: 600 var(--fs-heading)/1.15 var(--serif); font-style: normal; color: var(--ink); overflow-wrap: anywhere; }
.pmc-rd { display: block; margin-top: 7px; font: 600 var(--fs-label)/1.2 var(--sans); letter-spacing: 1.2px; text-transform: uppercase; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pmc-row { display: flex; align-items: flex-end; gap: 8px; margin-top: 13px; }
.pmc-pb { appearance: none; padding: 0; border: 0; background: none; cursor: pointer; flex: none; }
.pmc-po, .pmc-po.gth-card-ph { display: block; width: 50px; height: 75px; object-fit: cover; border-radius: 5px; background: var(--line); }
.pmc-po.is-newest { box-shadow: 4px 4px 0 var(--shadow); }
.pmc-pl { margin-left: 6px; padding-bottom: 2px; font: 500 var(--fs-meta)/1.35 var(--sans); color: var(--faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.pmc-pl b { display: block; font: 600 var(--fs-label) var(--sans); letter-spacing: 1.2px; text-transform: uppercase; color: var(--muted); }
.pmc-rest { display: block; margin-top: 12px; font: 400 var(--fs-meta) var(--sans); color: var(--muted); }

/* The Letterboxd import top-up (rule 1148, mockups/journeys/import-topup-v1.html): the gate, the deck,
   the after-Save drawer and B's end. One red per screen: the gate's and the end's dash, the deck's
   hero shadow, the drawer's label dash. No italics, no divider lines. */
.tu-gate { cursor: pointer; }
.tu-gate-mid { text-align: center; margin: 72px 0 24px; }
.tu-gate-h { font: 600 var(--fs-heading)/1.2 var(--serif); color: var(--ink); margin: 0; }
.tu-gate-s { font: 600 var(--fs-heading)/1.2 var(--serif); color: var(--muted); margin: 6px 0 0; }
.tu-gate-mid .tu-segs-wrap { margin: 24px auto 0; max-width: 300px; text-align: left; }
.tu-gate-n { font: 400 var(--fs-meta)/1.4 var(--sans); color: var(--muted); margin: 16px 0 0; }
.tu-gate-foot { display: flex; flex-direction: column; align-items: center; gap: 12px; margin-top: 24px; }
.tu-gate-go { width: 100%; max-width: 346px; }
.tu-segs-wrap { display: block; width: 100%; }
.tu-segs-wrap .su-segs { margin-top: 0; }
.tu-segs-wrap .su-segs i.on { background: var(--accent-2); }
.tu-segs-l { display: block; margin-top: 7px; font: 400 var(--fs-meta) var(--sans); color: var(--muted); }
.tu-top { padding: 0 16px; }
.tu-top-row { display: flex; align-items: center; gap: 12px; width: 100%; min-height: 48px; }
.tu-top-count { flex: 1; min-width: 0; }
.tu-poster { position: relative; }
.tu-hero { box-shadow: var(--shadow-offset); }
.tu-lbtag { position: absolute; left: 50%; top: -11px; transform: translateX(-50%); white-space: nowrap; height: 22px; padding: 0 8px; border-radius: 6px;
  background: var(--bg); box-shadow: inset 0 0 0 1px rgba(239,232,218,.45); font: 600 var(--fs-label)/22px var(--sans); letter-spacing: .3px; color: var(--ink); }
.tu-logged { margin-top: 4px; font: 400 var(--fs-meta) var(--sans); color: var(--faint, var(--muted)); }
.tu-why { margin-top: 6px; font: 400 var(--fs-meta) var(--sans); color: var(--accent-2); }
.tu-forgot { width: 100%; max-width: 346px; margin-top: 14px; }
.tu-end { min-height: 100dvh; display: flex; flex-direction: column; justify-content: center; padding: 72px 16px 32px; max-width: 420px; margin: 0 auto; }
.tu-end-k { font: 400 var(--fs-meta) var(--sans); color: var(--muted); }
.tu-end-h { font: 600 var(--fs-heading)/1.2 var(--serif); color: var(--ink); margin: 8px 0 0; }
.tu-end-dash { margin: 14px 0 0; }
.tu-end-p { font: 400 var(--fs-ui)/1.45 var(--sans); color: var(--muted); margin: 16px 0 0; }
.tu-strands { margin-top: 16px; display: flex; flex-direction: column; gap: 8px; }
.tu-strand { display: flex; align-items: center; gap: 12px; background: var(--panel-2, rgba(255,255,255,.04)); border-radius: 12px; padding: 13px 14px; }
.tu-strand-l { flex: 1; font: 600 var(--fs-ui) var(--serif); color: var(--ink); }
.tu-strand-d { font: 400 var(--fs-meta) var(--sans); color: var(--muted); }
.tu-strand b { font: 600 var(--fs-ui) var(--sans); color: var(--ink); min-width: 28px; text-align: right; }
.tu-end-foot { display: flex; flex-direction: column; gap: 12px; margin-top: 24px; }
.tu-drawer .tu-dr-h { font: 600 var(--fs-heading)/1.25 var(--serif); color: var(--ink); margin: 6px 0 8px; }
.tu-drawer .tu-dr-n { font: 400 var(--fs-meta) var(--sans); color: var(--muted); margin: 0; }
.tu-drawer .tu-segs-wrap { margin: 14px 0 6px; }
.tu-drawer .tu-dr-g { font: 400 var(--fs-meta)/1.4 var(--sans); color: var(--muted); margin: 8px 0 14px; }
.tu-drawer .tu-dr-f { font: 400 var(--fs-meta) var(--sans); color: var(--faint, var(--muted)); text-align: center; margin: 10px 0 0; }

/* Drawers hold the page still (rule 1151, owner 2026-11-05: "when I scroll I can still scroll the page
   behind the drawer"). lib/scroll-lock.ts fixes <body> in place while one is open; here a scroll inside
   a drawer stays inside it, never chaining on to the page at its ends. */
.modal-overlay, .modal, .drawer-scrim, .drawer-body, .seen-sheet-backdrop, .share-sheet, .seen-sheet, .browse-fs-backdrop, .fdisc-backdrop,
.fp-overlay, .fp-sheet, .wt-overlay, .fd-wt-scrim, .fd-wt-sheet, .mnr-chat-scrim, .mnv-scrim, .why-drawer { overscroll-behavior: contain; }

/* Films together (owner-approved 2026-11-06, mockups/journeys/films-together-v1.html option A; rule
   1169). On someone else's profile, the viewer's only: a ticket and "N films together" under the
   @handle, 13px muted like the handle, the number in ink. It shares the Founding member badge's row,
   so the stack is never taller than today's founding one. The whole line is the button, its tap
   area grown to 44 without moving anything. */
.ph-together { display: flex; align-items: center; gap: 8px; min-width: 0; margin-top: 6px; white-space: nowrap; }
.ph-together .founding-badge { margin-left: 0; }
.ph-together-line { position: relative; display: inline-flex; align-items: center; gap: 5px; min-width: 0; padding: 0; border: 0; background: none;
  font: 400 var(--fs-meta)/16px var(--sans); color: var(--muted); cursor: pointer; white-space: nowrap; }
.ph-together-line::before { content: ""; position: absolute; left: -6px; right: -6px; top: -14px; bottom: -14px; }
.ph-together-line svg { flex: none; color: var(--muted); }
.ph-together-line b { font-weight: 600; color: var(--ink); }
.ph-together-line:hover > span { color: var(--ink); }
/* "Films with @handle": the streak's kind of sheet, fit to its rows. */
.modal-sheet.ftg-sheet { height: auto; }
@media (min-width: 701px) {
  .modal.modal-sheet.ftg-sheet { border: 1px solid var(--line-2); border-radius: var(--radius-drawer); padding-top: var(--sp-24); padding-bottom: var(--sp-24); }
}
/* Films together's kicker ("With @handle · N films since <day>") wraps, never cuts the handle. */
.ftg-sheet .modal-kicker, .ftg-sheet .modal-kicker .rdu { white-space: normal; overflow: visible; text-overflow: clip; overflow-wrap: anywhere; }
.ftg-wait { margin: 12px 0; font: 400 var(--fs-meta) var(--sans); color: var(--muted); }
.ftg-list { list-style: none; margin: 4px 0 0; padding: 0; }
.ftg-list li + li { border-top: 1px solid var(--line); }
.ftg-row { display: flex; gap: 12px; align-items: flex-start; width: 100%; padding: 12px 0; border: 0; background: none; text-align: left; color: inherit; text-decoration: none; cursor: pointer; }
.ftg-po { flex: none; width: 46px; height: 69px; border-radius: 4px; object-fit: cover; background: var(--panel-2); outline: 1px solid rgba(239, 232, 218, .1); outline-offset: -1px; }
.ftg-tx { display: flex; flex-direction: column; min-width: 0; flex: 1; }
.ftg-t { display: flex; align-items: baseline; gap: 6px; min-width: 0; font: 600 var(--fs-card)/1.15 var(--serif); color: var(--ink); }
.ftg-tn { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ftg-t small { flex: none; font: 400 var(--fs-meta) var(--sans); color: var(--faint); }
.ftg-m { margin-top: 3px; font: 400 var(--fs-meta)/1.35 var(--sans); color: var(--muted); overflow-wrap: anywhere; }
/* Both people's stars: one line when they fit, else one under the other (320pt: "You not logged
   yet" and a long first name); each pair never breaks inside. */
.ftg-s { display: flex; flex-wrap: wrap; column-gap: 16px; row-gap: 2px; margin-top: 6px; font: 400 var(--fs-meta)/1.35 var(--sans); color: var(--muted); align-items: baseline; }
.ftg-s > span { white-space: nowrap; }
.ftg-s b { margin-left: 4px; font: 600 var(--fs-ui) var(--sans); color: var(--ink); }
.ftg-s b.is-none { font: 400 var(--fs-meta) var(--sans); color: var(--faint); }
.ftg-foot { display: flex; align-items: center; gap: 6px; margin: 12px 0 0; font: 400 var(--fs-meta)/1.4 var(--sans); color: var(--faint); }
.ftg-foot svg { flex: none; }

/* Moods at the limit (owner-approved 2026-11-06, filters-review-v1): three on, the rest dim to 45%;
   the opposite of an on pace or scale mood stays live (it swaps). */
.mood-chip.dim, .browse-chip.dim { opacity: .45; }
.mood-chip.dim:hover { color: var(--ink); border-color: var(--line-2); }
.browse-chip.dim:disabled { cursor: default; }
/* "From your settings" under Age rating and Language while they are as Settings has them (2026-11-06). */
.browse-fs-note.fs-from-settings { font-size: var(--fs-label); color: var(--faint); margin-top: -4px; }

/* Called it (rule 1189, called-it-compact-v1 A): one muted 13px line, the last of your Film DNA block,
   no rule above it; the check in muted ink, never red. Under 300px the clause drops (one line always). */
.cit-line { container-type: inline-size; display: flex; align-items: center; gap: 8px; width: 100%; margin-top: 12px; padding: 4px 0; background: none; border: 0; text-align: left; font: 400 var(--fs-meta)/1.35 var(--sans); color: var(--muted); cursor: pointer; }
.cit-line b { color: var(--ink); font-weight: 600; }
.cit-ck { flex: none; font-weight: 700; color: var(--muted); }
.cit-t { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cit-chev { flex: none; color: var(--faint); font-weight: 600; }
@container (max-width: 300px) { .cit-more { display: none; } }
.cit-note { margin: 8px 0 0; font-size: var(--fs-meta); color: var(--muted); }
.cit-rows { display: flex; flex-direction: column; gap: 4px; margin-top: 12px; overflow-y: auto; }
.cit-row { display: flex; align-items: center; gap: 12px; padding: 6px 0; background: none; border: 0; text-align: left; color: var(--ink); cursor: pointer; }
.cit-po { flex: none; width: 32px; height: 48px; border-radius: 4px; object-fit: cover; background: var(--panel-2); }
.cit-rt { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.cit-rt b { font: 500 var(--fs-ui)/1.25 var(--serif); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cit-rt span { font-size: var(--fs-meta); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cit-v { flex: none; display: flex; align-items: center; gap: 6px; font: 600 var(--fs-meta) var(--sans); color: var(--ink); white-space: nowrap; }
.cit-v.on { color: var(--accent-2); }
.cit-v .hwd-mark { width: 18px; height: 18px; border: 0; background: rgba(239, 232, 218, .1); }
.cit-v.on .hwd-mark { background: rgba(143, 179, 217, .16); box-shadow: none; color: var(--accent-2); }
.cit-v .hwd-mark svg { width: 11px; height: 11px; stroke-width: 2.2; }
/* Details' fuller facts and the Parental guide (rule 1190, mockups/journeys/film-guide-v2.html A):
   two columns of facts, Genres and Collection across; the guide under a hairline, or beside the
   facts once the column is wide enough for both (about 600px). The hero's avoid flag is the
   screen's one red; on its films the poster's offset shadow is grey. */
.fd-details { display: grid; gap: var(--sp-16) var(--sp-32); grid-template-columns: 1fr; }
@media (min-width: 640px) { .fd-details.has-guide { grid-template-columns: repeat(auto-fit, minmax(270px, 1fr)); } }
.fd-details-grid { display: grid; grid-template-columns: 1fr 1fr; gap: var(--sp-12) var(--sp-16); align-content: start; }
.fd-details-grid .fd-detail-item { min-width: 0; gap: 2px; }
.fd-details-grid .fd-detail-item.wide { grid-column: 1 / -1; }
.fd-details-grid .fd-detail-v { overflow-wrap: anywhere; }
.fd-guide { min-width: 0; }
.fd-details.has-guide > .fd-details-grid + .fd-guide { border-top: 1px solid var(--line); padding-top: var(--sp-16); }
@media (min-width: 640px) { .fd-details.has-guide > .fd-details-grid + .fd-guide { border-top: 0; padding-top: 0; } }
.fd-guide-h { font-family: var(--label); font-size: var(--fs-label); font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--faint); margin: 0 0 10px; }
.fd-guide-head { display: flex; align-items: center; flex-wrap: wrap; gap: 10px; }
.fd-guide-badge { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 9px; border: 1.5px solid var(--ink); border-radius: 5px; font-size: var(--fs-meta); font-weight: 700; letter-spacing: .02em; color: var(--ink); }
.fd-guide-badge small { font-size: var(--fs-label); font-weight: 600; letter-spacing: .06em; color: var(--muted); }
.fd-guide-why { font-size: var(--fs-meta); font-weight: 500; color: var(--ink); }
.fd-guide-levels { margin-top: 12px; }
.fd-guide-row { display: flex; align-items: center; gap: 10px; min-height: 34px; border-top: 1px solid var(--line); }
.fd-guide-row:first-child { border-top: 0; }
.fd-guide-n { flex: 1; font-size: var(--fs-meta); font-weight: 500; color: var(--ink); }
.fd-guide-meter { display: inline-flex; gap: 3px; }
.fd-guide-meter i { width: 14px; height: 5px; border-radius: 2px; background: var(--line); }
.fd-guide-meter i.f { background: var(--muted); }
.fd-guide-w { width: 74px; text-align: right; font-size: var(--fs-meta); font-weight: 600; color: var(--ink); }
.fd-guide-w.none { color: var(--faint); font-weight: 500; }
.fd-guide-cws { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; }
.fd-guide-cw { display: inline-flex; align-items: center; min-height: 26px; padding: 0 9px; border: 1px solid var(--line-2); border-radius: 6px; font-size: var(--fs-meta); font-weight: 500; color: var(--ink); }
.fd-guide-cw.mine { border-color: var(--ink); }
.fd-guide-cw-on { margin-left: 6px; color: var(--muted); }
.fd-guide-src { margin: 10px 0 0; font-size: var(--fs-label); line-height: 1.45; color: var(--faint); }
.fd-avoid-flag { display: flex; align-items: center; gap: 6px; appearance: none; background: none; border: 0; padding: 0; margin: -4px 0 10px; min-height: 24px; cursor: pointer; text-align: left;
  font: inherit; font-size: var(--fs-meta); font-weight: 600; color: var(--danger); }
.fd-avoid-flag svg { flex: none; }
.fd-herowrap > .fd-hero-body > .fd-hero-poster.is-quiet, .fd-herowrap > .fd-hero-stack > .fd-hero-poster.is-quiet { box-shadow: 6px 6px 0 var(--line); }

/* The bio limit (owner, 2026-11-06; BioField.tsx): the counter from 120 (muted, ink from 140) and
   the paste note under a bio or group description field, and four lines then More on the page. */
.bio-meta { display: flex; align-items: baseline; gap: 8px; margin-top: 2px; font-family: var(--sans); font-size: var(--fs-meta); font-weight: 400; letter-spacing: normal; text-transform: none; color: var(--muted); }
.bio-count { margin-left: auto; font-variant-numeric: tabular-nums; color: var(--muted); }
.bio-count.is-ink { color: var(--ink); }
.gedit .bio-meta { margin-top: 6px; }
.bio-clamp { display: block; }
.bio-clamp.is-clamped { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 4; overflow: hidden; }
.bio-more { display: block; margin-top: 4px; }
/* Rule 1243 (owner-approved journeys/rating-history-v1): Your rating's line, "YOUR RATING · 4.0★ on
   Letterboxd · Popular". One row high; an extra that does not fit wraps onto a hidden second row, so
   Popular drops first, then the average, and the line never wraps. */
.fd-s.fd-s .fd-ratings-head.fd-rhead, .fd-ratings-head.fd-rhead { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: flex-start;
  column-gap: var(--sp-8); row-gap: var(--sp-24); height: 20px; overflow: hidden; line-height: 20px; }
.fd-s.fd-s .fd-ratings-head.fd-rhead > .fd-sh { flex: none; align-self: center; }
.fd-ratings-head.fd-rhead .fd-rx { flex: none; margin: 0; display: block; overflow: visible;
  font: 400 var(--fs-meta)/20px var(--sans); color: var(--muted); white-space: nowrap; }
.fd-ratings-head.fd-rhead .fd-rx b { font-weight: 600; color: var(--ink); }
.fd-ratings-head.fd-rhead .fd-rx-dot { color: var(--faint); margin-right: var(--sp-8); }
/* History's Watched: a film with a take you may see carries a speech bubble on the rating badge's plate. */
.lib-take { position: absolute; right: 6px; bottom: 6px; display: flex; padding: 3px 5px; color: var(--ink);
  background: rgba(9,11,16,.82); border-radius: var(--radius-sm); }
